(function(g){g.__QURAN_DATA=g.__QURAN_DATA||{};g.__QURAN_DATA["tamil-020"]={"sura":20,"name_ar":"طه","name_en":"Taha","verses":135,"source":"https://www.tamililquran.com/tafsiribnkathir.php","count":135,"missing":[],"data":{"1":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=8\" class=\"link\">20:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:8 ஐ பார்க்கவும்"},"2":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=8\" class=\"link\">20:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:8 ஐ பார்க்கவும்"},"3":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=8\" class=\"link\">20:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:8 ஐ பார்க்கவும்"},"4":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=8\" class=\"link\">20:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:8 ஐ பார்க்கவும்"},"5":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=8\" class=\"link\">20:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:8 ஐ பார்க்கவும்"},"6":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=8\" class=\"link\">20:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:8 ஐ பார்க்கவும்"},"7":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=8\" class=\"link\">20:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:8 ஐ பார்க்கவும்"},"8":{"html":"<strong>மக்காவில் அருளப்பட்டது</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بِسْمِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمِ</span><br />\r\n<br />\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.<br />\r\n<br />\r\n<strong>குர்ஆன் ஒரு நினைவூட்டல் மற்றும் அல்லாஹ்விடமிருந்து அருளப்பட்ட வஹீ (இறைச்செய்தி)</strong><br />\r\n<br />\r\nசூரா அல்-பகரா அத்தியாயத்தின் தொடக்கத்தில் உள்ள தனித்தனி எழுத்துக்கள் (முக்கத்தாத்) குறித்து நாம் ஏற்கனவே விவாதித்துள்ளோம், எனவே அதன் விவாதத்தை இங்கே மீண்டும் கூறத் தேவையில்லை. அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أَنَزَلْنَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْكَ</span> <span class=\"quran-arabic-font text-success\">الْقُرْءَانَ</span> <span class=\"quran-arabic-font text-success\">لِتَشْقَى</span><br />\r\n<br />\r\n(நபியே!) உம்மைத் துன்பத்திற்குள்ளாக்குவதற்காக இந்தக் குர்ஆனை நாம் உம்மீது இறக்கவில்லை. ஜுவைபிர் அறிவிக்கிறார்கள், அத்-தஹ்ஹாக் கூறினார்கள்: \"அல்லாஹ் தனது தூதருக்கு (ஸல்) குர்ஆனை அருளியபோது, அவர்களும் அவர்களது தோழர்களும் (ரழி) அதைக் கடைப்பிடித்தார்கள். அப்போது குரைஷி இணைவைப்பாளர்கள், 'இந்தக் குர்ஆன் முஹம்மதை (ஸல்) வருத்தத்திற்குள்ளாக்கவே அருளப்பட்டது' என்று கூறினார்கள். எனவே அல்லாஹ் இதனை அருளினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">طه</span> - <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أَنَزَلْنَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْكَ</span> <span class=\"quran-arabic-font text-success\">الْقُرْءَانَ</span> <span class=\"quran-arabic-font text-success\">لِتَشْقَى</span> - <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">تَذْكِرَةً</span> <span class=\"quran-arabic-font text-success\">لِّمَن</span> <span class=\"quran-arabic-font text-success\">يَخْشَى</span><br />\r\n<br />\r\n(தா ஹா. உம்மைத் துன்புறுத்துவதற்காக இந்தக் குர்ஆனை நாம் உம்மீது இறக்கவில்லை. மாறாக, (அல்லாஹ்வுக்கு) அஞ்சுபவர்களுக்கு ஒரு நினைவூட்டலாகவே இதனை இறக்கினோம்.) அந்தப் பொய்யர்களின் கூற்றைப் போன்றதல்ல இது. மாறாக, அல்லாஹ் யாருக்கு அறிவை வழங்குகிறானோ, அவருக்கு அபரிமிதமான நன்மையை அவன் நாடுகிறான் என்பதே இதன் பொருளாகும். இது இப்னு மஸ்ஊத் (ரழி) அவர்கள் அறிவிக்க, புகாரி மற்றும் முஸ்லிம் ஆகிய இரு ஆதாரப்பூர்வமான நூல்களில் (ஸஹீஹ்களில்) இடம்பெற்றுள்ள பின்வரும் ஹதீஸைப் போன்றதாகும். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">يُرِدِ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">خَيْرًا</span> <span class=\"quran-arabic-font text-success\">يُفَقِّهْهُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الدِّين</span>»<br />\r\n<br />\r\n\"யாருக்கு அல்லாஹ் நன்மையை நாடுகிறானோ, அவருக்கு மார்க்கத்தில் ஆழ்ந்த ஞானத்தை வழங்குகிறான்.\" முஜாஹித் அவர்கள் அல்லாஹ்வின் வசனத்திற்குப் பின்வருமாறு விளக்கமளித்தார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أَنَزَلْنَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْكَ</span> <span class=\"quran-arabic-font text-success\">الْقُرْءَانَ</span> <span class=\"quran-arabic-font text-success\">لِتَشْقَى</span><br />\r\n<br />\r\n(உம்மைத் துன்புறுத்துவதற்காக இந்தக் குர்ஆனை நாம் உம்மீது இறக்கவில்லை,) \"இது அவனது மற்றொரு வசனத்தைப் போன்றது: 'ஆகவே, குர்ஆனிலிருந்து உங்களுக்கு எளிதானதை ஓதுங்கள்.' (<a href=\"qurandisp.php?sura=73&ayah=20\" class=\"link\">73:20</a>). ஏனெனில், (ஆரம்ப காலத்தில்) மக்கள் தொழுகையில் சோர்வடையும் போது பிடித்துக் கொள்வதற்காகத் தங்கள் மார்புக்கு நேராகக் கயிறுகளைத் தொங்கவிட்டுக் கொண்டிருந்தார்கள்.\" கதாதா கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أَنَزَلْنَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْكَ</span> <span class=\"quran-arabic-font text-success\">الْقُرْءَانَ</span> <span class=\"quran-arabic-font text-success\">لِتَشْقَى</span><br />\r\n<br />\r\n(உம்மைத் துன்புறுத்துவதற்காக இந்தக் குர்ஆனை நாம் உம்மீது இறக்கவில்லை,) \"இல்லை, அல்லாஹ்வின் மீது ஆணையாக! அல்லாஹ் இதனை ஒரு சிரமமான விஷயமாக ஆக்கவில்லை. மாறாக, இதனை ஒரு கருணையாகவும், பேரொளியாகவும், சொர்க்கத்திற்கு வழிகாட்டியாகவும் அவன் ஆக்கியுள்ளான்.\" அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">تَذْكِرَةً</span> <span class=\"quran-arabic-font text-success\">لِّمَن</span> <span class=\"quran-arabic-font text-success\">يَخْشَى</span><br />\r\n<br />\r\n(மாறாக, (அல்லாஹ்வுக்கு) அஞ்சுபவர்களுக்கு ஒரு நினைவூட்டலாகவே இதனை இறக்கினோம்.)<br />\r\n<br />\r\nஅல்லாஹ் தனது வேதத்தை அருளி, தனது தூதரைத் (ஸல்) தனது அடியார்களுக்கு ஒரு கருணையாக அனுப்பினான். சிந்திக்கும் மனிதன் இதன் மூலம் படிப்பினை பெறுவதற்காகவே இவ்வாறு செய்தான். ஒரு மனிதன் அல்லாஹ்வின் வேதத்தைச் செவியேற்கும்போது அதன் மூலம் பயனடைவான். இது அல்லாஹ் எதை அனுமதிக்கிறான், எதைத் தடுக்கிறான் என்பதை விளக்கியுள்ள ஒரு நினைவூட்டலாகும். அவனது வசனம்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">تَنزِيلاً</span> <span class=\"quran-arabic-font text-success\">مِّمَّنْ</span> <span class=\"quran-arabic-font text-success\">خَلَق</span> <span class=\"quran-arabic-font text-success\">الْأَرْضَ</span> <span class=\"quran-arabic-font text-success\">وَالسَّمَـوَتِ</span> <span class=\"quran-arabic-font text-success\">الْعُلَى</span><br />\r\n<br />\r\n(இது) பூமியையும் உயர்ந்த வானங்களையும் படைத்தவனிடமிருந்து (அல்லாஹ்விடமிருந்து) அருளப்பட்ட வஹீ (இறைச்செய்தி) ஆகும். இதன் பொருள்: \"முஹம்மதே (ஸல்)! உமக்கு வந்துள்ள இந்தக் குர்ஆன் உமது இறைவனிடமிருந்து அருளப்பட்ட வஹீ (இறைச்செய்தி) ஆகும். அவனே அனைத்திற்கும் அதிபதியும் அரசனும் ஆவான். தான் நாடுவனவற்றைச் செய்ய அவன் பேராற்றல் மிக்கவன். அவனே ஆழமான பகுதிகளையும் அடர்த்தியான நிலப்பரப்பையும் கொண்ட பூமியைப் படைத்தான். மிக உயர்ந்த வானங்களையும் அவற்றின் நுட்பங்களுடன் படைத்தான்.\" ஒரு ஹதீஸில் (இதனைத் திர்மிதி உள்ளிட்டோர் ஆதாரப்பூர்வமானது எனக் குறிப்பிட்டுள்ளனர்) இவ்வாறு வந்துள்ளது: ஒவ்வொரு வானத்தின் தடிமனும் ஐநூறு ஆண்டுப் பயண தூரமாகும்; ஒரு வானத்திற்கும் அடுத்த வானத்திற்கும் இடையிலான தூரமும் ஐநூறு ஆண்டுகளாகும். அல்லாஹ்வின் வசனத்தைப் பற்றி:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الرَّحْمَـنُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْعَرْشِ</span> <span class=\"quran-arabic-font text-success\">اسْتَوَى</span><br />\r\n<br />\r\n(அளவற்ற அருளாளன் அர்ஷின் மீது இஸ்தவா (உயர்ந்து) இருக்கிறான்.) இது தொடர்பான விளக்கம் ஏற்கனவே சூரா அல்-அஃராஃபில் கூறப்பட்டுவிட்டது, எனவே அதனை இங்கே மீண்டும் கூறத் தேவையில்லை. இப்பண்புகளைப் புரிந்துகொள்வதில் 'ஸலஃபுகள்' (முன்னோர்கள்) பின்பற்றிய வழியே பாதுகாப்பானதாகும். வேதத்திலும் ஸுன்னாவிலும் இது குறித்து வந்துள்ளதை அதன் தன்மை பற்றி விவரிக்காமலும், தவறான விளக்கம் அளிக்காமலும், படைப்பினங்களுக்கு ஒப்பிடாமலும், நிராகரிக்காமலும் அல்லது படைப்புகளின் பண்புகளுடன் ஒப்பிடாமலும் அப்படியே ஏற்றுக் கொள்வதே அவர்களின் வழியாக இருந்தது. அல்லாஹ்வின் வசனத்தைப் பற்றி:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">السَّمَـوَتِ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمَا</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">تَحْتَ</span> <span class=\"quran-arabic-font text-success\">الثَّرَى</span><br />\r\n<br />\r\n(வானங்களில் உள்ளவை, பூமியில் உள்ளவை, அவ்விருவற்றுக்கும் இடையில் உள்ளவை மற்றும் நிலத்திற்கு அடியில் இருப்பவை அனைத்தும் அவனுக்கே உரியன.) இதன் பொருள் இவை யாவும் அவனது உடமைகள், அவனது அதிகாரத்தின் கீழ் உள்ளவை. அனைத்தும் அவனது கட்டுப்பாடு, நாட்டம், எண்ணம் மற்றும் தீர்ப்பின் கீழேயே இயங்குகின்றன. அவனே இவை அனைத்தையும் படைத்தான், அவனே அவற்றின் உரிமையாளன் மற்றும் இறைவன். அவனைத் தவிர வேறு உண்மையான கடவுள் இல்லை; அவனைத் தவிர வேறு இரட்சகனும் இல்லை. அல்லாஹ்வின் வசனத்தைப் பற்றி:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">تَحْتَ</span> <span class=\"quran-arabic-font text-success\">الثَّرَى</span><br />\r\n<br />\r\n(மண்ணுக்கு அடியில் உள்ளவை.) முஹம்மது பின் கஅப் கூறினார்கள்: \"இதன் பொருள் ஏழாவது பூமிக்கும் கீழே இருப்பவை என்பதாகும்.\" அல்லாஹ்வின் வசனத்தைப் பற்றி:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">تَجْهَرْ</span> <span class=\"quran-arabic-font text-success\">بِالْقَوْلِ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">السِّرَّ</span> <span class=\"quran-arabic-font text-success\">وَأَخْفَى</span><br />\r\n<br />\r\n(நீர் பேச்சை உரக்கச் சொன்னாலும் சரி, நிச்சயமாக அவன் இரகசியத்தையும், அதைவிட மறைவானதையும் அறிகிறான்.) அதாவது, இந்தக் குர்ஆனை அருளியவன், உயர்ந்த வானங்களையும் பூமியையும் படைத்தவன் ஆவான். அவன் இரகசியங்களையும் அதைவிட மறைவான விஷயங்களையும் அறிந்தவன். அல்லாஹ் கூறுவது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">أَنزَلَهُ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">السِّرَّ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">السَّمَـوَتِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">غَفُوراً</span> <span class=\"quran-arabic-font text-success\">رَّحِيماً</span><br />\r\n<br />\r\n(கூறுவீராக: \"வானங்கள் மற்றும் பூமியின் இரகசியத்தை அறிந்தவன் தான் இதை இறக்கினான். நிச்சயமாக, அவன் மிகவும் மன்னிப்பவன், மிக்க கருணையாளன்.\") <a href=\"qurandisp.php?sura=25&ayah=6\" class=\"link\">25:6</a> அலி பின் அபி தல்ஹா, இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">السِّرَّ</span> <span class=\"quran-arabic-font text-success\">وَأَخْفَى</span><br />\r\n<br />\r\n(நிச்சயமாக அவன் இரகசியத்தையும், அதைவிட மறைவானதையும் அறிகிறான்.) \"இரகசியம் என்பது மனிதன் தனக்குள் மறைத்து வைத்திருப்பதாகும், மற்றும்<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَخْفَى</span><br />\r\n<br />\r\n(அதைவிட மறைவானது) என்பது மனிதன் ஒரு செயலைச் செய்வதற்கு முன்பே அவனது எதிர்காலச் செயல்களைப் பற்றி அல்லாஹ் அறிந்திருப்பதாகும். அல்லாஹ் அவை அனைத்தையும் அறிவான். அவனுடைய அறிவு கடந்த காலத்தையும் எதிர்காலத்தையும் உள்ளடக்கியது; அது ஒரு முழுமையான அறிவு. படைப்பினங்கள் அனைத்தும் அவனது அறிவில் ஒரே ஒரு ஆன்மாவைப் போன்றதே. இதனையே அல்லாஹ் தனது வசனத்தில் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">خَلْقُكُمْ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">بَعْثُكُمْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">كَنَفْسٍ</span> <span class=\"quran-arabic-font text-success\">وَحِدَةٍ</span><br />\r\n<br />\r\n(உங்கள் அனைவரையும் படைப்பதும், உங்கள் அனைவரையும் உயிர்த்தெழச் செய்வதும் ஒரே ஒரு நபரைப் (படைப்பதைப்) போன்றதே.) <a href=\"qurandisp.php?sura=31&ayah=28\" class=\"link\">31:28</a> அல்லாஹ்வின் வசனத்தைப் பற்றி:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">لا</span> <span class=\"quran-arabic-font text-success\">إِلَـهَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">الْأَسْمَاءُ</span> <span class=\"quran-arabic-font text-success\">الْحُسْنَى</span><br />\r\n<br />\r\n(அல்லாஹ்! அவனைத் தவிர வேறு இறைவன் இல்லை! அவனுக்கே அழகிய பெயர்கள் உரியன.) இதன் பொருள்: (முஹம்மதே (ஸல்)!) உமக்கு இந்தக் குர்ஆனை அருளியவன் அல்லாஹ் ஆவான். அவனைத் தவிர வணக்கத்திற்குரியவன் யாருமில்லை. அவனே மிக அழகிய திருநாமங்களுக்கும் மிக உயர்ந்த பண்புகளுக்கும் உரிமையாளன். இது குறித்த ஹதீஸ் புகாரி மற்றும் முஸ்லிம் ஆகிய இரண்டு ஸஹீஹான நூல்களில், அபூ ஹுரைரா (ரழி) அவர்கள் அறிவிப்பதாக இடம்பெற்றுள்ளது. நபி (ஸல்) அவர்கள் கூறினார்கள்: \"நிச்சயமாக அல்லாஹ்விற்குத் தொண்ணூற்று ஒன்பது - ஒன்றைத் தவிர நூறு - திருநாமங்கள் இருக்கின்றன. அவற்றை (மனனமிட்டு) அறிபவர் சொர்க்கத்தில் நுழைவார்.\"<br />\r\n<br />","text":"மக்காவில் அருளப்பட்டது\n\r\n\n\r\nبِسْمِ اللَّهِ الرَّحْمَـنِ الرَّحِيمِ\n\r\n\n\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.\n\r\n\n\r\nகுர்ஆன் ஒரு நினைவூட்டல் மற்றும் அல்லாஹ்விடமிருந்து அருளப்பட்ட வஹீ (இறைச்செய்தி)\n\r\n\n\r\nசூரா அல்-பகரா அத்தியாயத்தின் தொடக்கத்தில் உள்ள தனித்தனி எழுத்துக்கள் (முக்கத்தாத்) குறித்து நாம் ஏற்கனவே விவாதித்துள்ளோம், எனவே அதன் விவாதத்தை இங்கே மீண்டும் கூறத் தேவையில்லை. அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nمَآ أَنَزَلْنَا عَلَيْكَ الْقُرْءَانَ لِتَشْقَى\n\r\n\n\r\n(நபியே!) உம்மைத் துன்பத்திற்குள்ளாக்குவதற்காக இந்தக் குர்ஆனை நாம் உம்மீது இறக்கவில்லை. ஜுவைபிர் அறிவிக்கிறார்கள், அத்-தஹ்ஹாக் கூறினார்கள்: \"அல்லாஹ் தனது தூதருக்கு (ஸல்) குர்ஆனை அருளியபோது, அவர்களும் அவர்களது தோழர்களும் (ரழி) அதைக் கடைப்பிடித்தார்கள். அப்போது குரைஷி இணைவைப்பாளர்கள், 'இந்தக் குர்ஆன் முஹம்மதை (ஸல்) வருத்தத்திற்குள்ளாக்கவே அருளப்பட்டது' என்று கூறினார்கள். எனவே அல்லாஹ் இதனை அருளினான்:\n\r\n\n\r\nطه - مَآ أَنَزَلْنَا عَلَيْكَ الْقُرْءَانَ لِتَشْقَى - إِلاَّ تَذْكِرَةً لِّمَن يَخْشَى\n\r\n\n\r\n(தா ஹா. உம்மைத் துன்புறுத்துவதற்காக இந்தக் குர்ஆனை நாம் உம்மீது இறக்கவில்லை. மாறாக, (அல்லாஹ்வுக்கு) அஞ்சுபவர்களுக்கு ஒரு நினைவூட்டலாகவே இதனை இறக்கினோம்.) அந்தப் பொய்யர்களின் கூற்றைப் போன்றதல்ல இது. மாறாக, அல்லாஹ் யாருக்கு அறிவை வழங்குகிறானோ, அவருக்கு அபரிமிதமான நன்மையை அவன் நாடுகிறான் என்பதே இதன் பொருளாகும். இது இப்னு மஸ்ஊத் (ரழி) அவர்கள் அறிவிக்க, புகாரி மற்றும் முஸ்லிம் ஆகிய இரு ஆதாரப்பூர்வமான நூல்களில் (ஸஹீஹ்களில்) இடம்பெற்றுள்ள பின்வரும் ஹதீஸைப் போன்றதாகும். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«مَنْ يُرِدِ اللهُ بِهِ خَيْرًا يُفَقِّهْهُ فِي الدِّين»\n\r\n\n\r\n\"யாருக்கு அல்லாஹ் நன்மையை நாடுகிறானோ, அவருக்கு மார்க்கத்தில் ஆழ்ந்த ஞானத்தை வழங்குகிறான்.\" முஜாஹித் அவர்கள் அல்லாஹ்வின் வசனத்திற்குப் பின்வருமாறு விளக்கமளித்தார்கள்:\n\r\n\n\r\nمَآ أَنَزَلْنَا عَلَيْكَ الْقُرْءَانَ لِتَشْقَى\n\r\n\n\r\n(உம்மைத் துன்புறுத்துவதற்காக இந்தக் குர்ஆனை நாம் உம்மீது இறக்கவில்லை,) \"இது அவனது மற்றொரு வசனத்தைப் போன்றது: 'ஆகவே, குர்ஆனிலிருந்து உங்களுக்கு எளிதானதை ஓதுங்கள்.' (73:20). ஏனெனில், (ஆரம்ப காலத்தில்) மக்கள் தொழுகையில் சோர்வடையும் போது பிடித்துக் கொள்வதற்காகத் தங்கள் மார்புக்கு நேராகக் கயிறுகளைத் தொங்கவிட்டுக் கொண்டிருந்தார்கள்.\" கதாதா கூறினார்கள்:\n\r\n\n\r\nمَآ أَنَزَلْنَا عَلَيْكَ الْقُرْءَانَ لِتَشْقَى\n\r\n\n\r\n(உம்மைத் துன்புறுத்துவதற்காக இந்தக் குர்ஆனை நாம் உம்மீது இறக்கவில்லை,) \"இல்லை, அல்லாஹ்வின் மீது ஆணையாக! அல்லாஹ் இதனை ஒரு சிரமமான விஷயமாக ஆக்கவில்லை. மாறாக, இதனை ஒரு கருணையாகவும், பேரொளியாகவும், சொர்க்கத்திற்கு வழிகாட்டியாகவும் அவன் ஆக்கியுள்ளான்.\" அல்லாஹ் கூறினான்:\n\r\n\n\r\nإِلاَّ تَذْكِرَةً لِّمَن يَخْشَى\n\r\n\n\r\n(மாறாக, (அல்லாஹ்வுக்கு) அஞ்சுபவர்களுக்கு ஒரு நினைவூட்டலாகவே இதனை இறக்கினோம்.)\n\r\n\n\r\nஅல்லாஹ் தனது வேதத்தை அருளி, தனது தூதரைத் (ஸல்) தனது அடியார்களுக்கு ஒரு கருணையாக அனுப்பினான். சிந்திக்கும் மனிதன் இதன் மூலம் படிப்பினை பெறுவதற்காகவே இவ்வாறு செய்தான். ஒரு மனிதன் அல்லாஹ்வின் வேதத்தைச் செவியேற்கும்போது அதன் மூலம் பயனடைவான். இது அல்லாஹ் எதை அனுமதிக்கிறான், எதைத் தடுக்கிறான் என்பதை விளக்கியுள்ள ஒரு நினைவூட்டலாகும். அவனது வசனம்:\n\r\n\n\r\nتَنزِيلاً مِّمَّنْ خَلَق الْأَرْضَ وَالسَّمَـوَتِ الْعُلَى\n\r\n\n\r\n(இது) பூமியையும் உயர்ந்த வானங்களையும் படைத்தவனிடமிருந்து (அல்லாஹ்விடமிருந்து) அருளப்பட்ட வஹீ (இறைச்செய்தி) ஆகும். இதன் பொருள்: \"முஹம்மதே (ஸல்)! உமக்கு வந்துள்ள இந்தக் குர்ஆன் உமது இறைவனிடமிருந்து அருளப்பட்ட வஹீ (இறைச்செய்தி) ஆகும். அவனே அனைத்திற்கும் அதிபதியும் அரசனும் ஆவான். தான் நாடுவனவற்றைச் செய்ய அவன் பேராற்றல் மிக்கவன். அவனே ஆழமான பகுதிகளையும் அடர்த்தியான நிலப்பரப்பையும் கொண்ட பூமியைப் படைத்தான். மிக உயர்ந்த வானங்களையும் அவற்றின் நுட்பங்களுடன் படைத்தான்.\" ஒரு ஹதீஸில் (இதனைத் திர்மிதி உள்ளிட்டோர் ஆதாரப்பூர்வமானது எனக் குறிப்பிட்டுள்ளனர்) இவ்வாறு வந்துள்ளது: ஒவ்வொரு வானத்தின் தடிமனும் ஐநூறு ஆண்டுப் பயண தூரமாகும்; ஒரு வானத்திற்கும் அடுத்த வானத்திற்கும் இடையிலான தூரமும் ஐநூறு ஆண்டுகளாகும். அல்லாஹ்வின் வசனத்தைப் பற்றி:\n\r\n\n\r\nالرَّحْمَـنُ عَلَى الْعَرْشِ اسْتَوَى\n\r\n\n\r\n(அளவற்ற அருளாளன் அர்ஷின் மீது இஸ்தவா (உயர்ந்து) இருக்கிறான்.) இது தொடர்பான விளக்கம் ஏற்கனவே சூரா அல்-அஃராஃபில் கூறப்பட்டுவிட்டது, எனவே அதனை இங்கே மீண்டும் கூறத் தேவையில்லை. இப்பண்புகளைப் புரிந்துகொள்வதில் 'ஸலஃபுகள்' (முன்னோர்கள்) பின்பற்றிய வழியே பாதுகாப்பானதாகும். வேதத்திலும் ஸுன்னாவிலும் இது குறித்து வந்துள்ளதை அதன் தன்மை பற்றி விவரிக்காமலும், தவறான விளக்கம் அளிக்காமலும், படைப்பினங்களுக்கு ஒப்பிடாமலும், நிராகரிக்காமலும் அல்லது படைப்புகளின் பண்புகளுடன் ஒப்பிடாமலும் அப்படியே ஏற்றுக் கொள்வதே அவர்களின் வழியாக இருந்தது. அல்லாஹ்வின் வசனத்தைப் பற்றி:\n\r\n\n\r\nلَهُ مَا فِي السَّمَـوَتِ وَمَا فِي الْأَرْضِ وَمَا بَيْنَهُمَا وَمَا تَحْتَ الثَّرَى\n\r\n\n\r\n(வானங்களில் உள்ளவை, பூமியில் உள்ளவை, அவ்விருவற்றுக்கும் இடையில் உள்ளவை மற்றும் நிலத்திற்கு அடியில் இருப்பவை அனைத்தும் அவனுக்கே உரியன.) இதன் பொருள் இவை யாவும் அவனது உடமைகள், அவனது அதிகாரத்தின் கீழ் உள்ளவை. அனைத்தும் அவனது கட்டுப்பாடு, நாட்டம், எண்ணம் மற்றும் தீர்ப்பின் கீழேயே இயங்குகின்றன. அவனே இவை அனைத்தையும் படைத்தான், அவனே அவற்றின் உரிமையாளன் மற்றும் இறைவன். அவனைத் தவிர வேறு உண்மையான கடவுள் இல்லை; அவனைத் தவிர வேறு இரட்சகனும் இல்லை. அல்லாஹ்வின் வசனத்தைப் பற்றி:\n\r\n\n\r\nوَمَا تَحْتَ الثَّرَى\n\r\n\n\r\n(மண்ணுக்கு அடியில் உள்ளவை.) முஹம்மது பின் கஅப் கூறினார்கள்: \"இதன் பொருள் ஏழாவது பூமிக்கும் கீழே இருப்பவை என்பதாகும்.\" அல்லாஹ்வின் வசனத்தைப் பற்றி:\n\r\n\n\r\nوَإِن تَجْهَرْ بِالْقَوْلِ فَإِنَّهُ يَعْلَمُ السِّرَّ وَأَخْفَى\n\r\n\n\r\n(நீர் பேச்சை உரக்கச் சொன்னாலும் சரி, நிச்சயமாக அவன் இரகசியத்தையும், அதைவிட மறைவானதையும் அறிகிறான்.) அதாவது, இந்தக் குர்ஆனை அருளியவன், உயர்ந்த வானங்களையும் பூமியையும் படைத்தவன் ஆவான். அவன் இரகசியங்களையும் அதைவிட மறைவான விஷயங்களையும் அறிந்தவன். அல்லாஹ் கூறுவது போல:\n\r\n\n\r\nقُلْ أَنزَلَهُ الَّذِى يَعْلَمُ السِّرَّ فِى السَّمَـوَتِ وَالْأَرْضِ إِنَّهُ كَانَ غَفُوراً رَّحِيماً\n\r\n\n\r\n(கூறுவீராக: \"வானங்கள் மற்றும் பூமியின் இரகசியத்தை அறிந்தவன் தான் இதை இறக்கினான். நிச்சயமாக, அவன் மிகவும் மன்னிப்பவன், மிக்க கருணையாளன்.\") 25:6 அலி பின் அபி தல்ஹா, இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்:\n\r\n\n\r\nيَعْلَمُ السِّرَّ وَأَخْفَى\n\r\n\n\r\n(நிச்சயமாக அவன் இரகசியத்தையும், அதைவிட மறைவானதையும் அறிகிறான்.) \"இரகசியம் என்பது மனிதன் தனக்குள் மறைத்து வைத்திருப்பதாகும், மற்றும்\n\r\n\n\r\nوَأَخْفَى\n\r\n\n\r\n(அதைவிட மறைவானது) என்பது மனிதன் ஒரு செயலைச் செய்வதற்கு முன்பே அவனது எதிர்காலச் செயல்களைப் பற்றி அல்லாஹ் அறிந்திருப்பதாகும். அல்லாஹ் அவை அனைத்தையும் அறிவான். அவனுடைய அறிவு கடந்த காலத்தையும் எதிர்காலத்தையும் உள்ளடக்கியது; அது ஒரு முழுமையான அறிவு. படைப்பினங்கள் அனைத்தும் அவனது அறிவில் ஒரே ஒரு ஆன்மாவைப் போன்றதே. இதனையே அல்லாஹ் தனது வசனத்தில் கூறுகிறான்:\n\r\n\n\r\nمَّا خَلْقُكُمْ وَلاَ بَعْثُكُمْ إِلاَّ كَنَفْسٍ وَحِدَةٍ\n\r\n\n\r\n(உங்கள் அனைவரையும் படைப்பதும், உங்கள் அனைவரையும் உயிர்த்தெழச் செய்வதும் ஒரே ஒரு நபரைப் (படைப்பதைப்) போன்றதே.) 31:28 அல்லாஹ்வின் வசனத்தைப் பற்றி:\n\r\n\n\r\nاللَّهُ لا إِلَـهَ إِلاَّ هُوَ لَهُ الْأَسْمَاءُ الْحُسْنَى\n\r\n\n\r\n(அல்லாஹ்! அவனைத் தவிர வேறு இறைவன் இல்லை! அவனுக்கே அழகிய பெயர்கள் உரியன.) இதன் பொருள்: (முஹம்மதே (ஸல்)!) உமக்கு இந்தக் குர்ஆனை அருளியவன் அல்லாஹ் ஆவான். அவனைத் தவிர வணக்கத்திற்குரியவன் யாருமில்லை. அவனே மிக அழகிய திருநாமங்களுக்கும் மிக உயர்ந்த பண்புகளுக்கும் உரிமையாளன். இது குறித்த ஹதீஸ் புகாரி மற்றும் முஸ்லிம் ஆகிய இரண்டு ஸஹீஹான நூல்களில், அபூ ஹுரைரா (ரழி) அவர்கள் அறிவிப்பதாக இடம்பெற்றுள்ளது. நபி (ஸல்) அவர்கள் கூறினார்கள்: \"நிச்சயமாக அல்லாஹ்விற்குத் தொண்ணூற்று ஒன்பது - ஒன்றைத் தவிர நூறு - திருநாமங்கள் இருக்கின்றன. அவற்றை (மனனமிட்டு) அறிபவர் சொர்க்கத்தில் நுழைவார்.\""},"9":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=10\" class=\"link\">20:10</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:10 ஐ பார்க்கவும்"},"10":{"html":"<strong>மூஸா (அலை) அவர்களின் தூதுத்துவம் குறித்த விளக்கம்</strong><br />\r\n<br />\r\nஇவ்விடத்திலிருந்து அல்லாஹ், மூஸா (அலை) அவர்களின் வரலாற்றையும், அவர்களுக்கு வஹீ (இறைச்செய்தி) அருளப்படத் தொடங்கிய விதம் மற்றும் அல்லாஹ் அவர்களுடன் நேரடியாகப் பேசியது குறித்தும் கூறத் தொடங்குகிறான். ஆடுகளை மேய்ப்பது தொடர்பாக அவருக்கும் அவரது மாமனாருக்கும் இடையே ஏற்பட்ட ஒப்பந்தத்தின் காலத்தை மூஸா (அலை) அவர்கள் முடித்த பிறகு இது நிகழ்ந்தது. அவர்கள் தம் குடும்பத்தாருடன் பயணம் செய்து கொண்டிருந்தார்கள். பத்து ஆண்டுகளுக்கும் மேலாகப் பிரிந்திருந்த எகிப்து தேசத்தை நோக்கியே அவர்கள் சென்றுகொண்டிருந்தார்கள் என்று கூறப்படுகிறது. அவர்களுடன் அவர்களது மனைவியும் இருந்தார்கள். கடும் குளிரான ஒரு பனிக்கால இரவில் அவர்கள் வழியில் திசைமாறிப் போய்விட்டார்கள். எனவே, பனிப்பொழிவு, ஆலங்கட்டி மழை, அடர்ந்த மேகங்கள், இருள் மற்றும் மூடுபனி சூழ்ந்திருந்த மலைகளுக்கும் கணவாய்களுக்கும் இடையே அவர்கள் முகாமிட்டார்கள். வழக்கம்போல நெருப்பை உண்டாக்குவதற்காகத் தம்மிடமிருந்த தீமூட்டும் கருவியைக் கொண்டு தீப்பற்ற வைக்க முயன்றார்கள். ஆனால், அது எரியவில்லை; தீப்பொறிகளைக் கூட உண்டாக்கவில்லை. அவர்கள் இந்த நிலையில் இருந்தபோது, மலையின் ஒரு பக்கத்தில் ஒரு நெருப்பைக் கண்டார்கள். அவர்கள் இருந்த இடத்திற்கு வலது பக்கமாக மலையில் ஒரு நெருப்புப் பிரகாசிப்பது அவர்களுக்குத் தெரிந்தது. உடனே அவர்கள் தம் குடும்பத்தாரிடம் நற்செய்தி அறிவிப்பவர்களாகக் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾إِنِّي</span> <span class=\"quran-arabic-font text-success\">آنَسْتُ</span> <span class=\"quran-arabic-font text-success\">نَارًا</span> <span class=\"quran-arabic-font text-success\">لَّعَلِّي</span> <span class=\"quran-arabic-font text-success\">آتِيكُم</span> <span class=\"quran-arabic-font text-success\">مِّنْهَا</span> <span class=\"quran-arabic-font text-success\">بِقَبَسٍ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக நான் ஒரு நெருப்பைக் காண்கிறேன்; அதிலிருந்து எரியும் ஒரு கொள்ளிக்கட்டையை நான் உங்களிடம் கொண்டு வரக்கூடும்.) இதன் பொருள் நெருப்பிலிருந்து ஒரு சுடரை எடுத்து வருவது என்பதாகும். வேறொரு வசனத்தில் அல்லாஹ் <span class=\"quran-arabic-font text-success\">﴾أَوْ</span> <span class=\"quran-arabic-font text-success\">جَذْوَةٍ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">النَّارِ﴿</span> (அல்லது நெருப்பின் ஒரு தணல் - <a href=\"qurandisp.php?sura=28&ayah=29\" class=\"link\">28:29</a>) என்று கூறுகிறான். இது தணலாக எரியும் ஒரு கரியாகும். <span class=\"quran-arabic-font text-success\">﴾لَعَلَّكُمْ</span> <span class=\"quran-arabic-font text-success\">تَصْطَلُونَ﴿</span><br />\r\n<br />\r\n(அதன் மூலம் நீங்கள் குளிர்காயலாம் - <a href=\"qurandisp.php?sura=28&ayah=29\" class=\"link\">28:29</a>) என்பது, அக்காலத்தில் கடும் குளிர் நிலவியதை நிரூபிக்கிறது. <span class=\"quran-arabic-font text-success\">﴾بِقَبَسٍ﴿</span><br />\r\n<br />\r\n(எரியும் கொள்ளிக்கட்டை) என்ற அவர்களின் கூற்று, சூழல் இருட்டாக இருந்ததை உணர்த்துகிறது. மேலும், <span class=\"quran-arabic-font text-success\">﴾أَوْ</span> <span class=\"quran-arabic-font text-success\">أَجِدُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">هُدًى﴿</span><br />\r\n<br />\r\n(அல்லது அந்த நெருப்பின் அருகே ஏதேனும் வழிகாட்டியைக் காண்பேன்) என்ற அவர்களின் கூற்று, தமக்கு வழிகாட்டக்கூடிய ஒருவரை அவர்கள் எதிர்பார்த்தார்கள் என்பதைக் குறிக்கிறது. அவர்கள் வழிதவறிவிட்டார்கள் என்பதற்கு இதுவே சான்றாகும். அத்-தவ்ரீ அவர்கள், அபூ ஸஈத் அல்-அவார் வழியாக, இக்ரிமாவிடமிருந்து, இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்: <span class=\"quran-arabic-font text-success\">﴾أَوْ</span> <span class=\"quran-arabic-font text-success\">أَجِدُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">هُدًى﴿</span><br />\r\n<br />\r\n(அல்லது அந்த நெருப்பின் அருகே ஏதேனும் வழிகாட்டியைக் காண்பேன்) என்பதற்கு, \"எனக்கு வழிகாட்டக்கூடிய ஒருவரை அங்கே காண்பேன்\" என்று இப்னு அப்பாஸ் (ரழி) அவர்கள் பொருள் கூறினார்கள். அவர்கள் குளிரில் வாடிக்கொண்டிருந்தார்கள், மேலும் வழியையும் தவறவிட்டிருந்தார்கள். அப்போது நெருப்பைக் கண்ட மூஸா (அலை) அவர்கள், \"ஒன்று நமக்கு வழிகாட்டக்கூடிய ஒருவரை அங்கே காண்பேன், அல்லது குறைந்தபட்சம் நீங்கள் நெருப்பு மூட்டுவதற்குத் தேவையான ஒரு கொள்ளிக்கட்டையையாவது கொண்டு வருவேன்\" எனக் கூறினார்கள்.<br />\r\n<br />\r\n<br />\r\n<br />","text":"மூஸா (அலை) அவர்களின் தூதுத்துவம் குறித்த விளக்கம்\n\r\n\n\r\nஇவ்விடத்திலிருந்து அல்லாஹ், மூஸா (அலை) அவர்களின் வரலாற்றையும், அவர்களுக்கு வஹீ (இறைச்செய்தி) அருளப்படத் தொடங்கிய விதம் மற்றும் அல்லாஹ் அவர்களுடன் நேரடியாகப் பேசியது குறித்தும் கூறத் தொடங்குகிறான். ஆடுகளை மேய்ப்பது தொடர்பாக அவருக்கும் அவரது மாமனாருக்கும் இடையே ஏற்பட்ட ஒப்பந்தத்தின் காலத்தை மூஸா (அலை) அவர்கள் முடித்த பிறகு இது நிகழ்ந்தது. அவர்கள் தம் குடும்பத்தாருடன் பயணம் செய்து கொண்டிருந்தார்கள். பத்து ஆண்டுகளுக்கும் மேலாகப் பிரிந்திருந்த எகிப்து தேசத்தை நோக்கியே அவர்கள் சென்றுகொண்டிருந்தார்கள் என்று கூறப்படுகிறது. அவர்களுடன் அவர்களது மனைவியும் இருந்தார்கள். கடும் குளிரான ஒரு பனிக்கால இரவில் அவர்கள் வழியில் திசைமாறிப் போய்விட்டார்கள். எனவே, பனிப்பொழிவு, ஆலங்கட்டி மழை, அடர்ந்த மேகங்கள், இருள் மற்றும் மூடுபனி சூழ்ந்திருந்த மலைகளுக்கும் கணவாய்களுக்கும் இடையே அவர்கள் முகாமிட்டார்கள். வழக்கம்போல நெருப்பை உண்டாக்குவதற்காகத் தம்மிடமிருந்த தீமூட்டும் கருவியைக் கொண்டு தீப்பற்ற வைக்க முயன்றார்கள். ஆனால், அது எரியவில்லை; தீப்பொறிகளைக் கூட உண்டாக்கவில்லை. அவர்கள் இந்த நிலையில் இருந்தபோது, மலையின் ஒரு பக்கத்தில் ஒரு நெருப்பைக் கண்டார்கள். அவர்கள் இருந்த இடத்திற்கு வலது பக்கமாக மலையில் ஒரு நெருப்புப் பிரகாசிப்பது அவர்களுக்குத் தெரிந்தது. உடனே அவர்கள் தம் குடும்பத்தாரிடம் நற்செய்தி அறிவிப்பவர்களாகக் கூறினார்கள்: ﴾إِنِّي آنَسْتُ نَارًا لَّعَلِّي آتِيكُم مِّنْهَا بِقَبَسٍ﴿\n\r\n\n\r\n(நிச்சயமாக நான் ஒரு நெருப்பைக் காண்கிறேன்; அதிலிருந்து எரியும் ஒரு கொள்ளிக்கட்டையை நான் உங்களிடம் கொண்டு வரக்கூடும்.) இதன் பொருள் நெருப்பிலிருந்து ஒரு சுடரை எடுத்து வருவது என்பதாகும். வேறொரு வசனத்தில் அல்லாஹ் ﴾أَوْ جَذْوَةٍ مِّنَ النَّارِ﴿ (அல்லது நெருப்பின் ஒரு தணல் - 28:29) என்று கூறுகிறான். இது தணலாக எரியும் ஒரு கரியாகும். ﴾لَعَلَّكُمْ تَصْطَلُونَ﴿\n\r\n\n\r\n(அதன் மூலம் நீங்கள் குளிர்காயலாம் - 28:29) என்பது, அக்காலத்தில் கடும் குளிர் நிலவியதை நிரூபிக்கிறது. ﴾بِقَبَسٍ﴿\n\r\n\n\r\n(எரியும் கொள்ளிக்கட்டை) என்ற அவர்களின் கூற்று, சூழல் இருட்டாக இருந்ததை உணர்த்துகிறது. மேலும், ﴾أَوْ أَجِدُ عَلَى النَّارِ هُدًى﴿\n\r\n\n\r\n(அல்லது அந்த நெருப்பின் அருகே ஏதேனும் வழிகாட்டியைக் காண்பேன்) என்ற அவர்களின் கூற்று, தமக்கு வழிகாட்டக்கூடிய ஒருவரை அவர்கள் எதிர்பார்த்தார்கள் என்பதைக் குறிக்கிறது. அவர்கள் வழிதவறிவிட்டார்கள் என்பதற்கு இதுவே சான்றாகும். அத்-தவ்ரீ அவர்கள், அபூ ஸஈத் அல்-அவார் வழியாக, இக்ரிமாவிடமிருந்து, இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்: ﴾أَوْ أَجِدُ عَلَى النَّارِ هُدًى﴿\n\r\n\n\r\n(அல்லது அந்த நெருப்பின் அருகே ஏதேனும் வழிகாட்டியைக் காண்பேன்) என்பதற்கு, \"எனக்கு வழிகாட்டக்கூடிய ஒருவரை அங்கே காண்பேன்\" என்று இப்னு அப்பாஸ் (ரழி) அவர்கள் பொருள் கூறினார்கள். அவர்கள் குளிரில் வாடிக்கொண்டிருந்தார்கள், மேலும் வழியையும் தவறவிட்டிருந்தார்கள். அப்போது நெருப்பைக் கண்ட மூஸா (அலை) அவர்கள், \"ஒன்று நமக்கு வழிகாட்டக்கூடிய ஒருவரை அங்கே காண்பேன், அல்லது குறைந்தபட்சம் நீங்கள் நெருப்பு மூட்டுவதற்குத் தேவையான ஒரு கொள்ளிக்கட்டையையாவது கொண்டு வருவேன்\" எனக் கூறினார்கள்."},"11":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=16\" class=\"link\">20:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:16 ஐ பார்க்கவும்"},"12":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=16\" class=\"link\">20:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:16 ஐ பார்க்கவும்"},"13":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=16\" class=\"link\">20:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:16 ஐ பார்க்கவும்"},"14":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=16\" class=\"link\">20:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:16 ஐ பார்க்கவும்"},"15":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=16\" class=\"link\">20:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:16 ஐ பார்க்கவும்"},"16":{"html":"<strong>மூஸா (அலை) அவர்களுக்கு அருளப்பட்ட முதல் வஹீ (இறைச்செய்தி)</strong><br />\r\n<br />\r\nஉயர்ந்தோன் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَلَمَّآ</span> <span class=\"quran-arabic-font text-success\">أَتَاهَا</span><br />\r\n<br />\r\n(அவர் அதனிடம் வந்தபோது,) அதாவது மூஸா (அலை) அவர்கள் நெருப்பினை நெருங்கியபோது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">نُودِيَ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span><br />\r\n<br />\r\n(அவர் பெயர் சொல்லி அழைக்கப்பட்‌டார்: \"மூஸாவே!\") மற்றொரு வசனத்தில் அல்லாஹ் பின்வருமாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">نُودِىَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">شَاطِىءِ</span> <span class=\"quran-arabic-font text-success\">الْوَادِى</span> <span class=\"quran-arabic-font text-success\">الأَيْمَنِ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْبُقْعَةِ</span> <span class=\"quran-arabic-font text-success\">الْمُبَارَكَةِ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الشَّجَرَةِ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span> <span class=\"quran-arabic-font text-success\">إِنِّى</span> <span class=\"quran-arabic-font text-success\">أَنَا</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span><br />\r\n<br />\r\n(அந்தப் பள்ளத்தாக்கின் வலது பக்கத்திலுள்ள பாக்கியம் பெற்ற இடத்தில் இருந்த ஒரு மரத்திலிருந்து அவர் அழைக்கப்பட்டார்: \"மூஸாவே! நிச்சயமாக நானே அல்லாஹ்!\") <a href=\"qurandisp.php?sura=28&ayah=30\" class=\"link\">28:30</a>. இருப்பினும், இங்கு அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنِّى</span> <span class=\"quran-arabic-font text-success\">أَنَاْ</span> <span class=\"quran-arabic-font text-success\">رَبُّكَ</span><br />\r\n<br />\r\n(நிச்சயமாக நானே உன்னுடைய இறைவன்!) அதாவது, \"உன்னிடம் பேசுபவனும், உரையாடுபவனும் நானே\" என்று பொருள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَاخْلَعْ</span> <span class=\"quran-arabic-font text-success\">نَعْلَيْكَ</span><br />\r\n<br />\r\n(ஆகவே, உன்னுடைய காலணிகளைக் கழற்றிவிடு;) அலீ இப்னு அபீ தாலிப் (ரழி), அபூ தர் (ரழி), அபூ அய்யூப் (ரழி) மற்றும் ஸலஃபுகள் (முன்னோர்கள்) சிலர் கூறினார்கள்: \"அவரது காலணிகள் அறுக்கப்படாத (அறுத்துப் பலியிடப்படாத) கழுதையின் தோலினால் செய்யப்பட்டிருந்தன.\" மேலும், அந்தப் புனிதமான இடத்திற்கு மரியாதை செலுத்தும் விதமாகவே காலணிகளைக் கழற்றுமாறு அவர் (அலை) பணிக்கப்பட்டார் என்றும் கூறப்படுகிறது. அல்லாஹ்வின் கூற்றைப் பொறுத்தவரை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">طُوًى</span><br />\r\n<br />\r\n(துவா) அலி இப்னு அபீ தல்ஹா (ரழி) அவர்கள், இப்னு அப்பாஸ் (ரழி) அவர்கள் \"இது அந்தப் பள்ளத்தாக்கின் பெயர்\" என்று கூறியதாக அறிவிக்கிறார்கள். மற்றவர்களும் இதையே கூறியுள்ளனர். இக்கதைக்கு கூடுதல் விளக்கம் அளிப்பதற்காகவே இது குறிப்பிடப்பட்டுள்ளது. இது ஒரு உருவகப் பேச்சு என்றும், தனது பாதங்களைக் கீழே வைப்பதைக் குறிக்கும் கட்டளையிலிருந்து இது பிறந்தது என்றும் கூறப்படுகிறது. 'இரட்டிப்புப் புனிதமானது' என்றும், 'துவா' என்பது திரும்பத் திரும்பக் கிடைக்கும் அருட்கொடைகளைக் கொண்டது என்றும் இதற்குப் பொருள் கூறப்பட்டுள்ளது. இருப்பினும், முதல் கருத்தே மிகவும் சரியானது. இது அல்லாஹ்வின் பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">نَادَاهُ</span> <span class=\"quran-arabic-font text-success\">رَبُّهُ</span> <span class=\"quran-arabic-font text-success\">بِالْوَادِ</span> <span class=\"quran-arabic-font text-success\">الْمُقَدَّسِ</span> <span class=\"quran-arabic-font text-success\">طُوًى</span><br />\r\n<br />\r\n(துவா எனும் புனிதப் பள்ளத்தாக்கில் அவருடைய இறைவன் அவரை அழைத்தபோது.) <a href=\"qurandisp.php?sura=79&ayah=16\" class=\"link\">79:16</a>. அல்லாஹ்வின் கூற்றான:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَنَا</span> <span class=\"quran-arabic-font text-success\">اخْتَرْتُكَ</span><br />\r\n<br />\r\n(மேலும், நான் உன்னைத் தேர்ந்தெடுத்துக் கொண்டேன்.) என்பது அவனது மற்றொரு கூற்றைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنِّي</span> <span class=\"quran-arabic-font text-success\">اصْطَفَيْتُكَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">النَّاسِ</span> <span class=\"quran-arabic-font text-success\">بِرِسَالَاتِي</span> <span class=\"quran-arabic-font text-success\">وَبِكَلَامِي</span><br />\r\n<br />\r\n(நிச்சயமாக எனது தூதுத்துவத்தைக் கொண்டும், நான் (உன்னுடன்) பேசுவதைக் கொண்டும் மனிதர்களில் உன்னை நான் தேர்ந்தெடுத்துக் கொண்டேன்.) <a href=\"qurandisp.php?sura=7&ayah=144\" class=\"link\">7:144</a>. இதன் பொருள், அந்தக் காலத்தில் வாழ்ந்த அனைத்து மனிதர்களுக்கும் மேலாக என்பதாகும். அல்லாஹ், \"மூஸாவே! அனைத்து மக்களையும் விடுத்து உன்னுடன் நேரடியாகப் பேச நான் ஏன் தேர்ந்தெடுத்தேன் என்று உனக்குத் தெரியுமா?\" என்று கேட்டான்; அதற்கு மூஸா (அலை) அவர்கள் \"இல்லை\" எனப் பதிலளித்தார்கள். அப்போது அல்லாஹ், \"நீ உன்னைத் தாழ்த்திக் கொண்டது போல வேறெவரும் என்னிடம் தங்களைத் தாழ்த்திக் கொண்டதில்லை என்பதால்தான் (உன்னைத் தேர்ந்தெடுத்தேன்)\" எனக் கூறினான் என்றும் சொல்லப்படுகிறது. அல்லாஹ்வின் கூற்றைப் பொறுத்தவரை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَاسْتَمِعْ</span> <span class=\"quran-arabic-font text-success\">لِمَا</span> <span class=\"quran-arabic-font text-success\">يُوحَى</span><br />\r\n<br />\r\n(எனவே, வஹீ (இறைச்செய்தி)யாக அருளப்படுவதைச் செவிமடுப்பாயாக.) \"இப்போது நான் உன்னிடம் கூறுவதையும், உனக்கு வஹீயாக அறிவிப்பதையும் கூர்ந்து கவனி\" என்று பொருள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّنِى</span> <span class=\"quran-arabic-font text-success\">أَنَا</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">لا</span> <span class=\"quran-arabic-font text-success\">إِلَـهَ</span> <span class=\"quran-arabic-font text-success\">إِلا</span> <span class=\"quran-arabic-font text-success\">أَنَاْ</span><br />\r\n<br />\r\n(நிச்சயமாக, நானே அல்லாஹ்! என்னைத் தவிர வேறு இறைவன் இல்லை,) வயது வந்த, பொறுப்புள்ள ஒவ்வொருவர் மீதும் உள்ள முதல் கடமை இதுதான்; வணக்கத்திற்குரிய இறைவன் அல்லாஹ்வைத் தவிர வேறு யாருமில்லை என்பதையும், அவனுக்கு இணை எவரும் இல்லை என்பதையும் அவர்கள் அறிந்துகொள்ள வேண்டும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَاعْبُدْنِى</span><br />\r\n<br />\r\n(ஆகவே, என்னையே வணங்கு,) இதன் பொருள், \"வணக்கத்திற்கு என்னை மட்டுமே தனிப்படுத்து, எனக்கு எதனையும் இணையாக்காமல் எனது வணக்கத்தை நிலைநிறுத்து.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَقِمِ</span> <span class=\"quran-arabic-font text-success\">الصَّلَوةَ</span> <span class=\"quran-arabic-font text-success\">لِذِكْرِى</span><br />\r\n<br />\r\n(மேலும், என்னை நினைவு கூர்வதற்காகத் தொழுகையை நிலைநாட்டு.) இதன் பொருள், \"என்னை நினைவுகூர்வதற்காகத் தொழு\" என்பதாகும். \"என்னை நீ எப்போது நினைத்தாலும் தொழுகையை நிலைநாட்டு\" என்றும் இதற்குப் பொருள் கூறப்பட்டுள்ளது. இந்த இரண்டாவது கருத்திற்கு ஆதரவாக, இமாம் அஹ்மத் அவர்கள் அனஸ் (ரழி) வாயிலாகப் பதிவு செய்துள்ள ஒரு ஹதீஸ் உள்ளது: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">رَقَدَ</span> <span class=\"quran-arabic-font text-success\">أَحَدُكُمْ</span> <span class=\"quran-arabic-font text-success\">عَنِ</span> <span class=\"quran-arabic-font text-success\">الصَّلَاةِ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">غَفَلَ</span> <span class=\"quran-arabic-font text-success\">عَنْهَا،</span> <span class=\"quran-arabic-font text-success\">فَلْيُصَلِّهَا</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">ذَكَرَهَا،</span> <span class=\"quran-arabic-font text-success\">فَإِنَّ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">تَعَالى</span> <span class=\"quran-arabic-font text-success\">قَالَ</span>:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَقِمِ</span> <span class=\"quran-arabic-font text-success\">الصَّلَوةَ</span> <span class=\"quran-arabic-font text-success\">لِذِكْرِى</span>»<br />\r\n<br />\r\n(உங்களில் ஒருவர் தொழுகையை விட்டுவிட்டு உறங்கிவிட்டாலோ அல்லது அதனை மறந்தாலோ, அவர் நினைவுக்கு வரும்போது அதனைத் தொழட்டும். ஏனெனில், நிச்சயமாக அல்லாஹ் கூறுகிறான்: \"என்னை நினைவுகூர்வதற்காகத் தொழுகையை நிலைநாட்டு.\") புஹாரி, முஸ்லிம் ஆகிய இரு நூல்களிலும் அனஸ் (ரழி) அவர்கள் மூலமாக அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியதாகப் பதிவாகியுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">نَامَ</span> <span class=\"quran-arabic-font text-success\">عَنْ</span> <span class=\"quran-arabic-font text-success\">صَلَاةٍ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">نَسِيَهَا</span> <span class=\"quran-arabic-font text-success\">فَكَفَّارَتُهَا</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يُصَلِّيَهَا</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">ذَكَرَهَا،</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">كَفَّارَةَ</span> <span class=\"quran-arabic-font text-success\">لَهَا</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">ذَلِك</span>»<br />\r\n<br />\r\n(யார் ஒரு தொழுகையை விட்டுவிட்டுத் தூங்கிவிட்டாரோ அல்லது அதனை மறந்துவிட்டாரோ, அவர் நினைவுக்கு வரும்போது அதனைத் தொழுவதே அதற்கான பரிகாரமாகும். அதனைத் தவிர வேறு பரிகாரம் அதற்கு இல்லை.) அல்லாஹ்வின் கூற்றான:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">السَّاعَةَ</span> <span class=\"quran-arabic-font text-success\">ءَاتِيَةٌ</span><br />\r\n<br />\r\n(நிச்சயமாக மறுமை நேரம் வரக்கூடியதே ஆகும்) இதன் பொருள், அது தீர்மானிக்கப்பட்டுவிட்டது, அதனைத் தவிர்க்க முடியாது. அது நிச்சயமாக நடக்கும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَكَادُ</span> <span class=\"quran-arabic-font text-success\">أُخْفِيهَا</span><br />\r\n<br />\r\n(நான் அதனை மறைத்து வைக்க முற்படுகிறேன்) அத்-தஹ்ஹாக், இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அறிவிப்பதாவது: இப்னு அப்பாஸ் (ரழி) அவர்கள் இதனை \"நான் அதனை என்னிடமிருந்தே மறைத்து வைக்க முற்படுகிறேன்\" என்று ஓதுபவர்களாக இருந்தார்கள். \"ஏனெனில் அல்லாஹ்விடமிருந்து எதுவும் ஒருபோதும் மறைந்திருப்பதில்லை\" என்று அவர்கள் கூறுவார்கள். அலீ இப்னு அபீ தல்ஹா (ரழி), இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அறிவிப்பதாவது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَكَادُ</span> <span class=\"quran-arabic-font text-success\">أُخْفِيهَا</span><br />\r\n<br />\r\n(நான் அதனை மறைத்து வைக்க முற்படுகிறேன்.) \"இதன் பொருள், அந்த நேரத்தை என்னை (அல்லாஹ்வை)த் தவிர வேறு யாரும் அறியமாட்டார்கள் என்பதாகும்.\" அல்லாஹ் மேலும் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ثَقُلَتْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَأْتِيكُمْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">بَغْتَةً</span><br />\r\n<br />\r\n(வானங்களிலும் பூமியிலும் அதன் சுமை மிகக் கனமானது. அது திடீரென்றே ஒழிய உங்களிடம் வராது.) <a href=\"qurandisp.php?sura=7&ayah=187\" class=\"link\">7:187</a>. இதன் பொருள், அதன் அறிவு வானவர்களுக்கும் பூலோகவாசிகளுக்கும் மிகவும் பாரமானது என்பதாகும். அல்லாஹ்வின் கூற்றான:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِتُجْزَى</span> <span class=\"quran-arabic-font text-success\">كُلُّ</span> <span class=\"quran-arabic-font text-success\">نَفْسٍ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">تَسْعَى</span><br />\r\n<br />\r\n(ஒவ்வொரு ஆன்மாவும் தான் செய்த முயற்சிக்கு ஏற்பக் கூலி வழங்கப்படுவதற்காக.) \"நான் அதனை நிலைநாட்டுவேன், அது தவிர்க்க முடியாதது. ஒவ்வொரு நபரும் செய்த செயல்களுக்கு ஏற்ப நிச்சயமாக அவர்களுக்கு நான் கூலி வழங்குவேன்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَمَن</span> <span class=\"quran-arabic-font text-success\">يَعْمَلْ</span> <span class=\"quran-arabic-font text-success\">مِثْقَالَ</span> <span class=\"quran-arabic-font text-success\">ذَرَّةٍ</span> <span class=\"quran-arabic-font text-success\">خَيْراً</span> <span class=\"quran-arabic-font text-success\">يَرَهُ</span> - <span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">يَعْـمَلْ</span> <span class=\"quran-arabic-font text-success\">مِثْقَالَ</span> <span class=\"quran-arabic-font text-success\">ذَرَّةٍ</span> <span class=\"quran-arabic-font text-success\">شَرّاً</span> <span class=\"quran-arabic-font text-success\">يَرَهُ</span><br />\r\n<br />\r\n(ஆகவே, எவர் ஓர் அணுவளவு நன்மை செய்தாரோ அவர் அதைக் காண்பார். மேலும், எவர் ஓர் அணுவளவு தீமை செய்தாரோ அவர் அதைக் காண்பார்.) <a href=\"qurandisp.php?sura=99&ayah=7\" class=\"link\">99:7</a>-8.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّمَا</span> <span class=\"quran-arabic-font text-success\">تُجْزَوْنَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">تَعْمَلُونَ</span><br />\r\n<br />\r\n(நீங்கள் செய்துகொண்டிருந்தவற்றிற்கே கூலி வழங்கப்படுகிறீர்கள்.) <a href=\"qurandisp.php?sura=52&ayah=16\" class=\"link\">52:16</a>. அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَلاَ</span> <span class=\"quran-arabic-font text-success\">يَصُدَّنَّكَ</span> <span class=\"quran-arabic-font text-success\">عَنْهَا</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُ</span> <span class=\"quran-arabic-font text-success\">بِهَا</span> <span class=\"quran-arabic-font text-success\">وَاتَّبَعَ</span> <span class=\"quran-arabic-font text-success\">هَوَاهُ</span><br />\r\n<br />\r\n(ஆகவே, அதனை நம்பாதவனும், தனது இச்சையைப் பின்பற்றுபவனும் உன்னை அதிலிருந்து திருப்பிவிட வேண்டாம்,) இந்தப் பேச்சு பொறுப்புள்ள ஒவ்வொரு மனிதரையும் நோக்கியதாகும். இதன் பொருள், \"மறுமை நாளை நம்பாமல், இவ்வுலகில் தனது மனோஇச்சையைப் பின்பற்றுபவனின் வழியை நீ பின்பற்றாதே. அவன் தனது இறைவனுக்கு மாறுசெய்து தனது ஆசைகளை மட்டுமே பின்பற்றுகிறான். இத்தகையவர்களைப் போல நடப்பவன் நிச்சயமாகத் தோல்வியடைந்து நஷ்டமடைந்துவிட்டான்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَتَرْدَى</span><br />\r\n<br />\r\n(அவ்வாறு செய்தால் நீ அழிந்துவிடுவாய்.) அதாவது நீ நாசமாய் போவாய்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">يُغْنِى</span> <span class=\"quran-arabic-font text-success\">عَنْهُ</span> <span class=\"quran-arabic-font text-success\">مَالُهُ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">تَرَدَّى</span><br />\r\n<br />\r\n(அவன் (அழிவில்) விழும்போது அவனது செல்வம் அவனுக்கு என்ன பயன் தரும்?) <a href=\"qurandisp.php?sura=92&ayah=11\" class=\"link\">92:11</a>.<br />\r\n<br />","text":"மூஸா (அலை) அவர்களுக்கு அருளப்பட்ட முதல் வஹீ (இறைச்செய்தி)\n\r\n\n\r\nஉயர்ந்தோன் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nفَلَمَّآ أَتَاهَا\n\r\n\n\r\n(அவர் அதனிடம் வந்தபோது,) அதாவது மூஸா (அலை) அவர்கள் நெருப்பினை நெருங்கியபோது.\n\r\n\n\r\nنُودِيَ يَا مُوسَى\n\r\n\n\r\n(அவர் பெயர் சொல்லி அழைக்கப்பட்‌டார்: \"மூஸாவே!\") மற்றொரு வசனத்தில் அல்லாஹ் பின்வருமாறு கூறுகிறான்:\n\r\n\n\r\nنُودِىَ مِن شَاطِىءِ الْوَادِى الأَيْمَنِ فِى الْبُقْعَةِ الْمُبَارَكَةِ مِنَ الشَّجَرَةِ أَنْ يَا مُوسَى إِنِّى أَنَا اللَّهُ\n\r\n\n\r\n(அந்தப் பள்ளத்தாக்கின் வலது பக்கத்திலுள்ள பாக்கியம் பெற்ற இடத்தில் இருந்த ஒரு மரத்திலிருந்து அவர் அழைக்கப்பட்டார்: \"மூஸாவே! நிச்சயமாக நானே அல்லாஹ்!\") 28:30. இருப்பினும், இங்கு அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nإِنِّى أَنَاْ رَبُّكَ\n\r\n\n\r\n(நிச்சயமாக நானே உன்னுடைய இறைவன்!) அதாவது, \"உன்னிடம் பேசுபவனும், உரையாடுபவனும் நானே\" என்று பொருள்.\n\r\n\n\r\nفَاخْلَعْ نَعْلَيْكَ\n\r\n\n\r\n(ஆகவே, உன்னுடைய காலணிகளைக் கழற்றிவிடு;) அலீ இப்னு அபீ தாலிப் (ரழி), அபூ தர் (ரழி), அபூ அய்யூப் (ரழி) மற்றும் ஸலஃபுகள் (முன்னோர்கள்) சிலர் கூறினார்கள்: \"அவரது காலணிகள் அறுக்கப்படாத (அறுத்துப் பலியிடப்படாத) கழுதையின் தோலினால் செய்யப்பட்டிருந்தன.\" மேலும், அந்தப் புனிதமான இடத்திற்கு மரியாதை செலுத்தும் விதமாகவே காலணிகளைக் கழற்றுமாறு அவர் (அலை) பணிக்கப்பட்டார் என்றும் கூறப்படுகிறது. அல்லாஹ்வின் கூற்றைப் பொறுத்தவரை:\n\r\n\n\r\nطُوًى\n\r\n\n\r\n(துவா) அலி இப்னு அபீ தல்ஹா (ரழி) அவர்கள், இப்னு அப்பாஸ் (ரழி) அவர்கள் \"இது அந்தப் பள்ளத்தாக்கின் பெயர்\" என்று கூறியதாக அறிவிக்கிறார்கள். மற்றவர்களும் இதையே கூறியுள்ளனர். இக்கதைக்கு கூடுதல் விளக்கம் அளிப்பதற்காகவே இது குறிப்பிடப்பட்டுள்ளது. இது ஒரு உருவகப் பேச்சு என்றும், தனது பாதங்களைக் கீழே வைப்பதைக் குறிக்கும் கட்டளையிலிருந்து இது பிறந்தது என்றும் கூறப்படுகிறது. 'இரட்டிப்புப் புனிதமானது' என்றும், 'துவா' என்பது திரும்பத் திரும்பக் கிடைக்கும் அருட்கொடைகளைக் கொண்டது என்றும் இதற்குப் பொருள் கூறப்பட்டுள்ளது. இருப்பினும், முதல் கருத்தே மிகவும் சரியானது. இது அல்லாஹ்வின் பின்வரும் வசனத்தைப் போன்றது:\n\r\n\n\r\nإِذْ نَادَاهُ رَبُّهُ بِالْوَادِ الْمُقَدَّسِ طُوًى\n\r\n\n\r\n(துவா எனும் புனிதப் பள்ளத்தாக்கில் அவருடைய இறைவன் அவரை அழைத்தபோது.) 79:16. அல்லாஹ்வின் கூற்றான:\n\r\n\n\r\nوَأَنَا اخْتَرْتُكَ\n\r\n\n\r\n(மேலும், நான் உன்னைத் தேர்ந்தெடுத்துக் கொண்டேன்.) என்பது அவனது மற்றொரு கூற்றைப் போன்றது:\n\r\n\n\r\nإِنِّي اصْطَفَيْتُكَ عَلَى النَّاسِ بِرِسَالَاتِي وَبِكَلَامِي\n\r\n\n\r\n(நிச்சயமாக எனது தூதுத்துவத்தைக் கொண்டும், நான் (உன்னுடன்) பேசுவதைக் கொண்டும் மனிதர்களில் உன்னை நான் தேர்ந்தெடுத்துக் கொண்டேன்.) 7:144. இதன் பொருள், அந்தக் காலத்தில் வாழ்ந்த அனைத்து மனிதர்களுக்கும் மேலாக என்பதாகும். அல்லாஹ், \"மூஸாவே! அனைத்து மக்களையும் விடுத்து உன்னுடன் நேரடியாகப் பேச நான் ஏன் தேர்ந்தெடுத்தேன் என்று உனக்குத் தெரியுமா?\" என்று கேட்டான்; அதற்கு மூஸா (அலை) அவர்கள் \"இல்லை\" எனப் பதிலளித்தார்கள். அப்போது அல்லாஹ், \"நீ உன்னைத் தாழ்த்திக் கொண்டது போல வேறெவரும் என்னிடம் தங்களைத் தாழ்த்திக் கொண்டதில்லை என்பதால்தான் (உன்னைத் தேர்ந்தெடுத்தேன்)\" எனக் கூறினான் என்றும் சொல்லப்படுகிறது. அல்லாஹ்வின் கூற்றைப் பொறுத்தவரை:\n\r\n\n\r\nفَاسْتَمِعْ لِمَا يُوحَى\n\r\n\n\r\n(எனவே, வஹீ (இறைச்செய்தி)யாக அருளப்படுவதைச் செவிமடுப்பாயாக.) \"இப்போது நான் உன்னிடம் கூறுவதையும், உனக்கு வஹீயாக அறிவிப்பதையும் கூர்ந்து கவனி\" என்று பொருள்.\n\r\n\n\r\nإِنَّنِى أَنَا اللَّهُ لا إِلَـهَ إِلا أَنَاْ\n\r\n\n\r\n(நிச்சயமாக, நானே அல்லாஹ்! என்னைத் தவிர வேறு இறைவன் இல்லை,) வயது வந்த, பொறுப்புள்ள ஒவ்வொருவர் மீதும் உள்ள முதல் கடமை இதுதான்; வணக்கத்திற்குரிய இறைவன் அல்லாஹ்வைத் தவிர வேறு யாருமில்லை என்பதையும், அவனுக்கு இணை எவரும் இல்லை என்பதையும் அவர்கள் அறிந்துகொள்ள வேண்டும்.\n\r\n\n\r\nفَاعْبُدْنِى\n\r\n\n\r\n(ஆகவே, என்னையே வணங்கு,) இதன் பொருள், \"வணக்கத்திற்கு என்னை மட்டுமே தனிப்படுத்து, எனக்கு எதனையும் இணையாக்காமல் எனது வணக்கத்தை நிலைநிறுத்து.\"\n\r\n\n\r\nوَأَقِمِ الصَّلَوةَ لِذِكْرِى\n\r\n\n\r\n(மேலும், என்னை நினைவு கூர்வதற்காகத் தொழுகையை நிலைநாட்டு.) இதன் பொருள், \"என்னை நினைவுகூர்வதற்காகத் தொழு\" என்பதாகும். \"என்னை நீ எப்போது நினைத்தாலும் தொழுகையை நிலைநாட்டு\" என்றும் இதற்குப் பொருள் கூறப்பட்டுள்ளது. இந்த இரண்டாவது கருத்திற்கு ஆதரவாக, இமாம் அஹ்மத் அவர்கள் அனஸ் (ரழி) வாயிலாகப் பதிவு செய்துள்ள ஒரு ஹதீஸ் உள்ளது: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِذَا رَقَدَ أَحَدُكُمْ عَنِ الصَّلَاةِ أَوْ غَفَلَ عَنْهَا، فَلْيُصَلِّهَا إِذَا ذَكَرَهَا، فَإِنَّ اللهَ تَعَالى قَالَ:\n\r\n\n\r\nوَأَقِمِ الصَّلَوةَ لِذِكْرِى»\n\r\n\n\r\n(உங்களில் ஒருவர் தொழுகையை விட்டுவிட்டு உறங்கிவிட்டாலோ அல்லது அதனை மறந்தாலோ, அவர் நினைவுக்கு வரும்போது அதனைத் தொழட்டும். ஏனெனில், நிச்சயமாக அல்லாஹ் கூறுகிறான்: \"என்னை நினைவுகூர்வதற்காகத் தொழுகையை நிலைநாட்டு.\") புஹாரி, முஸ்லிம் ஆகிய இரு நூல்களிலும் அனஸ் (ரழி) அவர்கள் மூலமாக அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியதாகப் பதிவாகியுள்ளது:\n\r\n\n\r\n«مَنْ نَامَ عَنْ صَلَاةٍ أَوْ نَسِيَهَا فَكَفَّارَتُهَا أَنْ يُصَلِّيَهَا إِذَا ذَكَرَهَا، لَا كَفَّارَةَ لَهَا إِلَّا ذَلِك»\n\r\n\n\r\n(யார் ஒரு தொழுகையை விட்டுவிட்டுத் தூங்கிவிட்டாரோ அல்லது அதனை மறந்துவிட்டாரோ, அவர் நினைவுக்கு வரும்போது அதனைத் தொழுவதே அதற்கான பரிகாரமாகும். அதனைத் தவிர வேறு பரிகாரம் அதற்கு இல்லை.) அல்லாஹ்வின் கூற்றான:\n\r\n\n\r\nإِنَّ السَّاعَةَ ءَاتِيَةٌ\n\r\n\n\r\n(நிச்சயமாக மறுமை நேரம் வரக்கூடியதே ஆகும்) இதன் பொருள், அது தீர்மானிக்கப்பட்டுவிட்டது, அதனைத் தவிர்க்க முடியாது. அது நிச்சயமாக நடக்கும்.\n\r\n\n\r\nأَكَادُ أُخْفِيهَا\n\r\n\n\r\n(நான் அதனை மறைத்து வைக்க முற்படுகிறேன்) அத்-தஹ்ஹாக், இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அறிவிப்பதாவது: இப்னு அப்பாஸ் (ரழி) அவர்கள் இதனை \"நான் அதனை என்னிடமிருந்தே மறைத்து வைக்க முற்படுகிறேன்\" என்று ஓதுபவர்களாக இருந்தார்கள். \"ஏனெனில் அல்லாஹ்விடமிருந்து எதுவும் ஒருபோதும் மறைந்திருப்பதில்லை\" என்று அவர்கள் கூறுவார்கள். அலீ இப்னு அபீ தல்ஹா (ரழி), இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அறிவிப்பதாவது:\n\r\n\n\r\nأَكَادُ أُخْفِيهَا\n\r\n\n\r\n(நான் அதனை மறைத்து வைக்க முற்படுகிறேன்.) \"இதன் பொருள், அந்த நேரத்தை என்னை (அல்லாஹ்வை)த் தவிர வேறு யாரும் அறியமாட்டார்கள் என்பதாகும்.\" அல்லாஹ் மேலும் கூறுகிறான்:\n\r\n\n\r\nثَقُلَتْ فِى السَّمَاوَاتِ وَالْأَرْضِ لاَ تَأْتِيكُمْ إِلاَّ بَغْتَةً\n\r\n\n\r\n(வானங்களிலும் பூமியிலும் அதன் சுமை மிகக் கனமானது. அது திடீரென்றே ஒழிய உங்களிடம் வராது.) 7:187. இதன் பொருள், அதன் அறிவு வானவர்களுக்கும் பூலோகவாசிகளுக்கும் மிகவும் பாரமானது என்பதாகும். அல்லாஹ்வின் கூற்றான:\n\r\n\n\r\nلِتُجْزَى كُلُّ نَفْسٍ بِمَا تَسْعَى\n\r\n\n\r\n(ஒவ்வொரு ஆன்மாவும் தான் செய்த முயற்சிக்கு ஏற்பக் கூலி வழங்கப்படுவதற்காக.) \"நான் அதனை நிலைநாட்டுவேன், அது தவிர்க்க முடியாதது. ஒவ்வொரு நபரும் செய்த செயல்களுக்கு ஏற்ப நிச்சயமாக அவர்களுக்கு நான் கூலி வழங்குவேன்.\"\n\r\n\n\r\nفَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْراً يَرَهُ - وَمَن يَعْـمَلْ مِثْقَالَ ذَرَّةٍ شَرّاً يَرَهُ\n\r\n\n\r\n(ஆகவே, எவர் ஓர் அணுவளவு நன்மை செய்தாரோ அவர் அதைக் காண்பார். மேலும், எவர் ஓர் அணுவளவு தீமை செய்தாரோ அவர் அதைக் காண்பார்.) 99:7-8.\n\r\n\n\r\nإِنَّمَا تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ\n\r\n\n\r\n(நீங்கள் செய்துகொண்டிருந்தவற்றிற்கே கூலி வழங்கப்படுகிறீர்கள்.) 52:16. அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nفَلاَ يَصُدَّنَّكَ عَنْهَا مَن لاَّ يُؤْمِنُ بِهَا وَاتَّبَعَ هَوَاهُ\n\r\n\n\r\n(ஆகவே, அதனை நம்பாதவனும், தனது இச்சையைப் பின்பற்றுபவனும் உன்னை அதிலிருந்து திருப்பிவிட வேண்டாம்,) இந்தப் பேச்சு பொறுப்புள்ள ஒவ்வொரு மனிதரையும் நோக்கியதாகும். இதன் பொருள், \"மறுமை நாளை நம்பாமல், இவ்வுலகில் தனது மனோஇச்சையைப் பின்பற்றுபவனின் வழியை நீ பின்பற்றாதே. அவன் தனது இறைவனுக்கு மாறுசெய்து தனது ஆசைகளை மட்டுமே பின்பற்றுகிறான். இத்தகையவர்களைப் போல நடப்பவன் நிச்சயமாகத் தோல்வியடைந்து நஷ்டமடைந்துவிட்டான்.\"\n\r\n\n\r\nفَتَرْدَى\n\r\n\n\r\n(அவ்வாறு செய்தால் நீ அழிந்துவிடுவாய்.) அதாவது நீ நாசமாய் போவாய்.\n\r\n\n\r\nوَمَا يُغْنِى عَنْهُ مَالُهُ إِذَا تَرَدَّى\n\r\n\n\r\n(அவன் (அழிவில்) விழும்போது அவனது செல்வம் அவனுக்கு என்ன பயன் தரும்?) 92:11."},"17":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=21\" class=\"link\">20:21</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:21 ஐ பார்க்கவும்"},"18":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=21\" class=\"link\">20:21</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:21 ஐ பார்க்கவும்"},"19":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=21\" class=\"link\">20:21</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:21 ஐ பார்க்கவும்"},"20":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=21\" class=\"link\">20:21</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:21 ஐ பார்க்கவும்"},"21":{"html":"<strong>மூஸா (அலை) அவர்களின் கைத்தடி பாம்பாக மாறியது</strong><br />\r\n<br />\r\nஇது மூஸா (அலை) அவர்களுக்கு அல்லாஹ்விடமிருந்து கிடைத்த ஓர் அத்தாட்சியாகவும் மாபெரும் அற்புதமாகவும் அமைந்தது. இது இயல்பான நடைமுறைகளை மீறிய ஒன்றாக இருந்ததால், அல்லாஹ்வைத் தவிர வேறு எவராலும் செய்ய முடியாத ஒரு தெளிவான சான்றாகும். மேலும், (அல்லாஹ்வால்) அனுப்பப்பட்ட ஓர் இறைத்தூதரைத் தவிர வேறு எந்த மனிதராலும் இது போன்ற ஒன்றைக் கொண்டு வர முடியாது என்பதற்கும் இது ஒரு அத்தாட்சியாக இருந்தது. அல்லாஹ்வின் கூற்றைப் பொறுத்தவரை: <span class=\"quran-arabic-font text-success\">﴾وَمَا</span> <span class=\"quran-arabic-font text-success\">تِلْكَ</span> <span class=\"quran-arabic-font text-success\">بِيَمِينِكَ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">مُوسَى﴿</span><br />\r\n<br />\r\n(மூஸாவே! உமது வலது கையில் இருப்பது என்ன?) இது குறித்துச் சில தஃப்ஸீர் அறிஞர்கள், \"அல்லாஹ் இதை அவரிடம் கேட்டது, அவரது கவனத்தை அதன் பக்கம் ஈர்ப்பதற்காகவே\" என்று கூறியுள்ளனர். \"அவர் கையில் இருந்ததை அவருக்கு உறுதிப்படுத்துவதற்காகவே அல்லாஹ் இப்படிக் கேட்டான். அதாவது, 'உமது வலது கையில் இருப்பது உமக்கு நன்கு அறிமுகமான ஒரு கைத்தடிதான்; இப்போது நாம் அதற்கு என்ன செய்யப்போகிறோம் என்பதை நீர் பாரும்' என்பதற்காகவே\" என்றும் கூறப்படுகிறது. இது உறுதிப்படுத்துவதற்காகக் கேட்கப்பட்ட ஒரு வினா வாக்கியமாகும். <span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">هِيَ</span> <span class=\"quran-arabic-font text-success\">عَصَايَ</span> <span class=\"quran-arabic-font text-success\">أَتَوَكَّأُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهَا﴿</span><br />\r\n<br />\r\n(அதற்கு அவர், \"இது என்னுடைய கைத்தடி, இதன் மீது நான் சாய்ந்துகொள்வேன்...\" என்று கூறினார்.) நான் நடக்கும்போது இதன் மீது சாய்ந்துகொள்வேன். <span class=\"quran-arabic-font text-success\">﴾وَأَهُشُّ</span> <span class=\"quran-arabic-font text-success\">بِهَا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">غَنَمِي﴿</span><br />\r\n<br />\r\n(மேலும், இதைக் கொண்டு என் ஆடுகளுக்காக இலைகளை உதிர்ப்பேன்,) இதன் பொருள், ‘எனது ஆடுகள் உண்பதற்காக, மரங்களின் இலைகள் கீழே விழுமாறு அதன் கிளைகளை அசைக்க நான் இதைப் பயன்படுத்துகிறேன்’ என்பதாகும். அப்துர் ரஹ்மான் பின் அல்-காசிம் அவர்கள் இமாம் மாலிக் அவர்கள் கூறியதாகப் பின்வருமாறு அறிவிக்கிறார்கள்: \"ஒரு மனிதன் தனது கைத்தடியைக் கிளையில் வைத்து, அக்கிளை உடையாமல் அதன் இலைகளும் பழங்களும் உதிரும்படி அதனை அசைப்பதாகும். இது மரத்தை அடிப்பது போன்ற செயலல்ல.\" மைமூன் பின் மஹ்ரான் அவர்களும் இதையே கூறியுள்ளார்கள். அவரது கூற்றைப் பொறுத்தவரை: <span class=\"quran-arabic-font text-success\">﴾وَلِيَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">مَآرِبُ</span> <span class=\"quran-arabic-font text-success\">أُخْرَى﴿</span><br />\r\n<br />\r\n(மேலும், இதில் எனக்கு வேறு பல பயன்களும் உள்ளன.) இது தவிர எனக்கு இதில் வேறு பல நன்மைகளும், பணிகளும், தேவைகளும் உள்ளன என்பதாகும். சில அறிஞர்கள் அதிகம் அறியப்படாத இத்தகைய பல பயன்களைக் குறிப்பிடும் சிரமத்தை (ஆய்வை) மேற்கொண்டனர். அல்லாஹ்வின் கூற்றைப் பொறுத்தவரை: <span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">أَلْقِهَا</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">مُوسَى﴿</span><br />\r\n<br />\r\n((அல்லாஹ்) கூறினான்: \"மூஸாவே! அதைக் கீழே எறியும்!\") \"மூஸாவே! உமது வலது கையில் இருக்கும் இந்தக் கைத்தடியைக் கீழே எறியும்!\" <span class=\"quran-arabic-font text-success\">﴾فَأَلْقَاهَا</span> <span class=\"quran-arabic-font text-success\">فَإِذَا</span> <span class=\"quran-arabic-font text-success\">هِيَ</span> <span class=\"quran-arabic-font text-success\">حَيَّةٌ</span> <span class=\"quran-arabic-font text-success\">تَسْعَى﴿</span><br />\r\n<br />\r\n(அவர் அதைக் கீழே எறிந்தார்; உடனே அது வேகமாக ஊர்ந்து செல்லும் ஒரு பாம்பாக மாறியது.) இதன் பொருள், அந்தக் கைத்தடி ஒரு நீண்ட மலைப்பாம்பைப் போன்ற ஒரு பெரிய பாம்பாக மாறி, அதிவேகமாக நகரத் தொடங்கியது என்பதாகும். அது மிகச் சிறிய வகை பாம்பைப் போன்ற வேகத்தில் நகர்ந்தது. இருப்பினும், அது உருவத்தில் மிகப்பெரிய பாம்பாக இருந்தும், மிக வேகமான அசைவுகளைக் கொண்டிருந்தது. <span class=\"quran-arabic-font text-success\">﴾تَسْعَى﴿</span><br />\r\n<br />\r\n(வேகமாக நகர்கிறது.) அமைதியின்றித் துடிப்புடன் நகர்கிறது. அல்லாஹ்வின் கூற்றைப் பொறுத்தவரை: <span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">خُذْهَا</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَخَفْ﴿</span><br />\r\n<br />\r\n((அல்லாஹ்) கூறினான்: \"அதைப் பிடியும்; பயப்படாதீர்!\") அல்லாஹ்வின் கூற்றைப் பொறுத்தவரை: <span class=\"quran-arabic-font text-success\">﴾سَنُعِيدُهَا</span> <span class=\"quran-arabic-font text-success\">سِيرَتَهَا</span> <span class=\"quran-arabic-font text-success\">الأُولَى﴿</span><br />\r\n<br />\r\n(நாம் அதை அதன் முந்தைய நிலைக்குத் திரும்பக் கொண்டு வருவோம்.) அதாவது, நீர் முன்பு அறிந்திருந்த அதே கைத்தடி வடிவிற்கே அதனை மாற்றுவோம்.<br />\r\n<br />","text":"மூஸா (அலை) அவர்களின் கைத்தடி பாம்பாக மாறியது\n\r\n\n\r\nஇது மூஸா (அலை) அவர்களுக்கு அல்லாஹ்விடமிருந்து கிடைத்த ஓர் அத்தாட்சியாகவும் மாபெரும் அற்புதமாகவும் அமைந்தது. இது இயல்பான நடைமுறைகளை மீறிய ஒன்றாக இருந்ததால், அல்லாஹ்வைத் தவிர வேறு எவராலும் செய்ய முடியாத ஒரு தெளிவான சான்றாகும். மேலும், (அல்லாஹ்வால்) அனுப்பப்பட்ட ஓர் இறைத்தூதரைத் தவிர வேறு எந்த மனிதராலும் இது போன்ற ஒன்றைக் கொண்டு வர முடியாது என்பதற்கும் இது ஒரு அத்தாட்சியாக இருந்தது. அல்லாஹ்வின் கூற்றைப் பொறுத்தவரை: ﴾وَمَا تِلْكَ بِيَمِينِكَ يَا مُوسَى﴿\n\r\n\n\r\n(மூஸாவே! உமது வலது கையில் இருப்பது என்ன?) இது குறித்துச் சில தஃப்ஸீர் அறிஞர்கள், \"அல்லாஹ் இதை அவரிடம் கேட்டது, அவரது கவனத்தை அதன் பக்கம் ஈர்ப்பதற்காகவே\" என்று கூறியுள்ளனர். \"அவர் கையில் இருந்ததை அவருக்கு உறுதிப்படுத்துவதற்காகவே அல்லாஹ் இப்படிக் கேட்டான். அதாவது, 'உமது வலது கையில் இருப்பது உமக்கு நன்கு அறிமுகமான ஒரு கைத்தடிதான்; இப்போது நாம் அதற்கு என்ன செய்யப்போகிறோம் என்பதை நீர் பாரும்' என்பதற்காகவே\" என்றும் கூறப்படுகிறது. இது உறுதிப்படுத்துவதற்காகக் கேட்கப்பட்ட ஒரு வினா வாக்கியமாகும். ﴾قَالَ هِيَ عَصَايَ أَتَوَكَّأُ عَلَيْهَا﴿\n\r\n\n\r\n(அதற்கு அவர், \"இது என்னுடைய கைத்தடி, இதன் மீது நான் சாய்ந்துகொள்வேன்...\" என்று கூறினார்.) நான் நடக்கும்போது இதன் மீது சாய்ந்துகொள்வேன். ﴾وَأَهُشُّ بِهَا عَلَى غَنَمِي﴿\n\r\n\n\r\n(மேலும், இதைக் கொண்டு என் ஆடுகளுக்காக இலைகளை உதிர்ப்பேன்,) இதன் பொருள், ‘எனது ஆடுகள் உண்பதற்காக, மரங்களின் இலைகள் கீழே விழுமாறு அதன் கிளைகளை அசைக்க நான் இதைப் பயன்படுத்துகிறேன்’ என்பதாகும். அப்துர் ரஹ்மான் பின் அல்-காசிம் அவர்கள் இமாம் மாலிக் அவர்கள் கூறியதாகப் பின்வருமாறு அறிவிக்கிறார்கள்: \"ஒரு மனிதன் தனது கைத்தடியைக் கிளையில் வைத்து, அக்கிளை உடையாமல் அதன் இலைகளும் பழங்களும் உதிரும்படி அதனை அசைப்பதாகும். இது மரத்தை அடிப்பது போன்ற செயலல்ல.\" மைமூன் பின் மஹ்ரான் அவர்களும் இதையே கூறியுள்ளார்கள். அவரது கூற்றைப் பொறுத்தவரை: ﴾وَلِيَ فِيهَا مَآرِبُ أُخْرَى﴿\n\r\n\n\r\n(மேலும், இதில் எனக்கு வேறு பல பயன்களும் உள்ளன.) இது தவிர எனக்கு இதில் வேறு பல நன்மைகளும், பணிகளும், தேவைகளும் உள்ளன என்பதாகும். சில அறிஞர்கள் அதிகம் அறியப்படாத இத்தகைய பல பயன்களைக் குறிப்பிடும் சிரமத்தை (ஆய்வை) மேற்கொண்டனர். அல்லாஹ்வின் கூற்றைப் பொறுத்தவரை: ﴾قَالَ أَلْقِهَا يَا مُوسَى﴿\n\r\n\n\r\n((அல்லாஹ்) கூறினான்: \"மூஸாவே! அதைக் கீழே எறியும்!\") \"மூஸாவே! உமது வலது கையில் இருக்கும் இந்தக் கைத்தடியைக் கீழே எறியும்!\" ﴾فَأَلْقَاهَا فَإِذَا هِيَ حَيَّةٌ تَسْعَى﴿\n\r\n\n\r\n(அவர் அதைக் கீழே எறிந்தார்; உடனே அது வேகமாக ஊர்ந்து செல்லும் ஒரு பாம்பாக மாறியது.) இதன் பொருள், அந்தக் கைத்தடி ஒரு நீண்ட மலைப்பாம்பைப் போன்ற ஒரு பெரிய பாம்பாக மாறி, அதிவேகமாக நகரத் தொடங்கியது என்பதாகும். அது மிகச் சிறிய வகை பாம்பைப் போன்ற வேகத்தில் நகர்ந்தது. இருப்பினும், அது உருவத்தில் மிகப்பெரிய பாம்பாக இருந்தும், மிக வேகமான அசைவுகளைக் கொண்டிருந்தது. ﴾تَسْعَى﴿\n\r\n\n\r\n(வேகமாக நகர்கிறது.) அமைதியின்றித் துடிப்புடன் நகர்கிறது. அல்லாஹ்வின் கூற்றைப் பொறுத்தவரை: ﴾قَالَ خُذْهَا وَلاَ تَخَفْ﴿\n\r\n\n\r\n((அல்லாஹ்) கூறினான்: \"அதைப் பிடியும்; பயப்படாதீர்!\") அல்லாஹ்வின் கூற்றைப் பொறுத்தவரை: ﴾سَنُعِيدُهَا سِيرَتَهَا الأُولَى﴿\n\r\n\n\r\n(நாம் அதை அதன் முந்தைய நிலைக்குத் திரும்பக் கொண்டு வருவோம்.) அதாவது, நீர் முன்பு அறிந்திருந்த அதே கைத்தடி வடிவிற்கே அதனை மாற்றுவோம்."},"22":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=35\" class=\"link\">20:35</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:35 ஐ பார்க்கவும்"},"23":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=35\" class=\"link\">20:35</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:35 ஐ பார்க்கவும்"},"24":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=35\" class=\"link\">20:35</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:35 ஐ பார்க்கவும்"},"25":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=35\" class=\"link\">20:35</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:35 ஐ பார்க்கவும்"},"26":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=35\" class=\"link\">20:35</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:35 ஐ பார்க்கவும்"},"27":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=35\" class=\"link\">20:35</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:35 ஐ பார்க்கவும்"},"28":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=35\" class=\"link\">20:35</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:35 ஐ பார்க்கவும்"},"29":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=35\" class=\"link\">20:35</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:35 ஐ பார்க்கவும்"},"30":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=35\" class=\"link\">20:35</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:35 ஐ பார்க்கவும்"},"31":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=35\" class=\"link\">20:35</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:35 ஐ பார்க்கவும்"},"32":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=35\" class=\"link\">20:35</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:35 ஐ பார்க்கவும்"},"33":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=35\" class=\"link\">20:35</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:35 ஐ பார்க்கவும்"},"34":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=35\" class=\"link\">20:35</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:35 ஐ பார்க்கவும்"},"35":{"html":"<strong>எந்த நோயுமின்றி மூஸா (அலை) அவர்களின் கை வெண்மையாக மாறியது</strong><br />\r\n<br />\r\nஇது மூஸா (அலை) அவர்களுக்கு வழங்கப்பட்ட இரண்டாவது அத்தாட்சியாகும். அதாவது, அல்லாஹ் அவர்களுக்குத் தனது ஆடையின் திறப்புக்குள் கையை விடுமாறு கட்டளையிட்டான். இது மற்றொரு வசனத்தில் (ஆயத்தில்) தெளிவாகக் கூறப்பட்டுள்ளது. இங்கு அது சுருக்கமாகக் குறிப்பிடப்பட்டுள்ளது: <span class=\"quran-arabic-font text-success\">﴾وَاضْمُمْ</span> <span class=\"quran-arabic-font text-success\">يَدَكَ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">جَنَاحِكَ﴿</span><br />\r\n<br />\r\n(உமது கையை உமது விலாப்புறமாகச் சேர்த்து அணைத்துக் கொள்வீராக!) அல்லாஹ் மற்றொரு வசனத்தில் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾وَاضْمُمْ</span> <span class=\"quran-arabic-font text-success\">إِلَيْكَ</span> <span class=\"quran-arabic-font text-success\">جَنَاحَكَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الرَّهْبِ</span> <span class=\"quran-arabic-font text-success\">فَذَانِكَ</span> <span class=\"quran-arabic-font text-success\">بُرْهَانَانِ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">رَّبِّكَ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">فِرْعَوْنَ</span> <span class=\"quran-arabic-font text-success\">وَمَلَئِهِ﴿</span><br />\r\n<br />\r\n(அச்சத்திலிருந்து விடுபட உமது கையை உமது விலாப்புறமாகச் சேர்த்து அணைத்துக் கொள்வீராக. இவை உமது இறைவனிடமிருந்து ஃபிர்அவ்னுக்கும் அவனது பிரதானிகளுக்கும் வந்த இரு அத்தாட்சிகளாகும்.) (அல்குர்ஆன் <a href=\"qurandisp.php?sura=28&ayah=32\" class=\"link\">28:32</a>). முஜாஹித் (ரழி) அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾وَاضْمُمْ</span> <span class=\"quran-arabic-font text-success\">يَدَكَ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">جَنَاحِكَ﴿</span><br />\r\n<br />\r\n(உமது கையை உமது விலாப்புறமாகச் சேர்த்து அணைத்துக் கொள்வீராக:) \"இதன் பொருள், உமது உள்ளங்கையை உமது புஜத்தின் கீழ் வைப்பதாகும்.\" மூஸா (அலை) அவர்கள் தமது கையை ஆடையின் திறப்புக்குள் நுழைத்து வெளியே எடுத்தபோது, அது ஒரு பிறை நிலவைப் போல் பிரகாசித்தது. அவனது (அல்லாஹ்வின்) கூற்றான <span class=\"quran-arabic-font text-success\">﴾تَخْرُجْ</span> <span class=\"quran-arabic-font text-success\">بَيْضَآءَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">غَيْرِ</span> <span class=\"quran-arabic-font text-success\">سُوءٍ﴿</span> என்பது குறித்து:<br />\r\n<br />\r\n(அது எந்த நோயுமின்றி வெண்மையாக வெளிவரும்.) இதன் பொருள் வெண்புள்ளி (குஷ்டம்), நோய் அல்லது ஊனம் ஏதுமின்றி என்பதாகும். இதனை இப்னு அப்பாஸ் (ரழி), முஜாஹித் (ரழி), இக்ரிமா (ரழி), கதாதா (ரழி), அத்-தஹ்ஹாக், அஸ்-ஸுத்தி மற்றும் பிறர் கூறியுள்ளனர். ஹஸன் அல்-பஸரி (ரழி) அவர்கள் கூறினார்கள்: \"அவர் கையை வெளியே எடுத்தார், அல்லாஹ்வின் மீது சத்தியமாக, அது ஒரு விளக்கைப் போல் பிரகாசித்தது. இதன் மூலம் மூஸா (அலை) அவர்கள், கண்ணியமும் மேன்மையும் மிக்க தமது இறைவனைத் தாம் நிச்சயமாகச் சந்தித்துவிட்டோம் என்பதை அறிந்துகொண்டார்கள்.\" இதனால்தான் அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾لِنُرِيَكَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">ءَايَـتِنَا</span> <span class=\"quran-arabic-font text-success\">الْكُبْرَى</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நமது மிகப்பெரிய அத்தாட்சிகளில் சிலவற்றை உமக்குக் காண்பிப்பதற்காக.)<br />\r\n<br />\r\n<strong>அல்லாஹ்வின் செய்தியை எத்திவைப்பதற்காக ஃபிர்அவ்னிடம் செல்லுமாறு மூஸா (அலை) அவர்களுக்கு அல்லாஹ் கட்டளையிட்டான். அல்லாஹ் கூறினான்:</strong><br />\r\n<br />\r\nஅல்லாஹ்வின் செய்தியை எத்திவைப்பதற்காக ஃபிர்அவ்னிடம் செல்லுமாறு மூஸா (அலை) அவர்களுக்கு அல்லாஹ் கட்டளையிட்டான்: <span class=\"quran-arabic-font text-success\">﴾اذْهَبْ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">فِرْعَوْنَ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">طَغَى</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(ஃபிர்அவ்னிடம் செல்வீராக! நிச்சயமாக அவன் வரம்பு மீறிவிட்டான்.) இதன் பொருள்: \"நீர் எகிப்தை விட்டுத் தப்பியோடி வந்தபோது அங்கிருந்த எகிப்தின் மன்னன் ஃபிர்அவ்னிடம் செல்வீராக. இணையற்றவனாகிய அல்லாஹ்வை மட்டும் வணங்குமாறு அவனுக்கு அழைப்பு விடுப்பீராக. பனூ இஸ்ராயீல்களை உம்முடன் அனுப்பி வைக்குமாறும், அவர்களைத் துன்புறுத்த வேண்டாம் என்றும் அவனுக்குக் கட்டளையிடுவீராக. ஏனெனில் அவன் வரம்பு மீறி, அக்கிரமம் செய்து, இவ்வுலக வாழ்க்கையைத் தேர்ந்தெடுத்து, உன்னதமான இறைவனை மறந்துவிட்டான்.\"<br />\r\n<br />\r\n<strong>மூஸா (அலை) அவர்களின் பிரார்த்தனை</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">اشْرَحْ</span> <span class=\"quran-arabic-font text-success\">لِى</span> <span class=\"quran-arabic-font text-success\">صَدْرِى</span> - <span class=\"quran-arabic-font text-success\">وَيَسِّرْ</span> <span class=\"quran-arabic-font text-success\">لِى</span> <span class=\"quran-arabic-font text-success\">أَمْرِى</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n((மூஸா (அலை)) அவர்கள் கூறினார்கள்: \"என் இறைவனே! எனக்காக எனது உள்ளத்தை விரிவுபடுத்துவாயாக, எனது பணியை எனக்கு எளிதாக்குவாயாக.\") மூஸா (அலை) அவர்கள் தமது பணிக்காகத் தமது உள்ளத்தை விரிவுபடுத்துமாறு தமது இறைவனிடம் வேண்டினார்கள். ஏனெனில், அல்லாஹ் அவர்களுக்கு ஒரு மகத்தான பணியையும் கடினமான காரியத்தையும் கட்டளையிட்டிருந்தான். அக்காலத்தில் பூமியின் மிக வலிமை வாய்ந்த மன்னனிடம் அவர்களை அவன் அனுப்பினான். அவன் மற்ற மனிதர்களை விடத் தனது இறைமறுப்பில் மிகுந்த ஆணவமும் கடுமையும் கொண்டவனாக இருந்தான். அவனிடம் மிகப்பெரிய படையும் ஆற்றல்மிக்க அரசும் இருந்தன. அவன் ஆட்சியாளர்களிலேயே மிகவும் கொடுங்கோலனாகவும் பிடிவாதக்காரனாகவும் இருந்தான். தான் அல்லாஹ்வை அறியவே இல்லை என்றும், தனது குடிமக்களுக்குத் தன்னைத் தவிர வேறு ஒரு கடவுள் இருப்பதை தான் அறியவில்லை என்றும் அவன் வாதிட்டு வந்தான். அத்துடன், மூஸா (அலை) அவர்கள் குழந்தையாக இருந்தபோது ஒரு குறிப்பிட்ட காலம் அவனது வீட்டிலேயே வளர்ந்தார்கள். ஃபிர்அவ்னின் அறையிலேயே தங்கி அவனது கட்டிலிலேயே உறங்கினார்கள். அதன் பிறகு, அவர்கள் அவனது மக்களில் ஒருவரைக் கொன்றுவிட்டதால், அதற்குப் பதிலாகத் தங்களைக் கொன்றுவிடுவார்களோ என்று அஞ்சி, அங்கிருந்து தப்பியோடி தலைமறைவாக வாழ்ந்து வந்தார்கள். இவ்வளவுக்கும் பிறகு, அவனது இறைவன் அவர்களுக்குத் தூதுத்துவத்தை வழங்கி, இணையற்ற அல்லாஹ்வை வணங்குமாறு அவனுக்கு எச்சரிக்கை செய்ய அவர்களை அனுப்பினான். இதனால்தான் அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">اشْرَحْ</span> <span class=\"quran-arabic-font text-success\">لِى</span> <span class=\"quran-arabic-font text-success\">صَدْرِى</span> - <span class=\"quran-arabic-font text-success\">وَيَسِّرْ</span> <span class=\"quran-arabic-font text-success\">لِى</span> <span class=\"quran-arabic-font text-success\">أَمْرِى</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(என் இறைவனே! எனக்காக எனது உள்ளத்தை விரிவுபடுத்துவாயாக, எனது பணியை எனக்கு எளிதாக்குவாயாக.) இதன் பொருள்: \"நீ எனக்கு உதவி செய்து, துணை புரிந்து, ஆதரவளிக்கவில்லை என்றால் இந்தப் பணியை என்னால் செய்ய முடியாது\" என்பதாகும். <span class=\"quran-arabic-font text-success\">﴾وَاحْلُلْ</span> <span class=\"quran-arabic-font text-success\">عُقْدَةً</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">لِّسَانِى</span> - <span class=\"quran-arabic-font text-success\">يَفْقَهُواْ</span> <span class=\"quran-arabic-font text-success\">قَوْلِي</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(எனது நாவிலுள்ள முடிச்சை அவிழ்த்து விடுவாயாக, அவர்கள் எனது பேச்சைப் புரிந்துகொள்வார்கள்.) இது அவர்களுக்கு இருந்த திக்குவாயைக் குறிக்கிறது. சிறுவயதில் அவர்களுக்கு முன்னால் ஒரு பேரீச்சம்பழமும் எரியும் ஒரு நெருப்புக்கரியும் வைக்கப்பட்டபோது, அவர்கள் பேரீச்சம்பழத்திற்குப் பதிலாக நெருப்புக்கரியைத் தமது நாவில் வைத்துக் கொண்டதால் ஏற்பட்ட சம்பவத்தின் விளைவே இந்தத் திக்குவாய் ஆகும். இக்கதையின் விரிவான விளக்கம் வரும் அத்தியாயங்களில் இடம்பெறும். இருப்பினும், அவர்கள் இந்தத் தடையை முற்றிலும் நீக்குமாறு அல்லாஹ்விடம் கேட்கவில்லை. மாறாக, தாம் சொல்ல வருவதை மக்கள் புரிந்து கொள்ள வேண்டும் என்பதற்காகத் தமது திக்குவாயை மட்டும் நீக்குமாறு கேட்டார்கள். தமது செய்தியை எத்திவைக்கத் தேவையானதை மட்டுமே அவர்கள் கேட்டார்கள். அவர்கள் அந்தத் தடையை முழுமையாக நீக்குமாறு கேட்டிருந்தால் அது முழுமையாகக் குணமடைந்திருக்கும். இருப்பினும், நபிமார்கள் தேவைக்கு அதிகமாக எதையும் கேட்பதில்லை. எனவே, நாவில் ஏற்பட்ட அந்த விபத்தின் சில தழும்புகள் அவர்களிடம் எஞ்சியிருந்தன. ஃபிர்அவ்ன் அவர்களைப் பற்றிக் கூறியதை அல்லாஹ் இவ்வாறு குறிப்பிடுகிறான்: <span class=\"quran-arabic-font text-success\">﴾أَمْ</span> <span class=\"quran-arabic-font text-success\">أَنَآ</span> <span class=\"quran-arabic-font text-success\">خَيْرٌ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">مَهِينٌ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَكَادُ</span> <span class=\"quran-arabic-font text-success\">يُبِينُ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(இழிவானவனாகவும், தெளிவாகப் பேச முடியாதவனாகவும் இருக்கும் இவனை விட நான் சிறந்தவன் அல்லவா?) (அல்குர்ஆன் <a href=\"qurandisp.php?sura=43&ayah=52\" class=\"link\">43:52</a>). இதன் பொருள், அவர் சரளமாகப் பேச மாட்டார் என்பதாகும். அல்லாஹ்வின் கூற்றான: <span class=\"quran-arabic-font text-success\">﴾وَاجْعَل</span> <span class=\"quran-arabic-font text-success\">لِّى</span> <span class=\"quran-arabic-font text-success\">وَزِيراً</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">أَهْلِى</span> - <span class=\"quran-arabic-font text-success\">هَـرُونَ</span> <span class=\"quran-arabic-font text-success\">أَخِى</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(எனது குடும்பத்திலிருந்து எனக்கு ஓர் உதவியாளரை - எனது சகோதரர் ஹாரூனை - நியமிப்பாயாக.) இதுவும் மூஸா (அலை) அவர்கள் தமக்காக அன்றிப் பிறருக்காகக் கேட்ட ஒரு கோரிக்கையாகும். அது தமது சகோதரர் ஹாரூன் (அலை) அவர்களின் உதவிக்கான கோரிக்கையாகும். அத்-தவ்ரி (ரழி) அவர்கள் அபூ ஸயீத் (ரழி) வழியாக இக்ரிமா (ரழி) அவர்கள் அறிவிப்பதைக் குறிப்பிடுகிறார்கள்: \"மூஸா (அலை) அவர்கள் நபியாக்கப்பட்ட அதே தருணத்தில் ஹாரூன் (அலை) அவர்களும் நபியாக்கப்பட்டார்கள்\" என்று இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள். இப்னு அபீ ஹாதிம் (ரழி) அவர்கள் பதிவு செய்துள்ள ஒரு அறிவிப்பில்: ஆயிஷா (ரழி) அவர்கள் உம்ரா செய்யும் நோக்கத்தில் வெளியே சென்று சில கிராமப்புற அரபிகளிடம் (பெடோயின்கள்) முகாமிட்டிருந்தார்கள். அங்கே ஒரு மனிதர், \"இவ்வுலகில் எந்தச் சகோதரர் தனது சகோதரருக்கு அதிகப் பயனுள்ளதாக இருந்தார்?\" என்று கேட்டார். அதற்கு மக்கள் \"எங்களுக்குத் தெரியாது\" என்றனர். அப்போது அந்த மனிதர், \"அல்லாஹ்வின் மீது சத்தியமாக எனக்குத் தெரியும்\" என்றார். ஆயிஷா (ரழி) அவர்கள் கூறினார்கள்: \"யார் தனது சகோதரருக்கு அதிகப் பயன் தந்தார் என்பதைத் தான் மட்டுமே அறிந்தவர் போல அவர் சத்தியம் செய்வதைக் கண்டு நான் வியப்படைந்தேன்.\" அந்த மனிதர் சொன்னார், \"அது மூஸா (அலை) அவர்கள்தாம்; அவர் தனது சகோதரருக்கும் நபித்துவம் வழங்கப்பட வேண்டும் என்று கேட்டபோது (அவர் அவ்வாறு திகழ்ந்தார்).\" பிறகு ஆயிஷா (ரழி) அவர்கள், \"அல்லாஹ்வின் மீது சத்தியமாக அவர் உண்மையைத்தான் சொன்னார்\" என்று கூறினார்கள். இதனால்தான் அல்லாஹ் மூஸா (அலை) அவர்களை இவ்வாறு புகழ்கிறான்: <span class=\"quran-arabic-font text-success\">﴾وَكَانَ</span> <span class=\"quran-arabic-font text-success\">عِندَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَجِيهاً﴿</span><br />\r\n<br />\r\n(அவர் அல்லாஹ்விடத்தில் கண்ணியமிக்கவராக இருந்தார்.) (அல்குர்ஆன் <a href=\"qurandisp.php?sura=33&ayah=69\" class=\"link\">33:69</a>). மூஸா (அலை) அவர்களின் கூற்றான: <span class=\"quran-arabic-font text-success\">﴾اشْدُدْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">أَزْرِى</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அவரைக் கொண்டு எனது பலத்தை அதிகரிப்பாயாக.) இதன் பொருள், \"எனது முதுகை (பலத்தை) உறுதிப்படுத்துவாயாக\" என்று முஜாஹித் (ரழி) அவர்கள் கூறினார்கள். <span class=\"quran-arabic-font text-success\">﴾وَأَشْرِكْهُ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">أَمْرِى</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(எனது பணியில் அவரைப் பங்குதாரராக்குவாயாக.) அதாவது, இவ்விஷயத்தில் அவரை எனது ஆலோசகராக ஆக்குவாயாக. <span class=\"quran-arabic-font text-success\">﴾كَىْ</span> <span class=\"quran-arabic-font text-success\">نُسَبِّحَكَ</span> <span class=\"quran-arabic-font text-success\">كَثِيراً</span> - <span class=\"quran-arabic-font text-success\">وَنَذْكُرَكَ</span> <span class=\"quran-arabic-font text-success\">كَثِيراً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நாங்கள் உன்னை அதிகமாகத் துதிப்பதற்கும், உன்னை அதிகமாக நினைவு கூர்வதற்கும்.) முஜாஹித் (ரழி) அவர்கள் கூறினார்கள்: \"ஓர் அடியான் நின்ற நிலையிலும், அமர்ந்த நிலையிலும், படுத்த நிலையிலும் அல்லாஹ்வை நினைவு கூராத வரை, அவன் அல்லாஹ்வை அதிகமாக நினைவு கூர்பவர்களில் ஒருவனாகக் கருதப்பட மாட்டான்.\" அவர்களது கூற்றான: <span class=\"quran-arabic-font text-success\">﴾إِنَّكَ</span> <span class=\"quran-arabic-font text-success\">كُنتَ</span> <span class=\"quran-arabic-font text-success\">بِنَا</span> <span class=\"quran-arabic-font text-success\">بَصِيراً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நிச்சயமாக நீ எங்களை உற்று நோக்குபவனாக இருக்கிறாய்.) இதன் பொருள்: \"எங்களைத் தேர்ந்தெடுத்ததிலும், எங்களுக்குத் தூதுத்துவத்தை வழங்கியதிலும், உனது எதிரியான ஃபிர்அவ்னிடம் எங்களை அனுப்பியதிலும் (நீ எங்களைக் கண்காணிப்பவனாக இருக்கிறாய்)\". எனவே இதற்காக உனக்கே அனைத்துப் புகழும். மேலும், (உனக்கே) அனைத்து அருட்கொடையும் உரியன.<br />\r\n<br />\r\n<br />\r\n<br />","text":"எந்த நோயுமின்றி மூஸா (அலை) அவர்களின் கை வெண்மையாக மாறியது\n\r\n\n\r\nஇது மூஸா (அலை) அவர்களுக்கு வழங்கப்பட்ட இரண்டாவது அத்தாட்சியாகும். அதாவது, அல்லாஹ் அவர்களுக்குத் தனது ஆடையின் திறப்புக்குள் கையை விடுமாறு கட்டளையிட்டான். இது மற்றொரு வசனத்தில் (ஆயத்தில்) தெளிவாகக் கூறப்பட்டுள்ளது. இங்கு அது சுருக்கமாகக் குறிப்பிடப்பட்டுள்ளது: ﴾وَاضْمُمْ يَدَكَ إِلَى جَنَاحِكَ﴿\n\r\n\n\r\n(உமது கையை உமது விலாப்புறமாகச் சேர்த்து அணைத்துக் கொள்வீராக!) அல்லாஹ் மற்றொரு வசனத்தில் கூறினான்: ﴾وَاضْمُمْ إِلَيْكَ جَنَاحَكَ مِنَ الرَّهْبِ فَذَانِكَ بُرْهَانَانِ مِن رَّبِّكَ إِلَى فِرْعَوْنَ وَمَلَئِهِ﴿\n\r\n\n\r\n(அச்சத்திலிருந்து விடுபட உமது கையை உமது விலாப்புறமாகச் சேர்த்து அணைத்துக் கொள்வீராக. இவை உமது இறைவனிடமிருந்து ஃபிர்அவ்னுக்கும் அவனது பிரதானிகளுக்கும் வந்த இரு அத்தாட்சிகளாகும்.) (அல்குர்ஆன் 28:32). முஜாஹித் (ரழி) அவர்கள் கூறினார்கள்: ﴾وَاضْمُمْ يَدَكَ إِلَى جَنَاحِكَ﴿\n\r\n\n\r\n(உமது கையை உமது விலாப்புறமாகச் சேர்த்து அணைத்துக் கொள்வீராக:) \"இதன் பொருள், உமது உள்ளங்கையை உமது புஜத்தின் கீழ் வைப்பதாகும்.\" மூஸா (அலை) அவர்கள் தமது கையை ஆடையின் திறப்புக்குள் நுழைத்து வெளியே எடுத்தபோது, அது ஒரு பிறை நிலவைப் போல் பிரகாசித்தது. அவனது (அல்லாஹ்வின்) கூற்றான ﴾تَخْرُجْ بَيْضَآءَ مِنْ غَيْرِ سُوءٍ﴿ என்பது குறித்து:\n\r\n\n\r\n(அது எந்த நோயுமின்றி வெண்மையாக வெளிவரும்.) இதன் பொருள் வெண்புள்ளி (குஷ்டம்), நோய் அல்லது ஊனம் ஏதுமின்றி என்பதாகும். இதனை இப்னு அப்பாஸ் (ரழி), முஜாஹித் (ரழி), இக்ரிமா (ரழி), கதாதா (ரழி), அத்-தஹ்ஹாக், அஸ்-ஸுத்தி மற்றும் பிறர் கூறியுள்ளனர். ஹஸன் அல்-பஸரி (ரழி) அவர்கள் கூறினார்கள்: \"அவர் கையை வெளியே எடுத்தார், அல்லாஹ்வின் மீது சத்தியமாக, அது ஒரு விளக்கைப் போல் பிரகாசித்தது. இதன் மூலம் மூஸா (அலை) அவர்கள், கண்ணியமும் மேன்மையும் மிக்க தமது இறைவனைத் தாம் நிச்சயமாகச் சந்தித்துவிட்டோம் என்பதை அறிந்துகொண்டார்கள்.\" இதனால்தான் அல்லாஹ் கூறுகிறான்: ﴾لِنُرِيَكَ مِنْ ءَايَـتِنَا الْكُبْرَى ﴿\n\r\n\n\r\n(நமது மிகப்பெரிய அத்தாட்சிகளில் சிலவற்றை உமக்குக் காண்பிப்பதற்காக.)\n\r\n\n\r\nஅல்லாஹ்வின் செய்தியை எத்திவைப்பதற்காக ஃபிர்அவ்னிடம் செல்லுமாறு மூஸா (அலை) அவர்களுக்கு அல்லாஹ் கட்டளையிட்டான். அல்லாஹ் கூறினான்:\n\r\n\n\r\nஅல்லாஹ்வின் செய்தியை எத்திவைப்பதற்காக ஃபிர்அவ்னிடம் செல்லுமாறு மூஸா (அலை) அவர்களுக்கு அல்லாஹ் கட்டளையிட்டான்: ﴾اذْهَبْ إِلَى فِرْعَوْنَ إِنَّهُ طَغَى ﴿\n\r\n\n\r\n(ஃபிர்அவ்னிடம் செல்வீராக! நிச்சயமாக அவன் வரம்பு மீறிவிட்டான்.) இதன் பொருள்: \"நீர் எகிப்தை விட்டுத் தப்பியோடி வந்தபோது அங்கிருந்த எகிப்தின் மன்னன் ஃபிர்அவ்னிடம் செல்வீராக. இணையற்றவனாகிய அல்லாஹ்வை மட்டும் வணங்குமாறு அவனுக்கு அழைப்பு விடுப்பீராக. பனூ இஸ்ராயீல்களை உம்முடன் அனுப்பி வைக்குமாறும், அவர்களைத் துன்புறுத்த வேண்டாம் என்றும் அவனுக்குக் கட்டளையிடுவீராக. ஏனெனில் அவன் வரம்பு மீறி, அக்கிரமம் செய்து, இவ்வுலக வாழ்க்கையைத் தேர்ந்தெடுத்து, உன்னதமான இறைவனை மறந்துவிட்டான்.\"\n\r\n\n\r\nமூஸா (அலை) அவர்களின் பிரார்த்தனை\n\r\n\n\r\n﴾قَالَ رَبِّ اشْرَحْ لِى صَدْرِى - وَيَسِّرْ لِى أَمْرِى ﴿\n\r\n\n\r\n((மூஸா (அலை)) அவர்கள் கூறினார்கள்: \"என் இறைவனே! எனக்காக எனது உள்ளத்தை விரிவுபடுத்துவாயாக, எனது பணியை எனக்கு எளிதாக்குவாயாக.\") மூஸா (அலை) அவர்கள் தமது பணிக்காகத் தமது உள்ளத்தை விரிவுபடுத்துமாறு தமது இறைவனிடம் வேண்டினார்கள். ஏனெனில், அல்லாஹ் அவர்களுக்கு ஒரு மகத்தான பணியையும் கடினமான காரியத்தையும் கட்டளையிட்டிருந்தான். அக்காலத்தில் பூமியின் மிக வலிமை வாய்ந்த மன்னனிடம் அவர்களை அவன் அனுப்பினான். அவன் மற்ற மனிதர்களை விடத் தனது இறைமறுப்பில் மிகுந்த ஆணவமும் கடுமையும் கொண்டவனாக இருந்தான். அவனிடம் மிகப்பெரிய படையும் ஆற்றல்மிக்க அரசும் இருந்தன. அவன் ஆட்சியாளர்களிலேயே மிகவும் கொடுங்கோலனாகவும் பிடிவாதக்காரனாகவும் இருந்தான். தான் அல்லாஹ்வை அறியவே இல்லை என்றும், தனது குடிமக்களுக்குத் தன்னைத் தவிர வேறு ஒரு கடவுள் இருப்பதை தான் அறியவில்லை என்றும் அவன் வாதிட்டு வந்தான். அத்துடன், மூஸா (அலை) அவர்கள் குழந்தையாக இருந்தபோது ஒரு குறிப்பிட்ட காலம் அவனது வீட்டிலேயே வளர்ந்தார்கள். ஃபிர்அவ்னின் அறையிலேயே தங்கி அவனது கட்டிலிலேயே உறங்கினார்கள். அதன் பிறகு, அவர்கள் அவனது மக்களில் ஒருவரைக் கொன்றுவிட்டதால், அதற்குப் பதிலாகத் தங்களைக் கொன்றுவிடுவார்களோ என்று அஞ்சி, அங்கிருந்து தப்பியோடி தலைமறைவாக வாழ்ந்து வந்தார்கள். இவ்வளவுக்கும் பிறகு, அவனது இறைவன் அவர்களுக்குத் தூதுத்துவத்தை வழங்கி, இணையற்ற அல்லாஹ்வை வணங்குமாறு அவனுக்கு எச்சரிக்கை செய்ய அவர்களை அனுப்பினான். இதனால்தான் அவர்கள் கூறினார்கள்: ﴾قَالَ رَبِّ اشْرَحْ لِى صَدْرِى - وَيَسِّرْ لِى أَمْرِى ﴿\n\r\n\n\r\n(என் இறைவனே! எனக்காக எனது உள்ளத்தை விரிவுபடுத்துவாயாக, எனது பணியை எனக்கு எளிதாக்குவாயாக.) இதன் பொருள்: \"நீ எனக்கு உதவி செய்து, துணை புரிந்து, ஆதரவளிக்கவில்லை என்றால் இந்தப் பணியை என்னால் செய்ய முடியாது\" என்பதாகும். ﴾وَاحْلُلْ عُقْدَةً مِّن لِّسَانِى - يَفْقَهُواْ قَوْلِي ﴿\n\r\n\n\r\n(எனது நாவிலுள்ள முடிச்சை அவிழ்த்து விடுவாயாக, அவர்கள் எனது பேச்சைப் புரிந்துகொள்வார்கள்.) இது அவர்களுக்கு இருந்த திக்குவாயைக் குறிக்கிறது. சிறுவயதில் அவர்களுக்கு முன்னால் ஒரு பேரீச்சம்பழமும் எரியும் ஒரு நெருப்புக்கரியும் வைக்கப்பட்டபோது, அவர்கள் பேரீச்சம்பழத்திற்குப் பதிலாக நெருப்புக்கரியைத் தமது நாவில் வைத்துக் கொண்டதால் ஏற்பட்ட சம்பவத்தின் விளைவே இந்தத் திக்குவாய் ஆகும். இக்கதையின் விரிவான விளக்கம் வரும் அத்தியாயங்களில் இடம்பெறும். இருப்பினும், அவர்கள் இந்தத் தடையை முற்றிலும் நீக்குமாறு அல்லாஹ்விடம் கேட்கவில்லை. மாறாக, தாம் சொல்ல வருவதை மக்கள் புரிந்து கொள்ள வேண்டும் என்பதற்காகத் தமது திக்குவாயை மட்டும் நீக்குமாறு கேட்டார்கள். தமது செய்தியை எத்திவைக்கத் தேவையானதை மட்டுமே அவர்கள் கேட்டார்கள். அவர்கள் அந்தத் தடையை முழுமையாக நீக்குமாறு கேட்டிருந்தால் அது முழுமையாகக் குணமடைந்திருக்கும். இருப்பினும், நபிமார்கள் தேவைக்கு அதிகமாக எதையும் கேட்பதில்லை. எனவே, நாவில் ஏற்பட்ட அந்த விபத்தின் சில தழும்புகள் அவர்களிடம் எஞ்சியிருந்தன. ஃபிர்அவ்ன் அவர்களைப் பற்றிக் கூறியதை அல்லாஹ் இவ்வாறு குறிப்பிடுகிறான்: ﴾أَمْ أَنَآ خَيْرٌ مِّنْ هَـذَا الَّذِى هُوَ مَهِينٌ وَلاَ يَكَادُ يُبِينُ ﴿\n\r\n\n\r\n(இழிவானவனாகவும், தெளிவாகப் பேச முடியாதவனாகவும் இருக்கும் இவனை விட நான் சிறந்தவன் அல்லவா?) (அல்குர்ஆன் 43:52). இதன் பொருள், அவர் சரளமாகப் பேச மாட்டார் என்பதாகும். அல்லாஹ்வின் கூற்றான: ﴾وَاجْعَل لِّى وَزِيراً مِّنْ أَهْلِى - هَـرُونَ أَخِى ﴿\n\r\n\n\r\n(எனது குடும்பத்திலிருந்து எனக்கு ஓர் உதவியாளரை - எனது சகோதரர் ஹாரூனை - நியமிப்பாயாக.) இதுவும் மூஸா (அலை) அவர்கள் தமக்காக அன்றிப் பிறருக்காகக் கேட்ட ஒரு கோரிக்கையாகும். அது தமது சகோதரர் ஹாரூன் (அலை) அவர்களின் உதவிக்கான கோரிக்கையாகும். அத்-தவ்ரி (ரழி) அவர்கள் அபூ ஸயீத் (ரழி) வழியாக இக்ரிமா (ரழி) அவர்கள் அறிவிப்பதைக் குறிப்பிடுகிறார்கள்: \"மூஸா (அலை) அவர்கள் நபியாக்கப்பட்ட அதே தருணத்தில் ஹாரூன் (அலை) அவர்களும் நபியாக்கப்பட்டார்கள்\" என்று இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள். இப்னு அபீ ஹாதிம் (ரழி) அவர்கள் பதிவு செய்துள்ள ஒரு அறிவிப்பில்: ஆயிஷா (ரழி) அவர்கள் உம்ரா செய்யும் நோக்கத்தில் வெளியே சென்று சில கிராமப்புற அரபிகளிடம் (பெடோயின்கள்) முகாமிட்டிருந்தார்கள். அங்கே ஒரு மனிதர், \"இவ்வுலகில் எந்தச் சகோதரர் தனது சகோதரருக்கு அதிகப் பயனுள்ளதாக இருந்தார்?\" என்று கேட்டார். அதற்கு மக்கள் \"எங்களுக்குத் தெரியாது\" என்றனர். அப்போது அந்த மனிதர், \"அல்லாஹ்வின் மீது சத்தியமாக எனக்குத் தெரியும்\" என்றார். ஆயிஷா (ரழி) அவர்கள் கூறினார்கள்: \"யார் தனது சகோதரருக்கு அதிகப் பயன் தந்தார் என்பதைத் தான் மட்டுமே அறிந்தவர் போல அவர் சத்தியம் செய்வதைக் கண்டு நான் வியப்படைந்தேன்.\" அந்த மனிதர் சொன்னார், \"அது மூஸா (அலை) அவர்கள்தாம்; அவர் தனது சகோதரருக்கும் நபித்துவம் வழங்கப்பட வேண்டும் என்று கேட்டபோது (அவர் அவ்வாறு திகழ்ந்தார்).\" பிறகு ஆயிஷா (ரழி) அவர்கள், \"அல்லாஹ்வின் மீது சத்தியமாக அவர் உண்மையைத்தான் சொன்னார்\" என்று கூறினார்கள். இதனால்தான் அல்லாஹ் மூஸா (அலை) அவர்களை இவ்வாறு புகழ்கிறான்: ﴾وَكَانَ عِندَ اللَّهِ وَجِيهاً﴿\n\r\n\n\r\n(அவர் அல்லாஹ்விடத்தில் கண்ணியமிக்கவராக இருந்தார்.) (அல்குர்ஆன் 33:69). மூஸா (அலை) அவர்களின் கூற்றான: ﴾اشْدُدْ بِهِ أَزْرِى ﴿\n\r\n\n\r\n(அவரைக் கொண்டு எனது பலத்தை அதிகரிப்பாயாக.) இதன் பொருள், \"எனது முதுகை (பலத்தை) உறுதிப்படுத்துவாயாக\" என்று முஜாஹித் (ரழி) அவர்கள் கூறினார்கள். ﴾وَأَشْرِكْهُ فِى أَمْرِى ﴿\n\r\n\n\r\n(எனது பணியில் அவரைப் பங்குதாரராக்குவாயாக.) அதாவது, இவ்விஷயத்தில் அவரை எனது ஆலோசகராக ஆக்குவாயாக. ﴾كَىْ نُسَبِّحَكَ كَثِيراً - وَنَذْكُرَكَ كَثِيراً ﴿\n\r\n\n\r\n(நாங்கள் உன்னை அதிகமாகத் துதிப்பதற்கும், உன்னை அதிகமாக நினைவு கூர்வதற்கும்.) முஜாஹித் (ரழி) அவர்கள் கூறினார்கள்: \"ஓர் அடியான் நின்ற நிலையிலும், அமர்ந்த நிலையிலும், படுத்த நிலையிலும் அல்லாஹ்வை நினைவு கூராத வரை, அவன் அல்லாஹ்வை அதிகமாக நினைவு கூர்பவர்களில் ஒருவனாகக் கருதப்பட மாட்டான்.\" அவர்களது கூற்றான: ﴾إِنَّكَ كُنتَ بِنَا بَصِيراً ﴿\n\r\n\n\r\n(நிச்சயமாக நீ எங்களை உற்று நோக்குபவனாக இருக்கிறாய்.) இதன் பொருள்: \"எங்களைத் தேர்ந்தெடுத்ததிலும், எங்களுக்குத் தூதுத்துவத்தை வழங்கியதிலும், உனது எதிரியான ஃபிர்அவ்னிடம் எங்களை அனுப்பியதிலும் (நீ எங்களைக் கண்காணிப்பவனாக இருக்கிறாய்)\". எனவே இதற்காக உனக்கே அனைத்துப் புகழும். மேலும், (உனக்கே) அனைத்து அருட்கொடையும் உரியன."},"36":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=39\" class=\"link\">20:39</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:39 ஐ பார்க்கவும்"},"37":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=39\" class=\"link\">20:39</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:39 ஐ பார்க்கவும்"},"38":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=39\" class=\"link\">20:39</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:39 ஐ பார்க்கவும்"},"39":{"html":"<strong>மூஸா (அலை) அவர்களின் பிரார்த்தனை அங்கீகரிக்கப்பட்ட நற்செய்தியும், முந்தைய அருட்கொடைகள் பற்றிய நினைவூட்டலும்</strong><br />\r\n<br />\r\nஇது, தனது இறைவனிடம் மூஸா (அலை) அவர்கள் வேண்டியதற்கு, அல்லாஹ்வின் தூதரான அவர்களுக்கு அல்லாஹ் அளித்த பதிலாகும். மேலும், அவர் மீது அல்லாஹ் புரிந்த முந்தைய அருட்கொடைகளைப் பற்றிய நினைவூட்டலையும் இது கொண்டுள்ளது. முதலாவது (அருட்கொடை), மூஸா (அலை) அவர்களுக்கு அவரது தாயார் பாலூட்டிக் கொண்டிருந்தபோது, ஃபிர்அவ்னும் அவனது தலைவர்களும் அவரைக் கொன்றுவிடுவார்களோ என்று அவர் அஞ்சிய தருணத்தில், அல்லாஹ் அவரது தாயாருக்கு வஹீ (இறைச்செய்தி) மூலம் அறிவித்ததாகும். ஃபிர்அவ்னின் ஆட்கள் ஆண் குழந்தைகள் அனைவரையும் கொன்று கொண்டிருந்த ஒரு ஆண்டில்தான் மூஸா (அலை) அவர்கள் பிறந்தார்கள். ஆகவே, அவர் (தாயார்) குழந்தையை ஒரு பெட்டியில் வைத்து ஆற்றில் போட்டார்கள். ஆறு அவரைக் கொண்டு சென்றது; அல்லாஹ் குறிப்பிட்டது போல, அவரது தாயார் பெரும் கவலையிலும் மனவேதனையிலும் ஆழ்ந்தார்கள்: <span class=\"quran-arabic-font text-success\">﴾وَأَصْبَحَ</span> <span class=\"quran-arabic-font text-success\">فُؤَادُ</span> <span class=\"quran-arabic-font text-success\">أُمِّ</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span> <span class=\"quran-arabic-font text-success\">فَارِغاً</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كَادَتْ</span> <span class=\"quran-arabic-font text-success\">لَتُبْدِى</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">لَوْلا</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">رَّبَطْنَا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">قَلْبِهَا﴿</span><br />\r\n(மூஸாவின் தாயாருடைய இதயம் கவலையால் வெறுமையாகிவிட்டது. நாம் அவரது இதயத்தைப் பலப்படுத்தியிருக்காவிட்டால், அவர் அந்த விஷயத்தை வெளிப்படுத்தியிருப்பார்.) <a href=\"qurandisp.php?sura=28&ayah=10\" class=\"link\">28:10</a> அவ்வாறு, ஆறு அவரை ஃபிர்அவ்னின் இல்லத்திற்குக் கொண்டு சென்றது. <span class=\"quran-arabic-font text-success\">﴾فَالْتَقَطَهُ</span> <span class=\"quran-arabic-font text-success\">آلُ</span> <span class=\"quran-arabic-font text-success\">فِرْعَوْنَ</span> <span class=\"quran-arabic-font text-success\">لِيَكُونَ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَدُوّاً</span> <span class=\"quran-arabic-font text-success\">وَحَزَناً﴿</span><br />\r\n(ஃபிர்அவ்னின் குடும்பத்தினர் அவரைக் கண்டெடுத்தனர்; அவர் அவர்களுக்குப் பகையாகவும் துக்கமாகவும் முடிவதற்காக.) <a href=\"qurandisp.php?sura=28&ayah=8\" class=\"link\">28:8</a> இதன் பொருள், இது அல்லாஹ்வினால் விதிக்கப்பட்ட, தீர்மானிக்கப்பட்ட ஒரு விதியாகும். மூஸா (அலை) அவர்களின் வருகைக்கு அஞ்சி அவர்கள் இஸ்ரவேலர்களின் ஆண் குழந்தைகளைக் கொன்று வந்தனர். எனவே, மகத்தான அதிகாரமும் முழுமையான ஆற்றலும் கொண்ட அல்லாஹ், மூஸா (அலை) அவர்கள் ஃபிர்அவ்னின் சொந்தப் படுக்கையிலேயே வளர வேண்டும் என்று தீர்மானித்தான். அவர் ஃபிர்அவ்னின் உணவு மற்றும் பானங்களை அருந்தி வளர்ந்தார்; அதே சமயம் ஃபிர்அவ்ன் மற்றும் அவனது மனைவியின் அன்பையும் அவர் பெற்றார். இதனால்தான் அல்லாஹ் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾يَأْخُذْهُ</span> <span class=\"quran-arabic-font text-success\">عَدُوٌّ</span> <span class=\"quran-arabic-font text-success\">لِّى</span> <span class=\"quran-arabic-font text-success\">وَعَدُوٌّ</span> <span class=\"quran-arabic-font text-success\">لَّهُ</span> <span class=\"quran-arabic-font text-success\">وَأَلْقَيْتُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكَ</span> <span class=\"quran-arabic-font text-success\">مَحَبَّةً</span> <span class=\"quran-arabic-font text-success\">مِّنِّى﴿</span><br />\r\n(எனக்கும் அவனுக்கும் எதிரியான ஒருவன் அவனை எடுத்துக்கொள்வான். மேலும், உமது மீது என்னிடமிருந்து ஒரு அன்பைப் பொழிந்தேன்.) இதன் பொருள், 'உமது எதிரியே உம்மை நேசிக்குமாறு நான் செய்தேன்' என்பதாகும். ஸலமா பின் குஹைல் அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾وَأَلْقَيْتُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكَ</span> <span class=\"quran-arabic-font text-success\">مَحَبَّةً</span> <span class=\"quran-arabic-font text-success\">مِّنِّى﴿</span><br />\r\n(மேலும், உமது மீது என்னிடமிருந்து ஒரு அன்பைப் பொழிந்தேன்.) 'இதன் பொருள், எனது படைப்புகள் உம்மை நேசிக்கும்படி நான் செய்தேன் என்பதாகும்.' <span class=\"quran-arabic-font text-success\">﴾وَلِتُصْنَعَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">عَيْنِى﴿</span><br />\r\n(நீர் எனது கண்காணிப்பில் வளர்க்கப்படுவதற்காக.) அபூ இம்ரான் அல்-ஜவ்னீ அவர்கள் கூறினார்கள்: 'இதன் பொருள், நீர் அல்லாஹ்வின் கண்காணிப்பில் வளர்க்கப்படுவீர் என்பதாகும்.'<br />\r\n<br />\r\nஅல்லாஹ்வின் இந்தக் கூற்றைப் பொறுத்தவரை: <span class=\"quran-arabic-font text-success\">﴾إِذْ</span> <span class=\"quran-arabic-font text-success\">تَمْشِى</span> <span class=\"quran-arabic-font text-success\">أُخْتُكَ</span> <span class=\"quran-arabic-font text-success\">فَتَقُولُ</span> <span class=\"quran-arabic-font text-success\">هَلْ</span> <span class=\"quran-arabic-font text-success\">أَدُلُّكُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">يَكْفُلُهُ</span> <span class=\"quran-arabic-font text-success\">فَرَجَعْنَاكَ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">أُمِّكَ</span> <span class=\"quran-arabic-font text-success\">كَى</span> <span class=\"quran-arabic-font text-success\">تَقَرَّ</span> <span class=\"quran-arabic-font text-success\">عَيْنُها﴿</span><br />\r\n(உமது சகோதரி நடந்து சென்று, 'அவரைப் பராமரிக்கக்கூடிய ஒருவரைப் பற்றி நான் உங்களுக்கு அறிவிக்கட்டுமா?' என்று கூறியபோது, உமது தாயின் கண்கள் குளிர்ச்சியடைவதற்காக நாம் உம்மை அவரிடமே திரும்பக் கொண்டு வந்தோம்.)<br />\r\n<br />\r\nஃபிர்அவ்னின் இல்லத்தில் அவர் ஏற்றுக்கொள்ளப்பட்டபோது, அவருக்குப் பாலூட்டுவதற்காகச் செவிலித்தாய்மார்கள் வரவழைக்கப்பட்டனர். ஆனால், அவர் அவர்களில் யாரிடமும் பாலருந்த மறுத்துவிட்டார். மேலான அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَحَرَّمْنَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">الْمَرَاضِعَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلُ﴿</span><br />\r\n(அவருக்கு முன்பே செவிலித்தாய்மார்களின் முலைப்பாலை அவருக்கு நாம் தடுத்திருந்தோம்.) <a href=\"qurandisp.php?sura=28&ayah=12\" class=\"link\">28:12</a> பிறகு, அவரது சகோதரி வந்து கூறினாள்: <span class=\"quran-arabic-font text-success\">﴾هَلْ</span> <span class=\"quran-arabic-font text-success\">أَدُلُّكُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَهْلِ</span> <span class=\"quran-arabic-font text-success\">بَيْتٍ</span> <span class=\"quran-arabic-font text-success\">يَكْفُلُونَهُ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">نَاصِحُونَ﴿</span><br />\r\n(உங்களுக்காக அவரைப் பராமரித்து, அவருக்கு நலம் நாடுவோராக இருக்கக்கூடிய ஒரு வீட்டை நான் உங்களுக்குக் காட்டட்டுமா?) <a href=\"qurandisp.php?sura=28&ayah=12\" class=\"link\">28:12</a> அதாவது, 'உங்களுக்காக ஊதியத்திற்கு இவருக்குப் பாலூட்டக்கூடிய ஒருவரை நான் உங்களுக்குக் காட்டட்டுமா?' என்று அவர் கருதினார். எனவே, அவர் குழந்தையை அழைத்துக்கொண்டு அவரது உண்மையான தாயிடம் சென்றார், அவர்களும் (ஃபிர்அவ்னின் ஆட்கள்) அவருடன் சென்றனர். தாயின் மார்பகம் அவருக்குக் கொடுக்கப்பட்டபோது, அவர் அதை ஏற்றுக்கொண்டார். இதைக் கண்டு ஃபிர்அவ்னின் குடும்பத்தினர் மிகுந்த மகிழ்ச்சியடைந்தனர். இதனால், குழந்தைக்குப் பாலூட்ட அவர்கள் அவரையே பணியமர்த்தினார்கள். இதன் மூலம் அவர் (தாயார்) இவ்வுலகிலும், மறுமையிலும் அதைவிட அதிகமாகவும், அவர் (மூஸா அலை) மூலம் பெரும் மகிழ்ச்சியையும் ஆறுதலையும் பெற்றார்கள். மேலான அல்லாஹ் இங்கு கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾فَرَجَعْنَاكَ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">أُمِّكَ</span> <span class=\"quran-arabic-font text-success\">كَى</span> <span class=\"quran-arabic-font text-success\">تَقَرَّ</span> <span class=\"quran-arabic-font text-success\">عَيْنُها</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَحْزَنَ﴿</span><br />\r\n(இவ்வாறு, உமது தாயின் கண்கள் குளிர்ச்சியடைவதற்காகவும், அவர் வருத்தப்படாமல் இருப்பதற்காகவும் உம்மை அவரிடமே நாம் திரும்பக் கொண்டு வந்தோம்.)<br />\r\n<br />\r\nஇதன் பொருள், உமது விஷயத்தில் அவர் கவலைப்படக்கூடாது என்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَقَتَلْتَ</span> <span class=\"quran-arabic-font text-success\">نَفْساً﴿</span><br />\r\n(பின்னர் நீர் ஒரு மனிதரைக் கொன்றீர்,) இதன் பொருள், அவர் ஒரு கிப்தியரைக் (எகிப்து தேசத்தவர், ஃபிர்அவ்னின் கூட்டத்தினர்) கொன்றார் என்பதாகும். <span class=\"quran-arabic-font text-success\">﴾فَنَجَّيْنَاكَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْغَمِّ﴿</span><br />\r\n(ஆனால், நாம் உம்மைப் பெரும் கவலையிலிருந்து காப்பாற்றினோம்.) ஃபிர்அவ்னின் குடும்பத்தினர் அவரைக் கொல்ல எண்ணியதால் அவர் அடைந்த மனத்துயரத்தையே இது குறிக்கிறது. ஆகவே, அவர் அவர்களிடமிருந்து தப்பித்து மத்யன் மக்களின் நீர்நிலைக்குச் சென்றார். அங்குதான் அந்த நல்ல மனிதர் அவரிடம் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾لاَ</span> <span class=\"quran-arabic-font text-success\">تَخَفْ</span> <span class=\"quran-arabic-font text-success\">نَجَوْتَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْقَوْمِ</span> <span class=\"quran-arabic-font text-success\">الظَّالِمِينَ﴿</span><br />\r\n(நீர் அஞ்சாதீர்! அநியாயக்கார மக்களிடமிருந்து நீர் தப்பித்துவிட்டீர்.) <a href=\"qurandisp.php?sura=28&ayah=25\" class=\"link\">28:25</a><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَفَتَنَّاكَ</span> <span class=\"quran-arabic-font text-success\">فُتُوناً﴿</span><br />\r\n(மேலும், நாம் உம்மைப் பல சோதனைகளால் சோதித்தோம்.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَلَبِثْتَ</span> <span class=\"quran-arabic-font text-success\">سِنِينَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">أَهْلِ</span> <span class=\"quran-arabic-font text-success\">مَدْيَنَ﴿</span><br />\r\n(பிறகு நீர் மத்யன் மக்களுடன் பல ஆண்டுகள் தங்கினீர்.) அதாவது, அங்கு நீர் ஆடு மேய்த்துக் கொண்டிருந்தீர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾ثُمَّ</span> <span class=\"quran-arabic-font text-success\">جِئْتَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">قَدَرٍ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">مُوسَى﴿</span><br />\r\n(மூஸாவே! பின்னர் நீர் (நமது) திட்டப்படியே (இங்கு) வந்து சேர்ந்தீர்.) அதாவது, நான் நாடிய, எனக்குத் தெரிந்த அந்தக் குறிப்பிட்ட நேரத்தில்தான்.<br />\r\n<br />","text":"மூஸா (அலை) அவர்களின் பிரார்த்தனை அங்கீகரிக்கப்பட்ட நற்செய்தியும், முந்தைய அருட்கொடைகள் பற்றிய நினைவூட்டலும்\n\r\n\n\r\nஇது, தனது இறைவனிடம் மூஸா (அலை) அவர்கள் வேண்டியதற்கு, அல்லாஹ்வின் தூதரான அவர்களுக்கு அல்லாஹ் அளித்த பதிலாகும். மேலும், அவர் மீது அல்லாஹ் புரிந்த முந்தைய அருட்கொடைகளைப் பற்றிய நினைவூட்டலையும் இது கொண்டுள்ளது. முதலாவது (அருட்கொடை), மூஸா (அலை) அவர்களுக்கு அவரது தாயார் பாலூட்டிக் கொண்டிருந்தபோது, ஃபிர்அவ்னும் அவனது தலைவர்களும் அவரைக் கொன்றுவிடுவார்களோ என்று அவர் அஞ்சிய தருணத்தில், அல்லாஹ் அவரது தாயாருக்கு வஹீ (இறைச்செய்தி) மூலம் அறிவித்ததாகும். ஃபிர்அவ்னின் ஆட்கள் ஆண் குழந்தைகள் அனைவரையும் கொன்று கொண்டிருந்த ஒரு ஆண்டில்தான் மூஸா (அலை) அவர்கள் பிறந்தார்கள். ஆகவே, அவர் (தாயார்) குழந்தையை ஒரு பெட்டியில் வைத்து ஆற்றில் போட்டார்கள். ஆறு அவரைக் கொண்டு சென்றது; அல்லாஹ் குறிப்பிட்டது போல, அவரது தாயார் பெரும் கவலையிலும் மனவேதனையிலும் ஆழ்ந்தார்கள்: ﴾وَأَصْبَحَ فُؤَادُ أُمِّ مُوسَى فَارِغاً إِن كَادَتْ لَتُبْدِى بِهِ لَوْلا أَن رَّبَطْنَا عَلَى قَلْبِهَا﴿\n\r\n(மூஸாவின் தாயாருடைய இதயம் கவலையால் வெறுமையாகிவிட்டது. நாம் அவரது இதயத்தைப் பலப்படுத்தியிருக்காவிட்டால், அவர் அந்த விஷயத்தை வெளிப்படுத்தியிருப்பார்.) 28:10 அவ்வாறு, ஆறு அவரை ஃபிர்அவ்னின் இல்லத்திற்குக் கொண்டு சென்றது. ﴾فَالْتَقَطَهُ آلُ فِرْعَوْنَ لِيَكُونَ لَهُمْ عَدُوّاً وَحَزَناً﴿\n\r\n(ஃபிர்அவ்னின் குடும்பத்தினர் அவரைக் கண்டெடுத்தனர்; அவர் அவர்களுக்குப் பகையாகவும் துக்கமாகவும் முடிவதற்காக.) 28:8 இதன் பொருள், இது அல்லாஹ்வினால் விதிக்கப்பட்ட, தீர்மானிக்கப்பட்ட ஒரு விதியாகும். மூஸா (அலை) அவர்களின் வருகைக்கு அஞ்சி அவர்கள் இஸ்ரவேலர்களின் ஆண் குழந்தைகளைக் கொன்று வந்தனர். எனவே, மகத்தான அதிகாரமும் முழுமையான ஆற்றலும் கொண்ட அல்லாஹ், மூஸா (அலை) அவர்கள் ஃபிர்அவ்னின் சொந்தப் படுக்கையிலேயே வளர வேண்டும் என்று தீர்மானித்தான். அவர் ஃபிர்அவ்னின் உணவு மற்றும் பானங்களை அருந்தி வளர்ந்தார்; அதே சமயம் ஃபிர்அவ்ன் மற்றும் அவனது மனைவியின் அன்பையும் அவர் பெற்றார். இதனால்தான் அல்லாஹ் கூறினான்: ﴾يَأْخُذْهُ عَدُوٌّ لِّى وَعَدُوٌّ لَّهُ وَأَلْقَيْتُ عَلَيْكَ مَحَبَّةً مِّنِّى﴿\n\r\n(எனக்கும் அவனுக்கும் எதிரியான ஒருவன் அவனை எடுத்துக்கொள்வான். மேலும், உமது மீது என்னிடமிருந்து ஒரு அன்பைப் பொழிந்தேன்.) இதன் பொருள், 'உமது எதிரியே உம்மை நேசிக்குமாறு நான் செய்தேன்' என்பதாகும். ஸலமா பின் குஹைல் அவர்கள் கூறினார்கள்: ﴾وَأَلْقَيْتُ عَلَيْكَ مَحَبَّةً مِّنِّى﴿\n\r\n(மேலும், உமது மீது என்னிடமிருந்து ஒரு அன்பைப் பொழிந்தேன்.) 'இதன் பொருள், எனது படைப்புகள் உம்மை நேசிக்கும்படி நான் செய்தேன் என்பதாகும்.' ﴾وَلِتُصْنَعَ عَلَى عَيْنِى﴿\n\r\n(நீர் எனது கண்காணிப்பில் வளர்க்கப்படுவதற்காக.) அபூ இம்ரான் அல்-ஜவ்னீ அவர்கள் கூறினார்கள்: 'இதன் பொருள், நீர் அல்லாஹ்வின் கண்காணிப்பில் வளர்க்கப்படுவீர் என்பதாகும்.'\n\r\n\n\r\nஅல்லாஹ்வின் இந்தக் கூற்றைப் பொறுத்தவரை: ﴾إِذْ تَمْشِى أُخْتُكَ فَتَقُولُ هَلْ أَدُلُّكُمْ عَلَى مَن يَكْفُلُهُ فَرَجَعْنَاكَ إِلَى أُمِّكَ كَى تَقَرَّ عَيْنُها﴿\n\r\n(உமது சகோதரி நடந்து சென்று, 'அவரைப் பராமரிக்கக்கூடிய ஒருவரைப் பற்றி நான் உங்களுக்கு அறிவிக்கட்டுமா?' என்று கூறியபோது, உமது தாயின் கண்கள் குளிர்ச்சியடைவதற்காக நாம் உம்மை அவரிடமே திரும்பக் கொண்டு வந்தோம்.)\n\r\n\n\r\nஃபிர்அவ்னின் இல்லத்தில் அவர் ஏற்றுக்கொள்ளப்பட்டபோது, அவருக்குப் பாலூட்டுவதற்காகச் செவிலித்தாய்மார்கள் வரவழைக்கப்பட்டனர். ஆனால், அவர் அவர்களில் யாரிடமும் பாலருந்த மறுத்துவிட்டார். மேலான அல்லாஹ் கூறுகிறான்: ﴾وَحَرَّمْنَا عَلَيْهِ الْمَرَاضِعَ مِن قَبْلُ﴿\n\r\n(அவருக்கு முன்பே செவிலித்தாய்மார்களின் முலைப்பாலை அவருக்கு நாம் தடுத்திருந்தோம்.) 28:12 பிறகு, அவரது சகோதரி வந்து கூறினாள்: ﴾هَلْ أَدُلُّكُمْ عَلَى أَهْلِ بَيْتٍ يَكْفُلُونَهُ لَكُمْ وَهُمْ لَهُ نَاصِحُونَ﴿\n\r\n(உங்களுக்காக அவரைப் பராமரித்து, அவருக்கு நலம் நாடுவோராக இருக்கக்கூடிய ஒரு வீட்டை நான் உங்களுக்குக் காட்டட்டுமா?) 28:12 அதாவது, 'உங்களுக்காக ஊதியத்திற்கு இவருக்குப் பாலூட்டக்கூடிய ஒருவரை நான் உங்களுக்குக் காட்டட்டுமா?' என்று அவர் கருதினார். எனவே, அவர் குழந்தையை அழைத்துக்கொண்டு அவரது உண்மையான தாயிடம் சென்றார், அவர்களும் (ஃபிர்அவ்னின் ஆட்கள்) அவருடன் சென்றனர். தாயின் மார்பகம் அவருக்குக் கொடுக்கப்பட்டபோது, அவர் அதை ஏற்றுக்கொண்டார். இதைக் கண்டு ஃபிர்அவ்னின் குடும்பத்தினர் மிகுந்த மகிழ்ச்சியடைந்தனர். இதனால், குழந்தைக்குப் பாலூட்ட அவர்கள் அவரையே பணியமர்த்தினார்கள். இதன் மூலம் அவர் (தாயார்) இவ்வுலகிலும், மறுமையிலும் அதைவிட அதிகமாகவும், அவர் (மூஸா அலை) மூலம் பெரும் மகிழ்ச்சியையும் ஆறுதலையும் பெற்றார்கள். மேலான அல்லாஹ் இங்கு கூறுகிறான்: ﴾فَرَجَعْنَاكَ إِلَى أُمِّكَ كَى تَقَرَّ عَيْنُها وَلاَ تَحْزَنَ﴿\n\r\n(இவ்வாறு, உமது தாயின் கண்கள் குளிர்ச்சியடைவதற்காகவும், அவர் வருத்தப்படாமல் இருப்பதற்காகவும் உம்மை அவரிடமே நாம் திரும்பக் கொண்டு வந்தோம்.)\n\r\n\n\r\nஇதன் பொருள், உமது விஷயத்தில் அவர் கவலைப்படக்கூடாது என்பதாகும்.\n\r\n\n\r\n﴾وَقَتَلْتَ نَفْساً﴿\n\r\n(பின்னர் நீர் ஒரு மனிதரைக் கொன்றீர்,) இதன் பொருள், அவர் ஒரு கிப்தியரைக் (எகிப்து தேசத்தவர், ஃபிர்அவ்னின் கூட்டத்தினர்) கொன்றார் என்பதாகும். ﴾فَنَجَّيْنَاكَ مِنَ الْغَمِّ﴿\n\r\n(ஆனால், நாம் உம்மைப் பெரும் கவலையிலிருந்து காப்பாற்றினோம்.) ஃபிர்அவ்னின் குடும்பத்தினர் அவரைக் கொல்ல எண்ணியதால் அவர் அடைந்த மனத்துயரத்தையே இது குறிக்கிறது. ஆகவே, அவர் அவர்களிடமிருந்து தப்பித்து மத்யன் மக்களின் நீர்நிலைக்குச் சென்றார். அங்குதான் அந்த நல்ல மனிதர் அவரிடம் கூறினார்கள்: ﴾لاَ تَخَفْ نَجَوْتَ مِنَ الْقَوْمِ الظَّالِمِينَ﴿\n\r\n(நீர் அஞ்சாதீர்! அநியாயக்கார மக்களிடமிருந்து நீர் தப்பித்துவிட்டீர்.) 28:25\n\r\n\n\r\n﴾وَفَتَنَّاكَ فُتُوناً﴿\n\r\n(மேலும், நாம் உம்மைப் பல சோதனைகளால் சோதித்தோம்.)\n\r\n\n\r\n﴾فَلَبِثْتَ سِنِينَ فِى أَهْلِ مَدْيَنَ﴿\n\r\n(பிறகு நீர் மத்யன் மக்களுடன் பல ஆண்டுகள் தங்கினீர்.) அதாவது, அங்கு நீர் ஆடு மேய்த்துக் கொண்டிருந்தீர்.\n\r\n\n\r\n﴾ثُمَّ جِئْتَ عَلَى قَدَرٍ يَا مُوسَى﴿\n\r\n(மூஸாவே! பின்னர் நீர் (நமது) திட்டப்படியே (இங்கு) வந்து சேர்ந்தீர்.) அதாவது, நான் நாடிய, எனக்குத் தெரிந்த அந்தக் குறிப்பிட்ட நேரத்தில்தான்."},"40":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=44\" class=\"link\">20:44</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:44 ஐ பார்க்கவும்"},"41":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=44\" class=\"link\">20:44</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:44 ஐ பார்க்கவும்"},"42":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=44\" class=\"link\">20:44</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:44 ஐ பார்க்கவும்"},"43":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=44\" class=\"link\">20:44</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:44 ஐ பார்க்கவும்"},"44":{"html":"<strong>ஃபிர்அவ்னிடம் செல்ல மூஸாவைத் தேர்ந்தெடுத்தலும், அவரிடம் மென்மையாகவும் கனிவாகவும் அழைப்பு விடுக்குமாறு பணித்தலும்</strong><br />\r\n<br />\r\nஉயர்ந்தோனாகிய அல்லாஹ், மூஸா (அலை) அவர்களிடம் உரையாற்றுகையில், அவர் ஃபிர்அவ்னையும் அவனது பிரதானிகளையும் தவிர்த்து மத்யன் மக்களிடையே வாழ்ந்ததைக் குறிப்பிடுகிறான். மூஸா (அலை) தனது மாமனாருக்காக நிர்ணயிக்கப்பட்ட காலம் முடியும் வரை ஒரு மேய்ப்பராகப் பணியாற்றினார். அதன் பிறகு, அவர் எவ்விதமான முன்கூட்டியத் திட்டமுமின்றி, அல்லாஹ்வின் தீர்ப்பையும் அவனது முன்நிர்ணயிக்கப்பட்ட நாட்டத்தையும் சந்திக்க நேர்ந்தது. இந்த முழுச் சூழலும் புகழுக்குரியவனும், மிக உயர்ந்தோனுமாகிய அல்லாஹ்வின் கட்டுப்பாட்டில் இருந்தது. அவன் தனது அடியார்களையும் படைப்புகளையும் தான் நாடுகின்ற முடிவின் பக்கம் செலுத்துகிறான். இதனால்தான் அல்லாஹ் இவ்வாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">جِئْتَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">قَدَرٍ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span><br />\r\n<br />\r\n(மூஸாவே! பிறகு, (உமக்காக) நான் நிர்ணயித்திருந்த ஒரு கால அளவின்படி நீர் இங்கு வந்தீர்.) \"நிர்ணயிக்கப்பட்ட ஒரு சந்திப்பு நேரத்திற்காக\" என்று முஜாஹித் அவர்கள் கூறுகிறார்கள். கதாதா (ரழி) அவர்கள் கூறியதாக மஃமர் அவர்களிடமிருந்து அப்துர் ரஸ்ஸாக் அவர்கள் பின்வருமாறு பதிவு செய்துள்ளார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">جِئْتَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">قَدَرٍ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span><br />\r\n<br />\r\n(மூஸாவே! பிறகு, (உமக்காக) நான் நிர்ணயித்திருந்த ஒரு கால அளவின்படி நீர் இங்கு வந்தீர்.) \"தூதுத்துவத்திற்கும் நபித்துவத்திற்குமான விதிப்படி.\" அல்லாஹ்வின் கூற்றைப் பற்றி:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاصْطَنَعْتُكَ</span> <span class=\"quran-arabic-font text-success\">لِنَفْسِى</span><br />\r\n<br />\r\n(மேலும், நான் உம்மை எனக்காகவே தேர்ந்தெடுத்துக் கொண்டேன்.) \"எனது தூதராக இருப்பதற்காக நான் உம்மைத் தேர்ந்தெடுத்துக் கொண்டேன். இது எனது விருப்பப்படியும் எனது நாட்டப்படியும் அமைந்ததாகும்\" என்பது இதன் பொருளாகும். இந்த வசனத்தின் தஃப்ஸீரைப் பற்றி அல்-புகாரி (ரஹ்) அவர்கள் பதிவு செய்துள்ள ஒரு ஹதீஸில், அபூ ஹுரைரா (ரழி) அவர்கள் அறிவிக்கிறார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">الْتَقَى</span> <span class=\"quran-arabic-font text-success\">آدَمُ</span> <span class=\"quran-arabic-font text-success\">وَمُوسَى</span> <span class=\"quran-arabic-font text-success\">فَقَالَ</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span>: <span class=\"quran-arabic-font text-success\">أَنْتَ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">أَشْقَيْتَ</span> <span class=\"quran-arabic-font text-success\">النَّاسَ</span> <span class=\"quran-arabic-font text-success\">وَأَخْرَجْتَهُمْ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ،</span> <span class=\"quran-arabic-font text-success\">فَقَالَ</span> <span class=\"quran-arabic-font text-success\">آدَمُ</span>: <span class=\"quran-arabic-font text-success\">وَأَنْتَ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">اصْطَفَاكَ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">بِرِسَالَتِهِ</span> <span class=\"quran-arabic-font text-success\">وَاصْطَفَاكَ</span> <span class=\"quran-arabic-font text-success\">لِنَفْسِهِ،</span> <span class=\"quran-arabic-font text-success\">وَأَنْزَلَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكَ</span> <span class=\"quran-arabic-font text-success\">التَّوْرَاةَ؟</span> <span class=\"quran-arabic-font text-success\">قَالَ</span>: <span class=\"quran-arabic-font text-success\">نَعَمْ،</span> <span class=\"quran-arabic-font text-success\">قَالَ</span>: <span class=\"quran-arabic-font text-success\">فَوَجَدْتَهُ</span> <span class=\"quran-arabic-font text-success\">مَكْتُوبًا</span> <span class=\"quran-arabic-font text-success\">عَلَيَّ</span> <span class=\"quran-arabic-font text-success\">قَبْلَ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يَخْلُقَنِي</span> <span class=\"quran-arabic-font text-success\">بِأَرْبَعِينَ</span> <span class=\"quran-arabic-font text-success\">سَنَةً؟</span> <span class=\"quran-arabic-font text-success\">قَالَ</span>: <span class=\"quran-arabic-font text-success\">نَعَمْ،</span> <span class=\"quran-arabic-font text-success\">فَحَجَّ</span> <span class=\"quran-arabic-font text-success\">آدَمُ</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span>»<br />\r\n<br />\r\n(ஆதம் (அலை) அவர்களும் மூஸா (அலை) அவர்களும் சந்தித்தார்கள். அப்போது மூஸா (அலை) அவர்கள், \"நீங்கள்தானே மனிதர்களைச் சிரமத்திற்குள்ளாக்கி, அவர்களைச் சொர்க்கத்திலிருந்து வெளியேறக் காரணமாக இருந்தவர்?\" என்று கேட்டார்கள். அதற்கு ஆதம் (அலை) அவர்கள், \"அல்லாஹ் தனது தூதுச் செய்திக்காகத் தேர்ந்தெடுத்து, தனக்காகவே உம்மைத் தெரிவு செய்து, உமக்குத் தவ்ராத் வேதத்தையும் அருளினானே, அந்த மூஸா நீர்தானே?\" என்று கேட்டார்கள். மூஸா (அலை) அவர்கள் \"ஆம்\" என்றார்கள். பிறகு ஆதம் (அலை) அவர்கள், \"அல்லாஹ் என்னைப் படைப்பதற்கு நாற்பது ஆண்டுகளுக்கு முன்பே இது எனக்கு விதிக்கப்பட்டிருந்தது என்பதை (உமது வேதத்தில்) கண்டீரா?\" என்று கேட்டார்கள். மூஸா (அலை) அவர்கள் \"ஆம்\" என்று பதிலளித்தார்கள். இவ்வாறு ஆதம் (அலை) அவர்கள் மூஸா (அலை) அவர்களின் வாதத்தை வென்றார்கள்.) இந்தச் செய்தியை அல்-புகாரி மற்றும் முஸ்லிம் ஆகிய இருவரும் பதிவு செய்துள்ளனர். அல்லாஹ்வின் கூற்றைப் பற்றி:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">اذْهَبْ</span> <span class=\"quran-arabic-font text-success\">أَنتَ</span> <span class=\"quran-arabic-font text-success\">وَأَخُوكَ</span> <span class=\"quran-arabic-font text-success\">بِآيَاتِي</span><br />\r\n<br />\r\n(நீரும் உமது சகோதரரும் எனது அத்தாட்சிகளுடன் செல்லுங்கள்.) இது எனது சான்றுகள், ஆதாரங்கள் மற்றும் அற்புதங்களுடன் செல்லுங்கள் என்பதைக் குறிக்கும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَنِيَا</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">ذِكْرِى</span><br />\r\n<br />\r\n(மேலும், நீங்கள் இருவரும் என்னை நினைவுகூர்வதில் (திக்ர் செய்வதில்) தளர்ந்துவிடாதீர்கள்.) \"இதன் பொருள் மந்தமாக இருக்காதீர்கள்\" என்று இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அலீ பின் அபீ தல்ஹா (ரழி) அவர்கள் அறிவிக்கிறார்கள். \"இதன் பொருள் பலவீனமடையாதீர்கள்\" என்று இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக முஜாஹித் அவர்கள் அறிவிக்கிறார்கள். அதாவது, அவர்கள் அல்லாஹ்வின் திக்ரில் சோர்வடையக் கூடாது என்பதாகும். மாறாக, ஃபிர்அவ்னைச் சந்திக்கும்போது அவர்கள் இருவரும் அல்லாஹ்வை அதிகம் நினைவுகூர வேண்டும்; அப்போதுதான் அல்லாஹ்வின் அந்த நினைவு அவனுக்கு எதிராக அவர்களுக்கு உதவியாக இருக்கும். அல்லாஹ்வின் திக்ர் அவர்களை வலிமைப்படுத்தி, அவனைத் தோற்கடிக்க உதவும் ஆற்றலாகத் திகழும். அல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">اذْهَبَا</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">فِرْعَوْنَ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">طَغَى</span><br />\r\n<br />\r\n(நீங்கள் இருவரும் ஃபிர்அவ்னிடம் செல்லுங்கள்; நிச்சயமாக அவன் வரம்பு மீறிவிட்டான்.) அதாவது அவன் கலகம் செய்து, அல்லாஹ்வுக்கு எதிராகப் பெருமையும் அகந்தையும் கொண்டு, அவனுக்குக் கீழ்ப்படியாமல் மறுத்துவிட்டான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَقُولاَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">قَوْلاً</span> <span class=\"quran-arabic-font text-success\">لَّيِّناً</span> <span class=\"quran-arabic-font text-success\">لَّعَلَّهُ</span> <span class=\"quran-arabic-font text-success\">يَتَذَكَّرُ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">يَخْشَى</span><br />\r\n<br />\r\n(மேலும் அவனிடம் மென்மையான முறையில் பேசுங்கள்; அவன் அறிவுரை பெறலாம் அல்லது (அல்லாஹ்வுக்கு) அஞ்சலாம்.) இந்த வசனத்தில் ஒரு மகத்தான பாடம் பொதிந்துள்ளது. ஃபிர்அவ்ன் மனிதர்களிலேயே மிகவும் அகந்தை கொண்டவனாகவும் ஆணவம் பிடித்தவனாகவும் இருந்த போதிலும், அதே சமயம் மூஸா (அலை) அவர்கள் அக்காலத்தில் அல்லாஹ்வின் படைப்புகளில் அவனது நேசராக இருந்த போதிலும், மூஸா (அலை) அவர்கள் ஃபிர்அவ்னிடம் மென்மையாகவும் கனிவாகவும் பேச வேண்டும் என்றே கட்டளையிடப்பட்டார்கள். எனவே, அவர்களது அழைப்பானது ஒரு நெருங்கிய நண்பரிடம் பேசுவது போன்ற மென்மையான மற்றும் எளிமையான நடையில் அமைந்திருந்தது. அப்போதுதான் அந்தச் செய்தி உள்ளங்களில் அதிகத் தாக்கத்தை ஏற்படுத்தும், மேலும் ஆழமான நற்பயன்களைத் தரும். இதனை உயர்ந்தோனாகிய அல்லாஹ் வேறொரு வசனத்தில் இவ்வாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ادْعُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">سَبِيلِ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">بِالْحِكْمَةِ</span> <span class=\"quran-arabic-font text-success\">وَالْمَوْعِظَةِ</span> <span class=\"quran-arabic-font text-success\">الْحَسَنَةِ</span> <span class=\"quran-arabic-font text-success\">وَجَـدِلْهُم</span> <span class=\"quran-arabic-font text-success\">بِالَّتِى</span> <span class=\"quran-arabic-font text-success\">هِىَ</span> <span class=\"quran-arabic-font text-success\">أَحْسَنُ</span><br />\r\n<br />\r\n(ஞானத்துடனும் அழகான அறிவுரையுடனும் உமது இறைவனின் வழியின் பக்கம் (மனிதர்களை) அழைப்பீராக; மேலும் அவர்களுடன் மிக அழகான முறையில் விவாதம் செய்வீராக.) <a href=\"qurandisp.php?sura=16&ayah=125\" class=\"link\">16:125</a> அல்லாஹ்வின் கூற்றைப் பற்றி:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَّعَلَّهُ</span> <span class=\"quran-arabic-font text-success\">يَتَذَكَّرُ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">يَخْشَى</span><br />\r\n<br />\r\n(அவன் அறிவுரை பெறலாம் அல்லது (அல்லாஹ்வுக்கு) அஞ்சலாம்.) அதாவது தான் இருக்கும் வழிகேட்டிலிருந்தும் அழிவிலிருந்தும் அவன் ஒருவேளை திருந்தி வரலாம்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">يَخْشَى</span><br />\r\n<br />\r\n(அல்லது அவன் அஞ்சுவான்) அதாவது இறை அச்சத்தின் காரணமாக அவன் கீழ்ப்படிபவனாக மாறக்கூடும். இதனை அல்லாஹ் இவ்வாறு குறிப்பிடுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِّمَنْ</span> <span class=\"quran-arabic-font text-success\">أَرَادَ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَذَّكَّرَ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">أَرَادَ</span> <span class=\"quran-arabic-font text-success\">شُكُوراً</span><br />\r\n<br />\r\n(நினைவுகூர விரும்புபவனுக்காக அல்லது நன்றியறிதலை வெளிப்படுத்த விரும்புபவனுக்காக.) <a href=\"qurandisp.php?sura=25&ayah=62\" class=\"link\">25:62</a> ஆகவே, நினைவுகூருதல் என்பது ஆபத்தான பாதையிலிருந்து திரும்புவதைக் குறிக்கிறது; அஞ்சுதல் என்பது கீழ்ப்படிதலை அடைவதைக் குறிக்கிறது.<br />\r\n<br />","text":"ஃபிர்அவ்னிடம் செல்ல மூஸாவைத் தேர்ந்தெடுத்தலும், அவரிடம் மென்மையாகவும் கனிவாகவும் அழைப்பு விடுக்குமாறு பணித்தலும்\n\r\n\n\r\nஉயர்ந்தோனாகிய அல்லாஹ், மூஸா (அலை) அவர்களிடம் உரையாற்றுகையில், அவர் ஃபிர்அவ்னையும் அவனது பிரதானிகளையும் தவிர்த்து மத்யன் மக்களிடையே வாழ்ந்ததைக் குறிப்பிடுகிறான். மூஸா (அலை) தனது மாமனாருக்காக நிர்ணயிக்கப்பட்ட காலம் முடியும் வரை ஒரு மேய்ப்பராகப் பணியாற்றினார். அதன் பிறகு, அவர் எவ்விதமான முன்கூட்டியத் திட்டமுமின்றி, அல்லாஹ்வின் தீர்ப்பையும் அவனது முன்நிர்ணயிக்கப்பட்ட நாட்டத்தையும் சந்திக்க நேர்ந்தது. இந்த முழுச் சூழலும் புகழுக்குரியவனும், மிக உயர்ந்தோனுமாகிய அல்லாஹ்வின் கட்டுப்பாட்டில் இருந்தது. அவன் தனது அடியார்களையும் படைப்புகளையும் தான் நாடுகின்ற முடிவின் பக்கம் செலுத்துகிறான். இதனால்தான் அல்லாஹ் இவ்வாறு கூறுகிறான்:\n\r\n\n\r\nثُمَّ جِئْتَ عَلَى قَدَرٍ يَا مُوسَى\n\r\n\n\r\n(மூஸாவே! பிறகு, (உமக்காக) நான் நிர்ணயித்திருந்த ஒரு கால அளவின்படி நீர் இங்கு வந்தீர்.) \"நிர்ணயிக்கப்பட்ட ஒரு சந்திப்பு நேரத்திற்காக\" என்று முஜாஹித் அவர்கள் கூறுகிறார்கள். கதாதா (ரழி) அவர்கள் கூறியதாக மஃமர் அவர்களிடமிருந்து அப்துர் ரஸ்ஸாக் அவர்கள் பின்வருமாறு பதிவு செய்துள்ளார்கள்:\n\r\n\n\r\nثُمَّ جِئْتَ عَلَى قَدَرٍ يَا مُوسَى\n\r\n\n\r\n(மூஸாவே! பிறகு, (உமக்காக) நான் நிர்ணயித்திருந்த ஒரு கால அளவின்படி நீர் இங்கு வந்தீர்.) \"தூதுத்துவத்திற்கும் நபித்துவத்திற்குமான விதிப்படி.\" அல்லாஹ்வின் கூற்றைப் பற்றி:\n\r\n\n\r\nوَاصْطَنَعْتُكَ لِنَفْسِى\n\r\n\n\r\n(மேலும், நான் உம்மை எனக்காகவே தேர்ந்தெடுத்துக் கொண்டேன்.) \"எனது தூதராக இருப்பதற்காக நான் உம்மைத் தேர்ந்தெடுத்துக் கொண்டேன். இது எனது விருப்பப்படியும் எனது நாட்டப்படியும் அமைந்ததாகும்\" என்பது இதன் பொருளாகும். இந்த வசனத்தின் தஃப்ஸீரைப் பற்றி அல்-புகாரி (ரஹ்) அவர்கள் பதிவு செய்துள்ள ஒரு ஹதீஸில், அபூ ஹுரைரா (ரழி) அவர்கள் அறிவிக்கிறார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«الْتَقَى آدَمُ وَمُوسَى فَقَالَ مُوسَى: أَنْتَ الَّذِي أَشْقَيْتَ النَّاسَ وَأَخْرَجْتَهُمْ مِنَ الْجَنَّةِ، فَقَالَ آدَمُ: وَأَنْتَ الَّذِي اصْطَفَاكَ اللهُ بِرِسَالَتِهِ وَاصْطَفَاكَ لِنَفْسِهِ، وَأَنْزَلَ عَلَيْكَ التَّوْرَاةَ؟ قَالَ: نَعَمْ، قَالَ: فَوَجَدْتَهُ مَكْتُوبًا عَلَيَّ قَبْلَ أَنْ يَخْلُقَنِي بِأَرْبَعِينَ سَنَةً؟ قَالَ: نَعَمْ، فَحَجَّ آدَمُ مُوسَى»\n\r\n\n\r\n(ஆதம் (அலை) அவர்களும் மூஸா (அலை) அவர்களும் சந்தித்தார்கள். அப்போது மூஸா (அலை) அவர்கள், \"நீங்கள்தானே மனிதர்களைச் சிரமத்திற்குள்ளாக்கி, அவர்களைச் சொர்க்கத்திலிருந்து வெளியேறக் காரணமாக இருந்தவர்?\" என்று கேட்டார்கள். அதற்கு ஆதம் (அலை) அவர்கள், \"அல்லாஹ் தனது தூதுச் செய்திக்காகத் தேர்ந்தெடுத்து, தனக்காகவே உம்மைத் தெரிவு செய்து, உமக்குத் தவ்ராத் வேதத்தையும் அருளினானே, அந்த மூஸா நீர்தானே?\" என்று கேட்டார்கள். மூஸா (அலை) அவர்கள் \"ஆம்\" என்றார்கள். பிறகு ஆதம் (அலை) அவர்கள், \"அல்லாஹ் என்னைப் படைப்பதற்கு நாற்பது ஆண்டுகளுக்கு முன்பே இது எனக்கு விதிக்கப்பட்டிருந்தது என்பதை (உமது வேதத்தில்) கண்டீரா?\" என்று கேட்டார்கள். மூஸா (அலை) அவர்கள் \"ஆம்\" என்று பதிலளித்தார்கள். இவ்வாறு ஆதம் (அலை) அவர்கள் மூஸா (அலை) அவர்களின் வாதத்தை வென்றார்கள்.) இந்தச் செய்தியை அல்-புகாரி மற்றும் முஸ்லிம் ஆகிய இருவரும் பதிவு செய்துள்ளனர். அல்லாஹ்வின் கூற்றைப் பற்றி:\n\r\n\n\r\nاذْهَبْ أَنتَ وَأَخُوكَ بِآيَاتِي\n\r\n\n\r\n(நீரும் உமது சகோதரரும் எனது அத்தாட்சிகளுடன் செல்லுங்கள்.) இது எனது சான்றுகள், ஆதாரங்கள் மற்றும் அற்புதங்களுடன் செல்லுங்கள் என்பதைக் குறிக்கும்.\n\r\n\n\r\nوَلاَ تَنِيَا فِى ذِكْرِى\n\r\n\n\r\n(மேலும், நீங்கள் இருவரும் என்னை நினைவுகூர்வதில் (திக்ர் செய்வதில்) தளர்ந்துவிடாதீர்கள்.) \"இதன் பொருள் மந்தமாக இருக்காதீர்கள்\" என்று இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அலீ பின் அபீ தல்ஹா (ரழி) அவர்கள் அறிவிக்கிறார்கள். \"இதன் பொருள் பலவீனமடையாதீர்கள்\" என்று இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக முஜாஹித் அவர்கள் அறிவிக்கிறார்கள். அதாவது, அவர்கள் அல்லாஹ்வின் திக்ரில் சோர்வடையக் கூடாது என்பதாகும். மாறாக, ஃபிர்அவ்னைச் சந்திக்கும்போது அவர்கள் இருவரும் அல்லாஹ்வை அதிகம் நினைவுகூர வேண்டும்; அப்போதுதான் அல்லாஹ்வின் அந்த நினைவு அவனுக்கு எதிராக அவர்களுக்கு உதவியாக இருக்கும். அல்லாஹ்வின் திக்ர் அவர்களை வலிமைப்படுத்தி, அவனைத் தோற்கடிக்க உதவும் ஆற்றலாகத் திகழும். அல்லாஹ்வின் கூற்று:\n\r\n\n\r\nاذْهَبَا إِلَى فِرْعَوْنَ إِنَّهُ طَغَى\n\r\n\n\r\n(நீங்கள் இருவரும் ஃபிர்அவ்னிடம் செல்லுங்கள்; நிச்சயமாக அவன் வரம்பு மீறிவிட்டான்.) அதாவது அவன் கலகம் செய்து, அல்லாஹ்வுக்கு எதிராகப் பெருமையும் அகந்தையும் கொண்டு, அவனுக்குக் கீழ்ப்படியாமல் மறுத்துவிட்டான்.\n\r\n\n\r\nفَقُولاَ لَهُ قَوْلاً لَّيِّناً لَّعَلَّهُ يَتَذَكَّرُ أَوْ يَخْشَى\n\r\n\n\r\n(மேலும் அவனிடம் மென்மையான முறையில் பேசுங்கள்; அவன் அறிவுரை பெறலாம் அல்லது (அல்லாஹ்வுக்கு) அஞ்சலாம்.) இந்த வசனத்தில் ஒரு மகத்தான பாடம் பொதிந்துள்ளது. ஃபிர்அவ்ன் மனிதர்களிலேயே மிகவும் அகந்தை கொண்டவனாகவும் ஆணவம் பிடித்தவனாகவும் இருந்த போதிலும், அதே சமயம் மூஸா (அலை) அவர்கள் அக்காலத்தில் அல்லாஹ்வின் படைப்புகளில் அவனது நேசராக இருந்த போதிலும், மூஸா (அலை) அவர்கள் ஃபிர்அவ்னிடம் மென்மையாகவும் கனிவாகவும் பேச வேண்டும் என்றே கட்டளையிடப்பட்டார்கள். எனவே, அவர்களது அழைப்பானது ஒரு நெருங்கிய நண்பரிடம் பேசுவது போன்ற மென்மையான மற்றும் எளிமையான நடையில் அமைந்திருந்தது. அப்போதுதான் அந்தச் செய்தி உள்ளங்களில் அதிகத் தாக்கத்தை ஏற்படுத்தும், மேலும் ஆழமான நற்பயன்களைத் தரும். இதனை உயர்ந்தோனாகிய அல்லாஹ் வேறொரு வசனத்தில் இவ்வாறு கூறுகிறான்:\n\r\n\n\r\nادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَـدِلْهُم بِالَّتِى هِىَ أَحْسَنُ\n\r\n\n\r\n(ஞானத்துடனும் அழகான அறிவுரையுடனும் உமது இறைவனின் வழியின் பக்கம் (மனிதர்களை) அழைப்பீராக; மேலும் அவர்களுடன் மிக அழகான முறையில் விவாதம் செய்வீராக.) 16:125 அல்லாஹ்வின் கூற்றைப் பற்றி:\n\r\n\n\r\nلَّعَلَّهُ يَتَذَكَّرُ أَوْ يَخْشَى\n\r\n\n\r\n(அவன் அறிவுரை பெறலாம் அல்லது (அல்லாஹ்வுக்கு) அஞ்சலாம்.) அதாவது தான் இருக்கும் வழிகேட்டிலிருந்தும் அழிவிலிருந்தும் அவன் ஒருவேளை திருந்தி வரலாம்,\n\r\n\n\r\nأَوْ يَخْشَى\n\r\n\n\r\n(அல்லது அவன் அஞ்சுவான்) அதாவது இறை அச்சத்தின் காரணமாக அவன் கீழ்ப்படிபவனாக மாறக்கூடும். இதனை அல்லாஹ் இவ்வாறு குறிப்பிடுகிறான்:\n\r\n\n\r\nلِّمَنْ أَرَادَ أَن يَذَّكَّرَ أَوْ أَرَادَ شُكُوراً\n\r\n\n\r\n(நினைவுகூர விரும்புபவனுக்காக அல்லது நன்றியறிதலை வெளிப்படுத்த விரும்புபவனுக்காக.) 25:62 ஆகவே, நினைவுகூருதல் என்பது ஆபத்தான பாதையிலிருந்து திரும்புவதைக் குறிக்கிறது; அஞ்சுதல் என்பது கீழ்ப்படிதலை அடைவதைக் குறிக்கிறது."},"45":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=48\" class=\"link\">20:48</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:48 ஐ பார்க்கவும்"},"46":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=48\" class=\"link\">20:48</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:48 ஐ பார்க்கவும்"},"47":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=48\" class=\"link\">20:48</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:48 ஐ பார்க்கவும்"},"48":{"html":"<strong>3 மூஸா (அலை) அவர்கள் ஃபிர்அவ்னைக் கண்டு அஞ்சுவதும், அல்லாஹ் அவர்களுக்கு மனவலிமை அளிப்பதும்</strong><br />\r\n<br />\r\nஉயர்வானவனான அல்லாஹ், மூஸா (அலை) அவர்களும் ஹாரூன் (அலை) அவர்களும் அல்லாஹ்விடம் மன்றாடி, தங்கள் கவலையை அவனிடம் வெளிப்படுத்தியதை இவ்வாறு தெரிவிக்கிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّنَا</span> <span class=\"quran-arabic-font text-success\">نَخَافُ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَفْرُطَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْنَآ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَطْغَى</span><br />\r\n<br />\r\n(‘நிச்சயமாக, அவன் எங்களுக்கு உடனடித் தண்டனை அளிப்பதற்கோ அல்லது எங்கள் மீது அக்கிரமம் செய்வதற்கோ நாங்கள் அஞ்சுகிறோம்.’) ஃபிர்அவ்ன் தங்களை எதிர்பாராத விதமாகத் தண்டித்து பிடித்துக் கொள்ளலாம் அல்லது தாங்கள் அதற்குத் தகுதியற்றவர்களாக இருந்தும் அவன் தங்களைத் துன்புறுத்துவதன் மூலம் வரம்பு மீறலாம் என்று அவர்கள் கருதினார்கள். இப்னு அப்பாஸ் (ரழி) அவர்கள் அறிவித்ததாக அத்-தஹ்ஹாக் கூறுகிறார்கள்: \"இங்கு வரம்பு மீறுதல் என்பது எல்லைகளைக் கடந்து செல்வதைக் குறிக்கும்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَخَافَآ</span> <span class=\"quran-arabic-font text-success\">إِنَّنِى</span> <span class=\"quran-arabic-font text-success\">مَعَكُمَآ</span> <span class=\"quran-arabic-font text-success\">أَسْمَعُ</span> <span class=\"quran-arabic-font text-success\">وَأَرَى</span><br />\r\n<br />\r\n(அல்லாஹ் கூறினான்: \"அஞ்சாதீர்கள்; நிச்சயமாக நான் உங்கள் இருவருடனும் இருக்கிறேன்; நான் செவியேற்கிறேன், பார்க்கிறேன்.\") இதன் பொருள்; \"அவனுக்கு (ஃபிர்அவ்னுக்கு) அஞ்சாதீர்கள், நிச்சயமாக நான் உங்கள் இருவருடனும் இருக்கிறேன். உங்கள் பேச்சையும் அவனது பேச்சையும் நான் செவியேற்றுக் கொண்டிருக்கிறேன். உங்கள் இருப்பிடத்தையும் அவனது இருப்பிடத்தையும் நான் பார்த்துக் கொண்டிருக்கிறேன். உங்கள் விவகாரங்களில் எதுவும் எனக்கு மறைவானதல்ல. அவனது முன்முடி (நெற்றி) எனது கைவசமே உள்ளது என்பதை அறிந்து கொள்ளுங்கள். எனது அனுமதியின்றி, எனது கட்டளைக்குப் பின்னரே தவிர அவனால் பேசவோ, சுவாசிக்கவோ அல்லது எவ்வித சக்தியையும் பயன்படுத்தவோ முடியாது. எனது பாதுகாப்பு, உதவி மற்றும் ஆதரவுடன் நான் உங்கள் இருவருடனும் இருக்கிறேன்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأْتِيَاهُ</span> <span class=\"quran-arabic-font text-success\">فَقُولاَ</span> <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">رَسُولاَ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span><br />\r\n<br />\r\n(ஆகவே, நீங்கள் இருவரும் அவனிடம் சென்று கூறுங்கள்: \"நிச்சயமாக, நாங்கள் இருவரும் உமது இறைவனின் தூதர்கள்...\")<br />\r\n<br />\r\n<strong>மூஸா (அலை) அவர்கள் ஃபிர்அவ்னை எச்சரித்தல்</strong><br />\r\n<br />\r\nஅவனது கூற்றைப் பொறுத்தவரை,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">جِئْنَـكَ</span> <span class=\"quran-arabic-font text-success\">بِـَايَةٍ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">رَّبِّكَ</span><br />\r\n<br />\r\n(‘நிச்சயமாக, நாங்கள் உமது இறைவனிடமிருந்து ஓர் அத்தாட்சியுடன் வந்துள்ளோம்!’) அதாவது, உமது இறைவனிடமிருந்து ஒரு சான்று மற்றும் ஓர் அற்புதத்துடன் வந்துள்ளோம்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالسَّلَـمُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">مَنِ</span> <span class=\"quran-arabic-font text-success\">اتَّبَعَ</span> <span class=\"quran-arabic-font text-success\">الْهُدَى</span><br />\r\n<br />\r\n(‘நேர்வழியைப் பின்பற்றுபவர் மீது சாந்தி உண்டாவதாக!’) இதன் பொருள், ‘நீர் நேர்வழியைப் பின்பற்றினால் உமக்குச் சாந்தி (அமைதி) உண்டாகும்.’ இதனால்தான், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ரோம் பேரரசர் ஹெராக்ளியஸுக்குக் கடிதம் எழுதியபோது, அதனை இவ்வாறு தொடங்கினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">بِسْمِ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمنِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمِ،</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">مُحَمَّدٍ</span> <span class=\"quran-arabic-font text-success\">رَسُولِ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">هِرَقْلَ</span> <span class=\"quran-arabic-font text-success\">عَظِيمِ</span> <span class=\"quran-arabic-font text-success\">الرُّومِ،</span> <span class=\"quran-arabic-font text-success\">سَلَامٌ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">مَنِ</span> <span class=\"quran-arabic-font text-success\">اتَّبَعَ</span> <span class=\"quran-arabic-font text-success\">الْهُدى،</span> <span class=\"quran-arabic-font text-success\">أَمَّا</span> <span class=\"quran-arabic-font text-success\">بَعْدُ،</span> <span class=\"quran-arabic-font text-success\">فَإِنِّي</span> <span class=\"quran-arabic-font text-success\">أَدْعُوكَ</span> <span class=\"quran-arabic-font text-success\">بِدِعَايَةِ</span> <span class=\"quran-arabic-font text-success\">الْإِسْلَامِ،</span> <span class=\"quran-arabic-font text-success\">فَأَسْلِمْ</span> <span class=\"quran-arabic-font text-success\">تَسْلَمْ</span> <span class=\"quran-arabic-font text-success\">يُؤْتِكَ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">أَجْرَكَ</span> <span class=\"quran-arabic-font text-success\">مَرَّتَيْن</span>»<br />\r\n<br />\r\n(அளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால். அல்லாஹ்வின் தூதர் முஹம்மத் (ஸல்) அவர்களிடமிருந்து, ரோம் பேரரசர் ஹெராக்ளியஸுக்கு. நேர்வழியைப் பின்பற்றுபவர் மீது சாந்தி உண்டாவதாக. மேற்கொண்டு: நிச்சயமாக, நான் உங்களை இஸ்லாத்தின் அழைப்பால் அழைக்கிறேன். இஸ்லாத்தை ஏற்றுக் கொள்ளுங்கள், நீங்கள் பாதுகாப்புப் பெறுவீர்கள்; அல்லாஹ் உங்களுக்கு இரு மடங்கு நற்கூலியை வழங்குவான்.) இதன் காரணமாகவே, மூஸா (அலை) அவர்களும் ஹாரூன் (அலை) அவர்களும் ஃபிர்அவ்னிடம் இவ்வாறு கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأْتِيَاهُ</span> <span class=\"quran-arabic-font text-success\">فَقُولاَ</span> <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">رَسُولاَ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">فَأَرْسِلْ</span> <span class=\"quran-arabic-font text-success\">مَعَنَا</span> <span class=\"quran-arabic-font text-success\">بَنِى</span> <span class=\"quran-arabic-font text-success\">إِسْرَءِيلَ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تُعَذِّبْهُمْ</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">جِئْنَـكَ</span> <span class=\"quran-arabic-font text-success\">بِـَايَةٍ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">رَّبِّكَ</span> <span class=\"quran-arabic-font text-success\">وَالسَّلَـمُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">مَنِ</span> <span class=\"quran-arabic-font text-success\">اتَّبَعَ</span> <span class=\"quran-arabic-font text-success\">الْهُدَى</span> - <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">أُوحِىَ</span> <span class=\"quran-arabic-font text-success\">إِلَيْنَآ</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">الْعَذَابَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">كَذَّبَ</span> <span class=\"quran-arabic-font text-success\">وَتَوَلَّى</span><br />\r\n<br />\r\n(‘ஆகவே, நீங்கள் இருவரும் அவனிடம் சென்று கூறுங்கள்: \"நிச்சயமாக, நாங்கள் இருவரும் உமது இறைவனின் தூதர்கள்; ஆகவே பனூ இஸ்ராயீல்களை எங்களுடன் அனுப்பி வைப்பீராக! அவர்களை வேதனை செய்யாதீராக! நிச்சயமாக, நாங்கள் உமது இறைவனிடமிருந்து ஓர் அத்தாட்சியுடன் வந்துள்ளோம்! மேலும் நேர்வழியைப் பின்பற்றுபவர் மீது சாந்தி உண்டாவதாக! நிச்சயமாக, சத்தியத்தைப் பொய்ப்பித்து, புறக்கணிப்பவனுக்கே வேதனை உண்டு என்று எங்களுக்கு வஹீ (இறைச்செய்தி) அறிவிக்கப்பட்டுள்ளது.’) தனது பிழையற்ற வஹீ (இறைச்செய்தி)யில், அல்லாஹ்வின் அத்தாட்சிகளை மறுத்து, அவனது கீழ்ப்படிதலைப் புறக்கணிப்பவர்களுக்கென்றே வேதனை பிரத்தியேகமாகத் தயார் செய்யப்பட்டுள்ளது என்பதை அல்லாஹ் எங்களுக்கு அறிவித்துள்ளான். அல்லாஹ் கூறுவது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأَمَّا</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">طَغَى</span> - <span class=\"quran-arabic-font text-success\">وَءاثَرَ</span> <span class=\"quran-arabic-font text-success\">الْحَيَوةَ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> - <span class=\"quran-arabic-font text-success\">فَإِنَّ</span> <span class=\"quran-arabic-font text-success\">الْجَحِيمَ</span> <span class=\"quran-arabic-font text-success\">هِىَ</span> <span class=\"quran-arabic-font text-success\">الْمَأْوَى</span><br />\r\n<br />\r\n(ஆகவே, எவன் வரம்பு மீறினானோ, மேலும் இவ்வுலக வாழ்க்கையைத் தேர்ந்தெடுத்தானோ, நிச்சயமாக நரகமே அவனது தங்குமிடமாகும்.) <a href=\"qurandisp.php?sura=79&ayah=37\" class=\"link\">79:37</a>-39 உயர்வானவனான அல்லாஹ் மேலும் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأَنذَرْتُكُمْ</span> <span class=\"quran-arabic-font text-success\">نَاراً</span> <span class=\"quran-arabic-font text-success\">تَلَظَّى</span> - <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَصْلَـهَآ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">الاٌّشْقَى</span> - <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">كَذَّبَ</span> <span class=\"quran-arabic-font text-success\">وَتَوَلَّى</span><br />\r\n<br />\r\n(ஆகவே, கொழுந்துவிட்டெரியும் நெருப்பைப் பற்றி நான் உங்களை எச்சரித்துள்ளேன். பெரும் துர்ப்பாக்கியசாலியைத் தவிர வேறு எவனும் அதில் நுழையமாட்டான். அவன் சத்தியத்தைப் பொய்ப்பித்து, புறக்கணித்தான்.) <a href=\"qurandisp.php?sura=92&ayah=14\" class=\"link\">92:14</a>-16 அல்லாஹ் மேலும் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَلاَ</span> <span class=\"quran-arabic-font text-success\">صَدَّقَ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">صَلَّى</span> - <span class=\"quran-arabic-font text-success\">وَلَـكِن</span> <span class=\"quran-arabic-font text-success\">كَذَّبَ</span> <span class=\"quran-arabic-font text-success\">وَتَوَلَّى</span><br />\r\n<br />\r\n(ஏனெனில், அவன் உண்மையை நம்பவுமில்லை, தொழவுமில்லை! மாறாக, அவன் பொய்யெனக் கருதி, புறக்கணித்தான்.) <a href=\"qurandisp.php?sura=75&ayah=31\" class=\"link\">75:31</a>-32 இதன் பொருள், அவன் தனது உள்ளத்தால் (சத்தியத்தைப்) பொய்ப்பித்து, தனது செயல்களால் அதைப் புறக்கணித்தான் என்பதாகும்.<br />\r\n<br />\r\n<br />\r\n<br />","text":"3 மூஸா (அலை) அவர்கள் ஃபிர்அவ்னைக் கண்டு அஞ்சுவதும், அல்லாஹ் அவர்களுக்கு மனவலிமை அளிப்பதும்\n\r\n\n\r\nஉயர்வானவனான அல்லாஹ், மூஸா (அலை) அவர்களும் ஹாரூன் (அலை) அவர்களும் அல்லாஹ்விடம் மன்றாடி, தங்கள் கவலையை அவனிடம் வெளிப்படுத்தியதை இவ்வாறு தெரிவிக்கிறான்:\n\r\n\n\r\nإِنَّنَا نَخَافُ أَن يَفْرُطَ عَلَيْنَآ أَوْ أَن يَطْغَى\n\r\n\n\r\n(‘நிச்சயமாக, அவன் எங்களுக்கு உடனடித் தண்டனை அளிப்பதற்கோ அல்லது எங்கள் மீது அக்கிரமம் செய்வதற்கோ நாங்கள் அஞ்சுகிறோம்.’) ஃபிர்அவ்ன் தங்களை எதிர்பாராத விதமாகத் தண்டித்து பிடித்துக் கொள்ளலாம் அல்லது தாங்கள் அதற்குத் தகுதியற்றவர்களாக இருந்தும் அவன் தங்களைத் துன்புறுத்துவதன் மூலம் வரம்பு மீறலாம் என்று அவர்கள் கருதினார்கள். இப்னு அப்பாஸ் (ரழி) அவர்கள் அறிவித்ததாக அத்-தஹ்ஹாக் கூறுகிறார்கள்: \"இங்கு வரம்பு மீறுதல் என்பது எல்லைகளைக் கடந்து செல்வதைக் குறிக்கும்.\"\n\r\n\n\r\nقَالَ لاَ تَخَافَآ إِنَّنِى مَعَكُمَآ أَسْمَعُ وَأَرَى\n\r\n\n\r\n(அல்லாஹ் கூறினான்: \"அஞ்சாதீர்கள்; நிச்சயமாக நான் உங்கள் இருவருடனும் இருக்கிறேன்; நான் செவியேற்கிறேன், பார்க்கிறேன்.\") இதன் பொருள்; \"அவனுக்கு (ஃபிர்அவ்னுக்கு) அஞ்சாதீர்கள், நிச்சயமாக நான் உங்கள் இருவருடனும் இருக்கிறேன். உங்கள் பேச்சையும் அவனது பேச்சையும் நான் செவியேற்றுக் கொண்டிருக்கிறேன். உங்கள் இருப்பிடத்தையும் அவனது இருப்பிடத்தையும் நான் பார்த்துக் கொண்டிருக்கிறேன். உங்கள் விவகாரங்களில் எதுவும் எனக்கு மறைவானதல்ல. அவனது முன்முடி (நெற்றி) எனது கைவசமே உள்ளது என்பதை அறிந்து கொள்ளுங்கள். எனது அனுமதியின்றி, எனது கட்டளைக்குப் பின்னரே தவிர அவனால் பேசவோ, சுவாசிக்கவோ அல்லது எவ்வித சக்தியையும் பயன்படுத்தவோ முடியாது. எனது பாதுகாப்பு, உதவி மற்றும் ஆதரவுடன் நான் உங்கள் இருவருடனும் இருக்கிறேன்.\"\n\r\n\n\r\nفَأْتِيَاهُ فَقُولاَ إِنَّا رَسُولاَ رَبِّكَ\n\r\n\n\r\n(ஆகவே, நீங்கள் இருவரும் அவனிடம் சென்று கூறுங்கள்: \"நிச்சயமாக, நாங்கள் இருவரும் உமது இறைவனின் தூதர்கள்...\")\n\r\n\n\r\nமூஸா (அலை) அவர்கள் ஃபிர்அவ்னை எச்சரித்தல்\n\r\n\n\r\nஅவனது கூற்றைப் பொறுத்தவரை,\n\r\n\n\r\nقَدْ جِئْنَـكَ بِـَايَةٍ مِّن رَّبِّكَ\n\r\n\n\r\n(‘நிச்சயமாக, நாங்கள் உமது இறைவனிடமிருந்து ஓர் அத்தாட்சியுடன் வந்துள்ளோம்!’) அதாவது, உமது இறைவனிடமிருந்து ஒரு சான்று மற்றும் ஓர் அற்புதத்துடன் வந்துள்ளோம்.\n\r\n\n\r\nوَالسَّلَـمُ عَلَى مَنِ اتَّبَعَ الْهُدَى\n\r\n\n\r\n(‘நேர்வழியைப் பின்பற்றுபவர் மீது சாந்தி உண்டாவதாக!’) இதன் பொருள், ‘நீர் நேர்வழியைப் பின்பற்றினால் உமக்குச் சாந்தி (அமைதி) உண்டாகும்.’ இதனால்தான், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ரோம் பேரரசர் ஹெராக்ளியஸுக்குக் கடிதம் எழுதியபோது, அதனை இவ்வாறு தொடங்கினார்கள்:\n\r\n\n\r\n«بِسْمِ اللهِ الرَّحْمنِ الرَّحِيمِ، مِنْ مُحَمَّدٍ رَسُولِ اللهِ إِلَى هِرَقْلَ عَظِيمِ الرُّومِ، سَلَامٌ عَلَى مَنِ اتَّبَعَ الْهُدى، أَمَّا بَعْدُ، فَإِنِّي أَدْعُوكَ بِدِعَايَةِ الْإِسْلَامِ، فَأَسْلِمْ تَسْلَمْ يُؤْتِكَ اللهُ أَجْرَكَ مَرَّتَيْن»\n\r\n\n\r\n(அளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால். அல்லாஹ்வின் தூதர் முஹம்மத் (ஸல்) அவர்களிடமிருந்து, ரோம் பேரரசர் ஹெராக்ளியஸுக்கு. நேர்வழியைப் பின்பற்றுபவர் மீது சாந்தி உண்டாவதாக. மேற்கொண்டு: நிச்சயமாக, நான் உங்களை இஸ்லாத்தின் அழைப்பால் அழைக்கிறேன். இஸ்லாத்தை ஏற்றுக் கொள்ளுங்கள், நீங்கள் பாதுகாப்புப் பெறுவீர்கள்; அல்லாஹ் உங்களுக்கு இரு மடங்கு நற்கூலியை வழங்குவான்.) இதன் காரணமாகவே, மூஸா (அலை) அவர்களும் ஹாரூன் (அலை) அவர்களும் ஃபிர்அவ்னிடம் இவ்வாறு கூறினார்கள்:\n\r\n\n\r\nفَأْتِيَاهُ فَقُولاَ إِنَّا رَسُولاَ رَبِّكَ فَأَرْسِلْ مَعَنَا بَنِى إِسْرَءِيلَ وَلاَ تُعَذِّبْهُمْ قَدْ جِئْنَـكَ بِـَايَةٍ مِّن رَّبِّكَ وَالسَّلَـمُ عَلَى مَنِ اتَّبَعَ الْهُدَى - إِنَّا قَدْ أُوحِىَ إِلَيْنَآ أَنَّ الْعَذَابَ عَلَى مَن كَذَّبَ وَتَوَلَّى\n\r\n\n\r\n(‘ஆகவே, நீங்கள் இருவரும் அவனிடம் சென்று கூறுங்கள்: \"நிச்சயமாக, நாங்கள் இருவரும் உமது இறைவனின் தூதர்கள்; ஆகவே பனூ இஸ்ராயீல்களை எங்களுடன் அனுப்பி வைப்பீராக! அவர்களை வேதனை செய்யாதீராக! நிச்சயமாக, நாங்கள் உமது இறைவனிடமிருந்து ஓர் அத்தாட்சியுடன் வந்துள்ளோம்! மேலும் நேர்வழியைப் பின்பற்றுபவர் மீது சாந்தி உண்டாவதாக! நிச்சயமாக, சத்தியத்தைப் பொய்ப்பித்து, புறக்கணிப்பவனுக்கே வேதனை உண்டு என்று எங்களுக்கு வஹீ (இறைச்செய்தி) அறிவிக்கப்பட்டுள்ளது.’) தனது பிழையற்ற வஹீ (இறைச்செய்தி)யில், அல்லாஹ்வின் அத்தாட்சிகளை மறுத்து, அவனது கீழ்ப்படிதலைப் புறக்கணிப்பவர்களுக்கென்றே வேதனை பிரத்தியேகமாகத் தயார் செய்யப்பட்டுள்ளது என்பதை அல்லாஹ் எங்களுக்கு அறிவித்துள்ளான். அல்லாஹ் கூறுவது போல:\n\r\n\n\r\nفَأَمَّا مَن طَغَى - وَءاثَرَ الْحَيَوةَ الدُّنْيَا - فَإِنَّ الْجَحِيمَ هِىَ الْمَأْوَى\n\r\n\n\r\n(ஆகவே, எவன் வரம்பு மீறினானோ, மேலும் இவ்வுலக வாழ்க்கையைத் தேர்ந்தெடுத்தானோ, நிச்சயமாக நரகமே அவனது தங்குமிடமாகும்.) 79:37-39 உயர்வானவனான அல்லாஹ் மேலும் கூறுகிறான்:\n\r\n\n\r\nفَأَنذَرْتُكُمْ نَاراً تَلَظَّى - لاَ يَصْلَـهَآ إِلاَّ الاٌّشْقَى - الَّذِى كَذَّبَ وَتَوَلَّى\n\r\n\n\r\n(ஆகவே, கொழுந்துவிட்டெரியும் நெருப்பைப் பற்றி நான் உங்களை எச்சரித்துள்ளேன். பெரும் துர்ப்பாக்கியசாலியைத் தவிர வேறு எவனும் அதில் நுழையமாட்டான். அவன் சத்தியத்தைப் பொய்ப்பித்து, புறக்கணித்தான்.) 92:14-16 அல்லாஹ் மேலும் கூறுகிறான்:\n\r\n\n\r\nفَلاَ صَدَّقَ وَلاَ صَلَّى - وَلَـكِن كَذَّبَ وَتَوَلَّى\n\r\n\n\r\n(ஏனெனில், அவன் உண்மையை நம்பவுமில்லை, தொழவுமில்லை! மாறாக, அவன் பொய்யெனக் கருதி, புறக்கணித்தான்.) 75:31-32 இதன் பொருள், அவன் தனது உள்ளத்தால் (சத்தியத்தைப்) பொய்ப்பித்து, தனது செயல்களால் அதைப் புறக்கணித்தான் என்பதாகும்."},"49":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=52\" class=\"link\">20:52</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:52 ஐ பார்க்கவும்"},"50":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=52\" class=\"link\">20:52</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:52 ஐ பார்க்கவும்"},"51":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=52\" class=\"link\">20:52</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:52 ஐ பார்க்கவும்"},"52":{"html":"<strong>மூஸா (அலை) அவர்களுக்கும் ஃபிர்அவ்னுக்கும் இடையேயான உரையாடல்</strong><br />\r\n<br />\r\nஎல்லாவற்றிற்கும் இறைவனும், தனக்கும் எஜமானனுமான ஒரு உன்னத படைப்பாளன் இருப்பதை நிராகரித்த நிலையில், ஃபிர்அவ்ன் மூஸா (அலை) அவர்களிடம் கூறியதை அல்லாஹ் இங்குக் குறிப்பிடுகிறான்: <span class=\"quran-arabic-font text-success\">﴾فَمَن</span> <span class=\"quran-arabic-font text-success\">رَّبُّكُمَا</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">مُوسَى﴿</span><br />\r\n<br />\r\n(மூஸாவே! உங்கள் இருவருடைய இறைவன் யார்?) அதாவது, \"உங்களை அழைத்து அனுப்பியவன் யார்? நிச்சயமாக நான் அவனை அறியமாட்டேன்; என்னைத் தவிர வேறு எவரையும் உங்களுக்குக் கடவுளாக நான் ஆக்கவில்லை\" (என்று ஃபிர்அவ்ன் கூறினான்). <span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">رَبُّنَا</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">أَعْطَى</span> <span class=\"quran-arabic-font text-success\">كُلَّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">خَلْقَهُ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">هَدَى﴿</span><br />\r\n<br />\r\n((மூஸா (அலை) அவர்கள்) கூறினார்கள்: \"எங்கள் இறைவன் எத்தகையவன் என்றால், அவன் ஒவ்வொரு பொருளுக்கும் அதற்குரிய உருவத்தையும் இயற்கைத் தன்மையையும் வழங்கி, பின்னர் அதற்கு நேர்வழியும் காட்டினான்.\") அலீ பின் அபீ தல்ஹா (ரழி), இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்: \"ஒவ்வொரு படைப்பிற்கும் ஒரு துணையை அல்லாஹ் படைத்தான் என்பதையே இது குறிக்கிறது.\" அத்-தஹ்ஹாக் அவர்கள் இப்னு அப்பாஸ் (ரழி) வாயிலாகக் கூறுகையில், \"அவன் மனிதனை மனிதனாகவும், கழுதையை கழுதையாகவும், ஆட்டை ஆடாகவும் படைத்தான்\" என்றார்கள். லைஸ் பின் அபீ சுலைம், முஜாஹித் அவர்களிடமிருந்து அறிவிக்கிறார்கள்: \"ஒவ்வொரு பொருளுக்கும் அதற்குரிய வடிவத்தை அவன் வழங்கினான்.\" இப்னு அபீ நஜீஹ், முஜாஹித் அவர்கள் கூறியதாகக் குறிப்பிடுகிறார்கள்: \"அசையும் ஒவ்வொரு உயிரினத்தின் படைப்பையும் அவன் செம்மையாக வடிவமைத்தான்.\" ஸயீத் பின் ஜுபைர் அவர்கள் அல்லாஹ்வின் இக்கூற்றைப் பற்றிக் கூறும்போது, <span class=\"quran-arabic-font text-success\">﴾أَعْطَى</span> <span class=\"quran-arabic-font text-success\">كُلَّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">خَلْقَهُ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">هَدَى﴿</span><br />\r\n<br />\r\n((யார்) ஒவ்வொரு பொருளுக்கும் அதற்குரிய வடிவத்தையும் தன்மையையும் கொடுத்து, பின்னர் நேர்வழி காட்டினானோ) \"அவன் தன்னுடைய ஒவ்வொரு படைப்பிற்கும் அதன் படைப்பிற்கு ஏற்ற தகுதியை வழங்கினான்\" என்று விளக்கமளித்தார்கள். எனவே, அவன் மனிதனுக்கு ஒரு காட்டுவிலங்கின் உருவத்தையோ, காட்டுவிலங்குகளுக்கு நாயின் உருவத்தையோ கொடுக்கவில்லை. அதேபோல், நாயின் உருவம் ஆட்டைப் போன்றது அல்ல. மேலும் அவன் ஒவ்வொரு உயிரினத்திற்கும் பொருத்தமான துணையை வழங்கினான்; அதன்பால் அந்த உயிரினத்தை ஈர்க்கவும் செய்தான். படைப்புகளில் எந்த ஒரு இனமும் மற்றொரு இனத்தை முழுமையாகப் போன்றிருப்பதில்லை. அவை தங்களின் செயல்கள், உருவங்கள், வாழ்வாதாரம் மற்றும் தாம்பத்திய உறவு ஆகியவற்றில் மாறுபடுகின்றன. தஃப்ஸீர் அறிஞர்களில் சிலர், \"அவன் ஒவ்வொரு பொருளுக்கும் அதன் வடிவத்தையும் தன்மையையும் கொடுத்து, பின்னர் நேர்வழி காட்டினான்\" என்ற இந்தக் கூற்று, அல்லாஹ்வின் பின்வரும் வசனத்தைப் போன்றது எனக் கருதுகின்றனர்: <span class=\"quran-arabic-font text-success\">﴾وَالَّذِى</span> <span class=\"quran-arabic-font text-success\">قَدَّرَ</span> <span class=\"quran-arabic-font text-success\">فَهَدَى</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும் அவன்தான் ஒவ்வொன்றையும் நிர்ணயித்து, பின்னர் வழிகாட்டினான்.) <a href=\"qurandisp.php?sura=87&ayah=3\" class=\"link\">87:3</a> அதாவது, அவன் (வாழ்வாதாரம், செயல்கள் போன்றவற்றை) ஒரு குறிப்பிட்ட அளவில் நிர்ணயித்து, பின்னர் தனது படைப்புகளை அதன் பக்கம் வழிநடத்தினான். அவன் செயல்கள், மரண நேரங்கள் மற்றும் வாழ்வாதாரங்கள் ஆகியவற்றை எழுதிவிட்டான். படைப்புகள் அதன்படியே இயங்குகின்றன; அவர்களால் அதைத் தவிர்க்கவோ அல்லது கைவிடவோ முடியாது. இந்த வசனத்தில் மூஸா (அலை) அவர்கள், \"எங்கள் இறைவன் படைப்புகளைப் படைத்தவன், அவற்றின் விதியை நிர்ணயித்தவன், மேலும் தான் நாடியவற்றின் பக்கம் படைப்புகளை வழிநடத்துபவன்\" என்று குறிப்பிடுகிறார்கள். <span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">فَمَا</span> <span class=\"quran-arabic-font text-success\">بَالُ</span> <span class=\"quran-arabic-font text-success\">الْقُرُونِ</span> <span class=\"quran-arabic-font text-success\">الْأُولَى﴿</span><br />\r\n<br />\r\n((ஃபிர்அவ்ன்) கேட்டான்: \"அப்படியானால் முந்தைய தலைமுறையினரின் நிலை என்ன?\") இக்கேள்வியின் சரியான பொருள் என்னவென்றால், தன்னை அனுப்பிய இறைவன் படைப்பவன், உணவளிப்பவன், விதியை நிர்ணயிப்பவன் மற்றும் நேர்வழி காட்டுபவன் என்று மூஸா (அலை) அவர்கள் ஃபிர்அவ்னுக்குத் தெரிவித்தபோது, அவன் முந்தைய தலைமுறையினரை ஒரு சான்றாகப் பயன்படுத்தி வாதிடத் தொடங்கினான். அல்லாஹ்வை வணங்காத முற்கால மக்களை அவன் குறிப்பிடுகிறான். அதாவது, \"விஷயம் நீங்கள் சொல்வது போல் இருந்தால், அந்த முந்தைய மக்களுக்கு என்ன நேர்ந்தது? அவர்கள் உங்கள் இறைவனை வணங்கவில்லை; மாறாக, அவர்கள் அவனையன்றி பிற கடவுள்களை வணங்கினார்கள்\" என்று அவன் வினவினான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">عِلْمُهَا</span> <span class=\"quran-arabic-font text-success\">عِندَ</span> <span class=\"quran-arabic-font text-success\">رَبِّي</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">كِتَابٍ﴿</span><br />\r\n<br />\r\n((மூஸா (அலை)) கூறினார்: \"அவற்றைப் பற்றிய ஞானம் என் இறைவனிடம் ஒரு பதிவேட்டில் உள்ளது.\")<br />\r\n<br />\r\nஇதற்குப் பதிலாக மூஸா (அலை) அவர்கள் கூறினார்கள்: அவர்கள் அல்லாஹ்வை வணங்காவிட்டாலும், அவர்களுக்கு என்ன நடந்தது என்பதை அல்லாஹ் துல்லியமாக அறிவான். அல்லாஹ்வின் பதிவேட்டில் (கிதாப்) எழுதப்பட்டுள்ளபடி அவர்களின் செயல்களுக்கு அவன் உரிய கூலியை வழங்குவான். இந்தப் பதிவேடு 'அல்-லவ்ஹுல் மஹ்ஃபூழ்' (பாதுகாக்கப்பட்ட பலகை) என்று அழைக்கப்படுகிறது; இதுவே செயல்களின் புத்தகம் ஆகும். <span class=\"quran-arabic-font text-success\">﴾لَّا</span> <span class=\"quran-arabic-font text-success\">يَضِلُّ</span> <span class=\"quran-arabic-font text-success\">رَبِّي</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">يَنسَى﴿</span><br />\r\n<br />\r\n(என் இறைவன் தவறிழைக்க மாட்டான்; எதனையும் மறக்கவும் மாட்டான்.) இதன் பொருள் என்னவென்றால், சிறியதாக இருந்தாலும் பெரியதாக இருந்தாலும் எதுவுமே அவனிடமிருந்து தப்புவதில்லை; அவன் எதனையும் தவறவிடுவதில்லை. அவன் எதனையும் மறப்பதில்லை. அவனது மேலான அறிவு அனைத்தையும் சூழ்ந்திருப்பதாக விவரிக்கப்படுகிறது. அவன் தூய்மையானவன், குறைகளற்றவன், பாக்கியமிக்கவன். படைப்பினங்களிடம் உள்ள அறிவில் இரண்டு குறைபாடுகள் உள்ளன. முதலாவது, அந்த அறிவு எதையும் முழுமையாக உள்ளடக்காது; இரண்டாவது, ஒரு விஷயத்தை அறிந்த பிறகு படைப்பு அதனை மறந்துவிடக்கூடும். இத்தகைய குறைபாடுகளுக்கு அப்பாற்பட்டவன் என்று அல்லாஹ் தன்னைத் தெளிவுபடுத்தியுள்ளான்.<br />\r\n<br />","text":"மூஸா (அலை) அவர்களுக்கும் ஃபிர்அவ்னுக்கும் இடையேயான உரையாடல்\n\r\n\n\r\nஎல்லாவற்றிற்கும் இறைவனும், தனக்கும் எஜமானனுமான ஒரு உன்னத படைப்பாளன் இருப்பதை நிராகரித்த நிலையில், ஃபிர்அவ்ன் மூஸா (அலை) அவர்களிடம் கூறியதை அல்லாஹ் இங்குக் குறிப்பிடுகிறான்: ﴾فَمَن رَّبُّكُمَا يَا مُوسَى﴿\n\r\n\n\r\n(மூஸாவே! உங்கள் இருவருடைய இறைவன் யார்?) அதாவது, \"உங்களை அழைத்து அனுப்பியவன் யார்? நிச்சயமாக நான் அவனை அறியமாட்டேன்; என்னைத் தவிர வேறு எவரையும் உங்களுக்குக் கடவுளாக நான் ஆக்கவில்லை\" (என்று ஃபிர்அவ்ன் கூறினான்). ﴾قَالَ رَبُّنَا الَّذِي أَعْطَى كُلَّ شَيْءٍ خَلْقَهُ ثُمَّ هَدَى﴿\n\r\n\n\r\n((மூஸா (அலை) அவர்கள்) கூறினார்கள்: \"எங்கள் இறைவன் எத்தகையவன் என்றால், அவன் ஒவ்வொரு பொருளுக்கும் அதற்குரிய உருவத்தையும் இயற்கைத் தன்மையையும் வழங்கி, பின்னர் அதற்கு நேர்வழியும் காட்டினான்.\") அலீ பின் அபீ தல்ஹா (ரழி), இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்: \"ஒவ்வொரு படைப்பிற்கும் ஒரு துணையை அல்லாஹ் படைத்தான் என்பதையே இது குறிக்கிறது.\" அத்-தஹ்ஹாக் அவர்கள் இப்னு அப்பாஸ் (ரழி) வாயிலாகக் கூறுகையில், \"அவன் மனிதனை மனிதனாகவும், கழுதையை கழுதையாகவும், ஆட்டை ஆடாகவும் படைத்தான்\" என்றார்கள். லைஸ் பின் அபீ சுலைம், முஜாஹித் அவர்களிடமிருந்து அறிவிக்கிறார்கள்: \"ஒவ்வொரு பொருளுக்கும் அதற்குரிய வடிவத்தை அவன் வழங்கினான்.\" இப்னு அபீ நஜீஹ், முஜாஹித் அவர்கள் கூறியதாகக் குறிப்பிடுகிறார்கள்: \"அசையும் ஒவ்வொரு உயிரினத்தின் படைப்பையும் அவன் செம்மையாக வடிவமைத்தான்.\" ஸயீத் பின் ஜுபைர் அவர்கள் அல்லாஹ்வின் இக்கூற்றைப் பற்றிக் கூறும்போது, ﴾أَعْطَى كُلَّ شَيْءٍ خَلْقَهُ ثُمَّ هَدَى﴿\n\r\n\n\r\n((யார்) ஒவ்வொரு பொருளுக்கும் அதற்குரிய வடிவத்தையும் தன்மையையும் கொடுத்து, பின்னர் நேர்வழி காட்டினானோ) \"அவன் தன்னுடைய ஒவ்வொரு படைப்பிற்கும் அதன் படைப்பிற்கு ஏற்ற தகுதியை வழங்கினான்\" என்று விளக்கமளித்தார்கள். எனவே, அவன் மனிதனுக்கு ஒரு காட்டுவிலங்கின் உருவத்தையோ, காட்டுவிலங்குகளுக்கு நாயின் உருவத்தையோ கொடுக்கவில்லை. அதேபோல், நாயின் உருவம் ஆட்டைப் போன்றது அல்ல. மேலும் அவன் ஒவ்வொரு உயிரினத்திற்கும் பொருத்தமான துணையை வழங்கினான்; அதன்பால் அந்த உயிரினத்தை ஈர்க்கவும் செய்தான். படைப்புகளில் எந்த ஒரு இனமும் மற்றொரு இனத்தை முழுமையாகப் போன்றிருப்பதில்லை. அவை தங்களின் செயல்கள், உருவங்கள், வாழ்வாதாரம் மற்றும் தாம்பத்திய உறவு ஆகியவற்றில் மாறுபடுகின்றன. தஃப்ஸீர் அறிஞர்களில் சிலர், \"அவன் ஒவ்வொரு பொருளுக்கும் அதன் வடிவத்தையும் தன்மையையும் கொடுத்து, பின்னர் நேர்வழி காட்டினான்\" என்ற இந்தக் கூற்று, அல்லாஹ்வின் பின்வரும் வசனத்தைப் போன்றது எனக் கருதுகின்றனர்: ﴾وَالَّذِى قَدَّرَ فَهَدَى ﴿\n\r\n\n\r\n(மேலும் அவன்தான் ஒவ்வொன்றையும் நிர்ணயித்து, பின்னர் வழிகாட்டினான்.) 87:3 அதாவது, அவன் (வாழ்வாதாரம், செயல்கள் போன்றவற்றை) ஒரு குறிப்பிட்ட அளவில் நிர்ணயித்து, பின்னர் தனது படைப்புகளை அதன் பக்கம் வழிநடத்தினான். அவன் செயல்கள், மரண நேரங்கள் மற்றும் வாழ்வாதாரங்கள் ஆகியவற்றை எழுதிவிட்டான். படைப்புகள் அதன்படியே இயங்குகின்றன; அவர்களால் அதைத் தவிர்க்கவோ அல்லது கைவிடவோ முடியாது. இந்த வசனத்தில் மூஸா (அலை) அவர்கள், \"எங்கள் இறைவன் படைப்புகளைப் படைத்தவன், அவற்றின் விதியை நிர்ணயித்தவன், மேலும் தான் நாடியவற்றின் பக்கம் படைப்புகளை வழிநடத்துபவன்\" என்று குறிப்பிடுகிறார்கள். ﴾قَالَ فَمَا بَالُ الْقُرُونِ الْأُولَى﴿\n\r\n\n\r\n((ஃபிர்அவ்ன்) கேட்டான்: \"அப்படியானால் முந்தைய தலைமுறையினரின் நிலை என்ன?\") இக்கேள்வியின் சரியான பொருள் என்னவென்றால், தன்னை அனுப்பிய இறைவன் படைப்பவன், உணவளிப்பவன், விதியை நிர்ணயிப்பவன் மற்றும் நேர்வழி காட்டுபவன் என்று மூஸா (அலை) அவர்கள் ஃபிர்அவ்னுக்குத் தெரிவித்தபோது, அவன் முந்தைய தலைமுறையினரை ஒரு சான்றாகப் பயன்படுத்தி வாதிடத் தொடங்கினான். அல்லாஹ்வை வணங்காத முற்கால மக்களை அவன் குறிப்பிடுகிறான். அதாவது, \"விஷயம் நீங்கள் சொல்வது போல் இருந்தால், அந்த முந்தைய மக்களுக்கு என்ன நேர்ந்தது? அவர்கள் உங்கள் இறைவனை வணங்கவில்லை; மாறாக, அவர்கள் அவனையன்றி பிற கடவுள்களை வணங்கினார்கள்\" என்று அவன் வினவினான்.\n\r\n\n\r\n﴾قَالَ عِلْمُهَا عِندَ رَبِّي فِي كِتَابٍ﴿\n\r\n\n\r\n((மூஸா (அலை)) கூறினார்: \"அவற்றைப் பற்றிய ஞானம் என் இறைவனிடம் ஒரு பதிவேட்டில் உள்ளது.\")\n\r\n\n\r\nஇதற்குப் பதிலாக மூஸா (அலை) அவர்கள் கூறினார்கள்: அவர்கள் அல்லாஹ்வை வணங்காவிட்டாலும், அவர்களுக்கு என்ன நடந்தது என்பதை அல்லாஹ் துல்லியமாக அறிவான். அல்லாஹ்வின் பதிவேட்டில் (கிதாப்) எழுதப்பட்டுள்ளபடி அவர்களின் செயல்களுக்கு அவன் உரிய கூலியை வழங்குவான். இந்தப் பதிவேடு 'அல்-லவ்ஹுல் மஹ்ஃபூழ்' (பாதுகாக்கப்பட்ட பலகை) என்று அழைக்கப்படுகிறது; இதுவே செயல்களின் புத்தகம் ஆகும். ﴾لَّا يَضِلُّ رَبِّي وَلَا يَنسَى﴿\n\r\n\n\r\n(என் இறைவன் தவறிழைக்க மாட்டான்; எதனையும் மறக்கவும் மாட்டான்.) இதன் பொருள் என்னவென்றால், சிறியதாக இருந்தாலும் பெரியதாக இருந்தாலும் எதுவுமே அவனிடமிருந்து தப்புவதில்லை; அவன் எதனையும் தவறவிடுவதில்லை. அவன் எதனையும் மறப்பதில்லை. அவனது மேலான அறிவு அனைத்தையும் சூழ்ந்திருப்பதாக விவரிக்கப்படுகிறது. அவன் தூய்மையானவன், குறைகளற்றவன், பாக்கியமிக்கவன். படைப்பினங்களிடம் உள்ள அறிவில் இரண்டு குறைபாடுகள் உள்ளன. முதலாவது, அந்த அறிவு எதையும் முழுமையாக உள்ளடக்காது; இரண்டாவது, ஒரு விஷயத்தை அறிந்த பிறகு படைப்பு அதனை மறந்துவிடக்கூடும். இத்தகைய குறைபாடுகளுக்கு அப்பாற்பட்டவன் என்று அல்லாஹ் தன்னைத் தெளிவுபடுத்தியுள்ளான்."},"53":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=56\" class=\"link\">20:56</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:56 ஐ பார்க்கவும்"},"54":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=56\" class=\"link\">20:56</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:56 ஐ பார்க்கவும்"},"55":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=56\" class=\"link\">20:56</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:56 ஐ பார்க்கவும்"},"56":{"html":"<strong>மூஸா (அலை) அவர்கள் ஃபிர்அவ்னுக்கு அளித்த பதிலின் நிறைவு</strong><br />\r\n<br />\r\nஃபிர்அவ்ன் தனது இறைவனைப் பற்றி மூஸா (அலை) அவர்களிடம் கேட்டபோது, அவர் அளித்த விளக்கத்தின் நிறைவுப் பகுதி இதுவாகும். மூஸா (அலை) அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾الَّذِي</span> <span class=\"quran-arabic-font text-success\">أَعْطَىٰ</span> <span class=\"quran-arabic-font text-success\">كُلَّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">خَلْقَهُ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">هَدَىٰ﴿</span><br />\r\n<br />\r\n(அவன் ஒவ்வொரு பொருளுக்கும் அதற்குரிய உருவத்தையும் இயற்கையையும் வழங்கி, பின்னர் அதற்கு நேர்வழிகாட்டினான்.) மூஸா (அலை) அவர்கள் பதில் கூறிக்கொண்டிருந்தபோது, ஃபிர்அவ்ன் சில தர்க்கரீதியான மறுப்புகளை முன்வைக்க முயன்றான். ஆயினும், மூஸா (அலை) அவர்கள் தொடர்ந்து கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾الَّذِي</span> <span class=\"quran-arabic-font text-success\">جَعَلَ</span> <span class=\"quran-arabic-font text-success\">لَكُمُ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضَ</span> <span class=\"quran-arabic-font text-success\">مَهْدًا﴿</span> \"அவன்தான் பூமியை உங்களுக்கு ஒரு விரிப்பாக ஆக்கினான்.\" சிலர் அந்த வார்த்தையை ‘மிஹாதன்’ (Mihadan) என்றும், மற்றவர்கள் ‘மஹ்தன்’ (Mahdan) என்றும் ஓதினர். இதற்கு ‘நீங்கள் தங்கி ஓய்வெடுக்கும் இடம்’ என்று பொருளாகும். மேலும், ‘நீங்கள் எதன் மீது நிற்கிறீர்களோ, உறங்குகிறீர்களோ அல்லது எதன் மீது பயணம் செய்கிறீர்களோ அது’ என்றும் இது பொருள்படும். <span class=\"quran-arabic-font text-success\">﴾وَسَلَكَ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">سُبُلًا﴿</span><br />\r\n<br />\r\n(அதில் உங்களுக்காகப் பாதைகளை ஏற்படுத்தினான்.) அதாவது, நீங்கள் அவற்றின் வழியே நடப்பதற்காக அவன் பாதைகளை அமைத்தான் என்று பொருள்படும். இதையே மேலானவனாகிய அல்லாஹ் இவ்வாறு கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَجَعَلْنَا</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">فِجَاجًا</span> <span class=\"quran-arabic-font text-success\">سُبُلًا</span> <span class=\"quran-arabic-font text-success\">لَّعَلَّهُمْ</span> <span class=\"quran-arabic-font text-success\">يَهْتَدُونَ﴿</span><br />\r\n<br />\r\n(அவர்கள் நேர்வழி பெறுவதற்காக, நாம் அதில் விசாலமான பாதைகளை அமைத்தோம்.) <a href=\"qurandisp.php?sura=21&ayah=31\" class=\"link\">21:31</a> <span class=\"quran-arabic-font text-success\">﴾وَأَنزَلَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">السَّمَاءِ</span> <span class=\"quran-arabic-font text-success\">مَاءً</span> <span class=\"quran-arabic-font text-success\">فَأَخْرَجْنَا</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">أَزْوَاجًا</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">نَّبَاتٍ</span> <span class=\"quran-arabic-font text-success\">شَتَّىٰ﴿</span><br />\r\n<br />\r\n(மேலும், வானத்திலிருந்து தண்ணீரை இறக்கினான். அதைக் கொண்டு நாம் பலவகையான தாவரங்களை ஜோடி ஜோடியாக வெளிப்படுத்தினோம்.) இது செடிகொடிகள் மற்றும் பழங்கள் போன்ற பல்வேறு வகையான தாவர இனங்களைக் குறிக்கிறது. அவற்றில் சில புளிப்பானவை, சில இனிப்பானவை, சில கசப்பானவை எனப் பல வகைகள் உள்ளன. <span class=\"quran-arabic-font text-success\">﴾كُلُوا</span> <span class=\"quran-arabic-font text-success\">وَارْعَوْا</span> <span class=\"quran-arabic-font text-success\">أَنْعَامَكُمْ﴿</span><br />\r\n<br />\r\n(நீங்களும் உண்ணுங்கள், உங்கள் கால்நடைகளையும் மேயவிடுங்கள்;) அதாவது, உங்களுக்கு உணவாகவும், சுவையான பழமாகவும் இருப்பதையும், உங்கள் கால்நடைகளுக்குப் பசுமையான மற்றும் காய்ந்த தீவனமாகவும் இருப்பதையும் இது குறிக்கிறது. <span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">ذَٰلِكَ</span> <span class=\"quran-arabic-font text-success\">لَآيَاتٍ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக, இதில் அத்தாட்சிகள் இருக்கின்றன.) அதாவது சான்றுகள், அடையாளங்கள் மற்றும் ஆதாரங்கள் உள்ளன. <span class=\"quran-arabic-font text-success\">﴾لِّأُولِي</span> <span class=\"quran-arabic-font text-success\">النُّهَىٰ﴿</span><br />\r\n<br />\r\n(அறிவுடையவர்களுக்கு.) அதாவது, அல்லாஹ்வைத் தவிர வணக்கத்திற்குரிய இறைவன் யாருமில்லை என்பதையும், அவனைத் தவிர உண்மையான இரட்சகன் வேறு யாருமில்லை என்பதையும் உணர்ந்து, நேர்மையான அறிவைப் பெற்றவர்கள் என்று பொருளாகும். <span class=\"quran-arabic-font text-success\">﴾مِنْهَا</span> <span class=\"quran-arabic-font text-success\">خَلَقْنَاكُمْ</span> <span class=\"quran-arabic-font text-success\">وَفِيهَا</span> <span class=\"quran-arabic-font text-success\">نُعِيدُكُمْ</span> <span class=\"quran-arabic-font text-success\">وَمِنْهَا</span> <span class=\"quran-arabic-font text-success\">نُخْرِجُكُمْ</span> <span class=\"quran-arabic-font text-success\">تَارَةً</span> <span class=\"quran-arabic-font text-success\">أُخْرَىٰ﴿</span><br />\r\n<br />\r\n(அதிலிருந்தே நாம் உங்களைப் படைத்தோம், அதிலேயே நாம் உங்களைத் திரும்பக் கொண்டு செல்வோம், அதிலிருந்தே நாம் உங்களை மற்றொரு முறை வெளிப்படுத்துவோம்.) அதாவது, பூமியே உங்கள் ஆரம்பமாகும். ஏனெனில், உங்கள் தந்தை ஆதம் (அலை) அவர்கள் பூமியின் மேற்பரப்பிலுள்ள மண்ணிலிருந்து படைக்கப்பட்டார்கள். நீங்களும் பூமிக்கே திரும்பக் கொண்டு செல்லப்படுவீர்கள். அதாவது, நீங்கள் மரணித்து மட்கிப் போகும்போது மீண்டும் மண்ணாகவே மாறிவிடுவீர்கள் என்று பொருள்படும். \"அதிலிருந்தே நாம் உங்களை மற்றொரு முறை வெளிப்படுத்துவோம்\" என்ற கூற்றின் பொருள்: <span class=\"quran-arabic-font text-success\">﴾يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَدْعُوكُمْ</span> <span class=\"quran-arabic-font text-success\">فَتَسْتَجِيبُونَ</span> <span class=\"quran-arabic-font text-success\">بِحَمْدِهِ</span> <span class=\"quran-arabic-font text-success\">وَتَظُنُّونَ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">لَّبِثْتُمْ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">قَلِيلًا﴿</span><br />\r\n<br />\r\n(அவன் உங்களை அழைக்கும் நாளில், அவனது புகழுடன் அவனுக்குக் கீழ்ப்படிந்து நீங்கள் பதிலளிப்பீர்கள். மேலும், நீங்கள் (இவ்வுலகில்) மிகக் குறைந்த காலமே தங்கியிருந்ததாகக் கருதுவீர்கள்!) <a href=\"qurandisp.php?sura=17&ayah=52\" class=\"link\">17:52</a> இந்த வசனம் அல்லாஹ்வின் மற்றொரு கூற்றைப் போன்றதாகும்: <span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">تَحْيَوْنَ</span> <span class=\"quran-arabic-font text-success\">وَفِيهَا</span> <span class=\"quran-arabic-font text-success\">تَمُوتُونَ</span> <span class=\"quran-arabic-font text-success\">وَمِنْهَا</span> <span class=\"quran-arabic-font text-success\">تُخْرَجُونَ﴿</span><br />\r\n<br />\r\n(அவன் கூறினான்: \"அதிலேயே நீங்கள் வாழ்வீர்கள், அதிலேயே நீங்கள் மரணிப்பீர்கள், அதிலிருந்தே நீங்கள் வெளிக்கொணரப்படுவீர்கள்.\") <a href=\"qurandisp.php?sura=7&ayah=25\" class=\"link\">7:25</a><br />\r\n<br />\r\n<strong>மூஸா (அலை) அவர்கள் ஃபிர்அவ்னுக்கு எல்லா அத்தாட்சிகளையும் காட்டினார்கள், ஆனால் அவன் நம்பவில்லை</strong><br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்றைப் பற்றி: <span class=\"quran-arabic-font text-success\">﴾وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">أَرَيْنَاهُ</span> <span class=\"quran-arabic-font text-success\">آيَاتِنَا</span> <span class=\"quran-arabic-font text-success\">كُلَّهَا</span> <span class=\"quran-arabic-font text-success\">فَكَذَّبَ</span> <span class=\"quran-arabic-font text-success\">وَأَبَىٰ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக நாம் அவனுக்கு (ஃபிர்அவ்னுக்கு) நம்முடைய அத்தாட்சிகள் அனைத்தையும் காட்டினோம், ஆனால் அவன் அவற்றை பொய்யாக்கி நிராகரித்தான்.) ஃபிர்அவ்னுக்கு எதிராகச் சான்றுகளும் அடையாளங்களும் ஆதாரங்களும் நிலைநாட்டப்பட்டு, அவன் அவற்றை நேரில் கண்டான். இருப்பினும், அவன் தனது நிராகரிப்பு, பிடிவாதம் மற்றும் வரம்புமீறல் காரணமாக அவற்றை மறுத்து ஒதுக்கினான். இதையே மேலானவனாகிய அல்லாஹ் இவ்வாறு கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَجَحَدُوا</span> <span class=\"quran-arabic-font text-success\">بِهَا</span> <span class=\"quran-arabic-font text-success\">وَاسْتَيْقَنَتْهَا</span> <span class=\"quran-arabic-font text-success\">أَنفُسُهُمْ</span> <span class=\"quran-arabic-font text-success\">ظُلْمًا</span> <span class=\"quran-arabic-font text-success\">وَعُلُوًّا﴿</span><br />\r\n<br />\r\n(அவர்களுடைய உள்ளங்கள் அவற்றை உண்மையென உறுதியாகக் கொண்டிருந்தபோதிலும், அநியாயமாகவும் பெருமையாகவும் அவற்றை அவர்கள் மறுத்தார்கள்.) <a href=\"qurandisp.php?sura=27&ayah=14\" class=\"link\">27:14</a><br />\r\n<br />","text":"மூஸா (அலை) அவர்கள் ஃபிர்அவ்னுக்கு அளித்த பதிலின் நிறைவு\n\r\n\n\r\nஃபிர்அவ்ன் தனது இறைவனைப் பற்றி மூஸா (அலை) அவர்களிடம் கேட்டபோது, அவர் அளித்த விளக்கத்தின் நிறைவுப் பகுதி இதுவாகும். மூஸா (அலை) அவர்கள் கூறினார்கள்: ﴾الَّذِي أَعْطَىٰ كُلَّ شَيْءٍ خَلْقَهُ ثُمَّ هَدَىٰ﴿\n\r\n\n\r\n(அவன் ஒவ்வொரு பொருளுக்கும் அதற்குரிய உருவத்தையும் இயற்கையையும் வழங்கி, பின்னர் அதற்கு நேர்வழிகாட்டினான்.) மூஸா (அலை) அவர்கள் பதில் கூறிக்கொண்டிருந்தபோது, ஃபிர்அவ்ன் சில தர்க்கரீதியான மறுப்புகளை முன்வைக்க முயன்றான். ஆயினும், மூஸா (அலை) அவர்கள் தொடர்ந்து கூறினார்கள்: ﴾الَّذِي جَعَلَ لَكُمُ الْأَرْضَ مَهْدًا﴿ \"அவன்தான் பூமியை உங்களுக்கு ஒரு விரிப்பாக ஆக்கினான்.\" சிலர் அந்த வார்த்தையை ‘மிஹாதன்’ (Mihadan) என்றும், மற்றவர்கள் ‘மஹ்தன்’ (Mahdan) என்றும் ஓதினர். இதற்கு ‘நீங்கள் தங்கி ஓய்வெடுக்கும் இடம்’ என்று பொருளாகும். மேலும், ‘நீங்கள் எதன் மீது நிற்கிறீர்களோ, உறங்குகிறீர்களோ அல்லது எதன் மீது பயணம் செய்கிறீர்களோ அது’ என்றும் இது பொருள்படும். ﴾وَسَلَكَ لَكُمْ فِيهَا سُبُلًا﴿\n\r\n\n\r\n(அதில் உங்களுக்காகப் பாதைகளை ஏற்படுத்தினான்.) அதாவது, நீங்கள் அவற்றின் வழியே நடப்பதற்காக அவன் பாதைகளை அமைத்தான் என்று பொருள்படும். இதையே மேலானவனாகிய அல்லாஹ் இவ்வாறு கூறுகிறான்: ﴾وَجَعَلْنَا فِيهَا فِجَاجًا سُبُلًا لَّعَلَّهُمْ يَهْتَدُونَ﴿\n\r\n\n\r\n(அவர்கள் நேர்வழி பெறுவதற்காக, நாம் அதில் விசாலமான பாதைகளை அமைத்தோம்.) 21:31 ﴾وَأَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجْنَا بِهِ أَزْوَاجًا مِّن نَّبَاتٍ شَتَّىٰ﴿\n\r\n\n\r\n(மேலும், வானத்திலிருந்து தண்ணீரை இறக்கினான். அதைக் கொண்டு நாம் பலவகையான தாவரங்களை ஜோடி ஜோடியாக வெளிப்படுத்தினோம்.) இது செடிகொடிகள் மற்றும் பழங்கள் போன்ற பல்வேறு வகையான தாவர இனங்களைக் குறிக்கிறது. அவற்றில் சில புளிப்பானவை, சில இனிப்பானவை, சில கசப்பானவை எனப் பல வகைகள் உள்ளன. ﴾كُلُوا وَارْعَوْا أَنْعَامَكُمْ﴿\n\r\n\n\r\n(நீங்களும் உண்ணுங்கள், உங்கள் கால்நடைகளையும் மேயவிடுங்கள்;) அதாவது, உங்களுக்கு உணவாகவும், சுவையான பழமாகவும் இருப்பதையும், உங்கள் கால்நடைகளுக்குப் பசுமையான மற்றும் காய்ந்த தீவனமாகவும் இருப்பதையும் இது குறிக்கிறது. ﴾إِنَّ فِي ذَٰلِكَ لَآيَاتٍ﴿\n\r\n\n\r\n(நிச்சயமாக, இதில் அத்தாட்சிகள் இருக்கின்றன.) அதாவது சான்றுகள், அடையாளங்கள் மற்றும் ஆதாரங்கள் உள்ளன. ﴾لِّأُولِي النُّهَىٰ﴿\n\r\n\n\r\n(அறிவுடையவர்களுக்கு.) அதாவது, அல்லாஹ்வைத் தவிர வணக்கத்திற்குரிய இறைவன் யாருமில்லை என்பதையும், அவனைத் தவிர உண்மையான இரட்சகன் வேறு யாருமில்லை என்பதையும் உணர்ந்து, நேர்மையான அறிவைப் பெற்றவர்கள் என்று பொருளாகும். ﴾مِنْهَا خَلَقْنَاكُمْ وَفِيهَا نُعِيدُكُمْ وَمِنْهَا نُخْرِجُكُمْ تَارَةً أُخْرَىٰ﴿\n\r\n\n\r\n(அதிலிருந்தே நாம் உங்களைப் படைத்தோம், அதிலேயே நாம் உங்களைத் திரும்பக் கொண்டு செல்வோம், அதிலிருந்தே நாம் உங்களை மற்றொரு முறை வெளிப்படுத்துவோம்.) அதாவது, பூமியே உங்கள் ஆரம்பமாகும். ஏனெனில், உங்கள் தந்தை ஆதம் (அலை) அவர்கள் பூமியின் மேற்பரப்பிலுள்ள மண்ணிலிருந்து படைக்கப்பட்டார்கள். நீங்களும் பூமிக்கே திரும்பக் கொண்டு செல்லப்படுவீர்கள். அதாவது, நீங்கள் மரணித்து மட்கிப் போகும்போது மீண்டும் மண்ணாகவே மாறிவிடுவீர்கள் என்று பொருள்படும். \"அதிலிருந்தே நாம் உங்களை மற்றொரு முறை வெளிப்படுத்துவோம்\" என்ற கூற்றின் பொருள்: ﴾يَوْمَ يَدْعُوكُمْ فَتَسْتَجِيبُونَ بِحَمْدِهِ وَتَظُنُّونَ إِن لَّبِثْتُمْ إِلَّا قَلِيلًا﴿\n\r\n\n\r\n(அவன் உங்களை அழைக்கும் நாளில், அவனது புகழுடன் அவனுக்குக் கீழ்ப்படிந்து நீங்கள் பதிலளிப்பீர்கள். மேலும், நீங்கள் (இவ்வுலகில்) மிகக் குறைந்த காலமே தங்கியிருந்ததாகக் கருதுவீர்கள்!) 17:52 இந்த வசனம் அல்லாஹ்வின் மற்றொரு கூற்றைப் போன்றதாகும்: ﴾قَالَ فِيهَا تَحْيَوْنَ وَفِيهَا تَمُوتُونَ وَمِنْهَا تُخْرَجُونَ﴿\n\r\n\n\r\n(அவன் கூறினான்: \"அதிலேயே நீங்கள் வாழ்வீர்கள், அதிலேயே நீங்கள் மரணிப்பீர்கள், அதிலிருந்தே நீங்கள் வெளிக்கொணரப்படுவீர்கள்.\") 7:25\n\r\n\n\r\nமூஸா (அலை) அவர்கள் ஃபிர்அவ்னுக்கு எல்லா அத்தாட்சிகளையும் காட்டினார்கள், ஆனால் அவன் நம்பவில்லை\n\r\n\n\r\nஅல்லாஹ்வின் கூற்றைப் பற்றி: ﴾وَلَقَدْ أَرَيْنَاهُ آيَاتِنَا كُلَّهَا فَكَذَّبَ وَأَبَىٰ﴿\n\r\n\n\r\n(நிச்சயமாக நாம் அவனுக்கு (ஃபிர்அவ்னுக்கு) நம்முடைய அத்தாட்சிகள் அனைத்தையும் காட்டினோம், ஆனால் அவன் அவற்றை பொய்யாக்கி நிராகரித்தான்.) ஃபிர்அவ்னுக்கு எதிராகச் சான்றுகளும் அடையாளங்களும் ஆதாரங்களும் நிலைநாட்டப்பட்டு, அவன் அவற்றை நேரில் கண்டான். இருப்பினும், அவன் தனது நிராகரிப்பு, பிடிவாதம் மற்றும் வரம்புமீறல் காரணமாக அவற்றை மறுத்து ஒதுக்கினான். இதையே மேலானவனாகிய அல்லாஹ் இவ்வாறு கூறுகிறான்: ﴾وَجَحَدُوا بِهَا وَاسْتَيْقَنَتْهَا أَنفُسُهُمْ ظُلْمًا وَعُلُوًّا﴿\n\r\n\n\r\n(அவர்களுடைய உள்ளங்கள் அவற்றை உண்மையென உறுதியாகக் கொண்டிருந்தபோதிலும், அநியாயமாகவும் பெருமையாகவும் அவற்றை அவர்கள் மறுத்தார்கள்.) 27:14"},"57":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=59\" class=\"link\">20:59</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:59 ஐ பார்க்கவும்"},"58":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=59\" class=\"link\">20:59</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:59 ஐ பார்க்கவும்"},"59":{"html":"<strong>மூஸா (அலை) அவர்களின் அத்தாட்சிகளை சூனியம் என்று ஃபிர்அவ்ன் விவரித்ததும், ஒரு போட்டியை நடத்த அவர்கள் உடன்பட்டதும்</strong><br />\r\n<br />\r\nமூஸா (அலை) அவர்கள் ஃபிர்அவ்னிடம் மாபெரும் அத்தாட்சியைக் காண்பித்தபோது, அவன் அவரிடம் கூறியதைப்பற்றி அல்லாஹ் கூறுகிறான். ஃபிர்அவ்னுக்குக் காட்டப்பட்ட அந்த மாபெரும் அத்தாட்சி யாதெனில், மூஸா (அலை) அவர்கள் தமது தடியைக் கீழே போட்டதும் அது ஒரு பிரம்மாண்டமான பாம்பாக மாறியதும், மேலும் அவர்கள் தமது கையை அக்குளிலிருந்து வெளியே எடுத்தபோது அது எந்த நோயுமின்றி பிரகாசமான வெண்மையாக ஒளிர்ந்ததுமாகும். இதைக் கண்ட ஃபிர்அவ்ன் கூறினான்: \"எங்களை மயக்கி, மக்களை வென்று, அவர்கள் உம்மைப் பின்பற்றுவதற்காக நீர் எங்களிடம் கொண்டு வந்துள்ள சூனியம் இதுவாகும். அதன் மூலம் நீர் எங்களை விட எண்ணிக்கையில் மிஞ்சிவிடுவீர்.\" பிறகு ஃபிர்அவ்ன் கூறினான்: \"உமது திட்டம் பலிக்காது. உம்மிடம் இருப்பது போன்ற சூனியம் எங்களிடமும் இருக்கிறது, ஆகவே நீர் செய்வதைக் கண்டு நீரே ஏமாந்துவிட வேண்டாம்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَاجْعَلْ</span> <span class=\"quran-arabic-font text-success\">بَيْنَنَا</span> <span class=\"quran-arabic-font text-success\">وَبَيْنَكَ</span> <span class=\"quran-arabic-font text-success\">مَوْعِداً</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">نُخْلِفُهُ</span> <span class=\"quran-arabic-font text-success\">نَحْنُ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">أَنتَ</span> <span class=\"quran-arabic-font text-success\">مَكَاناً</span> <span class=\"quran-arabic-font text-success\">سُوًى﴿</span><br />\r\n<br />\r\n(ஆகவே, எங்களுக்கும் உமக்கும் இடையே ஒரு சந்திப்பை ஏற்பாடு செய்வீராக, அதை நாங்களும் மீறமாட்டோம்; நீரும் (மீறக் கூடாது); (அது) சமமான ஒரு இடமாக இருக்கட்டும்.) இதன் பொருள்: 'உமது சூனியத்தை எதிர்கொள்ள எங்களது சூனிய வித்தைகளை வெளிப்படுத்துவதற்காக நாம் ஒன்று கூடும் ஒரு நாள். அது ஒரு குறிப்பிட்ட இடத்திலும் நேரத்திலும் அமையட்டும்.' அப்துர்-ரஹ்மான் பின் ஸைத் பின் அஸ்லம் (ரழி) அவர்கள் கூறினார்கள்: \"அது ஒரு சமதளப் பகுதியாகும், அங்கு மக்கள் அனைவரும் ஒரே மட்டத்தில் இருந்ததால் அந்த நிகழ்வைச் சமமாகப் பார்க்கும் வாய்ப்பு அவர்களுக்கு இருந்தது. அங்கே பார்வையை மறைக்கக்கூடிய எந்தத் தடையும் இருக்கவில்லை, எனவே மக்கள் அனைவரும் அங்கு நடப்பவற்றைத் தெளிவாகக் காண முடிந்தது.\" இதற்கு மூஸா (அலை) அவர்கள் அவர்களிடம் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾مَوْعِدُكُمْ</span> <span class=\"quran-arabic-font text-success\">يَوْمُ</span> <span class=\"quran-arabic-font text-success\">الزِّينَةِ﴿</span><br />\r\n<br />\r\n(உங்களுக்கு வாக்களிக்கப்பட்ட சந்திப்பு திருவிழா நாள் ஆகும்,) அது அவர்களுடைய கொண்டாட்ட நாளாகவும், புத்தாண்டு விழாவாகவும் இருந்தது. அது அவர்களுக்கு ஒரு விடுமுறை நாளாக இருந்ததால், அவர்கள் தங்கள் வேலைகளிலிருந்து ஓய்வு பெற்று பெருந்திரளாக ஒன்று கூடுவார்கள். அல்லாஹ் தான் நாடியதைச் செய்யக்கூடிய ஆற்றல் மிக்கவன் என்பதை மக்கள் அனைவரும் நேரில் காண்பதற்காகவே இந்த நாள் தேர்ந்தெடுக்கப்பட்டது. இதன் மூலம் மக்கள் நபிமார்களின் அற்புதங்களையும், அமானுஷ்யமான நபித்துவ ஆற்றல்களுக்கு முன்னால் சூனியம் என்பது எவ்வளவு பயனற்றது என்பதையும் காண்பார்கள். இதனால்தான் மூஸா (அலை) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَأَن</span> <span class=\"quran-arabic-font text-success\">يُحْشَرَ</span> <span class=\"quran-arabic-font text-success\">النَّاسُ﴿</span><br />\r\n<br />\r\n(மேலும் மக்கள் ஒன்று திரட்டப்படட்டும்) அதாவது அவர்கள் அனைவரும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾ضُحًى﴿</span><br />\r\n<br />\r\n(சூரியன் உதித்த பிறகு (முற்பகல் நேரம்).) அதாவது காலையில், நண்பகலுக்குச் சற்று முன்பாக. இதன் மூலம் அந்தப் போட்டி மிகவும் தெளிவாகவும், வெளிச்சமாகவும், பட்டப்பகலில் மக்கள் அனைவருக்கும் வெளிப்படையாகவும் தெரியும். இதுவே நபிமார்களின் வழிமுறையாகும். அவர்களின் செயல்பாடுகள் எப்போதும் தெளிவானதாகவும் பகிரங்கமானதாகவும் இருக்கும். அது ஒருபோதும் மறைவானதாகவோ அல்லது ஆதாயத்திற்காகவோ இருக்காது. இதனால்தான் மூஸா (அலை) அவர்கள் அந்தச் சந்திப்பு இரவில் நடக்க வேண்டும் என்று கூறாமல், பகலின் பிரகாசமான நேரத்தில் நடக்க வேண்டும் என்று கூறினார்கள்.<br />\r\n<br />\r\nஇப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"அவர்களுடைய அந்தத் திருவிழா நாள் ஆஷூரா நாள் ஆகும்.\" அஸ்-ஸுத்தி, கதாதா மற்றும் இப்னு ஸைத் (ரழி) ஆகியோர், \"அது அவர்களுடைய மாபெரும் கொண்டாட்ட நாள்\" என்று கூறினார்கள். ஸயீத் பின் ஜுபைர் (ரழி) அவர்கள், \"அது அவர்களுடைய பெரிய சந்தை நாள்\" என்று கூறினார்கள். இந்தக் கூற்றுகள் ஒன்றுக்கொன்று முரண்பட்டவை அல்ல. ஸஹீஹ் (ஹதீஸ்) நூல்களில் உறுதிப்படுத்தப்பட்டுள்ளதைப் போலவே, இது போன்ற ஒரு நாளில்தான் அல்லாஹ் ஃபிர்அவ்னையும் அவனது படைகளையும் அழித்தான் என்று நான் கூறுகிறேன்.<br />\r\n<br />\r\n<br />\r\n<br />","text":"மூஸா (அலை) அவர்களின் அத்தாட்சிகளை சூனியம் என்று ஃபிர்அவ்ன் விவரித்ததும், ஒரு போட்டியை நடத்த அவர்கள் உடன்பட்டதும்\n\r\n\n\r\nமூஸா (அலை) அவர்கள் ஃபிர்அவ்னிடம் மாபெரும் அத்தாட்சியைக் காண்பித்தபோது, அவன் அவரிடம் கூறியதைப்பற்றி அல்லாஹ் கூறுகிறான். ஃபிர்அவ்னுக்குக் காட்டப்பட்ட அந்த மாபெரும் அத்தாட்சி யாதெனில், மூஸா (அலை) அவர்கள் தமது தடியைக் கீழே போட்டதும் அது ஒரு பிரம்மாண்டமான பாம்பாக மாறியதும், மேலும் அவர்கள் தமது கையை அக்குளிலிருந்து வெளியே எடுத்தபோது அது எந்த நோயுமின்றி பிரகாசமான வெண்மையாக ஒளிர்ந்ததுமாகும். இதைக் கண்ட ஃபிர்அவ்ன் கூறினான்: \"எங்களை மயக்கி, மக்களை வென்று, அவர்கள் உம்மைப் பின்பற்றுவதற்காக நீர் எங்களிடம் கொண்டு வந்துள்ள சூனியம் இதுவாகும். அதன் மூலம் நீர் எங்களை விட எண்ணிக்கையில் மிஞ்சிவிடுவீர்.\" பிறகு ஃபிர்அவ்ன் கூறினான்: \"உமது திட்டம் பலிக்காது. உம்மிடம் இருப்பது போன்ற சூனியம் எங்களிடமும் இருக்கிறது, ஆகவே நீர் செய்வதைக் கண்டு நீரே ஏமாந்துவிட வேண்டாம்.\"\n\r\n\n\r\n﴾فَاجْعَلْ بَيْنَنَا وَبَيْنَكَ مَوْعِداً لاَّ نُخْلِفُهُ نَحْنُ وَلاَ أَنتَ مَكَاناً سُوًى﴿\n\r\n\n\r\n(ஆகவே, எங்களுக்கும் உமக்கும் இடையே ஒரு சந்திப்பை ஏற்பாடு செய்வீராக, அதை நாங்களும் மீறமாட்டோம்; நீரும் (மீறக் கூடாது); (அது) சமமான ஒரு இடமாக இருக்கட்டும்.) இதன் பொருள்: 'உமது சூனியத்தை எதிர்கொள்ள எங்களது சூனிய வித்தைகளை வெளிப்படுத்துவதற்காக நாம் ஒன்று கூடும் ஒரு நாள். அது ஒரு குறிப்பிட்ட இடத்திலும் நேரத்திலும் அமையட்டும்.' அப்துர்-ரஹ்மான் பின் ஸைத் பின் அஸ்லம் (ரழி) அவர்கள் கூறினார்கள்: \"அது ஒரு சமதளப் பகுதியாகும், அங்கு மக்கள் அனைவரும் ஒரே மட்டத்தில் இருந்ததால் அந்த நிகழ்வைச் சமமாகப் பார்க்கும் வாய்ப்பு அவர்களுக்கு இருந்தது. அங்கே பார்வையை மறைக்கக்கூடிய எந்தத் தடையும் இருக்கவில்லை, எனவே மக்கள் அனைவரும் அங்கு நடப்பவற்றைத் தெளிவாகக் காண முடிந்தது.\" இதற்கு மூஸா (அலை) அவர்கள் அவர்களிடம் கூறினார்கள்:\n\r\n\n\r\n﴾مَوْعِدُكُمْ يَوْمُ الزِّينَةِ﴿\n\r\n\n\r\n(உங்களுக்கு வாக்களிக்கப்பட்ட சந்திப்பு திருவிழா நாள் ஆகும்,) அது அவர்களுடைய கொண்டாட்ட நாளாகவும், புத்தாண்டு விழாவாகவும் இருந்தது. அது அவர்களுக்கு ஒரு விடுமுறை நாளாக இருந்ததால், அவர்கள் தங்கள் வேலைகளிலிருந்து ஓய்வு பெற்று பெருந்திரளாக ஒன்று கூடுவார்கள். அல்லாஹ் தான் நாடியதைச் செய்யக்கூடிய ஆற்றல் மிக்கவன் என்பதை மக்கள் அனைவரும் நேரில் காண்பதற்காகவே இந்த நாள் தேர்ந்தெடுக்கப்பட்டது. இதன் மூலம் மக்கள் நபிமார்களின் அற்புதங்களையும், அமானுஷ்யமான நபித்துவ ஆற்றல்களுக்கு முன்னால் சூனியம் என்பது எவ்வளவு பயனற்றது என்பதையும் காண்பார்கள். இதனால்தான் மூஸா (அலை) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n﴾وَأَن يُحْشَرَ النَّاسُ﴿\n\r\n\n\r\n(மேலும் மக்கள் ஒன்று திரட்டப்படட்டும்) அதாவது அவர்கள் அனைவரும்.\n\r\n\n\r\n﴾ضُحًى﴿\n\r\n\n\r\n(சூரியன் உதித்த பிறகு (முற்பகல் நேரம்).) அதாவது காலையில், நண்பகலுக்குச் சற்று முன்பாக. இதன் மூலம் அந்தப் போட்டி மிகவும் தெளிவாகவும், வெளிச்சமாகவும், பட்டப்பகலில் மக்கள் அனைவருக்கும் வெளிப்படையாகவும் தெரியும். இதுவே நபிமார்களின் வழிமுறையாகும். அவர்களின் செயல்பாடுகள் எப்போதும் தெளிவானதாகவும் பகிரங்கமானதாகவும் இருக்கும். அது ஒருபோதும் மறைவானதாகவோ அல்லது ஆதாயத்திற்காகவோ இருக்காது. இதனால்தான் மூஸா (அலை) அவர்கள் அந்தச் சந்திப்பு இரவில் நடக்க வேண்டும் என்று கூறாமல், பகலின் பிரகாசமான நேரத்தில் நடக்க வேண்டும் என்று கூறினார்கள்.\n\r\n\n\r\nஇப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"அவர்களுடைய அந்தத் திருவிழா நாள் ஆஷூரா நாள் ஆகும்.\" அஸ்-ஸுத்தி, கதாதா மற்றும் இப்னு ஸைத் (ரழி) ஆகியோர், \"அது அவர்களுடைய மாபெரும் கொண்டாட்ட நாள்\" என்று கூறினார்கள். ஸயீத் பின் ஜுபைர் (ரழி) அவர்கள், \"அது அவர்களுடைய பெரிய சந்தை நாள்\" என்று கூறினார்கள். இந்தக் கூற்றுகள் ஒன்றுக்கொன்று முரண்பட்டவை அல்ல. ஸஹீஹ் (ஹதீஸ்) நூல்களில் உறுதிப்படுத்தப்பட்டுள்ளதைப் போலவே, இது போன்ற ஒரு நாளில்தான் அல்லாஹ் ஃபிர்அவ்னையும் அவனது படைகளையும் அழித்தான் என்று நான் கூறுகிறேன்."},"60":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=64\" class=\"link\">20:64</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:64 ஐ பார்க்கவும்"},"61":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=64\" class=\"link\">20:64</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:64 ஐ பார்க்கவும்"},"62":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=64\" class=\"link\">20:64</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:64 ஐ பார்க்கவும்"},"63":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=64\" class=\"link\">20:64</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:64 ஐ பார்க்கவும்"},"64":{"html":"<strong>இரு தரப்பினரின் சந்திப்பு, மூஸா (அலை) அவர்களின் பிரச்சாரம் மற்றும் சூனியக்காரர்கள்</strong><br />\r\n<br />\r\nஃபிர்அவ்னும் மூஸா (அலை) அவர்களும் ஒரு குறிப்பிட்ட இடத்திலும் நேரத்திலும் சந்திப்பதாக முடிவு செய்தபோது, ஃபிர்அவ்ன் தனது ராஜ்ஜியத்தின் நகரங்களிலிருந்து சூனியக்காரர்களைத் திரட்டத் தொடங்கினான் என்று கண்ணியமிக்க அல்லாஹ் கூறுகிறான். அக்காலத்தில் சூனியக்கலை மிகவும் பரவலாகவும் செல்வாக்கு பெற்றும் இருந்ததால், அத்துறையோடு தொடர்புடைய அனைவரும் அழைக்கப்பட்டனர். இதனை அல்லாஹ் பின்வருமாறு கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَقَالَ</span> <span class=\"quran-arabic-font text-success\">فِرْعَوْنُ</span> <span class=\"quran-arabic-font text-success\">ائْتُونِى</span> <span class=\"quran-arabic-font text-success\">بِكُلِّ</span> <span class=\"quran-arabic-font text-success\">سَاحِرٍ</span> <span class=\"quran-arabic-font text-success\">عَلِيمٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(மேலும் ஃபிர்அவ்ன் கூறினான்: \"தேர்ச்சி பெற்ற ஒவ்வொரு சூனியக்காரனையும் என்னிடம் கொண்டு வாருங்கள்.\") <a href=\"qurandisp.php?sura=10&ayah=79\" class=\"link\">10:79</a><br />\r\n<br />\r\nபிறகு, அந்த நாள் வந்தது. மக்கள் அனைவரும் ஒன்று கூடும் அந்தச் சிறப்புமிக்க திருவிழா நாளாக அது இருந்தது. ஃபிர்அவ்ன் தனது சிம்மாசனத்தில் அமர்ந்திருக்க, அவனைச் சுற்றி அவனது நாட்டு உயர் அதிகாரிகள் இருந்தனர். பொதுமக்கள் அனைவரும் அவனது வலது மற்றும் இடது புறங்களில் நின்றிருந்தனர். அப்போது மூஸா (அலை) அவர்கள் தனது சகோதரர் ஹாரூன் (அலை) அவர்களுடன், தனது கைத்தடியில் சாய்ந்தபடி முன்னே வந்தார்கள். சூனியக்காரர்கள் ஃபிர்அவ்னுக்கு முன்னால் வரிசையாக நின்றிருந்தனர். ஃபிர்அவ்ன் அவர்களைத் தூண்டிவிட்டு, அன்றைய தினம் தங்களின் முழுத் திறமையையும் வெளிப்படுத்த ஊக்கப்படுத்திக் கொண்டிருந்தான். சூனியக்காரர்கள் அவனைத் திருப்திப்படுத்த விரும்பினர். அவனும் அவர்களுக்குப் பல வாக்குறுதிகளை அளித்து அவர்களை உற்சாகப்படுத்தினான். அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾فَلَمَّا</span> <span class=\"quran-arabic-font text-success\">جَآءَ</span> <span class=\"quran-arabic-font text-success\">السَّحَرَةُ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">لِفِرْعَوْنَ</span> <span class=\"quran-arabic-font text-success\">أَإِنَّ</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">لَأَجْرًا</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كُنَّا</span> <span class=\"quran-arabic-font text-success\">نَحْنُ</span> <span class=\"quran-arabic-font text-success\">الْغَالِبِينَ</span> - <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">نَعَمْ</span> <span class=\"quran-arabic-font text-success\">وَإِنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">إِذًا</span> <span class=\"quran-arabic-font text-success\">لَّمِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُقَرَّبِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(நாங்கள் வெற்றி பெற்றால் எங்களுக்குத் திண்ணமாக வெகுமதி கிடைக்குமா? என்று அவர்கள் கேட்டனர். அவன் (ஃபிர்அவ்ன்) கூறினான்: \"ஆம், நிச்சயமாக நீங்கள் எனக்கு நெருக்கமானவர்களாகவும் ஆக்கப்படுவீர்கள்.\") <a href=\"qurandisp.php?sura=26&ayah=41\" class=\"link\">26:41</a>-42<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">مُّوسَى</span> <span class=\"quran-arabic-font text-success\">وَيْلَكُمْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَفْتَرُواْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">كَذِباً﴿</span><br />\r\n(மூஸா (அலை) அவர்கள் அவர்களிடம் கூறினார்கள்: \"உங்களுக்குக் கேடுதான்! அல்லாஹ்வின் மீது பொய்யை இட்டுக்கட்டாதீர்கள்...\") அதாவது, \"உண்மையில் இல்லாத ஒன்றை, ஒரு உயிரினத்தைப் போலத் தோற்றமளிக்கும்படி செய்து மக்கள் முன்னால் மாயையை ஏற்படுத்தாதீர்கள். நீங்கள் அவ்வாறு செய்தால், அல்லாஹ்வின் மீது பொய் சொன்னவர்களாகி விடுவீர்கள்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَيُسْحِتَكُم</span> <span class=\"quran-arabic-font text-success\">بِعَذَابٍ﴿</span><br />\r\n(அவன் (அல்லாஹ்) ஒரு வேதனையைக் கொண்டு உங்களை வேரோடு அழித்துவிடுவான்.) இதன் பொருள், எதையும் யாரையும் விட்டுவைக்காத ஒரு அழிவுகரமான தண்டனையைக் கொண்டு அவன் உங்களை அழித்துவிடுவான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَقَدْ</span> <span class=\"quran-arabic-font text-success\">خَابَ</span> <span class=\"quran-arabic-font text-success\">مَنِ</span> <span class=\"quran-arabic-font text-success\">افْتَرَى</span> <span class=\"quran-arabic-font text-success\">فَتَنَـزَعُواْ</span> <span class=\"quran-arabic-font text-success\">أَمْرَهُمْ</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمْ﴿</span><br />\r\n(\"...நிச்சயமாக, பொய்யை இட்டுக்கட்டுபவன் நஷ்டமடைவான்.\" பிறகு அவர்கள் தாங்கள் செய்ய வேண்டியது குறித்துத் தங்களுக்குள் விவாதித்துக் கொண்டனர்.) அவர்கள் தங்களுக்குள் வாக்குவாதம் செய்ததாகக் கூறப்படுகிறது. அவர்களில் ஒருவர், \"இது ஒரு சூனியக்காரரின் பேச்சல்ல, மாறாக ஒரு நபியின் பேச்சு\" என்றார். மற்றொருவரோ, \"இல்லை, அவர் ஒரு சூனியக்காரர் மட்டுமே\" என்றார். அவர்கள் விவாதித்தவை குறித்து இன்னும் பல கருத்துக்கள் கூறப்பட்டுள்ளன. அல்லாஹ்வே மிக அறிந்தவன்.<br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்றான <span class=\"quran-arabic-font text-success\">﴾وَأَسَرُّواْ</span> <span class=\"quran-arabic-font text-success\">النَّجْوَى﴿</span><br />\r\n(மேலும் அவர்கள் தங்கள் இரகசிய ஆலோசனையை மறைத்துக் கொண்டனர்.) என்பது, அவர்கள் இந்த விஷயம் குறித்துத் தங்களுக்குள் இரகசியமாக ஆலோசித்ததைக் குறிக்கிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالُواْ</span> <span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">هَذَانِ</span> <span class=\"quran-arabic-font text-success\">لَسَاحِرَانِ﴿</span><br />\r\n(அவர்கள் கூறினார்கள்: \"நிச்சயமாக இவர்கள் இருவரும் சூனியக்காரர்களே...\") இது சில அரபு கோத்திரத்தாரின் பேச்சு வழக்காகும். இந்த வசனம் அவர்களின் வட்டார மொழி இலக்கணப்படி ஓதப்பட்டுள்ளது. வேறு சிலர் இதனை (<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">هَذَيْنِ</span> <span class=\"quran-arabic-font text-success\">لَسَاحِرَانِ</span>) என்றும் ஓதுகின்றனர். இதற்கும் \"நிச்சயமாக இவர்கள் இருவரும் சூனியக்காரர்களே\" என்ற அதே பொருள்தான். இது அரபி இலக்கணத்தில் பொதுவாகப் பயன்படுத்தப்படும் முறையாகும். முதல் ஓதுமுறை மற்றும் அதன் இலக்கண விளக்கம் குறித்து இலக்கண அறிஞர்களிடையே விரிவான விவாதங்கள் உள்ளன, ஆனால் இது அதற்கான இடமல்ல. இதன் முக்கியக் கருத்து என்னவென்றால், அந்தச் சூனியக்காரர்கள் தங்களுக்குள் இவ்வாறு பேசிக்கொண்டனர்: \"இந்த மனிதரும் (மூஸா (அலை)) அவரது சகோதரரும் (ஹாரூன் (அலை)) சூனியக்கலையில் மிகுந்த தேர்ச்சி பெற்ற இரு சூனியக்காரர்கள் என்பதை நீங்கள் அறிவீர்கள். அவர்கள் இன்று உங்களையும் உங்கள் மக்களையும் தோற்கடித்து, மக்களைத் தங்கள் பக்கம் ஈர்க்க விரும்புகிறார்கள். அவர்கள் ஃபிர்அவ்னுக்கும் அவனது படைகளுக்கும் எதிராகப் போராடி வெற்றியடையத் துடிக்கிறார்கள். உங்களை உங்கள் நாட்டிலிருந்து வெளியேற்றுவதே அவர்களின் இறுதி லட்சியம்.\"<br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்றான <span class=\"quran-arabic-font text-success\">﴾وَيَذْهَبَا</span> <span class=\"quran-arabic-font text-success\">بِطَرِيقَتِكُمُ</span> <span class=\"quran-arabic-font text-success\">الْمُثْلَى﴿</span><br />\r\n(மேலும் உங்கள் மேன்மையான வழியிலிருந்து உங்களை அப்புறப்படுத்தவும் விரும்புகிறார்கள்.) என்பது, 'அவர்கள் உங்களின் இந்த வழியை (சூனியத்தை) பகிரங்கமாகத் தகர்க்க விரும்புகிறார்கள்' என்று பொருள்படும். ஏனெனில், அவர்கள் தங்களின் சூனியக் கலையினாலேயே கௌரவிக்கப்பட்டனர்; அவர்களுக்குச் செல்வமும் வாழ்வாதாரமும் இதன் மூலமே கிடைத்தன. அவர்கள் உண்மையில் என்ன கூறினார்கள் என்றால், \"இவர்கள் இருவரும் (மூஸா (அலை) மற்றும் ஹாரூன் (அலை)) வெற்றி பெற்றால், அவர்கள் உங்களை அழித்து உங்கள் தேசத்திலிருந்தே வெளியேற்றி விடுவார்கள். அவ்வாறு செய்வதன் மூலம் அவர்கள் அதிகாரத்தைக் கைப்பற்றிக் கொள்வார்கள், நீங்கள் தலைமைத்துவத்தை இழந்துவிடுவீர்கள்.\"<br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்றான <span class=\"quran-arabic-font text-success\">﴾وَيَذْهَبَا</span> <span class=\"quran-arabic-font text-success\">بِطَرِيقَتِكُمُ</span> <span class=\"quran-arabic-font text-success\">الْمُثْلَى﴿</span><br />\r\n(மேலும் உங்கள் மேன்மையான வழியிலிருந்து உங்களை அப்புறப்படுத்தவும்.) என்பது குறித்து இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறுகையில், \"இதன் பொருள் அவர்கள் அனுபவித்து வந்த ராஜ்ஜியம் மற்றும் வாழ்வாதாரம்\" என்றார்கள். அப்துர் ரஹ்மான் பின் ஸைத் அவர்கள் கூறுகையில், \"இந்த மேன்மையான வழி என்பது அவர்கள் கடைபிடித்து வந்த மார்க்கமாகும்\" என்றார்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَأَجْمِعُواْ</span> <span class=\"quran-arabic-font text-success\">كَيْدَكُمْ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">ائْتُواْ</span> <span class=\"quran-arabic-font text-success\">صَفّاً﴿</span><br />\r\n(எனவே உங்கள் சூழ்ச்சிகளை ஒன்று திரட்டுங்கள், பிறகு வரிசையாக வாருங்கள்.) இதன் பொருள், \"நீங்கள் அனைவரும் ஒரே அணியாகத் திரண்டு வாருங்கள். மக்களின் கண்களைக் கவரும் விதமாகவும், இந்த மனிதரையும் அவரது சகோதரரையும் தோற்கடிக்கும் விதமாகவும் உங்கள் கைகளில் உள்ளவற்றை ஒரே நேரத்தில் வீசுங்கள்\" என்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَقَدْ</span> <span class=\"quran-arabic-font text-success\">أَفْلَحَ</span> <span class=\"quran-arabic-font text-success\">الْيَوْمَ</span> <span class=\"quran-arabic-font text-success\">مَنِ</span> <span class=\"quran-arabic-font text-success\">اسْتَعْلَى﴿</span><br />\r\n(இன்று எவர் மேலோங்குகிறாரோ, அவரே நிச்சயமாக வெற்றி பெறுவார்.) அதாவது \"உங்களுக்கும் எங்களுக்கும் இடையிலான போட்டியில், எங்களைப் (சூனியக்காரர்களைப்) பொறுத்தவரை எங்களுக்கு மிகுந்த அதிகாரமும் கௌரவமும் அளிக்கப்படும் என்று வாக்குறுதி அளிக்கப்பட்டுள்ளது. மூஸா (அலை) அவர்களைப் பொறுத்தவரை, அவர் ஒரு பெரும் தலைவராகத் திகழ்வார் (என்று அவர்கள் பேசிக்கொண்டனர்).\"<br />\r\n<br />","text":"இரு தரப்பினரின் சந்திப்பு, மூஸா (அலை) அவர்களின் பிரச்சாரம் மற்றும் சூனியக்காரர்கள்\n\r\n\n\r\nஃபிர்அவ்னும் மூஸா (அலை) அவர்களும் ஒரு குறிப்பிட்ட இடத்திலும் நேரத்திலும் சந்திப்பதாக முடிவு செய்தபோது, ஃபிர்அவ்ன் தனது ராஜ்ஜியத்தின் நகரங்களிலிருந்து சூனியக்காரர்களைத் திரட்டத் தொடங்கினான் என்று கண்ணியமிக்க அல்லாஹ் கூறுகிறான். அக்காலத்தில் சூனியக்கலை மிகவும் பரவலாகவும் செல்வாக்கு பெற்றும் இருந்ததால், அத்துறையோடு தொடர்புடைய அனைவரும் அழைக்கப்பட்டனர். இதனை அல்லாஹ் பின்வருமாறு கூறுகிறான்: ﴾وَقَالَ فِرْعَوْنُ ائْتُونِى بِكُلِّ سَاحِرٍ عَلِيمٍ ﴿\n\r\n(மேலும் ஃபிர்அவ்ன் கூறினான்: \"தேர்ச்சி பெற்ற ஒவ்வொரு சூனியக்காரனையும் என்னிடம் கொண்டு வாருங்கள்.\") 10:79\n\r\n\n\r\nபிறகு, அந்த நாள் வந்தது. மக்கள் அனைவரும் ஒன்று கூடும் அந்தச் சிறப்புமிக்க திருவிழா நாளாக அது இருந்தது. ஃபிர்அவ்ன் தனது சிம்மாசனத்தில் அமர்ந்திருக்க, அவனைச் சுற்றி அவனது நாட்டு உயர் அதிகாரிகள் இருந்தனர். பொதுமக்கள் அனைவரும் அவனது வலது மற்றும் இடது புறங்களில் நின்றிருந்தனர். அப்போது மூஸா (அலை) அவர்கள் தனது சகோதரர் ஹாரூன் (அலை) அவர்களுடன், தனது கைத்தடியில் சாய்ந்தபடி முன்னே வந்தார்கள். சூனியக்காரர்கள் ஃபிர்அவ்னுக்கு முன்னால் வரிசையாக நின்றிருந்தனர். ஃபிர்அவ்ன் அவர்களைத் தூண்டிவிட்டு, அன்றைய தினம் தங்களின் முழுத் திறமையையும் வெளிப்படுத்த ஊக்கப்படுத்திக் கொண்டிருந்தான். சூனியக்காரர்கள் அவனைத் திருப்திப்படுத்த விரும்பினர். அவனும் அவர்களுக்குப் பல வாக்குறுதிகளை அளித்து அவர்களை உற்சாகப்படுத்தினான். அவர்கள் கூறினார்கள்: ﴾فَلَمَّا جَآءَ السَّحَرَةُ قَالُواْ لِفِرْعَوْنَ أَإِنَّ لَنَا لَأَجْرًا إِن كُنَّا نَحْنُ الْغَالِبِينَ - قَالَ نَعَمْ وَإِنَّكُمْ إِذًا لَّمِنَ الْمُقَرَّبِينَ ﴿\n\r\n(நாங்கள் வெற்றி பெற்றால் எங்களுக்குத் திண்ணமாக வெகுமதி கிடைக்குமா? என்று அவர்கள் கேட்டனர். அவன் (ஃபிர்அவ்ன்) கூறினான்: \"ஆம், நிச்சயமாக நீங்கள் எனக்கு நெருக்கமானவர்களாகவும் ஆக்கப்படுவீர்கள்.\") 26:41-42\n\r\n\n\r\n﴾قَالَ لَهُمْ مُّوسَى وَيْلَكُمْ لاَ تَفْتَرُواْ عَلَى اللَّهِ كَذِباً﴿\n\r\n(மூஸா (அலை) அவர்கள் அவர்களிடம் கூறினார்கள்: \"உங்களுக்குக் கேடுதான்! அல்லாஹ்வின் மீது பொய்யை இட்டுக்கட்டாதீர்கள்...\") அதாவது, \"உண்மையில் இல்லாத ஒன்றை, ஒரு உயிரினத்தைப் போலத் தோற்றமளிக்கும்படி செய்து மக்கள் முன்னால் மாயையை ஏற்படுத்தாதீர்கள். நீங்கள் அவ்வாறு செய்தால், அல்லாஹ்வின் மீது பொய் சொன்னவர்களாகி விடுவீர்கள்.\"\n\r\n\n\r\n﴾فَيُسْحِتَكُم بِعَذَابٍ﴿\n\r\n(அவன் (அல்லாஹ்) ஒரு வேதனையைக் கொண்டு உங்களை வேரோடு அழித்துவிடுவான்.) இதன் பொருள், எதையும் யாரையும் விட்டுவைக்காத ஒரு அழிவுகரமான தண்டனையைக் கொண்டு அவன் உங்களை அழித்துவிடுவான்.\n\r\n\n\r\n﴾وَقَدْ خَابَ مَنِ افْتَرَى فَتَنَـزَعُواْ أَمْرَهُمْ بَيْنَهُمْ﴿\n\r\n(\"...நிச்சயமாக, பொய்யை இட்டுக்கட்டுபவன் நஷ்டமடைவான்.\" பிறகு அவர்கள் தாங்கள் செய்ய வேண்டியது குறித்துத் தங்களுக்குள் விவாதித்துக் கொண்டனர்.) அவர்கள் தங்களுக்குள் வாக்குவாதம் செய்ததாகக் கூறப்படுகிறது. அவர்களில் ஒருவர், \"இது ஒரு சூனியக்காரரின் பேச்சல்ல, மாறாக ஒரு நபியின் பேச்சு\" என்றார். மற்றொருவரோ, \"இல்லை, அவர் ஒரு சூனியக்காரர் மட்டுமே\" என்றார். அவர்கள் விவாதித்தவை குறித்து இன்னும் பல கருத்துக்கள் கூறப்பட்டுள்ளன. அல்லாஹ்வே மிக அறிந்தவன்.\n\r\n\n\r\nஅல்லாஹ்வின் கூற்றான ﴾وَأَسَرُّواْ النَّجْوَى﴿\n\r\n(மேலும் அவர்கள் தங்கள் இரகசிய ஆலோசனையை மறைத்துக் கொண்டனர்.) என்பது, அவர்கள் இந்த விஷயம் குறித்துத் தங்களுக்குள் இரகசியமாக ஆலோசித்ததைக் குறிக்கிறது.\n\r\n\n\r\n﴾قَالُواْ إِنْ هَذَانِ لَسَاحِرَانِ﴿\n\r\n(அவர்கள் கூறினார்கள்: \"நிச்சயமாக இவர்கள் இருவரும் சூனியக்காரர்களே...\") இது சில அரபு கோத்திரத்தாரின் பேச்சு வழக்காகும். இந்த வசனம் அவர்களின் வட்டார மொழி இலக்கணப்படி ஓதப்பட்டுள்ளது. வேறு சிலர் இதனை (إِنَّ هَذَيْنِ لَسَاحِرَانِ) என்றும் ஓதுகின்றனர். இதற்கும் \"நிச்சயமாக இவர்கள் இருவரும் சூனியக்காரர்களே\" என்ற அதே பொருள்தான். இது அரபி இலக்கணத்தில் பொதுவாகப் பயன்படுத்தப்படும் முறையாகும். முதல் ஓதுமுறை மற்றும் அதன் இலக்கண விளக்கம் குறித்து இலக்கண அறிஞர்களிடையே விரிவான விவாதங்கள் உள்ளன, ஆனால் இது அதற்கான இடமல்ல. இதன் முக்கியக் கருத்து என்னவென்றால், அந்தச் சூனியக்காரர்கள் தங்களுக்குள் இவ்வாறு பேசிக்கொண்டனர்: \"இந்த மனிதரும் (மூஸா (அலை)) அவரது சகோதரரும் (ஹாரூன் (அலை)) சூனியக்கலையில் மிகுந்த தேர்ச்சி பெற்ற இரு சூனியக்காரர்கள் என்பதை நீங்கள் அறிவீர்கள். அவர்கள் இன்று உங்களையும் உங்கள் மக்களையும் தோற்கடித்து, மக்களைத் தங்கள் பக்கம் ஈர்க்க விரும்புகிறார்கள். அவர்கள் ஃபிர்அவ்னுக்கும் அவனது படைகளுக்கும் எதிராகப் போராடி வெற்றியடையத் துடிக்கிறார்கள். உங்களை உங்கள் நாட்டிலிருந்து வெளியேற்றுவதே அவர்களின் இறுதி லட்சியம்.\"\n\r\n\n\r\nஅல்லாஹ்வின் கூற்றான ﴾وَيَذْهَبَا بِطَرِيقَتِكُمُ الْمُثْلَى﴿\n\r\n(மேலும் உங்கள் மேன்மையான வழியிலிருந்து உங்களை அப்புறப்படுத்தவும் விரும்புகிறார்கள்.) என்பது, 'அவர்கள் உங்களின் இந்த வழியை (சூனியத்தை) பகிரங்கமாகத் தகர்க்க விரும்புகிறார்கள்' என்று பொருள்படும். ஏனெனில், அவர்கள் தங்களின் சூனியக் கலையினாலேயே கௌரவிக்கப்பட்டனர்; அவர்களுக்குச் செல்வமும் வாழ்வாதாரமும் இதன் மூலமே கிடைத்தன. அவர்கள் உண்மையில் என்ன கூறினார்கள் என்றால், \"இவர்கள் இருவரும் (மூஸா (அலை) மற்றும் ஹாரூன் (அலை)) வெற்றி பெற்றால், அவர்கள் உங்களை அழித்து உங்கள் தேசத்திலிருந்தே வெளியேற்றி விடுவார்கள். அவ்வாறு செய்வதன் மூலம் அவர்கள் அதிகாரத்தைக் கைப்பற்றிக் கொள்வார்கள், நீங்கள் தலைமைத்துவத்தை இழந்துவிடுவீர்கள்.\"\n\r\n\n\r\nஅல்லாஹ்வின் கூற்றான ﴾وَيَذْهَبَا بِطَرِيقَتِكُمُ الْمُثْلَى﴿\n\r\n(மேலும் உங்கள் மேன்மையான வழியிலிருந்து உங்களை அப்புறப்படுத்தவும்.) என்பது குறித்து இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறுகையில், \"இதன் பொருள் அவர்கள் அனுபவித்து வந்த ராஜ்ஜியம் மற்றும் வாழ்வாதாரம்\" என்றார்கள். அப்துர் ரஹ்மான் பின் ஸைத் அவர்கள் கூறுகையில், \"இந்த மேன்மையான வழி என்பது அவர்கள் கடைபிடித்து வந்த மார்க்கமாகும்\" என்றார்.\n\r\n\n\r\n﴾فَأَجْمِعُواْ كَيْدَكُمْ ثُمَّ ائْتُواْ صَفّاً﴿\n\r\n(எனவே உங்கள் சூழ்ச்சிகளை ஒன்று திரட்டுங்கள், பிறகு வரிசையாக வாருங்கள்.) இதன் பொருள், \"நீங்கள் அனைவரும் ஒரே அணியாகத் திரண்டு வாருங்கள். மக்களின் கண்களைக் கவரும் விதமாகவும், இந்த மனிதரையும் அவரது சகோதரரையும் தோற்கடிக்கும் விதமாகவும் உங்கள் கைகளில் உள்ளவற்றை ஒரே நேரத்தில் வீசுங்கள்\" என்பதாகும்.\n\r\n\n\r\n﴾وَقَدْ أَفْلَحَ الْيَوْمَ مَنِ اسْتَعْلَى﴿\n\r\n(இன்று எவர் மேலோங்குகிறாரோ, அவரே நிச்சயமாக வெற்றி பெறுவார்.) அதாவது \"உங்களுக்கும் எங்களுக்கும் இடையிலான போட்டியில், எங்களைப் (சூனியக்காரர்களைப்) பொறுத்தவரை எங்களுக்கு மிகுந்த அதிகாரமும் கௌரவமும் அளிக்கப்படும் என்று வாக்குறுதி அளிக்கப்பட்டுள்ளது. மூஸா (அலை) அவர்களைப் பொறுத்தவரை, அவர் ஒரு பெரும் தலைவராகத் திகழ்வார் (என்று அவர்கள் பேசிக்கொண்டனர்).\""},"65":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=70\" class=\"link\">20:70</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:70 ஐ பார்க்கவும்"},"66":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=70\" class=\"link\">20:70</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:70 ஐ பார்க்கவும்"},"67":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=70\" class=\"link\">20:70</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:70 ஐ பார்க்கவும்"},"68":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=70\" class=\"link\">20:70</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:70 ஐ பார்க்கவும்"},"69":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=70\" class=\"link\">20:70</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:70 ஐ பார்க்கவும்"},"70":{"html":"<strong>போட்டி, மூஸா (அலை) அவர்களின் வெற்றி மற்றும் சூனியக்காரர்களின் ஈமான் (நம்பிக்கை)</strong><br />\r\n<br />\r\nமூஸா (அலை) அவர்களைச் சந்தித்தபோது சூனியக்காரர்கள் அவரிடம் கூறியது குறித்து கண்ணியமிக்க அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾إِمَّآ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تُلْقِىَ﴿</span><br />\r\n<br />\r\n(\"ஒன்றில் நீர் எறியலாம்...\") அதாவது, \"நீரே முதலில் தொடங்கும்.\" <span class=\"quran-arabic-font text-success\">﴾وَإِمَّآ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">نَّكُونَ</span> <span class=\"quran-arabic-font text-success\">أَوَّلَ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">أَلْقَى</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">أَلْقُواْ﴿</span><br />\r\n<br />\r\n(\"...அல்லது முதலில் எறிபவர்களாக நாங்கள் இருக்க வேண்டுமா?\" அதற்கு மூஸா (அலை) கூறினார்கள்: \"இல்லை, நீங்களே (முதலில்) எறியுங்கள்!\") இதன் பொருள்: \"சூனியக்காரர்களாகிய நீங்கள் முதலில் உங்கள் கைவரிசையைக் காட்டுங்கள்; அப்போதுதான் நீங்கள் எத்தகைய சூனியத்தைச் செய்கிறீர்கள் என்பதை நாங்கள் பார்க்க முடியும், மேலும் அவர்களின் சூழ்ச்சியின் உண்மை நிலையும் மக்களுக்குத் தெளிவாகும்.\" <span class=\"quran-arabic-font text-success\">﴾فَإِذَا</span> <span class=\"quran-arabic-font text-success\">حِبَالُهُمْ</span> <span class=\"quran-arabic-font text-success\">وَعِصِيُّهُمْ</span> <span class=\"quran-arabic-font text-success\">يُخَيَّلُ</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">سِحْرِهِمْ</span> <span class=\"quran-arabic-font text-success\">أَنَّهَا</span> <span class=\"quran-arabic-font text-success\">تَسْعَى﴿</span><br />\r\n<br />\r\n(அப்பொழுது, இதோ! அவர்களுடைய கயிறுகளும் தடிகளும், அவர்களுடைய சூனியத்தினால் அவை வேகமாக நகர்வது போல் அவருக்குத் தோன்றியது.) மற்றோர் வசனத்தில் அவர்கள் எறிந்தபோது இவ்வாறு கூறியதாகக் குறிப்பிடப்பட்டுள்ளது: <span class=\"quran-arabic-font text-success\">﴾وَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">بِعِزَّةِ</span> <span class=\"quran-arabic-font text-success\">فِرْعَونَ</span> <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">لَنَحْنُ</span> <span class=\"quran-arabic-font text-success\">الْغَالِبُونَ﴿</span><br />\r\n<br />\r\n(அவர்கள் கூறினார்கள்: \"ஃபிர்அவ்னின் கண்ணியத்தின் மீது ஆணையாக! நிச்சயமாக நாங்களே வெற்றி பெறுவோம்!\") <a href=\"qurandisp.php?sura=26&ayah=44\" class=\"link\">26:44</a> மேலும், கண்ணியமிக்க அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾سَحَرُواْ</span> <span class=\"quran-arabic-font text-success\">أَعْيُنَ</span> <span class=\"quran-arabic-font text-success\">النَّاسِ</span> <span class=\"quran-arabic-font text-success\">وَاسْتَرْهَبُوهُمْ</span> <span class=\"quran-arabic-font text-success\">وَجَآءُو</span> <span class=\"quran-arabic-font text-success\">بِسِحْرٍ</span> <span class=\"quran-arabic-font text-success\">عَظِيمٍ﴿</span><br />\r\n<br />\r\n(அவர்கள் மக்களின் கண்களை மயக்கி, அவர்களை அச்சமடையச் செய்தனர்; மேலும், அவர்கள் ஒரு பெரிய சூனியத்தைக் கொண்டு வந்தனர்.) <a href=\"qurandisp.php?sura=7&ayah=116\" class=\"link\">7:116</a> இங்கே, இந்தச் சூராவில் அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾فَإِذَا</span> <span class=\"quran-arabic-font text-success\">حِبَالُهُمْ</span> <span class=\"quran-arabic-font text-success\">وَعِصِيُّهُمْ</span> <span class=\"quran-arabic-font text-success\">يُخَيَّلُ</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">سِحْرِهِمْ</span> <span class=\"quran-arabic-font text-success\">أَنَّهَا</span> <span class=\"quran-arabic-font text-success\">تَسْعَى﴿</span><br />\r\n<br />\r\n(அப்பொழுது, இதோ! அவர்களுடைய கயிறுகளும் தடிகளும், அவர்களுடைய சூனியத்தினால் அவை வேகமாக நகர்வது போல் அவருக்குத் தோன்றியது.) அவர்கள் ஒரு பெரும் கூட்டமாக இருந்தனர்; அவர்கள் ஒவ்வொருவரும் ஒரு தடியையும் கயிற்றையும் எறிந்தனர். இறுதியில் அந்தப் பள்ளத்தாக்கு முழுவதும் ஒன்றன் மேல் ஒன்றாக நெளியும் பாம்புகளால் நிறைந்தது. அல்லாஹ்வின் கூற்றான: <span class=\"quran-arabic-font text-success\">﴾فَأَوْجَسَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">نَفْسِهِ</span> <span class=\"quran-arabic-font text-success\">خِيفَةً</span> <span class=\"quran-arabic-font text-success\">مُّوسَى</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(ஆகவே, மூஸா (அலை) தமக்குள்ளே ஓர் அச்சத்தை உணர்ந்தார்கள்) என்பதன் பொருள்: தான் தனது வலது கையில் உள்ளதை எறிவதற்கு முன்பே, மக்கள் இவர்களது சூனியத்தைக் கண்டு குழப்பமடைந்து ஏமாந்து விடுவார்களோ என்று மூஸா (அலை) அஞ்சினார்கள். <span class=\"quran-arabic-font text-success\">﴾قُلْنَا</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَخَفْ</span> <span class=\"quran-arabic-font text-success\">إِنَّكَ</span> <span class=\"quran-arabic-font text-success\">أَنتَ</span> <span class=\"quran-arabic-font text-success\">الأَعْلَى</span> - <span class=\"quran-arabic-font text-success\">وَأَلْقِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">يَمِينِكَ</span> <span class=\"quran-arabic-font text-success\">تَلْقَفْ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">صَنَعُواْ﴿</span> (\"நாம் சொன்னோம்: பயப்படாதீர்! நிச்சயமாக நீர்தான் மேலோங்கி நிற்பீர். உமது வலது கையில் இருப்பதை எறிவீராக! அது அவர்கள் செய்தவற்றை விழுங்கிவிடும்.\") எனவே, சரியான தருணத்தில் அல்லாஹ் அவருக்கு வஹீ (இறைச்செய்தி) அறிவித்தான்: தனது வலது கையில் இருக்கும் தடியை எறியுமாறு. அவர் அதை எறிந்தபோது, அது அவர்கள் உருவாக்கிய சூனியங்கள் அனைத்தையும் விழுங்கியது. அது கால்கள், கழுத்து, தலை மற்றும் கோரைப் பற்களுடன் ஒரு பிரம்மாண்டமான ராட்சத உயிரினமாக மாறியது. அந்த மிருகம் அங்கிருந்த கயிறுகளையும் தடிகளையும் துரத்திச் சென்று, அவை எதையும் விட்டுவைக்காமல் அனைத்தையும் விழுங்கி ஏப்பமிட்டது. அதே நேரத்தில், சூனியக்காரர்களும் மக்களும் பட்டப்பகலில் நடந்த இந்த வியக்கத்தக்க அதிசயத்தை தங்கள் கண்களால் நேரடியாகக் கண்டனர். இவ்வாறாக அந்த அற்புதம் நிகழ்ந்தது, ஆதாரம் தெளிவாகியது. சத்தியம் வென்றது, சூனியம் பொய்யானது என்பது நிரூபணமானது. இதனால்தான் அல்லாஹ் இவ்வாறு கூறினான்: <span class=\"quran-arabic-font text-success\">﴾إِنَّمَا</span> <span class=\"quran-arabic-font text-success\">صَنَعُواْ</span> <span class=\"quran-arabic-font text-success\">كَيْدُ</span> <span class=\"quran-arabic-font text-success\">سَاحِرٍ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يُفْلِحُ</span> <span class=\"quran-arabic-font text-success\">السَّـحِرُ</span> <span class=\"quran-arabic-font text-success\">حَيْثُ</span> <span class=\"quran-arabic-font text-success\">أَتَى﴿</span><br />\r\n<br />\r\n(அவர்கள் செய்திருப்பவை எல்லாம் ஒரு சூனியக்காரனின் சதி தான்; ஒரு சூனியக்காரன் எங்கு சென்றாலும் அவன் ஒருபோதும் வெற்றி பெற மாட்டான்.) <span class=\"quran-arabic-font text-success\">﴾فَأُلْقِىَ</span> <span class=\"quran-arabic-font text-success\">السَّحَرَةُ</span> <span class=\"quran-arabic-font text-success\">سُجَّداً</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">ءَامَنَّا</span> <span class=\"quran-arabic-font text-success\">بِرَبِّ</span> <span class=\"quran-arabic-font text-success\">هَارُونَ</span> <span class=\"quran-arabic-font text-success\">وَمُوسَى﴿</span> (ஆகவே, சூனியக்காரர்கள் ஸஜ்தாவில் விழுந்தவர்களாக, \"நாங்கள் ஹாரூன், மூஸா ஆகியோரின் இறைவன் மீது ஈமான் கொண்டோம்\" என்று கூறினார்கள்.) எனவே, சூனியக்காரர்கள் இந்த நிகழ்வைத் தங்கள் கண்களால் கண்டபோது - அவர்கள் சூனியக் கலைகளின் பல்வேறு தந்திரங்களையும் முறைகளையும் நன்கு அறிந்தவர்களாக இருந்ததால் - மூஸா (அலை) செய்தது சூனியமோ அல்லது மாயஜாலத் தந்திரமோ அல்ல என்பதை அவர்கள் உறுதியாக அறிந்து கொண்டனர். அது எத்தகைய சந்தேகத்திற்கும் இடமில்லாத சத்தியம் என்பதை அவர்கள் உணர்ந்தார்கள். ஒரு பொருளுக்கு \"ஆகு\" என்று சொன்னால் அது ஆகிவிடும் என்ற வல்லமை கொண்ட அல்லாஹ்வைத் தவிர வேறு எவராலும் இதைச் செய்ய முடியாது என்பதை அவர்கள் அறிந்து கொண்டனர். ஆகவே, இது நடந்தபோது அவர்கள் அல்லாஹ்வுக்கு ஸஜ்தா (சிரவணக்கம்) செய்தவர்களாக விழுந்தனர். அவர்கள் கூறினார்கள்: \"மூஸா (அலை) மற்றும் ஹாரூன் (அலை) ஆகியோரின் இறைவன் மீது நாங்கள் நம்பிக்கை கொண்டோம்!\" இதனால்தான் இப்னு அப்பாஸ் (ரழி) மற்றும் உபைது பின் உமைர் (ரழி) ஆகிய இருவரும் கூறினார்கள்: \"அவர்கள் அன்றைய நாளின் தொடக்கத்தில் சூனியக்காரர்களாக இருந்தார்கள்; ஆனால் நாளின் இறுதியில் அவர்கள் ஈமானின் (இறைநம்பிக்கையின்) சிறந்த சாட்சியாளர்களாக மாறினார்கள்.\"<br />\r\n<br />\r\n<strong>சூனியக்காரர்களின் எண்ணிக்கை</strong><br />\r\n<br />\r\nஇப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக இப்னு அபீ ஹாதிம் பதிவு செய்துள்ளார்கள்: \"சூனியக்காரர்கள் எழுபது பேராக இருந்தனர். அவர்கள் காலையில் சூனியக்காரர்களாக இருந்தனர்; ஆனால் மாலை வந்தபோது இறைநம்பிக்கையாளர்களாக மாறினர்.\" இப்னு அபீ ஹாதிம் மேலும் அறிவிக்கிறார்கள்: \"சூனியக்காரர்கள் ஸஜ்தாவில் விழுந்தபோது, சொர்க்கம் அவர்களுக்கு முன்னால் உயர்த்தப்பட்டது; அவர்கள் அதைப் பார்த்துக் கொண்டிருந்தனர்\" என்று அல்-அவ்ஸாஈ (ரஹ்) கூறினார்கள். ஸயீத் பின் ஜுபைர் (ரஹ்) அவர்கள் அல்லாஹ்வின் கூற்றான: <span class=\"quran-arabic-font text-success\">﴾فَأُلْقِىَ</span> <span class=\"quran-arabic-font text-success\">السَّحَرَةُ</span> <span class=\"quran-arabic-font text-success\">سُجَّداً﴿</span><br />\r\n<br />\r\n(எனவே சூனியக்காரர்கள் ஸஜ்தா செய்தவர்களாக விழுந்தனர்) என்பதைக் குறித்துக் கூறினார்கள்: \"அவர்கள் ஸஜ்தாவில் இருந்தபோதே சொர்க்கத்தில் தங்களுக்குரிய இடங்கள் தெளிவாகக் காட்டப்படுவதைக் கண்டனர்.\" இக்ரிமா (ரஹ்) மற்றும் அல்-காஸிம் பின் அபீ பிஸ்ஸா (ரஹ்) ஆகிய இருவரும் இதையே கூறினார்கள்.<br />\r\n<br />","text":"போட்டி, மூஸா (அலை) அவர்களின் வெற்றி மற்றும் சூனியக்காரர்களின் ஈமான் (நம்பிக்கை)\n\r\n\n\r\nமூஸா (அலை) அவர்களைச் சந்தித்தபோது சூனியக்காரர்கள் அவரிடம் கூறியது குறித்து கண்ணியமிக்க அல்லாஹ் கூறுகிறான்: ﴾إِمَّآ أَن تُلْقِىَ﴿\n\r\n\n\r\n(\"ஒன்றில் நீர் எறியலாம்...\") அதாவது, \"நீரே முதலில் தொடங்கும்.\" ﴾وَإِمَّآ أَن نَّكُونَ أَوَّلَ مَنْ أَلْقَى قَالَ بَلْ أَلْقُواْ﴿\n\r\n\n\r\n(\"...அல்லது முதலில் எறிபவர்களாக நாங்கள் இருக்க வேண்டுமா?\" அதற்கு மூஸா (அலை) கூறினார்கள்: \"இல்லை, நீங்களே (முதலில்) எறியுங்கள்!\") இதன் பொருள்: \"சூனியக்காரர்களாகிய நீங்கள் முதலில் உங்கள் கைவரிசையைக் காட்டுங்கள்; அப்போதுதான் நீங்கள் எத்தகைய சூனியத்தைச் செய்கிறீர்கள் என்பதை நாங்கள் பார்க்க முடியும், மேலும் அவர்களின் சூழ்ச்சியின் உண்மை நிலையும் மக்களுக்குத் தெளிவாகும்.\" ﴾فَإِذَا حِبَالُهُمْ وَعِصِيُّهُمْ يُخَيَّلُ إِلَيْهِ مِن سِحْرِهِمْ أَنَّهَا تَسْعَى﴿\n\r\n\n\r\n(அப்பொழுது, இதோ! அவர்களுடைய கயிறுகளும் தடிகளும், அவர்களுடைய சூனியத்தினால் அவை வேகமாக நகர்வது போல் அவருக்குத் தோன்றியது.) மற்றோர் வசனத்தில் அவர்கள் எறிந்தபோது இவ்வாறு கூறியதாகக் குறிப்பிடப்பட்டுள்ளது: ﴾وَقَالُواْ بِعِزَّةِ فِرْعَونَ إِنَّا لَنَحْنُ الْغَالِبُونَ﴿\n\r\n\n\r\n(அவர்கள் கூறினார்கள்: \"ஃபிர்அவ்னின் கண்ணியத்தின் மீது ஆணையாக! நிச்சயமாக நாங்களே வெற்றி பெறுவோம்!\") 26:44 மேலும், கண்ணியமிக்க அல்லாஹ் கூறுகிறான்: ﴾سَحَرُواْ أَعْيُنَ النَّاسِ وَاسْتَرْهَبُوهُمْ وَجَآءُو بِسِحْرٍ عَظِيمٍ﴿\n\r\n\n\r\n(அவர்கள் மக்களின் கண்களை மயக்கி, அவர்களை அச்சமடையச் செய்தனர்; மேலும், அவர்கள் ஒரு பெரிய சூனியத்தைக் கொண்டு வந்தனர்.) 7:116 இங்கே, இந்தச் சூராவில் அல்லாஹ் கூறுகிறான்: ﴾فَإِذَا حِبَالُهُمْ وَعِصِيُّهُمْ يُخَيَّلُ إِلَيْهِ مِن سِحْرِهِمْ أَنَّهَا تَسْعَى﴿\n\r\n\n\r\n(அப்பொழுது, இதோ! அவர்களுடைய கயிறுகளும் தடிகளும், அவர்களுடைய சூனியத்தினால் அவை வேகமாக நகர்வது போல் அவருக்குத் தோன்றியது.) அவர்கள் ஒரு பெரும் கூட்டமாக இருந்தனர்; அவர்கள் ஒவ்வொருவரும் ஒரு தடியையும் கயிற்றையும் எறிந்தனர். இறுதியில் அந்தப் பள்ளத்தாக்கு முழுவதும் ஒன்றன் மேல் ஒன்றாக நெளியும் பாம்புகளால் நிறைந்தது. அல்லாஹ்வின் கூற்றான: ﴾فَأَوْجَسَ فِى نَفْسِهِ خِيفَةً مُّوسَى ﴿\n\r\n\n\r\n(ஆகவே, மூஸா (அலை) தமக்குள்ளே ஓர் அச்சத்தை உணர்ந்தார்கள்) என்பதன் பொருள்: தான் தனது வலது கையில் உள்ளதை எறிவதற்கு முன்பே, மக்கள் இவர்களது சூனியத்தைக் கண்டு குழப்பமடைந்து ஏமாந்து விடுவார்களோ என்று மூஸா (அலை) அஞ்சினார்கள். ﴾قُلْنَا لاَ تَخَفْ إِنَّكَ أَنتَ الأَعْلَى - وَأَلْقِ مَا فِى يَمِينِكَ تَلْقَفْ مَا صَنَعُواْ﴿ (\"நாம் சொன்னோம்: பயப்படாதீர்! நிச்சயமாக நீர்தான் மேலோங்கி நிற்பீர். உமது வலது கையில் இருப்பதை எறிவீராக! அது அவர்கள் செய்தவற்றை விழுங்கிவிடும்.\") எனவே, சரியான தருணத்தில் அல்லாஹ் அவருக்கு வஹீ (இறைச்செய்தி) அறிவித்தான்: தனது வலது கையில் இருக்கும் தடியை எறியுமாறு. அவர் அதை எறிந்தபோது, அது அவர்கள் உருவாக்கிய சூனியங்கள் அனைத்தையும் விழுங்கியது. அது கால்கள், கழுத்து, தலை மற்றும் கோரைப் பற்களுடன் ஒரு பிரம்மாண்டமான ராட்சத உயிரினமாக மாறியது. அந்த மிருகம் அங்கிருந்த கயிறுகளையும் தடிகளையும் துரத்திச் சென்று, அவை எதையும் விட்டுவைக்காமல் அனைத்தையும் விழுங்கி ஏப்பமிட்டது. அதே நேரத்தில், சூனியக்காரர்களும் மக்களும் பட்டப்பகலில் நடந்த இந்த வியக்கத்தக்க அதிசயத்தை தங்கள் கண்களால் நேரடியாகக் கண்டனர். இவ்வாறாக அந்த அற்புதம் நிகழ்ந்தது, ஆதாரம் தெளிவாகியது. சத்தியம் வென்றது, சூனியம் பொய்யானது என்பது நிரூபணமானது. இதனால்தான் அல்லாஹ் இவ்வாறு கூறினான்: ﴾إِنَّمَا صَنَعُواْ كَيْدُ سَاحِرٍ وَلاَ يُفْلِحُ السَّـحِرُ حَيْثُ أَتَى﴿\n\r\n\n\r\n(அவர்கள் செய்திருப்பவை எல்லாம் ஒரு சூனியக்காரனின் சதி தான்; ஒரு சூனியக்காரன் எங்கு சென்றாலும் அவன் ஒருபோதும் வெற்றி பெற மாட்டான்.) ﴾فَأُلْقِىَ السَّحَرَةُ سُجَّداً قَالُواْ ءَامَنَّا بِرَبِّ هَارُونَ وَمُوسَى﴿ (ஆகவே, சூனியக்காரர்கள் ஸஜ்தாவில் விழுந்தவர்களாக, \"நாங்கள் ஹாரூன், மூஸா ஆகியோரின் இறைவன் மீது ஈமான் கொண்டோம்\" என்று கூறினார்கள்.) எனவே, சூனியக்காரர்கள் இந்த நிகழ்வைத் தங்கள் கண்களால் கண்டபோது - அவர்கள் சூனியக் கலைகளின் பல்வேறு தந்திரங்களையும் முறைகளையும் நன்கு அறிந்தவர்களாக இருந்ததால் - மூஸா (அலை) செய்தது சூனியமோ அல்லது மாயஜாலத் தந்திரமோ அல்ல என்பதை அவர்கள் உறுதியாக அறிந்து கொண்டனர். அது எத்தகைய சந்தேகத்திற்கும் இடமில்லாத சத்தியம் என்பதை அவர்கள் உணர்ந்தார்கள். ஒரு பொருளுக்கு \"ஆகு\" என்று சொன்னால் அது ஆகிவிடும் என்ற வல்லமை கொண்ட அல்லாஹ்வைத் தவிர வேறு எவராலும் இதைச் செய்ய முடியாது என்பதை அவர்கள் அறிந்து கொண்டனர். ஆகவே, இது நடந்தபோது அவர்கள் அல்லாஹ்வுக்கு ஸஜ்தா (சிரவணக்கம்) செய்தவர்களாக விழுந்தனர். அவர்கள் கூறினார்கள்: \"மூஸா (அலை) மற்றும் ஹாரூன் (அலை) ஆகியோரின் இறைவன் மீது நாங்கள் நம்பிக்கை கொண்டோம்!\" இதனால்தான் இப்னு அப்பாஸ் (ரழி) மற்றும் உபைது பின் உமைர் (ரழி) ஆகிய இருவரும் கூறினார்கள்: \"அவர்கள் அன்றைய நாளின் தொடக்கத்தில் சூனியக்காரர்களாக இருந்தார்கள்; ஆனால் நாளின் இறுதியில் அவர்கள் ஈமானின் (இறைநம்பிக்கையின்) சிறந்த சாட்சியாளர்களாக மாறினார்கள்.\"\n\r\n\n\r\nசூனியக்காரர்களின் எண்ணிக்கை\n\r\n\n\r\nஇப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக இப்னு அபீ ஹாதிம் பதிவு செய்துள்ளார்கள்: \"சூனியக்காரர்கள் எழுபது பேராக இருந்தனர். அவர்கள் காலையில் சூனியக்காரர்களாக இருந்தனர்; ஆனால் மாலை வந்தபோது இறைநம்பிக்கையாளர்களாக மாறினர்.\" இப்னு அபீ ஹாதிம் மேலும் அறிவிக்கிறார்கள்: \"சூனியக்காரர்கள் ஸஜ்தாவில் விழுந்தபோது, சொர்க்கம் அவர்களுக்கு முன்னால் உயர்த்தப்பட்டது; அவர்கள் அதைப் பார்த்துக் கொண்டிருந்தனர்\" என்று அல்-அவ்ஸாஈ (ரஹ்) கூறினார்கள். ஸயீத் பின் ஜுபைர் (ரஹ்) அவர்கள் அல்லாஹ்வின் கூற்றான: ﴾فَأُلْقِىَ السَّحَرَةُ سُجَّداً﴿\n\r\n\n\r\n(எனவே சூனியக்காரர்கள் ஸஜ்தா செய்தவர்களாக விழுந்தனர்) என்பதைக் குறித்துக் கூறினார்கள்: \"அவர்கள் ஸஜ்தாவில் இருந்தபோதே சொர்க்கத்தில் தங்களுக்குரிய இடங்கள் தெளிவாகக் காட்டப்படுவதைக் கண்டனர்.\" இக்ரிமா (ரஹ்) மற்றும் அல்-காஸிம் பின் அபீ பிஸ்ஸா (ரஹ்) ஆகிய இருவரும் இதையே கூறினார்கள்."},"71":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=73\" class=\"link\">20:73</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:73 ஐ பார்க்கவும்"},"72":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=73\" class=\"link\">20:73</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:73 ஐ பார்க்கவும்"},"73":{"html":"<strong>சூனியக்காரர்களுக்கு எதிராக ஃபிர்அவ்ன் திரும்பியதும், அவர்களை அவன் அச்சுறுத்தியதும் மற்றும் அவர்களின் பதிலும்</strong><br />\r\n<br />\r\nஉயர்ந்தோனாகிய அல்லாஹ், ஃபிர்அவ்னின் இறைநிராகரிப்பு, பிடிவாதம், வரம்புமீறல் மற்றும் சத்தியத்திற்கு எதிராகப் பெருமையடித்து பொய்யை ஆதரித்தது குறித்துத் தெரிவிக்கிறான். அந்த மகத்தான அற்புதத்தையும் மாபெரும் அத்தாட்சியையும் கண்டபோது, தான் உதவி தேடியவர்கள் மக்கள் அனைவரின் முன்னிலையிலும் ஈமான் கொண்டதைக் கண்டு முற்றிலும் தோல்வியுற்ற ஃபிர்அவ்ன், ஆணவத்துடன் நடந்துகொள்ளத் தொடங்கி குற்றச்சாட்டுகளைச் சுமத்தினான். சூனியக்காரர்களுக்கு எதிராகத் தனது அதிகாரத்தையும் வலிமையையும் பயன்படுத்திய அவன், அவர்களை எச்சரித்து அச்சுறுத்தி <span class=\"quran-arabic-font text-success\">﴾ءَامَنتُمْ</span> <span class=\"quran-arabic-font text-success\">لَهُ﴿</span> எனக் கூறினான்.<br />\r\n<br />\r\n(நீங்கள் அவரை (மூஸாவை) நம்புகிறீர்களா?) இதன் பொருள், \"நீங்கள் அவர் மீது ஈமான் கொள்கிறீர்களா?\" என்பதாகும். <span class=\"quran-arabic-font text-success\">﴾قَبْلَ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">ءَاذَنَ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ﴿</span><br />\r\n<br />\r\n(நான் உங்களுக்கு அனுமதி அளிப்பதற்கு முன்னரே) அதாவது, \"நான் உங்களுக்கு அவ்வாறு செய்யுமாறு கட்டளையிடவில்லை, இதன் மூலம் நீங்கள் எனக்கு எதிராகக் கிளர்ச்சி செய்துவிட்டீர்கள்\" என்று கூறினான். பிறகு அவனும், அந்தச் சூனியக்காரர்களும் மற்றும் அனைத்துப் படைப்பினங்களும் அப்பட்டமான பொய் என்று அறிந்த ஒரு கூற்றை அவன் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">لَكَبِيرُكُمُ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">عَلَّمَكُمُ</span> <span class=\"quran-arabic-font text-success\">السِّحْرَ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக, அவரே உங்களுக்குச் சூனியத்தைக் கற்றுக்கொடுத்த உங்கள் தலைவர்.) அதாவது, \"நீங்கள் அனைவரும் மூஸாவிடமிருந்துதான் சூனியத்தைக் கற்றுக்கொண்டீர்கள். எனக்கும் என் குடிமக்களுக்கும் எதிராக அவருக்கு வெற்றி கிடைக்க உதவ வேண்டும் என்று அவருடன் நீங்கள் உடன்படிக்கை செய்துள்ளீர்கள்\" என்று கூறினான். அல்லாஹ் மற்றொரு வசனத்தில் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">لَمَكْرٌ</span> <span class=\"quran-arabic-font text-success\">مَّكَرْتُمُوهُ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْمَدِينَةِ</span> <span class=\"quran-arabic-font text-success\">لِتُخْرِجُواْ</span> <span class=\"quran-arabic-font text-success\">مِنْهَآ</span> <span class=\"quran-arabic-font text-success\">أَهْلَهَا</span> <span class=\"quran-arabic-font text-success\">فَسَوْفَ</span> <span class=\"quran-arabic-font text-success\">تَعْلَمُونَ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக இது இந்த நகரத்து மக்களை வெளியேற்றுவதற்காக நீங்கள் செய்த சூழ்ச்சியாகும். விரைவில் நீங்கள் (இதன் விளைவை) அறிந்துகொள்வீர்கள்.) <a href=\"qurandisp.php?sura=7&ayah=123\" class=\"link\">7:123</a> பின்னர் அவன் அவர்களை அச்சுறுத்தத் தொடங்கினான். அவன் அவர்களிடம் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾فَلأُقَطِّعَنَّ</span> <span class=\"quran-arabic-font text-success\">أَيْدِيَكُمْ</span> <span class=\"quran-arabic-font text-success\">وَأَرْجُلَكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">خِلاَفٍ</span> <span class=\"quran-arabic-font text-success\">وَلأُصَلِّبَنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">جُذُوعِ</span> <span class=\"quran-arabic-font text-success\">النَّخْلِ﴿</span><br />\r\n<br />\r\n(ஆகவே, நான் நிச்சயமாக உங்கள் கைகளையும் கால்களையும் மாறுகால் மாறுகை வெட்டி விடுவேன். மேலும், உங்களைப் பேரீச்சை மரத்தின் தண்டுகளில் சிலுவையில் அறையச் செய்வேன்.) அதாவது, \"நான் நிச்சயமாக உங்களை ஒரு முன்னுதாரணமாக ஆக்குவேன், உங்களைப் பகிரங்கமாக மரணதண்டனைக்கு உள்ளாக்குவேன்\" என்று கூறினான். \"இவ்வாறு (பகிரங்க மரணதண்டனை, சிலுவையில் அறைதல்) செய்த முதல் நபர் அவன்தான்\" என்று இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள். இதனை இப்னு அபீ ஹாதிம் பதிவு செய்துள்ளார். அல்லாஹ்வின் இந்தக் கூற்று குறித்து: <span class=\"quran-arabic-font text-success\">﴾وَلَتَعْلَمُنَّ</span> <span class=\"quran-arabic-font text-success\">أَيُّنَآ</span> <span class=\"quran-arabic-font text-success\">أَشَدُّ</span> <span class=\"quran-arabic-font text-success\">عَذَاباً</span> <span class=\"quran-arabic-font text-success\">وَأَبْقَى﴿</span><br />\r\n<br />\r\n(நம்மில் யார் கடுமையான மற்றும் நிலையான வேதனையை அளிக்கக்கூடியவர் என்பதை நீங்கள் விரைவில் அறிந்துகொள்வீர்கள்.) இதன் பொருள், \"நானும் எனது மக்களும் வழிகேட்டில் இருப்பதாகவும், நீங்கள் (சூனியக்காரர்கள்), மூஸா (அலை) மற்றும் அவரது மக்கள் நேர்வழியில் இருப்பதாகவும் கூறுகிறீர்கள். ஆனால் யார் தண்டிக்கப்படுவார், யாருடைய தண்டனை நிலைத்திருக்கும் என்பதை நீங்கள் விரைவில் அறிந்துகொள்வீர்கள்\" என்பதாகும். அவன் இவ்வாறு அச்சுறுத்தியபோது, கண்ணியமும் மேன்மையும் மிக்க அல்லாஹ்வின் மீது அவர்கள் கொண்டிருந்த நம்பிக்கையினால் அவர்கள் உள்ளம் அமைதி பெற்றது. அவர்கள் உரக்கக் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾قَالُواْ</span> <span class=\"quran-arabic-font text-success\">لَن</span> <span class=\"quran-arabic-font text-success\">نُّؤْثِرَكَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">جَآءَنَا</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْبَيِّنَاتِ﴿</span><br />\r\n<br />\r\n(அவர்கள் கூறினார்கள்: எங்களிடம் வந்துள்ள தெளிவான அத்தாட்சிகளை விட நாங்கள் உன்னைத் தேர்ந்தெடுக்க மாட்டோம்...) அதாவது, \"நாங்கள் பெற்றுக்கொண்ட நேர்வழியையும் உறுதியையும் விட உனக்கு நாங்கள் முன்னுரிமை அளிக்க மாட்டோம்.\" <span class=\"quran-arabic-font text-success\">﴾وَالَّذِى</span> <span class=\"quran-arabic-font text-success\">فَطَرَنَا﴿</span><br />\r\n<br />\r\n(மேலும் எங்களைப் படைத்தவன் (அல்லாஹ்) மீதும் சத்தியமாக.) இது \"எங்களைப் படைத்தவன் மீது சத்தியமாக\" என்று அவர்கள் சத்தியம் செய்வதாக இருக்கலாம். அல்லது இதற்கு முன் கூறப்பட்ட தெளிவான அத்தாட்சிகளுடன் இது பொருள் ரீதியாகத் தொடர்புடையதாகவும் இருக்கலாம். அவ்வாறாயின், \"ஒன்றுமில்லாத நிலையிலிருந்து எங்களை முதன்முதலில் படைத்த எங்கள் படைப்பாளனை விட உனக்கு நாங்கள் முன்னுரிமை அளிக்க மாட்டோம். அவன் எங்களைக் களிமண்ணிலிருந்து படைத்தான். எனவே, அவன் மட்டுமே வணக்கத்திற்கும் பணிவிற்கும் தகுதியானவன், நீ (ஃபிர்அவ்ன்) அல்ல!\" என்பது இதன் பொருளாகும். <span class=\"quran-arabic-font text-success\">﴾فَاقْضِ</span> <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أَنتَ</span> <span class=\"quran-arabic-font text-success\">قَاضٍ﴿</span><br />\r\n<br />\r\n(எனவே, நீ தீர்ப்பளிக்க விரும்புவதைத் தீர்ப்பளித்துக்கொள்.) \"நீ எதைச் செய்ய விரும்புகிறாயோ அதைச் செய்துகொள், உன்னால் எதைச் சாதிக்க முடியுமோ அதைச் செய்துகொள்.\" <span class=\"quran-arabic-font text-success\">﴾إِنَّمَا</span> <span class=\"quran-arabic-font text-success\">تَقْضِى</span> <span class=\"quran-arabic-font text-success\">هَـذِهِ</span> <span class=\"quran-arabic-font text-success\">الْحَيَوةَ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَآ﴿</span><br />\r\n<br />\r\n(உன்னால் இந்த உலக வாழ்க்கையில் மட்டுமே தீர்ப்பளிக்க முடியும்.) அதாவது, \"உனக்கு இந்த உலகத்தில் மட்டுமே அதிகாரம் உள்ளது, இது அழியக்கூடிய உலகம். நிச்சயமாக நாங்கள் நிலையான மறுவுலக வாழ்வையே எதிர்பார்க்கிறோம்.\" <span class=\"quran-arabic-font text-success\">﴾إِنَّآ</span> <span class=\"quran-arabic-font text-success\">آمَنَّا</span> <span class=\"quran-arabic-font text-success\">بِرَبِّنَا</span> <span class=\"quran-arabic-font text-success\">لِيَغْفِرَ</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">خَطَايَانَا﴿</span><br />\r\n<br />\r\n(நிச்சயமாக நாங்கள் எங்கள் இறைவனை ஈமான் கொண்டோம், அவன் எங்கள் தவறுகளை மன்னிப்பதற்காக,) \"நாங்கள் செய்த தீமைகளை அவன் மன்னிக்க வேண்டும்.\" குறிப்பாக, \"அல்லாஹ்வின் அத்தாட்சியையும் அவனது நபியின் அற்புதத்தையும் எதிர்ப்பதற்காக நாங்கள் கட்டாயப்படுத்தப்பட்ட அந்தச் சூனியத்தையும் அவன் மன்னிக்க வேண்டும்\" என்பது இதன் பொருளாகும். அல்லாஹ்வின் இந்தக் கூற்று குறித்து இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக இப்னு அபீ ஹாதிம் பதிவு செய்துள்ளார்: <span class=\"quran-arabic-font text-success\">﴾وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَكْرَهْتَنَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">السِّحْرِ﴿</span><br />\r\n<br />\r\n(எந்தச் சூனியத்தைச் செய்யுமாறு நீ எங்களைக் கட்டாயப்படுத்தினாயோ அதையும் அவன் மன்னிக்க வேண்டும்.) \"ஃபிர்அவ்ன் பனூ இஸ்ராயீல் மக்களிடமிருந்து நாற்பது சிறுவர்களைத் தேர்ந்தெடுத்து, அவர்களுக்கு அல்-ஃபரமா எனும் இடத்தில் சூனியத்தைக் கற்றுக்கொடுக்குமாறு உத்தரவிட்டான். அந்த நாட்டில் எவருக்கும் தெரியாத வித்தைகளை அவர்களுக்குக் கற்றுக்கொடுங்கள் என்று அவன் கூறினான்\" என்று இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள். மேலும் அவர்கள் கூறுகையில், \"அவர்கள் மூஸா (அலை) அவர்களை விசுவாசித்தவர்களில் சேர்ந்தவர்களாயினர். மேலும், <span class=\"quran-arabic-font text-success\">﴾آمَنَّا</span> <span class=\"quran-arabic-font text-success\">بِرَبِّنَا</span> <span class=\"quran-arabic-font text-success\">لِيَغْفِرَ</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">خَطَايَانَا</span> <span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَكْرَهْتَنَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">السِّحْرِ﴿</span> (நாங்கள் எங்கள் இறைவனை ஈமான் கொண்டோம்; அவன் எங்கள் தவறுகளையும், நீ எங்களைக் கட்டாயப்படுத்திச் செய்ய வைத்த சூனியத்தையும் மன்னிப்பதற்காக) என்று கூறியவர்களில் ஒருவராகிவிட்டனர்\" என்றார்கள். அப்துர் ரஹ்மான் பின் ஸைத் பின் அஸ்லம் அவர்களும் இதையே கூறியுள்ளார்கள். அல்லாஹ்வின் கூற்று: <span class=\"quran-arabic-font text-success\">﴾وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">خَيْرٌ</span> <span class=\"quran-arabic-font text-success\">وَأَبْقَى﴿</span><br />\r\n<br />\r\n(மேலும் அல்லாஹ் (உன் வெகுமதியை விட) சிறந்தவனாகவும் நிலையானவனாகவும் இருக்கிறான்.) அதாவது, \"உன்னை விட எங்களுக்கு அவனே சிறந்தவன்.\" <span class=\"quran-arabic-font text-success\">﴾وَأَبْقَى﴿</span><br />\r\n<br />\r\n(மேலும் நிலையானவன்.) நீ எங்களுக்கு வாக்களித்த மற்றும் நாங்கள் ஆசைப்பட்ட வெகுமதியை விட அவனது வெகுமதி மிகவும் நிலையானது. ஃபிர்அவ்ன் (அல்லாஹ் அவனைச் சபிப்பானாக) அவர்களைத் தண்டிப்பதில் குறியாக இருந்தான் என்பதும், அவன் அவர்களுக்குச் செய்தது அல்லாஹ்வின் ஒரு பெரும் கருணையாக அமைந்தது என்பதும் இதிலிருந்து தெளிவாகிறது. இதனால்தான் இப்னு அப்பாஸ் (ரழி) அவர்களும் மற்றும் பிற முன்னோர்களும் (ஸலஃபுகள்), \"அவர்கள் பகலின் ஆரம்பத்தில் சூனியக்காரர்களாக இருந்தார்கள், ஆனால் பகலின் இறுதியில் நல்லடியார்களாகவும் தியாகிகளாகவும் (ஷுஹுதாக்களாகவும்) ஆகிவிட்டார்கள்\" என்று கூறினார்கள்.<br />\r\n<br />\r\n<br />\r\n<br />","text":"சூனியக்காரர்களுக்கு எதிராக ஃபிர்அவ்ன் திரும்பியதும், அவர்களை அவன் அச்சுறுத்தியதும் மற்றும் அவர்களின் பதிலும்\n\r\n\n\r\nஉயர்ந்தோனாகிய அல்லாஹ், ஃபிர்அவ்னின் இறைநிராகரிப்பு, பிடிவாதம், வரம்புமீறல் மற்றும் சத்தியத்திற்கு எதிராகப் பெருமையடித்து பொய்யை ஆதரித்தது குறித்துத் தெரிவிக்கிறான். அந்த மகத்தான அற்புதத்தையும் மாபெரும் அத்தாட்சியையும் கண்டபோது, தான் உதவி தேடியவர்கள் மக்கள் அனைவரின் முன்னிலையிலும் ஈமான் கொண்டதைக் கண்டு முற்றிலும் தோல்வியுற்ற ஃபிர்அவ்ன், ஆணவத்துடன் நடந்துகொள்ளத் தொடங்கி குற்றச்சாட்டுகளைச் சுமத்தினான். சூனியக்காரர்களுக்கு எதிராகத் தனது அதிகாரத்தையும் வலிமையையும் பயன்படுத்திய அவன், அவர்களை எச்சரித்து அச்சுறுத்தி ﴾ءَامَنتُمْ لَهُ﴿ எனக் கூறினான்.\n\r\n\n\r\n(நீங்கள் அவரை (மூஸாவை) நம்புகிறீர்களா?) இதன் பொருள், \"நீங்கள் அவர் மீது ஈமான் கொள்கிறீர்களா?\" என்பதாகும். ﴾قَبْلَ أَنْ ءَاذَنَ لَكُمْ﴿\n\r\n\n\r\n(நான் உங்களுக்கு அனுமதி அளிப்பதற்கு முன்னரே) அதாவது, \"நான் உங்களுக்கு அவ்வாறு செய்யுமாறு கட்டளையிடவில்லை, இதன் மூலம் நீங்கள் எனக்கு எதிராகக் கிளர்ச்சி செய்துவிட்டீர்கள்\" என்று கூறினான். பிறகு அவனும், அந்தச் சூனியக்காரர்களும் மற்றும் அனைத்துப் படைப்பினங்களும் அப்பட்டமான பொய் என்று அறிந்த ஒரு கூற்றை அவன் கூறினான்: ﴾إِنَّهُ لَكَبِيرُكُمُ الَّذِى عَلَّمَكُمُ السِّحْرَ﴿\n\r\n\n\r\n(நிச்சயமாக, அவரே உங்களுக்குச் சூனியத்தைக் கற்றுக்கொடுத்த உங்கள் தலைவர்.) அதாவது, \"நீங்கள் அனைவரும் மூஸாவிடமிருந்துதான் சூனியத்தைக் கற்றுக்கொண்டீர்கள். எனக்கும் என் குடிமக்களுக்கும் எதிராக அவருக்கு வெற்றி கிடைக்க உதவ வேண்டும் என்று அவருடன் நீங்கள் உடன்படிக்கை செய்துள்ளீர்கள்\" என்று கூறினான். அல்லாஹ் மற்றொரு வசனத்தில் கூறுகிறான்: ﴾إِنَّ هَـذَا لَمَكْرٌ مَّكَرْتُمُوهُ فِى الْمَدِينَةِ لِتُخْرِجُواْ مِنْهَآ أَهْلَهَا فَسَوْفَ تَعْلَمُونَ﴿\n\r\n\n\r\n(நிச்சயமாக இது இந்த நகரத்து மக்களை வெளியேற்றுவதற்காக நீங்கள் செய்த சூழ்ச்சியாகும். விரைவில் நீங்கள் (இதன் விளைவை) அறிந்துகொள்வீர்கள்.) 7:123 பின்னர் அவன் அவர்களை அச்சுறுத்தத் தொடங்கினான். அவன் அவர்களிடம் கூறினான்: ﴾فَلأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُمْ مِّنْ خِلاَفٍ وَلأُصَلِّبَنَّكُمْ فِى جُذُوعِ النَّخْلِ﴿\n\r\n\n\r\n(ஆகவே, நான் நிச்சயமாக உங்கள் கைகளையும் கால்களையும் மாறுகால் மாறுகை வெட்டி விடுவேன். மேலும், உங்களைப் பேரீச்சை மரத்தின் தண்டுகளில் சிலுவையில் அறையச் செய்வேன்.) அதாவது, \"நான் நிச்சயமாக உங்களை ஒரு முன்னுதாரணமாக ஆக்குவேன், உங்களைப் பகிரங்கமாக மரணதண்டனைக்கு உள்ளாக்குவேன்\" என்று கூறினான். \"இவ்வாறு (பகிரங்க மரணதண்டனை, சிலுவையில் அறைதல்) செய்த முதல் நபர் அவன்தான்\" என்று இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள். இதனை இப்னு அபீ ஹாதிம் பதிவு செய்துள்ளார். அல்லாஹ்வின் இந்தக் கூற்று குறித்து: ﴾وَلَتَعْلَمُنَّ أَيُّنَآ أَشَدُّ عَذَاباً وَأَبْقَى﴿\n\r\n\n\r\n(நம்மில் யார் கடுமையான மற்றும் நிலையான வேதனையை அளிக்கக்கூடியவர் என்பதை நீங்கள் விரைவில் அறிந்துகொள்வீர்கள்.) இதன் பொருள், \"நானும் எனது மக்களும் வழிகேட்டில் இருப்பதாகவும், நீங்கள் (சூனியக்காரர்கள்), மூஸா (அலை) மற்றும் அவரது மக்கள் நேர்வழியில் இருப்பதாகவும் கூறுகிறீர்கள். ஆனால் யார் தண்டிக்கப்படுவார், யாருடைய தண்டனை நிலைத்திருக்கும் என்பதை நீங்கள் விரைவில் அறிந்துகொள்வீர்கள்\" என்பதாகும். அவன் இவ்வாறு அச்சுறுத்தியபோது, கண்ணியமும் மேன்மையும் மிக்க அல்லாஹ்வின் மீது அவர்கள் கொண்டிருந்த நம்பிக்கையினால் அவர்கள் உள்ளம் அமைதி பெற்றது. அவர்கள் உரக்கக் கூறினார்கள்: ﴾قَالُواْ لَن نُّؤْثِرَكَ عَلَى مَا جَآءَنَا مِنَ الْبَيِّنَاتِ﴿\n\r\n\n\r\n(அவர்கள் கூறினார்கள்: எங்களிடம் வந்துள்ள தெளிவான அத்தாட்சிகளை விட நாங்கள் உன்னைத் தேர்ந்தெடுக்க மாட்டோம்...) அதாவது, \"நாங்கள் பெற்றுக்கொண்ட நேர்வழியையும் உறுதியையும் விட உனக்கு நாங்கள் முன்னுரிமை அளிக்க மாட்டோம்.\" ﴾وَالَّذِى فَطَرَنَا﴿\n\r\n\n\r\n(மேலும் எங்களைப் படைத்தவன் (அல்லாஹ்) மீதும் சத்தியமாக.) இது \"எங்களைப் படைத்தவன் மீது சத்தியமாக\" என்று அவர்கள் சத்தியம் செய்வதாக இருக்கலாம். அல்லது இதற்கு முன் கூறப்பட்ட தெளிவான அத்தாட்சிகளுடன் இது பொருள் ரீதியாகத் தொடர்புடையதாகவும் இருக்கலாம். அவ்வாறாயின், \"ஒன்றுமில்லாத நிலையிலிருந்து எங்களை முதன்முதலில் படைத்த எங்கள் படைப்பாளனை விட உனக்கு நாங்கள் முன்னுரிமை அளிக்க மாட்டோம். அவன் எங்களைக் களிமண்ணிலிருந்து படைத்தான். எனவே, அவன் மட்டுமே வணக்கத்திற்கும் பணிவிற்கும் தகுதியானவன், நீ (ஃபிர்அவ்ன்) அல்ல!\" என்பது இதன் பொருளாகும். ﴾فَاقْضِ مَآ أَنتَ قَاضٍ﴿\n\r\n\n\r\n(எனவே, நீ தீர்ப்பளிக்க விரும்புவதைத் தீர்ப்பளித்துக்கொள்.) \"நீ எதைச் செய்ய விரும்புகிறாயோ அதைச் செய்துகொள், உன்னால் எதைச் சாதிக்க முடியுமோ அதைச் செய்துகொள்.\" ﴾إِنَّمَا تَقْضِى هَـذِهِ الْحَيَوةَ الدُّنْيَآ﴿\n\r\n\n\r\n(உன்னால் இந்த உலக வாழ்க்கையில் மட்டுமே தீர்ப்பளிக்க முடியும்.) அதாவது, \"உனக்கு இந்த உலகத்தில் மட்டுமே அதிகாரம் உள்ளது, இது அழியக்கூடிய உலகம். நிச்சயமாக நாங்கள் நிலையான மறுவுலக வாழ்வையே எதிர்பார்க்கிறோம்.\" ﴾إِنَّآ آمَنَّا بِرَبِّنَا لِيَغْفِرَ لَنَا خَطَايَانَا﴿\n\r\n\n\r\n(நிச்சயமாக நாங்கள் எங்கள் இறைவனை ஈமான் கொண்டோம், அவன் எங்கள் தவறுகளை மன்னிப்பதற்காக,) \"நாங்கள் செய்த தீமைகளை அவன் மன்னிக்க வேண்டும்.\" குறிப்பாக, \"அல்லாஹ்வின் அத்தாட்சியையும் அவனது நபியின் அற்புதத்தையும் எதிர்ப்பதற்காக நாங்கள் கட்டாயப்படுத்தப்பட்ட அந்தச் சூனியத்தையும் அவன் மன்னிக்க வேண்டும்\" என்பது இதன் பொருளாகும். அல்லாஹ்வின் இந்தக் கூற்று குறித்து இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக இப்னு அபீ ஹாதிம் பதிவு செய்துள்ளார்: ﴾وَمَآ أَكْرَهْتَنَا عَلَيْهِ مِنَ السِّحْرِ﴿\n\r\n\n\r\n(எந்தச் சூனியத்தைச் செய்யுமாறு நீ எங்களைக் கட்டாயப்படுத்தினாயோ அதையும் அவன் மன்னிக்க வேண்டும்.) \"ஃபிர்அவ்ன் பனூ இஸ்ராயீல் மக்களிடமிருந்து நாற்பது சிறுவர்களைத் தேர்ந்தெடுத்து, அவர்களுக்கு அல்-ஃபரமா எனும் இடத்தில் சூனியத்தைக் கற்றுக்கொடுக்குமாறு உத்தரவிட்டான். அந்த நாட்டில் எவருக்கும் தெரியாத வித்தைகளை அவர்களுக்குக் கற்றுக்கொடுங்கள் என்று அவன் கூறினான்\" என்று இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள். மேலும் அவர்கள் கூறுகையில், \"அவர்கள் மூஸா (அலை) அவர்களை விசுவாசித்தவர்களில் சேர்ந்தவர்களாயினர். மேலும், ﴾آمَنَّا بِرَبِّنَا لِيَغْفِرَ لَنَا خَطَايَانَا وَمَآ أَكْرَهْتَنَا عَلَيْهِ مِنَ السِّحْرِ﴿ (நாங்கள் எங்கள் இறைவனை ஈமான் கொண்டோம்; அவன் எங்கள் தவறுகளையும், நீ எங்களைக் கட்டாயப்படுத்திச் செய்ய வைத்த சூனியத்தையும் மன்னிப்பதற்காக) என்று கூறியவர்களில் ஒருவராகிவிட்டனர்\" என்றார்கள். அப்துர் ரஹ்மான் பின் ஸைத் பின் அஸ்லம் அவர்களும் இதையே கூறியுள்ளார்கள். அல்லாஹ்வின் கூற்று: ﴾وَاللَّهُ خَيْرٌ وَأَبْقَى﴿\n\r\n\n\r\n(மேலும் அல்லாஹ் (உன் வெகுமதியை விட) சிறந்தவனாகவும் நிலையானவனாகவும் இருக்கிறான்.) அதாவது, \"உன்னை விட எங்களுக்கு அவனே சிறந்தவன்.\" ﴾وَأَبْقَى﴿\n\r\n\n\r\n(மேலும் நிலையானவன்.) நீ எங்களுக்கு வாக்களித்த மற்றும் நாங்கள் ஆசைப்பட்ட வெகுமதியை விட அவனது வெகுமதி மிகவும் நிலையானது. ஃபிர்அவ்ன் (அல்லாஹ் அவனைச் சபிப்பானாக) அவர்களைத் தண்டிப்பதில் குறியாக இருந்தான் என்பதும், அவன் அவர்களுக்குச் செய்தது அல்லாஹ்வின் ஒரு பெரும் கருணையாக அமைந்தது என்பதும் இதிலிருந்து தெளிவாகிறது. இதனால்தான் இப்னு அப்பாஸ் (ரழி) அவர்களும் மற்றும் பிற முன்னோர்களும் (ஸலஃபுகள்), \"அவர்கள் பகலின் ஆரம்பத்தில் சூனியக்காரர்களாக இருந்தார்கள், ஆனால் பகலின் இறுதியில் நல்லடியார்களாகவும் தியாகிகளாகவும் (ஷுஹுதாக்களாகவும்) ஆகிவிட்டார்கள்\" என்று கூறினார்கள்."},"74":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=76\" class=\"link\">20:76</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:76 ஐ பார்க்கவும்"},"75":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=76\" class=\"link\">20:76</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:76 ஐ பார்க்கவும்"},"76":{"html":"<strong>சூனியக்காரர்கள் ஃபிர்அவ்னுக்கு அறிவுரை கூறுதல்</strong><br />\r\n<br />\r\nசூனியக்காரர்கள் ஃபிர்அவ்னுக்கு வழங்கிய அறிவுரையின் தொடர்ச்சியாக அமைவதே இதன் தெளிவான நோக்கமாகும். அவர்கள் அவனுக்கு அல்லாஹ்வின் பழிவாங்குதல் மற்றும் அவனது நிலையான, முடிவற்ற தண்டனை குறித்து எச்சரித்தார்கள். மேலும், அல்லாஹ்வின் நிலையான, முடிவில்லாத நற்கூலியைத் தேடும்படி அவனை ஊக்குவித்தார்கள். அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">يَأْتِ</span> <span class=\"quran-arabic-font text-success\">رَبَّهُ</span> <span class=\"quran-arabic-font text-success\">مُجْرِماً</span><br />\r\n<br />\r\n(நிச்சயமாக, எவர் தன் இறைவனிடம் குற்றவாளியாக வருகிறாரோ,) இதன் பொருள், எவர் மறுமை நாளில் ஒரு குற்றவாளியாக அல்லாஹ்வைச் சந்திக்கிறாரோ (அவருக்கு நரகம் உண்டு).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَإِنَّ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">جَهَنَّمَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَمُوتُ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَحْيَى</span><br />\r\n<br />\r\n(நிச்சயமாக அவருக்கு நரகம் உண்டு, அதில் அவர் சாகவும் மாட்டார், வாழவும் மாட்டார்.) இது அல்லாஹ்வின் பின்வரும் கூற்றைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُقْضَى</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">فَيَمُوتُواْ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يُخَفَّفُ</span> <span class=\"quran-arabic-font text-success\">عَنْهُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">عَذَابِهَا</span> <span class=\"quran-arabic-font text-success\">كَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">نَجْزِى</span> <span class=\"quran-arabic-font text-success\">كُلَّ</span> <span class=\"quran-arabic-font text-success\">كَفُورٍ</span><br />\r\n<br />\r\n(அவர்கள் இறந்துவிடுவதற்கு அவர்களுக்கு மரணமும் விதிக்கப்படாது; மேலும் அவர்களுக்கு அதன் வேதனை இலேசாக்கப்படவும் மாட்டாது. இவ்வாறே நிராகரிப்பாளர்கள் ஒவ்வொருவருக்கும் நாம் கூலி கொடுக்கிறோம்!) (<a href=\"qurandisp.php?sura=35&ayah=36\" class=\"link\">35:36</a>). அல்லாஹ் மேலும் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَتَجَنَّبُهَا</span> <span class=\"quran-arabic-font text-success\">الْأَشْقَى</span> - <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">يَصْلَى</span> <span class=\"quran-arabic-font text-success\">النَّارَ</span> <span class=\"quran-arabic-font text-success\">الْكُبْرَى</span> - <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَمُوتُ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَحْيَا</span><br />\r\n<br />\r\n(ஆனால் பெரும் துர்ப்பாக்கியசாலி அதைத் தவிர்ப்பான். அவன் பெரும் நெருப்பில் நுழைவான். அதில் அவன் சாகவும் மாட்டான், வாழவும் மாட்டான்.) (<a href=\"qurandisp.php?sura=87&ayah=11\" class=\"link\">87:11</a>-13).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَنَادَوْاْ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">مَالِكُ</span> <span class=\"quran-arabic-font text-success\">لِيَقْضِ</span> <span class=\"quran-arabic-font text-success\">عَلَيْنَا</span> <span class=\"quran-arabic-font text-success\">رَبُّكَ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">إِنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">مَّـكِثُونَ</span><br />\r\n<br />\r\n(மேலும் அவர்கள், \"ஓ மாலிக் (நரகத்தின் காவலரே)! உமது இறைவன் எங்களை முடித்துவிடட்டும் (எங்களுக்கு மரணத்தை அளிக்கட்டும்)\" என்று சத்தமிடுவார்கள். அதற்கு அவர், \"நிச்சயமாக, நீங்கள் (இங்கேயே) தங்கியிருப்பீர்கள்\" என்று கூறுவார்.) (<a href=\"qurandisp.php?sura=43&ayah=77\" class=\"link\">43:77</a>). இமாம் அஹ்மத் பின் ஹன்பல் அவர்கள், அபூ ஸஈத் அல்-குத்ரீ (ரழி) அவர்கள் அறிவித்ததாகப் பதிவு செய்துள்ளார்கள்; அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَمَّا</span> <span class=\"quran-arabic-font text-success\">أَهْلُ</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">أَهْلُهَا،</span> <span class=\"quran-arabic-font text-success\">فَإِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَمُوتُونَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">يَحْيَوْنَ،</span> <span class=\"quran-arabic-font text-success\">وَلكِنْ</span> <span class=\"quran-arabic-font text-success\">أُنَاسٌ</span> <span class=\"quran-arabic-font text-success\">تُصِيبُهُمُ</span> <span class=\"quran-arabic-font text-success\">النَّارُ</span> <span class=\"quran-arabic-font text-success\">بِذُنُوبِهِمْ</span> <span class=\"quran-arabic-font text-success\">فَتُمِيتُهُمْ</span> <span class=\"quran-arabic-font text-success\">إِمَاتَةً</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">صَارُوا</span> <span class=\"quran-arabic-font text-success\">فَحْمًا</span> <span class=\"quran-arabic-font text-success\">أُذِنَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الشَّفَاعَةِ</span> <span class=\"quran-arabic-font text-success\">فَجِيءَ</span> <span class=\"quran-arabic-font text-success\">بِهِمْ</span> <span class=\"quran-arabic-font text-success\">ضَبَائِرَ</span> <span class=\"quran-arabic-font text-success\">ضَبَائِرَ،</span> <span class=\"quran-arabic-font text-success\">فَبُثُّوا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَنْهَارِ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ،</span> <span class=\"quran-arabic-font text-success\">فَيُقَالُ</span>: <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">أَهْلَ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">أَفِيضُوا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ،</span> <span class=\"quran-arabic-font text-success\">فَيَنْبُتُونَ</span> <span class=\"quran-arabic-font text-success\">نَبَاتَ</span> <span class=\"quran-arabic-font text-success\">الْحِبَّةِ</span> <span class=\"quran-arabic-font text-success\">تَكُونُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">حَمِيلِ</span> <span class=\"quran-arabic-font text-success\">السَّيْل</span>»<br />\r\n<br />\r\n(நரகவாசிகள் - அதற்குத் தகுதியானவர்கள் யாரோ - அவர்கள் அதில் சாகவும் மாட்டார்கள், வாழவும் மாட்டார்கள். மாறாக, ஒரு சாரார் தங்கள் பாவங்களின் காரணமாக நரக நெருப்பால் தண்டிக்கப்படுவார்கள். அது அவர்களைக் கரிக்கட்டைகளாக மாற்றும் வரை படிப்படியாகக் கொல்லும். பின்னர், பரிந்துரைக்கு (ஷஃபாஅத்) அனுமதி அளிக்கப்படும்; அவர்கள் (நரகத்திலிருந்து) கூட்டம் கூட்டமாக வெளியே கொண்டு வரப்பட்டு, சொர்க்கத்தின் ஆறுகளில் விடப்படுவார்கள். பிறகு, \"சொர்க்கவாசிகளே! இவர்கள் மீது (தண்ணீரை) ஊற்றுங்கள்\" என்று கூறப்படும். அப்போது, அவர்கள் ஓடும் ஆற்றின் ஓரங்களில் அடித்து வரப்பட்ட சேற்றில் ஒரு விதை முளைப்பதைப் போல முளைத்து வளருவார்கள்.) மக்களில் ஒருவர், \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பாலைவனத்தில் வாழ்ந்தவர் போல (உவமை கூறுகிறார்கள்)\" என்று கூறினார். இமாம் முஸ்லிம் அவர்கள் இந்த அறிவிப்பைத் தனது ஸஹீஹ் நூலில் இவ்வாறே பதிவு செய்துள்ளார். அல்லாஹ்வின் பின்வரும் கூற்றைப் பொறுத்தவரை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">يَأْتِهِ</span> <span class=\"quran-arabic-font text-success\">مُؤْمِناً</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">عَمِلَ</span> <span class=\"quran-arabic-font text-success\">الصَّالِحَاتِ</span><br />\r\n<br />\r\n(ஆனால், எவர் அவனிடம் (அல்லாஹ்விடம்) நம்பிக்கையாளராக, நற்செயல்கள் புரிந்தவராக வருகிறாரோ,) எவர் மறுமை நாளில் தன் உள்ளத்தில் ஈமான் கொண்டவராகத் தன் இறைவனைச் சந்திக்கிறாரோ, நிச்சயமாக அவரது உள்ளத்தில் உள்ள எண்ணங்கள் அவரது சொல்லாலும் செயலாலும் உறுதிப்படுத்தப்பட்டிருக்கும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">لَهُمُ</span> <span class=\"quran-arabic-font text-success\">الدَّرَجَـتُ</span> <span class=\"quran-arabic-font text-success\">الْعُلَى</span><br />\r\n<br />\r\n(அத்தகையவர்களுக்கு உயர்ந்த அந்தஸ்துகள் உண்டு,) அதாவது சொர்க்கம்; அதில் மிக உயர்ந்த நிலைகளும், அமைதியான அறைகளும், மிக அழகான இல்லங்களும் உள்ளன. இமாம் அஹ்மத் அவர்கள் உபாதா பின் அஸ்-ஸாமித் (ரழி) அவர்கள் வாயிலாக அறிவிக்கிறார்கள், நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">الْجَنَّةُ</span> <span class=\"quran-arabic-font text-success\">مِائَةُ</span> <span class=\"quran-arabic-font text-success\">دَرَجَةٍ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">دَرَجَتَيْنِ</span> <span class=\"quran-arabic-font text-success\">كَمَا</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">السَّمَاءِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضِ،</span> <span class=\"quran-arabic-font text-success\">وَالْفِرْدَوْسُ</span> <span class=\"quran-arabic-font text-success\">أَعْلَاهَا</span> <span class=\"quran-arabic-font text-success\">دَرَجَةً،</span> <span class=\"quran-arabic-font text-success\">وَمِنْهَا</span> <span class=\"quran-arabic-font text-success\">تَخْرُجُ</span> <span class=\"quran-arabic-font text-success\">الْأَنْهَارُ</span> <span class=\"quran-arabic-font text-success\">الْأَرْبَعَةُ،</span> <span class=\"quran-arabic-font text-success\">وَالْعَرْشُ</span> <span class=\"quran-arabic-font text-success\">فَوْقَهَا،</span> <span class=\"quran-arabic-font text-success\">فَإِذَا</span> <span class=\"quran-arabic-font text-success\">سَأَلْتُمُ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">فَاسْأَلُوهُ</span> <span class=\"quran-arabic-font text-success\">الْفِرْدَوْس</span>»<br />\r\n<br />\r\n(சொர்க்கத்தில் நூறு நிலைகள் உள்ளன; ஒவ்வொரு இரு நிலைகளுக்கும் இடையிலான தூரம் வானத்திற்கும் பூமிக்கும் இடையிலான தூரம் போன்றதாகும். அல்-ஃபிர்தவ்ஸ் என்பது அதன் நிலைகளிலேயே மிக உயர்ந்ததாகும். அதிலிருந்தே நான்கு ஆறுகள் உற்பத்தியாகின்றன; அதற்கு மேலே (அல்லாஹ்வின்) அர்ஷு உள்ளது. எனவே, நீங்கள் அல்லாஹ்விடம் கேட்டால், அல்-ஃபிர்தவ்ஸைக் கேளுங்கள்.) இந்த ஹதீஸை அத்-திர்மிதி அவர்களும் பதிவு செய்துள்ளார்கள். புகாரி, முஸ்லிம் ஆகிய இரு நூல்களிலும் (ஸஹீஹைன்) அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பின்வருமாறு கூறியதாகப் பதிவு செய்யப்பட்டுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">أَهْلَ</span> <span class=\"quran-arabic-font text-success\">عِلِّيِّينَ</span> <span class=\"quran-arabic-font text-success\">لَيَرَوْنَ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">فَوْقَهُمْ</span> <span class=\"quran-arabic-font text-success\">كَمَا</span> <span class=\"quran-arabic-font text-success\">تَرَوْنَ</span> <span class=\"quran-arabic-font text-success\">الْكَوْكَبَ</span> <span class=\"quran-arabic-font text-success\">الْغَابِرَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">أُفُقِ</span> <span class=\"quran-arabic-font text-success\">السَّمَاءِ</span> <span class=\"quran-arabic-font text-success\">لِتَفَاضُلِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمْ</span> <span class=\"quran-arabic-font text-success\">قَالُوا</span>: <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">رَسُولَ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">تِلْكَ</span> <span class=\"quran-arabic-font text-success\">مَنَازِلُ</span> <span class=\"quran-arabic-font text-success\">الْأَنْبِيَاءِ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span>: <span class=\"quran-arabic-font text-success\">بَلى،</span> <span class=\"quran-arabic-font text-success\">وَالَّذِي</span> <span class=\"quran-arabic-font text-success\">نَفْسِي</span> <span class=\"quran-arabic-font text-success\">بِيَدِهِ</span> <span class=\"quran-arabic-font text-success\">رِجَالٌ</span> <span class=\"quran-arabic-font text-success\">آمَنُوا</span> <span class=\"quran-arabic-font text-success\">بِاللهِ</span> <span class=\"quran-arabic-font text-success\">وَصَدَّقُوا</span> <span class=\"quran-arabic-font text-success\">الْمُرْسَلِين</span>»<br />\r\n<br />\r\n(நிச்சயமாக, இல்லிய்யீனில் உள்ளவர்கள் தங்களுக்கு மேலே உள்ளவர்களை, வானத்தின் அடிவானத்தில் மறைந்து கொண்டிருக்கும் ஒரு நட்சத்திரத்தை நீங்கள் காண்பது போலக் காண்பார்கள். இது அவர்களுக்கிடையிலான சிறப்புகளின் வேறுபாட்டினால் ஏற்படுவதாகும்.) மக்கள், \"அல்லாஹ்வின் தூதரே (ஸல்)! இவை நபிமார்களின் இருப்பிடங்களா?\" என்று கேட்டனர். அதற்கு அவர்கள், \"ஆம், என் உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது சத்தியமாக! இவர்கள் அல்லாஹ்வின் மீது ஈமான் கொண்டு, இறைத்தூதர்களை உண்மையென நம்பிய மனிதர்கள்\" என்று பதிலளித்தார்கள். சுனன் நூல்களில் இந்த ஹதீஸ் கூடுதல் வார்த்தைகளுடன் இடம்பெற்றுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">أَبَا</span> <span class=\"quran-arabic-font text-success\">بَكْرٍ</span> <span class=\"quran-arabic-font text-success\">وَعُمَرَ</span> <span class=\"quran-arabic-font text-success\">لَمِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">وَأَنْعَمَا</span>»<br />\r\n<br />\r\n(நிச்சயமாக அபூபக்கர் (ரழி) அவர்களும் உமர் (ரழி) அவர்களும் அவர்களில் அடங்குவர்; மேலும் அவர்கள் நற்பேறு பெற்றவர்கள்.) அவனது கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">جَنَّاتُ</span> <span class=\"quran-arabic-font text-success\">عَدْنٍ</span><br />\r\n<br />\r\n(அத்ன் எனும் நிலையான தோட்டங்கள்,) அதாவது வசிப்பிடமாக நிலைபெற்றவை. இது முன்னர் குறிப்பிடப்பட்ட உயர் பதவிகளைக் குறிக்கவே இங்கு பயன்படுத்தப்பட்டுள்ளது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">تَجْرِى</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">تَحْتِهَا</span> <span class=\"quran-arabic-font text-success\">الْأَنْهَارُ</span> <span class=\"quran-arabic-font text-success\">خَـالِدِينَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span><br />\r\n<br />\r\n(அதன் கீழே ஆறுகள் ஓடிக்கொண்டிருக்கும், அதில் அவர்கள் என்றென்றும் தங்கியிருப்பார்கள்,) அதாவது அவர்கள் அதில் நிரந்தரமாக இருப்பார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَذلِكَ</span> <span class=\"quran-arabic-font text-success\">جَزَآءُ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">تَزَكَّى</span><br />\r\n<br />\r\n(தன்னைத் தூய்மைப்படுத்திக் கொண்டவர்களின் கூலி இதுவே.) அழுக்குகள், அசுத்தங்கள் மற்றும் அல்லாஹ்வுக்கு இணை வைத்தல் (ஷிர்க்) ஆகியவற்றிலிருந்து தன்னைத் தூய்மைப்படுத்திக் கொண்டவரையே இது குறிக்கிறது. இவர் அல்லாஹ்வுக்கு எதனையும் இணையாக்காமல் அவனை மட்டுமே வணங்குவார்; மேலும் இறைத்தூதர்கள் கொண்டு வந்த நன்மைகளிலும் அவர்கள் போதித்த அனைத்திலும் அவர்களைப் பின்பற்றுவார்.<br />\r\n<br />\r\n<br />\r\n<br />","text":"சூனியக்காரர்கள் ஃபிர்அவ்னுக்கு அறிவுரை கூறுதல்\n\r\n\n\r\nசூனியக்காரர்கள் ஃபிர்அவ்னுக்கு வழங்கிய அறிவுரையின் தொடர்ச்சியாக அமைவதே இதன் தெளிவான நோக்கமாகும். அவர்கள் அவனுக்கு அல்லாஹ்வின் பழிவாங்குதல் மற்றும் அவனது நிலையான, முடிவற்ற தண்டனை குறித்து எச்சரித்தார்கள். மேலும், அல்லாஹ்வின் நிலையான, முடிவில்லாத நற்கூலியைத் தேடும்படி அவனை ஊக்குவித்தார்கள். அவர்கள் கூறினார்கள்:\n\r\n\n\r\nإِنَّهُ مَن يَأْتِ رَبَّهُ مُجْرِماً\n\r\n\n\r\n(நிச்சயமாக, எவர் தன் இறைவனிடம் குற்றவாளியாக வருகிறாரோ,) இதன் பொருள், எவர் மறுமை நாளில் ஒரு குற்றவாளியாக அல்லாஹ்வைச் சந்திக்கிறாரோ (அவருக்கு நரகம் உண்டு).\n\r\n\n\r\nفَإِنَّ لَهُ جَهَنَّمَ لاَ يَمُوتُ فِيهَا وَلاَ يَحْيَى\n\r\n\n\r\n(நிச்சயமாக அவருக்கு நரகம் உண்டு, அதில் அவர் சாகவும் மாட்டார், வாழவும் மாட்டார்.) இது அல்லாஹ்வின் பின்வரும் கூற்றைப் போன்றதாகும்:\n\r\n\n\r\nلاَ يُقْضَى عَلَيْهِمْ فَيَمُوتُواْ وَلاَ يُخَفَّفُ عَنْهُمْ مِّنْ عَذَابِهَا كَذَلِكَ نَجْزِى كُلَّ كَفُورٍ\n\r\n\n\r\n(அவர்கள் இறந்துவிடுவதற்கு அவர்களுக்கு மரணமும் விதிக்கப்படாது; மேலும் அவர்களுக்கு அதன் வேதனை இலேசாக்கப்படவும் மாட்டாது. இவ்வாறே நிராகரிப்பாளர்கள் ஒவ்வொருவருக்கும் நாம் கூலி கொடுக்கிறோம்!) (35:36). அல்லாஹ் மேலும் கூறினான்:\n\r\n\n\r\nوَيَتَجَنَّبُهَا الْأَشْقَى - الَّذِى يَصْلَى النَّارَ الْكُبْرَى - ثُمَّ لاَ يَمُوتُ فِيهَا وَلاَ يَحْيَا\n\r\n\n\r\n(ஆனால் பெரும் துர்ப்பாக்கியசாலி அதைத் தவிர்ப்பான். அவன் பெரும் நெருப்பில் நுழைவான். அதில் அவன் சாகவும் மாட்டான், வாழவும் மாட்டான்.) (87:11-13).\n\r\n\n\r\nوَنَادَوْاْ يَا مَالِكُ لِيَقْضِ عَلَيْنَا رَبُّكَ قَالَ إِنَّكُمْ مَّـكِثُونَ\n\r\n\n\r\n(மேலும் அவர்கள், \"ஓ மாலிக் (நரகத்தின் காவலரே)! உமது இறைவன் எங்களை முடித்துவிடட்டும் (எங்களுக்கு மரணத்தை அளிக்கட்டும்)\" என்று சத்தமிடுவார்கள். அதற்கு அவர், \"நிச்சயமாக, நீங்கள் (இங்கேயே) தங்கியிருப்பீர்கள்\" என்று கூறுவார்.) (43:77). இமாம் அஹ்மத் பின் ஹன்பல் அவர்கள், அபூ ஸஈத் அல்-குத்ரீ (ரழி) அவர்கள் அறிவித்ததாகப் பதிவு செய்துள்ளார்கள்; அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«أَمَّا أَهْلُ النَّارِ الَّذِينَ هُمْ أَهْلُهَا، فَإِنَّهُمْ لَا يَمُوتُونَ فِيهَا وَلَا يَحْيَوْنَ، وَلكِنْ أُنَاسٌ تُصِيبُهُمُ النَّارُ بِذُنُوبِهِمْ فَتُمِيتُهُمْ إِمَاتَةً حَتَّى إِذَا صَارُوا فَحْمًا أُذِنَ فِي الشَّفَاعَةِ فَجِيءَ بِهِمْ ضَبَائِرَ ضَبَائِرَ، فَبُثُّوا عَلَى أَنْهَارِ الْجَنَّةِ، فَيُقَالُ: يَا أَهْلَ الْجَنَّةِ أَفِيضُوا عَلَيْهِمْ، فَيَنْبُتُونَ نَبَاتَ الْحِبَّةِ تَكُونُ فِي حَمِيلِ السَّيْل»\n\r\n\n\r\n(நரகவாசிகள் - அதற்குத் தகுதியானவர்கள் யாரோ - அவர்கள் அதில் சாகவும் மாட்டார்கள், வாழவும் மாட்டார்கள். மாறாக, ஒரு சாரார் தங்கள் பாவங்களின் காரணமாக நரக நெருப்பால் தண்டிக்கப்படுவார்கள். அது அவர்களைக் கரிக்கட்டைகளாக மாற்றும் வரை படிப்படியாகக் கொல்லும். பின்னர், பரிந்துரைக்கு (ஷஃபாஅத்) அனுமதி அளிக்கப்படும்; அவர்கள் (நரகத்திலிருந்து) கூட்டம் கூட்டமாக வெளியே கொண்டு வரப்பட்டு, சொர்க்கத்தின் ஆறுகளில் விடப்படுவார்கள். பிறகு, \"சொர்க்கவாசிகளே! இவர்கள் மீது (தண்ணீரை) ஊற்றுங்கள்\" என்று கூறப்படும். அப்போது, அவர்கள் ஓடும் ஆற்றின் ஓரங்களில் அடித்து வரப்பட்ட சேற்றில் ஒரு விதை முளைப்பதைப் போல முளைத்து வளருவார்கள்.) மக்களில் ஒருவர், \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பாலைவனத்தில் வாழ்ந்தவர் போல (உவமை கூறுகிறார்கள்)\" என்று கூறினார். இமாம் முஸ்லிம் அவர்கள் இந்த அறிவிப்பைத் தனது ஸஹீஹ் நூலில் இவ்வாறே பதிவு செய்துள்ளார். அல்லாஹ்வின் பின்வரும் கூற்றைப் பொறுத்தவரை:\n\r\n\n\r\nوَمَن يَأْتِهِ مُؤْمِناً قَدْ عَمِلَ الصَّالِحَاتِ\n\r\n\n\r\n(ஆனால், எவர் அவனிடம் (அல்லாஹ்விடம்) நம்பிக்கையாளராக, நற்செயல்கள் புரிந்தவராக வருகிறாரோ,) எவர் மறுமை நாளில் தன் உள்ளத்தில் ஈமான் கொண்டவராகத் தன் இறைவனைச் சந்திக்கிறாரோ, நிச்சயமாக அவரது உள்ளத்தில் உள்ள எண்ணங்கள் அவரது சொல்லாலும் செயலாலும் உறுதிப்படுத்தப்பட்டிருக்கும்.\n\r\n\n\r\nفَأُوْلَـئِكَ لَهُمُ الدَّرَجَـتُ الْعُلَى\n\r\n\n\r\n(அத்தகையவர்களுக்கு உயர்ந்த அந்தஸ்துகள் உண்டு,) அதாவது சொர்க்கம்; அதில் மிக உயர்ந்த நிலைகளும், அமைதியான அறைகளும், மிக அழகான இல்லங்களும் உள்ளன. இமாம் அஹ்மத் அவர்கள் உபாதா பின் அஸ்-ஸாமித் (ரழி) அவர்கள் வாயிலாக அறிவிக்கிறார்கள், நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«الْجَنَّةُ مِائَةُ دَرَجَةٍ مَا بَيْنَ كُلِّ دَرَجَتَيْنِ كَمَا بَيْنَ السَّمَاءِ وَالْأَرْضِ، وَالْفِرْدَوْسُ أَعْلَاهَا دَرَجَةً، وَمِنْهَا تَخْرُجُ الْأَنْهَارُ الْأَرْبَعَةُ، وَالْعَرْشُ فَوْقَهَا، فَإِذَا سَأَلْتُمُ اللهَ فَاسْأَلُوهُ الْفِرْدَوْس»\n\r\n\n\r\n(சொர்க்கத்தில் நூறு நிலைகள் உள்ளன; ஒவ்வொரு இரு நிலைகளுக்கும் இடையிலான தூரம் வானத்திற்கும் பூமிக்கும் இடையிலான தூரம் போன்றதாகும். அல்-ஃபிர்தவ்ஸ் என்பது அதன் நிலைகளிலேயே மிக உயர்ந்ததாகும். அதிலிருந்தே நான்கு ஆறுகள் உற்பத்தியாகின்றன; அதற்கு மேலே (அல்லாஹ்வின்) அர்ஷு உள்ளது. எனவே, நீங்கள் அல்லாஹ்விடம் கேட்டால், அல்-ஃபிர்தவ்ஸைக் கேளுங்கள்.) இந்த ஹதீஸை அத்-திர்மிதி அவர்களும் பதிவு செய்துள்ளார்கள். புகாரி, முஸ்லிம் ஆகிய இரு நூல்களிலும் (ஸஹீஹைன்) அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பின்வருமாறு கூறியதாகப் பதிவு செய்யப்பட்டுள்ளது:\n\r\n\n\r\n«إِنَّ أَهْلَ عِلِّيِّينَ لَيَرَوْنَ مَنْ فَوْقَهُمْ كَمَا تَرَوْنَ الْكَوْكَبَ الْغَابِرَ فِي أُفُقِ السَّمَاءِ لِتَفَاضُلِ مَا بَيْنَهُمْ قَالُوا: يَا رَسُولَ اللهِ تِلْكَ مَنَازِلُ الْأَنْبِيَاءِ قَالَ: بَلى، وَالَّذِي نَفْسِي بِيَدِهِ رِجَالٌ آمَنُوا بِاللهِ وَصَدَّقُوا الْمُرْسَلِين»\n\r\n\n\r\n(நிச்சயமாக, இல்லிய்யீனில் உள்ளவர்கள் தங்களுக்கு மேலே உள்ளவர்களை, வானத்தின் அடிவானத்தில் மறைந்து கொண்டிருக்கும் ஒரு நட்சத்திரத்தை நீங்கள் காண்பது போலக் காண்பார்கள். இது அவர்களுக்கிடையிலான சிறப்புகளின் வேறுபாட்டினால் ஏற்படுவதாகும்.) மக்கள், \"அல்லாஹ்வின் தூதரே (ஸல்)! இவை நபிமார்களின் இருப்பிடங்களா?\" என்று கேட்டனர். அதற்கு அவர்கள், \"ஆம், என் உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது சத்தியமாக! இவர்கள் அல்லாஹ்வின் மீது ஈமான் கொண்டு, இறைத்தூதர்களை உண்மையென நம்பிய மனிதர்கள்\" என்று பதிலளித்தார்கள். சுனன் நூல்களில் இந்த ஹதீஸ் கூடுதல் வார்த்தைகளுடன் இடம்பெற்றுள்ளது:\n\r\n\n\r\n«وَإِنَّ أَبَا بَكْرٍ وَعُمَرَ لَمِنْهُمْ وَأَنْعَمَا»\n\r\n\n\r\n(நிச்சயமாக அபூபக்கர் (ரழி) அவர்களும் உமர் (ரழி) அவர்களும் அவர்களில் அடங்குவர்; மேலும் அவர்கள் நற்பேறு பெற்றவர்கள்.) அவனது கூற்று:\n\r\n\n\r\nجَنَّاتُ عَدْنٍ\n\r\n\n\r\n(அத்ன் எனும் நிலையான தோட்டங்கள்,) அதாவது வசிப்பிடமாக நிலைபெற்றவை. இது முன்னர் குறிப்பிடப்பட்ட உயர் பதவிகளைக் குறிக்கவே இங்கு பயன்படுத்தப்பட்டுள்ளது.\n\r\n\n\r\nتَجْرِى مِن تَحْتِهَا الْأَنْهَارُ خَـالِدِينَ فِيهَا\n\r\n\n\r\n(அதன் கீழே ஆறுகள் ஓடிக்கொண்டிருக்கும், அதில் அவர்கள் என்றென்றும் தங்கியிருப்பார்கள்,) அதாவது அவர்கள் அதில் நிரந்தரமாக இருப்பார்கள்.\n\r\n\n\r\nوَذلِكَ جَزَآءُ مَن تَزَكَّى\n\r\n\n\r\n(தன்னைத் தூய்மைப்படுத்திக் கொண்டவர்களின் கூலி இதுவே.) அழுக்குகள், அசுத்தங்கள் மற்றும் அல்லாஹ்வுக்கு இணை வைத்தல் (ஷிர்க்) ஆகியவற்றிலிருந்து தன்னைத் தூய்மைப்படுத்திக் கொண்டவரையே இது குறிக்கிறது. இவர் அல்லாஹ்வுக்கு எதனையும் இணையாக்காமல் அவனை மட்டுமே வணங்குவார்; மேலும் இறைத்தூதர்கள் கொண்டு வந்த நன்மைகளிலும் அவர்கள் போதித்த அனைத்திலும் அவர்களைப் பின்பற்றுவார்."},"77":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=79\" class=\"link\">20:79</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:79 ஐ பார்க்கவும்"},"78":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=79\" class=\"link\">20:79</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:79 ஐ பார்க்கவும்"},"79":{"html":"<strong>இஸ்ரவேல் மக்கள் எகிப்தை விட்டு வெளியேறுதல்</strong><br />\r\n<br />\r\nமேன்மைமிக்க அல்லாஹ் கூறுகிறான்: மூஸாவை (அலை) விடுவித்து, தம்முடன் அனுப்பி வைக்க ஃபிர்அவ்ன் மறுத்தபோது, இஸ்ரவேல் மக்களுடன் இரவில் பயணப்படுமாறு மூஸாவுக்கு (அலை) அல்லாஹ் கட்டளையிட்டான். ஃபிர்அவ்னின் அடிமைத்தனத்திலிருந்து அவர்களை விடுவித்து அழைத்துச் செல்ல வேண்டும் என்பதே அதன் நோக்கமாகும். இந்த கண்ணியமிக்க சூராவைப் போன்றே மற்ற சூராக்களிலும் அல்லாஹ் இதனை விரிவாக விளக்குகிறான். மூஸா (அலை) இஸ்ரவேல் மக்களுடன் புறப்பட்டுச் சென்றார்கள். எகிப்து மக்கள் அதிகாலையில் விழித்தபோது, இஸ்ரவேலர்களில் ஒருவர்கூட அங்கு இல்லை என்பதைக் கண்டனர்.<br />\r\n<br />\r\nஃபிர்அவ்ன் மிகுந்த ஆத்திரமடைந்தான். தனது தேசத்தின் அனைத்துப் பகுதிகளிலிருந்தும் தனது படைகளைத் திரட்டுவதற்காக எல்லா நகரங்களுக்கும் ஆட்களை அனுப்பினான். அவன் அவர்களிடம் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">هَـؤُلاءِ</span> <span class=\"quran-arabic-font text-success\">لَشِرْذِمَةٌ</span> <span class=\"quran-arabic-font text-success\">قَلِيلُونَ</span> - <span class=\"quran-arabic-font text-success\">وَإِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">لَغَآئِظُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span> (நிச்சயமாக, இவர்கள் ஒரு சிறிய கூட்டத்தினரே. நிச்சயமாக, அவர்கள் நம்மைப் பெரிதும் கோபப்படுத்தியுள்ளனர்.) <a href=\"qurandisp.php?sura=26&ayah=54\" class=\"link\">26:54</a>-55<br />\r\n<br />\r\nபிறகு அவன் தனது படைகளைத் திரட்டி ஒருங்கிணைத்து, அவர்களைப் பின்தொடர்ந்து புறப்பட்டான். சூரியன் உதிக்கத் தொடங்கிய அதிகாலை நேரத்தில் அவர்கள் இஸ்ரவேல் மக்களை நெருங்கினர். <span class=\"quran-arabic-font text-success\">﴾فَلَمَّا</span> <span class=\"quran-arabic-font text-success\">تَرَآءَا</span> <span class=\"quran-arabic-font text-success\">الْجَمْعَانِ﴿</span> (இரு கூட்டத்தினரும் ஒருவரையொருவர் கண்டபோது) <a href=\"qurandisp.php?sura=26&ayah=61\" class=\"link\">26:61</a> அதாவது, இரு தரப்பிலும் உள்ள ஒவ்வொருவரும் மற்ற தரப்பினரைப் பார்த்தனர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَلَمَّا</span> <span class=\"quran-arabic-font text-success\">تَرَآءَا</span> <span class=\"quran-arabic-font text-success\">الْجَمْعَانِ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">أَصْحَـبُ</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span> <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">لَمُدْرَكُونَ</span> - <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">كَلاَّ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">مَعِىَ</span> <span class=\"quran-arabic-font text-success\">رَبِّى</span> <span class=\"quran-arabic-font text-success\">سَيَهْدِينِ</span> <span class=\"quran-arabic-font text-success\">﴿</span> (மூஸாவின் (அலை) தோழர்கள் கூறினார்கள்: \"நிச்சயமாக நாம் பிடிபட்டுவிடுவோம்.\" மூஸா (அலை) கூறினார்கள்: \"அப்படியல்ல, நிச்சயமாக என்னுடன் என் இறைவன் இருக்கிறான். அவன் எனக்கு வழிகாட்டுவான்.\") <a href=\"qurandisp.php?sura=26&ayah=61\" class=\"link\">26:61</a>-62<br />\r\n<br />\r\nமூஸா (அலை) இஸ்ரவேல் மக்களுடன் நின்றார்கள். அவர்களுக்கு முன்னால் கடலும், பின்னால் ஃபிர்அவ்னும் இருந்தான். அந்தத் தருணத்தில், அல்லாஹ் மூஸாவுக்கு (அலை) வஹீ (இறைச்செய்தி) அறிவித்தான்: <span class=\"quran-arabic-font text-success\">﴾فَاضْرِبْ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">طَرِيقاً</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْبَحْرِ</span> <span class=\"quran-arabic-font text-success\">يَبَساً﴿</span> (கடலில் அவர்களுக்காக ஒரு காய்ந்த பாதையை ஏற்படுத்துவீராக.)<br />\r\n<br />\r\nஎனவே, மூஸா (அலை) தமது கைத்தடியால் கடலில் அடித்தார்கள். \"அல்லாஹ்வின் அனுமதியுடன் எனக்காகப் பிளவுபடு\" என்று அவர்கள் கூறினார்கள். அவ்வாறே கடல் பிளவுபட்டது, <span class=\"quran-arabic-font text-success\">﴾فَانْفَلَقَ</span> <span class=\"quran-arabic-font text-success\">فَكَانَ</span> <span class=\"quran-arabic-font text-success\">كُلُّ</span> <span class=\"quran-arabic-font text-success\">فِرْقٍ</span> <span class=\"quran-arabic-font text-success\">كَالطَّوْدِ</span> <span class=\"quran-arabic-font text-success\">الْعَظِيمِ﴿</span> நீரின் ஒவ்வொரு பகுதியும் ஒரு பிரம்மாண்டமான மலையைப் போல நின்றது. பிறகு, கடலின் தரைப்பகுதிக்கு அல்லாஹ் ஒரு காற்றை அனுப்பினான்; அது நிலத்தைப் போல வறண்டு போகும் வரை அத்தரையினை உலர்த்தியது.<br />\r\n<br />\r\nஇதன் காரணமாகவே அல்லாஹ் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾فَاضْرِبْ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">طَرِيقاً</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْبَحْرِ</span> <span class=\"quran-arabic-font text-success\">يَبَساً</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">تَخَافُ</span> <span class=\"quran-arabic-font text-success\">دَرَكاً﴿</span> (...கடலில் அவர்களுக்காக ஒரு காய்ந்த பாதையை ஏற்படுத்துவீராக; ஃபிர்அவ்னால் பிடிபடுவோம் என்று அஞ்சாமலும்...) அதாவது ஃபிர்அவ்னிடம் அகப்படுவதைப் பற்றி கவலைப்படாமலும்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَخْشَى﴿</span> (அச்சப்படாமலும்.) அதாவது, \"கடல் உங்கள் மக்களை மூழ்கடித்துவிடும் என்று பயப்படாதீர்கள்\" என்று அல்லாஹ் கூறினான்.<br />\r\n<br />\r\nபிறகு, மேன்மைமிக்க அல்லாஹ் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾فَأَتْبَعَهُمْ</span> <span class=\"quran-arabic-font text-success\">فِرْعَوْنُ</span> <span class=\"quran-arabic-font text-success\">بِجُنُودِهِ</span> <span class=\"quran-arabic-font text-success\">فَغَشِيَهُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْيَمِّ﴿</span> (பிறகு ஃபிர்அவ்ன் தனது படைகளுடன் அவர்களைப் பின்தொடர்ந்தான், ஆனால் 'அல்-யம்' அவர்களை முழுமையாக மூழ்கடித்தது.) 'அல்-யம்' என்றால் கடல் என்று பொருள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾مَا</span> <span class=\"quran-arabic-font text-success\">غَشِيَهُمْ﴿</span> (மேலும் அது அவர்களை மூடிக்கொண்டது.) அதாவது, அத்தகைய சூழலில் அவர்களுக்கு நன்கு பரிச்சயமான ஒன்றால் அவர்களை மூடியது; இதனை அல்லாஹ் குறிப்பிடுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَالْمُؤْتَفِكَةَ</span> <span class=\"quran-arabic-font text-success\">أَهْوَى</span> - <span class=\"quran-arabic-font text-success\">فَغَشَّـهَا</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">غَشَّى</span> <span class=\"quran-arabic-font text-success\">﴿</span> (மேலும், தலைகீழாகப் புரட்டப்பட்ட நகரங்களையும் அவன் அழித்தான். எதனால் மூடப்பட வேண்டுமோ, அதைக் கொண்டு அவற்றை மூடினான்.) <a href=\"qurandisp.php?sura=53&ayah=53\" class=\"link\">53:53</a>-54<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَأَضَلَّ</span> <span class=\"quran-arabic-font text-success\">فِرْعَوْنُ</span> <span class=\"quran-arabic-font text-success\">قَوْمَهُ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">هَدَى</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\nஃபிர்அவ்ன் அவர்களைப் பின்தொடர்ந்து கடலுக்குள் சென்று, தனது மக்களை வழிகெடுத்து, நேர்வழிக்கு அவர்களை அழைத்துச் செல்லாமல் போனது போலவே, மறுமை நாளிலும் <span class=\"quran-arabic-font text-success\">﴾يَقْدُمُ</span> <span class=\"quran-arabic-font text-success\">قَوْمَهُ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَةِ</span> <span class=\"quran-arabic-font text-success\">فَأَوْرَدَهُمُ</span> <span class=\"quran-arabic-font text-success\">النَّارَ﴿</span> அவன் தனது மக்களுக்கு முன்னால் சென்று அவர்களை நரக நெருப்பிற்குள் இட்டுச் செல்வான். அவர்கள் அழைத்துச் செல்லப்படும் அந்த இடம் நிச்சயமாக மிகவும் கெட்டது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾يَـبَنِى</span> <span class=\"quran-arabic-font text-success\">إِسْرَءِيلَ</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">أَنجَيْنَـكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">عَدُوِّكُمْ</span> <span class=\"quran-arabic-font text-success\">وَوَاعَدْنَـكُمْ</span> <span class=\"quran-arabic-font text-success\">جَانِبَ</span> <span class=\"quran-arabic-font text-success\">الطُّورِ</span> <span class=\"quran-arabic-font text-success\">الْأَيْمَنَ</span> <span class=\"quran-arabic-font text-success\">وَنَزَّلْنَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمُ</span> <span class=\"quran-arabic-font text-success\">الْمَنَّ</span> <span class=\"quran-arabic-font text-success\">وَالسَّلْوَى</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />","text":"இஸ்ரவேல் மக்கள் எகிப்தை விட்டு வெளியேறுதல்\n\r\n\n\r\nமேன்மைமிக்க அல்லாஹ் கூறுகிறான்: மூஸாவை (அலை) விடுவித்து, தம்முடன் அனுப்பி வைக்க ஃபிர்அவ்ன் மறுத்தபோது, இஸ்ரவேல் மக்களுடன் இரவில் பயணப்படுமாறு மூஸாவுக்கு (அலை) அல்லாஹ் கட்டளையிட்டான். ஃபிர்அவ்னின் அடிமைத்தனத்திலிருந்து அவர்களை விடுவித்து அழைத்துச் செல்ல வேண்டும் என்பதே அதன் நோக்கமாகும். இந்த கண்ணியமிக்க சூராவைப் போன்றே மற்ற சூராக்களிலும் அல்லாஹ் இதனை விரிவாக விளக்குகிறான். மூஸா (அலை) இஸ்ரவேல் மக்களுடன் புறப்பட்டுச் சென்றார்கள். எகிப்து மக்கள் அதிகாலையில் விழித்தபோது, இஸ்ரவேலர்களில் ஒருவர்கூட அங்கு இல்லை என்பதைக் கண்டனர்.\n\r\n\n\r\nஃபிர்அவ்ன் மிகுந்த ஆத்திரமடைந்தான். தனது தேசத்தின் அனைத்துப் பகுதிகளிலிருந்தும் தனது படைகளைத் திரட்டுவதற்காக எல்லா நகரங்களுக்கும் ஆட்களை அனுப்பினான். அவன் அவர்களிடம் கூறினான்: ﴾إِنَّ هَـؤُلاءِ لَشِرْذِمَةٌ قَلِيلُونَ - وَإِنَّهُمْ لَنَا لَغَآئِظُونَ ﴿ (நிச்சயமாக, இவர்கள் ஒரு சிறிய கூட்டத்தினரே. நிச்சயமாக, அவர்கள் நம்மைப் பெரிதும் கோபப்படுத்தியுள்ளனர்.) 26:54-55\n\r\n\n\r\nபிறகு அவன் தனது படைகளைத் திரட்டி ஒருங்கிணைத்து, அவர்களைப் பின்தொடர்ந்து புறப்பட்டான். சூரியன் உதிக்கத் தொடங்கிய அதிகாலை நேரத்தில் அவர்கள் இஸ்ரவேல் மக்களை நெருங்கினர். ﴾فَلَمَّا تَرَآءَا الْجَمْعَانِ﴿ (இரு கூட்டத்தினரும் ஒருவரையொருவர் கண்டபோது) 26:61 அதாவது, இரு தரப்பிலும் உள்ள ஒவ்வொருவரும் மற்ற தரப்பினரைப் பார்த்தனர்.\n\r\n\n\r\n﴾فَلَمَّا تَرَآءَا الْجَمْعَانِ قَالَ أَصْحَـبُ مُوسَى إِنَّا لَمُدْرَكُونَ - قَالَ كَلاَّ إِنَّ مَعِىَ رَبِّى سَيَهْدِينِ ﴿ (மூஸாவின் (அலை) தோழர்கள் கூறினார்கள்: \"நிச்சயமாக நாம் பிடிபட்டுவிடுவோம்.\" மூஸா (அலை) கூறினார்கள்: \"அப்படியல்ல, நிச்சயமாக என்னுடன் என் இறைவன் இருக்கிறான். அவன் எனக்கு வழிகாட்டுவான்.\") 26:61-62\n\r\n\n\r\nமூஸா (அலை) இஸ்ரவேல் மக்களுடன் நின்றார்கள். அவர்களுக்கு முன்னால் கடலும், பின்னால் ஃபிர்அவ்னும் இருந்தான். அந்தத் தருணத்தில், அல்லாஹ் மூஸாவுக்கு (அலை) வஹீ (இறைச்செய்தி) அறிவித்தான்: ﴾فَاضْرِبْ لَهُمْ طَرِيقاً فِى الْبَحْرِ يَبَساً﴿ (கடலில் அவர்களுக்காக ஒரு காய்ந்த பாதையை ஏற்படுத்துவீராக.)\n\r\n\n\r\nஎனவே, மூஸா (அலை) தமது கைத்தடியால் கடலில் அடித்தார்கள். \"அல்லாஹ்வின் அனுமதியுடன் எனக்காகப் பிளவுபடு\" என்று அவர்கள் கூறினார்கள். அவ்வாறே கடல் பிளவுபட்டது, ﴾فَانْفَلَقَ فَكَانَ كُلُّ فِرْقٍ كَالطَّوْدِ الْعَظِيمِ﴿ நீரின் ஒவ்வொரு பகுதியும் ஒரு பிரம்மாண்டமான மலையைப் போல நின்றது. பிறகு, கடலின் தரைப்பகுதிக்கு அல்லாஹ் ஒரு காற்றை அனுப்பினான்; அது நிலத்தைப் போல வறண்டு போகும் வரை அத்தரையினை உலர்த்தியது.\n\r\n\n\r\nஇதன் காரணமாகவே அல்லாஹ் கூறினான்: ﴾فَاضْرِبْ لَهُمْ طَرِيقاً فِى الْبَحْرِ يَبَساً لاَّ تَخَافُ دَرَكاً﴿ (...கடலில் அவர்களுக்காக ஒரு காய்ந்த பாதையை ஏற்படுத்துவீராக; ஃபிர்அவ்னால் பிடிபடுவோம் என்று அஞ்சாமலும்...) அதாவது ஃபிர்அவ்னிடம் அகப்படுவதைப் பற்றி கவலைப்படாமலும்,\n\r\n\n\r\n﴾وَلاَ تَخْشَى﴿ (அச்சப்படாமலும்.) அதாவது, \"கடல் உங்கள் மக்களை மூழ்கடித்துவிடும் என்று பயப்படாதீர்கள்\" என்று அல்லாஹ் கூறினான்.\n\r\n\n\r\nபிறகு, மேன்மைமிக்க அல்லாஹ் கூறினான்: ﴾فَأَتْبَعَهُمْ فِرْعَوْنُ بِجُنُودِهِ فَغَشِيَهُمْ مِّنَ الْيَمِّ﴿ (பிறகு ஃபிர்அவ்ன் தனது படைகளுடன் அவர்களைப் பின்தொடர்ந்தான், ஆனால் 'அல்-யம்' அவர்களை முழுமையாக மூழ்கடித்தது.) 'அல்-யம்' என்றால் கடல் என்று பொருள்.\n\r\n\n\r\n﴾مَا غَشِيَهُمْ﴿ (மேலும் அது அவர்களை மூடிக்கொண்டது.) அதாவது, அத்தகைய சூழலில் அவர்களுக்கு நன்கு பரிச்சயமான ஒன்றால் அவர்களை மூடியது; இதனை அல்லாஹ் குறிப்பிடுகிறான்: ﴾وَالْمُؤْتَفِكَةَ أَهْوَى - فَغَشَّـهَا مَا غَشَّى ﴿ (மேலும், தலைகீழாகப் புரட்டப்பட்ட நகரங்களையும் அவன் அழித்தான். எதனால் மூடப்பட வேண்டுமோ, அதைக் கொண்டு அவற்றை மூடினான்.) 53:53-54\n\r\n\n\r\n﴾وَأَضَلَّ فِرْعَوْنُ قَوْمَهُ وَمَا هَدَى ﴿\n\r\n\n\r\nஃபிர்அவ்ன் அவர்களைப் பின்தொடர்ந்து கடலுக்குள் சென்று, தனது மக்களை வழிகெடுத்து, நேர்வழிக்கு அவர்களை அழைத்துச் செல்லாமல் போனது போலவே, மறுமை நாளிலும் ﴾يَقْدُمُ قَوْمَهُ يَوْمَ الْقِيَامَةِ فَأَوْرَدَهُمُ النَّارَ﴿ அவன் தனது மக்களுக்கு முன்னால் சென்று அவர்களை நரக நெருப்பிற்குள் இட்டுச் செல்வான். அவர்கள் அழைத்துச் செல்லப்படும் அந்த இடம் நிச்சயமாக மிகவும் கெட்டது.\n\r\n\n\r\n﴾يَـبَنِى إِسْرَءِيلَ قَدْ أَنجَيْنَـكُمْ مِّنْ عَدُوِّكُمْ وَوَاعَدْنَـكُمْ جَانِبَ الطُّورِ الْأَيْمَنَ وَنَزَّلْنَا عَلَيْكُمُ الْمَنَّ وَالسَّلْوَى ﴿"},"80":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=82\" class=\"link\">20:82</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:82 ஐ பார்க்கவும்"},"81":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=82\" class=\"link\">20:82</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:82 ஐ பார்க்கவும்"},"82":{"html":"<strong>இஸ்ரவேலர்களுக்கு அல்லாஹ் செய்த அருட்கொடைகளை நினைவூட்டுதல்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">بَنِي</span> <span class=\"quran-arabic-font text-success\">إِسْرَائِيلَ</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">أَنجَيْنَاكُم</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">عَدُوِّكُمْ</span> <span class=\"quran-arabic-font text-success\">وَوَاعَدْنَاكُمْ</span> <span class=\"quran-arabic-font text-success\">جَانِبَ</span> <span class=\"quran-arabic-font text-success\">الطُّورِ</span> <span class=\"quran-arabic-font text-success\">الأَيْمَنَ</span> <span class=\"quran-arabic-font text-success\">وَنَزَّلْنَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمُ</span> <span class=\"quran-arabic-font text-success\">الْمَنَّ</span> <span class=\"quran-arabic-font text-success\">وَالسَّلْوَى</span><br />\r\n<br />\r\n(இஸ்ரவேலர்களே! நிச்சயமாக நாம் உங்களை உங்கள் எதிரியிடமிருந்து பாதுகாத்தோம்; மேலும் (சினாய்) மலையின் வலது புறத்தில் உங்களுக்கு வாக்களித்தோம்; இன்னும் உங்கள் மீது 'மன்னா' மற்றும் 'சல்வா'வை இறக்கி வைத்தோம்.) <a href=\"qurandisp.php?sura=20&ayah=80\" class=\"link\">20:80</a><br />\r\n<br />\r\nஅல்லாஹ், இஸ்ரவேலர்களுக்கு தான் செய்த மகத்தான அருட்கொடைகளையும், எண்ணற்ற அருள்பாக்கியங்களையும் நினைவூட்டுகிறான். அவர்களின் எதிரியான ஃபிர்அவ்னிடமிருந்து அவர்களை அவன் காப்பாற்றினான். மேலும், அவர்கள் பார்த்துக் கொண்டிருக்கும் போதே ஃபிர்அவ்னையும் அவனது படைகளையும் ஒரே நேரத்தில் மூழ்கடித்து, அவர்களின் கண்களைக் குளிரச் செய்தான். அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَغْرَقْنَا</span> <span class=\"quran-arabic-font text-success\">ءَالَ</span> <span class=\"quran-arabic-font text-success\">فِرْعَوْنَ</span> <span class=\"quran-arabic-font text-success\">وَأَنتُمْ</span> <span class=\"quran-arabic-font text-success\">تَنظُرُونَ</span><br />\r\n<br />\r\n(நீங்கள் பார்த்துக் கொண்டிருக்கும் போதே ஃபிர்அவ்னின் கூட்டத்தாரை நாம் மூழ்கடித்தோம்.) <a href=\"qurandisp.php?sura=2&ayah=50\" class=\"link\">2:50</a>. இப்னு அப்பாஸ் (ரழி) அவர்கள் அறிவித்ததாக இமாம் புகாரி அவர்கள் பதிவு செய்துள்ளார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மதீனாவிற்கு வந்தபோது, யூதர்கள் ஆஷூரா நாளில் நோன்பு நோற்பதைக் கண்டார்கள். எனவே, அவர்கள் அதைப் பற்றி அவர்களிடம் கேட்டார்கள். அதற்கு அவர்கள், 'இது அல்லாஹ், மூஸா (அலை) அவர்களுக்கு ஃபிர்அவ்னுக்கு எதிராக வெற்றி அளித்த நாள்' என்று கூறினார்கள்.\" அப்போது நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">نَحْنُ</span> <span class=\"quran-arabic-font text-success\">أَوْلَى</span> <span class=\"quran-arabic-font text-success\">بِمُوسَى</span> <span class=\"quran-arabic-font text-success\">مِنْكُمْ</span> <span class=\"quran-arabic-font text-success\">فَصُومُوه</span>»<br />\r\n<br />\r\n((அவர்களை விட) மூஸா (அலை) அவர்களுக்கு நாம் தான் அதிக உரிமை உடையவர்கள், எனவே நீங்கள் நோன்பு நோற்பீர்களாக.) இமாம் முஸ்லிம் அவர்களும் இந்த அறிவிப்பைத் தனது ஸஹீஹ் நூலில் பதிவு செய்துள்ளார்கள்.<br />\r\n<br />\r\nபின்னர், ஃபிர்அவ்னின் அழிவிற்குப் பிறகு, மலையின் வலது பக்கத்தில் மூஸா (அலை) அவர்களுடனும் இஸ்ரவேலர்களுடனும் அல்லாஹ் ஒரு உடன்படிக்கையை மேற்கொண்டான். இந்த மலையில் தான் அல்லாஹ் மூஸா (அலை) அவர்களுடன் பேசினான். மேலும், மூஸா (அலை) அவர்களின் மக்கள் அல்லாஹ்வைக் காண வேண்டுகோள் விடுத்தபோது, இந்த மலையைப் பார்க்கும்படி அவன் கூறினான். இதே மலையில் தான் மூஸா (அலை) அவர்களுக்கு தவ்ராத் வழங்கப்பட்டது; அதே சமயம் இஸ்ரவேலர்கள் கன்றுக்குட்டி (சிலை)யை வணங்கத் தொடங்கினர். இதனைப் பற்றி அல்லாஹ் வரவிருக்கும் வசனங்களில் கூறுகிறான். 'மன்னா' மற்றும் 'சல்வா' பற்றி ஏற்கனவே ஸூரா அல்-பகரா மற்றும் பிற அத்தியாயங்களில் விளக்கப்பட்டுள்ளது. 'மன்னா' என்பது வானத்திலிருந்து அவர்கள் மீது இறங்கிய ஒரு இனிமையான பொருளாகும். 'சல்வா' என்பது அவர்கள் மீது இறங்கிய ஒரு வகை பறவையாகும் (காடை). அடுத்த நாள் வரை தங்களுக்குத் தேவையான போதுமான உணவாக, அவர்கள் ஒவ்வொரு பாத்திரத்தையும் அவற்றால் நிரப்பிக் கொள்வார்கள். இது அவர்கள் மீது அல்லாஹ் காட்டிய கருணையும் கிருபையும் ஆகும். இது அல்லாஹ் அவர்களை கண்ணியமாக நடத்தியதன் வெளிப்பாடாக இருந்தது. இதன் காரணமாகவே அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كُلُوا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">طَيِّبَاتِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">رَزَقْنَاكُمْ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَطْغَوْاْ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">فَيَحِلَّ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">غَضَبِى</span><br />\r\n<br />\r\n(நாம் உங்களுக்கு வழங்கிய தூய்மையானவற்றிலிருந்து உண்ணுங்கள். அதில் வரம்பு மீறாதீர்கள். (அவ்வாறு மீறினால்) என் கோபம் உங்கள் மீது இறங்கிவிடும்.) இதன் பொருள், \"நான் உங்களுக்கு வழங்கிய இந்த வாழ்வாதாரத்திலிருந்து உண்ணுங்கள், அவசியமின்றி அதனை எடுத்துக் கொள்வதன் மூலம் எனது வாழ்வாதாரத்தில் வரம்பு மீறாதீர்கள்; அவ்வாறு செய்தால் நான் உங்களுக்குக் கட்டளையிட்டதற்கு நீங்கள் மாறு செய்தவர்களாவீர்கள்\" என்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَيَحِلَّ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">غَضَبِى</span><br />\r\n<br />\r\n(என் கோபம் உங்கள் மீது இறங்கிவிடும்.) இதன் பொருள், \"நான் உங்கள் மீது கோபம் கொள்வேன்\" என்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">يَحْلِلْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">غَضَبِى</span> <span class=\"quran-arabic-font text-success\">فَقَدْ</span> <span class=\"quran-arabic-font text-success\">هَوَى</span><br />\r\n<br />\r\n(மேலும் எவன் மீது என் கோபம் இறங்குகிறதோ, அவன் நிச்சயமாக அழிந்துவிட்டான்.) அலி இப்னு அபீ தல்ஹா (ரழி) அவர்கள், இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்: \"இதன் பொருள், அவன் நிச்சயமாகத் துரதிர்ஷ்டசாலியாக ஆக்கப்படுவான் என்பதாகும்.\"<br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்றைப் பொறுத்தவரை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِنِّى</span> <span class=\"quran-arabic-font text-success\">لَغَفَّارٌ</span> <span class=\"quran-arabic-font text-success\">لِّمَن</span> <span class=\"quran-arabic-font text-success\">تَابَ</span> <span class=\"quran-arabic-font text-success\">وَآمَنَ</span> <span class=\"quran-arabic-font text-success\">وَعَمِلَ</span> <span class=\"quran-arabic-font text-success\">صَالِحًا</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">اهْتَدَى</span><br />\r\n<br />\r\n(நிச்சயமாக, எவர் தவ்பா செய்து, ஈமான் கொண்டு, நல்லறங்களைச் செய்து, பின்னர் நேர்வழி பெறுகிறாரோ அவரை நான் பெரிதும் மன்னிப்பவனாக இருக்கிறேன்.) இதன் பொருள், \"எவர் என்னிடம் பாவமன்னிப்புத் தேடி (தவ்பா செய்து) மீளுகிறாரோ, அவர் எத்தகைய பாவம் செய்திருந்தாலும் அவரது தவ்பாவை நான் ஏற்றுக்கொள்வேன்\" என்பதாகும். உயர்ந்தோன் அல்லாஹ், கன்றுக்குட்டியை வணங்கிய இஸ்ரவேலர்களின் தவ்பாவைக்கூட ஏற்றுக்கொண்டான்.<br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்றைப் பொறுத்தவரை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">تَابَ</span><br />\r\n<br />\r\n(தவ்பா செய்தவர்,) இதன் பொருள், ஒருவன் தான் ஈடுபட்டிருந்த இறைநிராகரிப்பு (குஃப்ர்), அல்லாஹ்வுக்கு இணைவைத்தல் (ஷிர்க்), அவனுக்கு மாறு செய்தல் அல்லது நயவஞ்சகம் ஆகியவற்றிலிருந்து விலகி மீள்வதைக் குறிக்கும்.<br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்றைப் பொறுத்தவரை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَآمَنَ</span><br />\r\n<br />\r\n(மேலும் ஈமான் கொள்கிறார்) இதன் பொருள், ஒரு நபரின் உள்ளத்தில் இருக்கும் நம்பிக்கையாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَعَمِلَ</span> <span class=\"quran-arabic-font text-success\">صَالِحًا</span><br />\r\n<br />\r\n(மேலும் நல்லறங்களைச் செய்கிறார்,) அதாவது, தனது உடல் உறுப்புகளால் நற்செயல்களைச் செய்தல்.<br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்றைப் பொறுத்தவரை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">اهْتَدَى</span><br />\r\n<br />\r\n(பின்னர் நேர்வழி பெறுகிறார்.) அலி இப்னு அபீ தல்ஹா (ரழி) அவர்கள், இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்: \"இதன் பொருள், அதன் பிறகு அவர் சந்தேகம் கொள்வதில்லை என்பதாகும்.\" கதாதா அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">اهْتَدَى</span><br />\r\n<br />\r\n(பின்னர் நேர்வழி பெறுகிறார்.) \"இதன் பொருள், அவர் மரணிக்கும் வரை இஸ்லாத்தில் உறுதியாக நிலைத்திருப்பார் என்பதாகும்.\" சயீத் இப்னு ஜுபைர் (ரஹ்) அவர்கள் கூறினார்கள்: \"இதன் பொருள், அவர் சுன்னத் மற்றும் ஜமாஅத் கொள்கையில் நிலைத்திருப்பார் என்பதாகும்.\" இங்கே இந்த விஷயங்கள் ஒரு குறிப்பிட்ட வரிசையில் வழங்கப்பட்டிருப்பதை நாம் காண்கிறோம். இது அல்லாஹ்வின் இந்த வாசகத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">وَتَوَاصَوْاْ</span> <span class=\"quran-arabic-font text-success\">بِالصَّبْرِ</span> <span class=\"quran-arabic-font text-success\">وَتَوَاصَوْاْ</span> <span class=\"quran-arabic-font text-success\">بِالْمَرْحَمَةِ</span><br />\r\n<br />\r\n(பின்னர் அவர் ஈமான் கொண்டவர்களில் ஒருவராகி, பொறுமையையும் சகிப்புத்தன்மையையும் ஒருவருக்கொருவர் உபதேசித்து, கருணையையும் இரக்கத்தையும் ஒருவருக்கொருவர் அறிவுறுத்திக் கொண்டிருப்பார்.) <a href=\"qurandisp.php?sura=90&ayah=17\" class=\"link\">90:17</a><br />\r\n<br />","text":"இஸ்ரவேலர்களுக்கு அல்லாஹ் செய்த அருட்கொடைகளை நினைவூட்டுதல்\n\r\n\n\r\nيَا بَنِي إِسْرَائِيلَ قَدْ أَنجَيْنَاكُم مِّنْ عَدُوِّكُمْ وَوَاعَدْنَاكُمْ جَانِبَ الطُّورِ الأَيْمَنَ وَنَزَّلْنَا عَلَيْكُمُ الْمَنَّ وَالسَّلْوَى\n\r\n\n\r\n(இஸ்ரவேலர்களே! நிச்சயமாக நாம் உங்களை உங்கள் எதிரியிடமிருந்து பாதுகாத்தோம்; மேலும் (சினாய்) மலையின் வலது புறத்தில் உங்களுக்கு வாக்களித்தோம்; இன்னும் உங்கள் மீது 'மன்னா' மற்றும் 'சல்வா'வை இறக்கி வைத்தோம்.) 20:80\n\r\n\n\r\nஅல்லாஹ், இஸ்ரவேலர்களுக்கு தான் செய்த மகத்தான அருட்கொடைகளையும், எண்ணற்ற அருள்பாக்கியங்களையும் நினைவூட்டுகிறான். அவர்களின் எதிரியான ஃபிர்அவ்னிடமிருந்து அவர்களை அவன் காப்பாற்றினான். மேலும், அவர்கள் பார்த்துக் கொண்டிருக்கும் போதே ஃபிர்அவ்னையும் அவனது படைகளையும் ஒரே நேரத்தில் மூழ்கடித்து, அவர்களின் கண்களைக் குளிரச் செய்தான். அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَأَغْرَقْنَا ءَالَ فِرْعَوْنَ وَأَنتُمْ تَنظُرُونَ\n\r\n\n\r\n(நீங்கள் பார்த்துக் கொண்டிருக்கும் போதே ஃபிர்அவ்னின் கூட்டத்தாரை நாம் மூழ்கடித்தோம்.) 2:50. இப்னு அப்பாஸ் (ரழி) அவர்கள் அறிவித்ததாக இமாம் புகாரி அவர்கள் பதிவு செய்துள்ளார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மதீனாவிற்கு வந்தபோது, யூதர்கள் ஆஷூரா நாளில் நோன்பு நோற்பதைக் கண்டார்கள். எனவே, அவர்கள் அதைப் பற்றி அவர்களிடம் கேட்டார்கள். அதற்கு அவர்கள், 'இது அல்லாஹ், மூஸா (அலை) அவர்களுக்கு ஃபிர்அவ்னுக்கு எதிராக வெற்றி அளித்த நாள்' என்று கூறினார்கள்.\" அப்போது நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«نَحْنُ أَوْلَى بِمُوسَى مِنْكُمْ فَصُومُوه»\n\r\n\n\r\n((அவர்களை விட) மூஸா (அலை) அவர்களுக்கு நாம் தான் அதிக உரிமை உடையவர்கள், எனவே நீங்கள் நோன்பு நோற்பீர்களாக.) இமாம் முஸ்லிம் அவர்களும் இந்த அறிவிப்பைத் தனது ஸஹீஹ் நூலில் பதிவு செய்துள்ளார்கள்.\n\r\n\n\r\nபின்னர், ஃபிர்அவ்னின் அழிவிற்குப் பிறகு, மலையின் வலது பக்கத்தில் மூஸா (அலை) அவர்களுடனும் இஸ்ரவேலர்களுடனும் அல்லாஹ் ஒரு உடன்படிக்கையை மேற்கொண்டான். இந்த மலையில் தான் அல்லாஹ் மூஸா (அலை) அவர்களுடன் பேசினான். மேலும், மூஸா (அலை) அவர்களின் மக்கள் அல்லாஹ்வைக் காண வேண்டுகோள் விடுத்தபோது, இந்த மலையைப் பார்க்கும்படி அவன் கூறினான். இதே மலையில் தான் மூஸா (அலை) அவர்களுக்கு தவ்ராத் வழங்கப்பட்டது; அதே சமயம் இஸ்ரவேலர்கள் கன்றுக்குட்டி (சிலை)யை வணங்கத் தொடங்கினர். இதனைப் பற்றி அல்லாஹ் வரவிருக்கும் வசனங்களில் கூறுகிறான். 'மன்னா' மற்றும் 'சல்வா' பற்றி ஏற்கனவே ஸூரா அல்-பகரா மற்றும் பிற அத்தியாயங்களில் விளக்கப்பட்டுள்ளது. 'மன்னா' என்பது வானத்திலிருந்து அவர்கள் மீது இறங்கிய ஒரு இனிமையான பொருளாகும். 'சல்வா' என்பது அவர்கள் மீது இறங்கிய ஒரு வகை பறவையாகும் (காடை). அடுத்த நாள் வரை தங்களுக்குத் தேவையான போதுமான உணவாக, அவர்கள் ஒவ்வொரு பாத்திரத்தையும் அவற்றால் நிரப்பிக் கொள்வார்கள். இது அவர்கள் மீது அல்லாஹ் காட்டிய கருணையும் கிருபையும் ஆகும். இது அல்லாஹ் அவர்களை கண்ணியமாக நடத்தியதன் வெளிப்பாடாக இருந்தது. இதன் காரணமாகவே அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nكُلُوا مِن طَيِّبَاتِ مَا رَزَقْنَاكُمْ وَلاَ تَطْغَوْاْ فِيهِ فَيَحِلَّ عَلَيْكُمْ غَضَبِى\n\r\n\n\r\n(நாம் உங்களுக்கு வழங்கிய தூய்மையானவற்றிலிருந்து உண்ணுங்கள். அதில் வரம்பு மீறாதீர்கள். (அவ்வாறு மீறினால்) என் கோபம் உங்கள் மீது இறங்கிவிடும்.) இதன் பொருள், \"நான் உங்களுக்கு வழங்கிய இந்த வாழ்வாதாரத்திலிருந்து உண்ணுங்கள், அவசியமின்றி அதனை எடுத்துக் கொள்வதன் மூலம் எனது வாழ்வாதாரத்தில் வரம்பு மீறாதீர்கள்; அவ்வாறு செய்தால் நான் உங்களுக்குக் கட்டளையிட்டதற்கு நீங்கள் மாறு செய்தவர்களாவீர்கள்\" என்பதாகும்.\n\r\n\n\r\nفَيَحِلَّ عَلَيْكُمْ غَضَبِى\n\r\n\n\r\n(என் கோபம் உங்கள் மீது இறங்கிவிடும்.) இதன் பொருள், \"நான் உங்கள் மீது கோபம் கொள்வேன்\" என்பதாகும்.\n\r\n\n\r\nوَمَن يَحْلِلْ عَلَيْهِ غَضَبِى فَقَدْ هَوَى\n\r\n\n\r\n(மேலும் எவன் மீது என் கோபம் இறங்குகிறதோ, அவன் நிச்சயமாக அழிந்துவிட்டான்.) அலி இப்னு அபீ தல்ஹா (ரழி) அவர்கள், இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்: \"இதன் பொருள், அவன் நிச்சயமாகத் துரதிர்ஷ்டசாலியாக ஆக்கப்படுவான் என்பதாகும்.\"\n\r\n\n\r\nஅல்லாஹ்வின் கூற்றைப் பொறுத்தவரை:\n\r\n\n\r\nوَإِنِّى لَغَفَّارٌ لِّمَن تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى\n\r\n\n\r\n(நிச்சயமாக, எவர் தவ்பா செய்து, ஈமான் கொண்டு, நல்லறங்களைச் செய்து, பின்னர் நேர்வழி பெறுகிறாரோ அவரை நான் பெரிதும் மன்னிப்பவனாக இருக்கிறேன்.) இதன் பொருள், \"எவர் என்னிடம் பாவமன்னிப்புத் தேடி (தவ்பா செய்து) மீளுகிறாரோ, அவர் எத்தகைய பாவம் செய்திருந்தாலும் அவரது தவ்பாவை நான் ஏற்றுக்கொள்வேன்\" என்பதாகும். உயர்ந்தோன் அல்லாஹ், கன்றுக்குட்டியை வணங்கிய இஸ்ரவேலர்களின் தவ்பாவைக்கூட ஏற்றுக்கொண்டான்.\n\r\n\n\r\nஅல்லாஹ்வின் கூற்றைப் பொறுத்தவரை:\n\r\n\n\r\nتَابَ\n\r\n\n\r\n(தவ்பா செய்தவர்,) இதன் பொருள், ஒருவன் தான் ஈடுபட்டிருந்த இறைநிராகரிப்பு (குஃப்ர்), அல்லாஹ்வுக்கு இணைவைத்தல் (ஷிர்க்), அவனுக்கு மாறு செய்தல் அல்லது நயவஞ்சகம் ஆகியவற்றிலிருந்து விலகி மீள்வதைக் குறிக்கும்.\n\r\n\n\r\nஅல்லாஹ்வின் கூற்றைப் பொறுத்தவரை:\n\r\n\n\r\nوَآمَنَ\n\r\n\n\r\n(மேலும் ஈமான் கொள்கிறார்) இதன் பொருள், ஒரு நபரின் உள்ளத்தில் இருக்கும் நம்பிக்கையாகும்.\n\r\n\n\r\nوَعَمِلَ صَالِحًا\n\r\n\n\r\n(மேலும் நல்லறங்களைச் செய்கிறார்,) அதாவது, தனது உடல் உறுப்புகளால் நற்செயல்களைச் செய்தல்.\n\r\n\n\r\nஅல்லாஹ்வின் கூற்றைப் பொறுத்தவரை:\n\r\n\n\r\nثُمَّ اهْتَدَى\n\r\n\n\r\n(பின்னர் நேர்வழி பெறுகிறார்.) அலி இப்னு அபீ தல்ஹா (ரழி) அவர்கள், இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்: \"இதன் பொருள், அதன் பிறகு அவர் சந்தேகம் கொள்வதில்லை என்பதாகும்.\" கதாதா அவர்கள் கூறினார்கள்:\n\r\n\n\r\nثُمَّ اهْتَدَى\n\r\n\n\r\n(பின்னர் நேர்வழி பெறுகிறார்.) \"இதன் பொருள், அவர் மரணிக்கும் வரை இஸ்லாத்தில் உறுதியாக நிலைத்திருப்பார் என்பதாகும்.\" சயீத் இப்னு ஜுபைர் (ரஹ்) அவர்கள் கூறினார்கள்: \"இதன் பொருள், அவர் சுன்னத் மற்றும் ஜமாஅத் கொள்கையில் நிலைத்திருப்பார் என்பதாகும்.\" இங்கே இந்த விஷயங்கள் ஒரு குறிப்பிட்ட வரிசையில் வழங்கப்பட்டிருப்பதை நாம் காண்கிறோம். இது அல்லாஹ்வின் இந்த வாசகத்தைப் போன்றது:\n\r\n\n\r\nثُمَّ كَانَ مِنَ الَّذِينَ ءَامَنُواْ وَتَوَاصَوْاْ بِالصَّبْرِ وَتَوَاصَوْاْ بِالْمَرْحَمَةِ\n\r\n\n\r\n(பின்னர் அவர் ஈமான் கொண்டவர்களில் ஒருவராகி, பொறுமையையும் சகிப்புத்தன்மையையும் ஒருவருக்கொருவர் உபதேசித்து, கருணையையும் இரக்கத்தையும் ஒருவருக்கொருவர் அறிவுறுத்திக் கொண்டிருப்பார்.) 90:17"},"83":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=89\" class=\"link\">20:89</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:89 ஐ பார்க்கவும்"},"84":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=89\" class=\"link\">20:89</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:89 ஐ பார்க்கவும்"},"85":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=89\" class=\"link\">20:89</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:89 ஐ பார்க்கவும்"},"86":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=89\" class=\"link\">20:89</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:89 ஐ பார்க்கவும்"},"87":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=89\" class=\"link\">20:89</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:89 ஐ பார்க்கவும்"},"88":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=89\" class=\"link\">20:89</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:89 ஐ பார்க்கவும்"},"89":{"html":"<strong>மூஸா (அலை) அவர்கள் அல்லாஹ்வுடனான சந்திப்பிற்குச் செல்வதும், இஸ்ரவேலர்கள் கன்றுக்குட்டியை வணங்கத் தொடங்குவதும்</strong><br />\r\n<br />\r\nஃபிர்அவ்ன் அழிக்கப்பட்ட பிறகு, மூஸா (அலை) அவர்கள் இஸ்ரவேலர்களுடன் பயணம் செய்தபோது நடந்தவற்றை அல்லாஹ் விவரிக்கிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأَتَوْاْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">قَوْمٍ</span> <span class=\"quran-arabic-font text-success\">يَعْكُفُونَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَصْنَامٍ</span> <span class=\"quran-arabic-font text-success\">لَّهُمْ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">يَمُوسَى</span> <span class=\"quran-arabic-font text-success\">اجْعَلْ</span> <span class=\"quran-arabic-font text-success\">لَّنَآ</span> <span class=\"quran-arabic-font text-success\">إِلَـهًا</span> <span class=\"quran-arabic-font text-success\">كَمَا</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">ءَالِهَةٌ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">إِنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">قَوْمٌ</span> <span class=\"quran-arabic-font text-success\">تَجْهَلُونَ</span><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">هَـؤُلآء</span> <span class=\"quran-arabic-font text-success\">مُتَبَّرٌ</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">وَبَـطِلٌ</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">يَعْمَلُونَ</span>-<br />\r\n<br />\r\n(மேலும் அவர்கள் சில சிலைகளை வழிபடுவதில் தங்களை அர்ப்பணித்திருந்த ஒரு கூட்டத்தினரைக் கடந்தனர். அவர்கள், \"மூஸாவே! இவர்களுக்குப் பல தெய்வங்கள் இருப்பதைப் போல எங்களுக்கும் ஒரு தெய்வத்தை உருவாக்குவீராக!\" என்றனர். அதற்கு அவர் (மூஸா), \"நிச்சயமாக நீங்கள் அறிவில்லாத ஒரு கூட்டத்தினர். நிச்சயமாக இவர்கள் எதில் ஈடுபட்டுள்ளார்களோ அது அழிக்கப்படக் கூடியது, அவர்கள் செய்தவை அனைத்தும் வீணானவை\" என்று கூறினார்.) <a href=\"qurandisp.php?sura=7&ayah=138\" class=\"link\">7:138</a>-139<br />\r\n<br />\r\nபிறகு, அல்லாஹ் மூஸா (அலை) அவர்களுக்கு முப்பது இரவுகளை வாக்களித்தான், பின்னர் அவற்றுடன் மேலும் பத்து இரவுகளைச் சேர்த்தான். இவ்வாறு மொத்தம் நாற்பது இரவுகள் ஆகின. அந்த உடன்படிக்கையின்படி அவர் அந்த நாட்களில் பகலிலும் இரவிலும் நோன்பு நோற்க வேண்டியிருந்தது. எனவே, மூஸா (அலை) அவர்கள் மலைக்குச் செல்ல விரைந்தார்கள்; தன் சகோதரர் ஹாரூன் (அலை) அவர்களை இஸ்ரவேலர்களுக்குப் பொறுப்பாளராக நியமித்தார்கள். இதையே அல்லாஹ் இவ்வாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَعْجَلَكَ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">قَومِكَ</span> <span class=\"quran-arabic-font text-success\">يمُوسَى</span><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">أُوْلآء</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَثَرِى</span><br />\r\n<br />\r\n(\"மூஸாவே! உம்முடைய மக்களை விட்டு நீர் இவ்வளவு விரைவாக வரக் காரணம் என்ன?\" என்று அல்லாஹ் கேட்டான். அதற்கு அவர், \"அவர்கள் இதோ எனது அடிச்சுவடுகளைப் பின்பற்றி (நெருங்கி) வந்து கொண்டிருக்கிறார்கள்\" என்றார்.) இதன் பொருள் அவர்கள் வந்து மலைக்கு அருகில் தங்கியிருக்கிறார்கள் என்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَعَجِلْتُ</span> <span class=\"quran-arabic-font text-success\">إِلَيْكَ</span> <span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">لِتَرْضَى</span><br />\r\n<br />\r\n(\"என் இறைவனே! நீ திருப்தியடைவதற்காகவே நான் உன்னிடம் விரைந்து வந்தேன்\" என்றார்.) அதாவது, \"இதனால் நீ என் மீது அதிகத் திருப்தி கொள்வாய்\" என்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّا</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">فَتَنَّا</span> <span class=\"quran-arabic-font text-success\">قَوْمَكَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَعْدِكَ</span> <span class=\"quran-arabic-font text-success\">وَأَضَلَّهُمُ</span> <span class=\"quran-arabic-font text-success\">السَّامِرِىُّ</span><br />\r\n<br />\r\n((அல்லாஹ்) கூறினான்: \"நிச்சயமாக, நீர் சென்ற பிறகு உமது மக்களை நாம் சோதித்தோம்; அஸ்-ஸாமிரீ அவர்களை வழிகெடுத்துவிட்டான்.\") மூஸா (அலை) அவர்கள் பிரிந்து சென்ற பிறகு இஸ்ரவேலர்களுக்கு என்ன நேர்ந்தது என்பதையும், அஸ்-ஸாமிரீ அவர்களுக்காகச் செய்த கன்றுக்குட்டியை அவர்கள் வணங்கத் தொடங்கியதையும் அல்லாஹ் தன் தூதர் மூஸா (அலை) அவர்களுக்குத் தெரிவிக்கிறான். இந்தக் காலப்பகுதியில்தான், தவ்ராத் வேதத்தைக் கொண்ட பலகைகளை (தகடுகளை) அல்லாஹ் மூஸா (அலை) அவர்களுக்காக எழுதினான். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكَتَبْنَا</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الاٌّلْوَاحِ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">مَّوْعِظَةً</span> <span class=\"quran-arabic-font text-success\">وَتَفْصِيلاً</span> <span class=\"quran-arabic-font text-success\">لِّكُلِّ</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">فَخُذْهَا</span> <span class=\"quran-arabic-font text-success\">بِقُوَّةٍ</span> <span class=\"quran-arabic-font text-success\">وَأْمُرْ</span> <span class=\"quran-arabic-font text-success\">قَوْمَكَ</span> <span class=\"quran-arabic-font text-success\">يَأْخُذُواْ</span> <span class=\"quran-arabic-font text-success\">بِأَحْسَنِهَا</span> <span class=\"quran-arabic-font text-success\">سَأُوْرِيكُمْ</span> <span class=\"quran-arabic-font text-success\">دَارَ</span> <span class=\"quran-arabic-font text-success\">الْفَـسِقِينَ</span><br />\r\n<br />\r\n(மேலும் நாம் அவருக்காக அந்தப் பலகைகளில் அனைத்து விஷயங்களைப் பற்றிய உபதேசங்களையும், ஒவ்வொரு விஷயத்தைப் பற்றிய விளக்கத்தையும் எழுதினோம். \"இவற்றை உறுதியாகப் பற்றிக்கொள்வீராக; உமது மக்களையும் இவற்றிலுள்ள மிகச் சிறந்தவற்றைப் பின்பற்றும்படி ஏவுவீராக. தீயவர்களின் (ஃபாஸிக்குகளின்) இருப்பிடத்தை நான் உங்களுக்கு விரைவில் காட்டுவேன்\" (என்றும் கூறினோம்).) <a href=\"qurandisp.php?sura=7&ayah=145\" class=\"link\">7:145</a> இதன் பொருள், \"எனது கட்டளைகளுக்கு அடிபணியாமல் மாறு செய்பவர்களுக்கு நேரும் இறுதி முடிவை நான் உமக்குக் காட்டுவேன்\" என்பதாகும். அல்லாஹ்வின் இக்கூற்றைப் பொறுத்தவரை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَرَجَعَ</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">قَوْمِهِ</span> <span class=\"quran-arabic-font text-success\">غَضْبَـنَ</span> <span class=\"quran-arabic-font text-success\">أَسِفاً</span><br />\r\n<br />\r\n(பின்னர் மூஸா (அலை) அவர்கள் மிகுந்த கோபத்துடனும் கவலையுடனும் தம் மக்களிடம் திரும்பி வந்தார்கள்.) அவர்கள் செய்த காரியத்தை அல்லாஹ் அவருக்குத் தெரிவித்த பிறகு, அவர் அவர்கள் மீது கடும் கோபமும் வருத்தமும் கொண்டார்கள். அவர்களைப் பற்றி மிகுந்த கவலை கொண்டார்கள். இச்சமயத்தில் அவர் தவ்ராத் வேதத்தைப் பெற்றிருந்தார்கள்; அதில் அவர்களின் ஷரீஆ (சட்டம்) இருந்தது, இது அவர்களுக்குக் கிடைத்த பெரும் கௌரவமாகும். ஆனால் அவர்கள் அல்லாஹ் அல்லாதவற்றை வணங்கும் நிலையில் இருந்தார்கள். பகுத்தறிவும் சிந்தனையும் உள்ள எவருக்கும் அவர்கள் செய்தது தவறு என்பதும் முட்டாள்தனம் என்பதும் தெளிவாகத் தெரியும். இதனால்தான் அவர் கோபத்துடனும் கவலையுடனும் திரும்பியதாக அல்லாஹ் கூறுகிறான். இங்கு 'கவலை' என்பதைக் குறிக்க 'அஸிஃப்' (Asif) என்ற வார்த்தை பயன்படுத்தப்பட்டுள்ளது, இது அவரது கோபத்தின் தீவிரத்தை உணர்த்துகிறது. முஜாஹித் அவர்கள், \"கோபத்துடனும் கவலையுடனும் என்றால் கவலையடைந்த நிலையில் என்று பொருள்\" என்றார்கள். கதாதா மற்றும் அஸ்-ஸுத்தீ ஆகியோர், \"அவருக்குப் பிறகு அவருடைய மக்கள் செய்த காரியத்தால் ஏற்பட்ட சோகமான நிலையையே அஸிஃப் குறிக்கிறது\" என்றார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">يَقَوْمِ</span> <span class=\"quran-arabic-font text-success\">أَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَعِدْكُمْ</span> <span class=\"quran-arabic-font text-success\">رَبُّكُمْ</span> <span class=\"quran-arabic-font text-success\">وَعْداً</span> <span class=\"quran-arabic-font text-success\">حَسَناً</span><br />\r\n<br />\r\n(அவர் (மூஸா) கூறினார்: \"எனது மக்களே! உங்கள் இறைவன் உங்களுக்கு ஒரு நல்ல வாக்குறுதியை அளிக்கவில்லையா?\") அதாவது, \"இவ்வுலகிலும் மறுமையிலும் உள்ள ஒவ்வொரு நன்மையையும், நற்பேறுகளையும் நான் உங்களுக்குக் கூறியவற்றின் மூலம் அவன் வாக்களிக்கவில்லையா? உங்கள் எதிரியான ஃபிர்அவ்னைத் தோற்கடிக்க அவன் உங்களுக்கு உதவியதையும், உங்களுக்கு வெற்றியைத் தந்து பல்வேறு அருட்கொடைகளை வழங்கியதையும் நீங்கள் ஏற்கனவே பார்த்துள்ளீர்கள்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَفَطَالَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمُ</span> <span class=\"quran-arabic-font text-success\">الْعَهْدُ</span><br />\r\n<br />\r\n(உங்களுக்கு அந்த வாக்குறுதி (நிறைவேறக் காலம்) நீண்டதாகத் தோன்றியதா?) அதாவது, 'அல்லாஹ் வாக்களித்ததைக் காண்பதற்காகக் காத்திருப்பதில் சலிப்படைந்து, அவனது முந்தைய அருட்கொடைகளையும் உங்களுக்கு வழங்கப்பட்ட உடன்படிக்கையையும் மறந்துவிட்டீர்களா?'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">أَرَدتُّمْ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَحِلَّ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">غَضَبٌ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">رَّبِّكُمْ</span> <span class=\"quran-arabic-font text-success\">فَأَخْلَفْتُم</span> <span class=\"quran-arabic-font text-success\">مَّوْعِدِى</span><br />\r\n<br />\r\n(அல்லது உங்கள் இறைவனுடைய கோபம் உங்கள் மீது இறங்க வேண்டும் என்று நீங்கள் விரும்பினீர்களா?) இங்கு 'அல்லது' என்பது 'இல்லை, மாறாக' என்ற பொருளில் வருகிறது. இது முந்தைய கருத்தையும் பிந்தைய கருத்தையும் பிரிக்கப் பயன்படுகிறது. அதாவது, \"இல்லை, மாறாக நீங்கள் செய்த காரியத்தின் மூலம் உங்கள் இறைவனின் கோபத்தை உங்கள் மீது ஆகுமாக்கிக் கொள்ளவே விரும்பினீர்கள்; அதனால் எனக்கு அளித்த வாக்குறுதியை நீங்கள் மீறிவிட்டீர்கள்\" என்று பொருள். மூஸா (அலை) அவர்களின் கண்டனத்திற்கு இஸ்ரவேலர்கள் பதிலளித்தனர்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أَخْلَفْنَا</span> <span class=\"quran-arabic-font text-success\">مَوْعِدَكَ</span> <span class=\"quran-arabic-font text-success\">بِمَلْكِنَا</span><br />\r\n<br />\r\n(அதற்கு அவர்கள், \"நாங்கள் எங்கள் சுயமாக உம்மிடம் அளித்த வாக்குறுதியை மீறவில்லை\" என்றார்கள்.) அதாவது, \"எங்கள் சக்தியாலோ அல்லது விருப்பத்தாலோ நாங்கள் அதைச் செய்யவில்லை\" என்றார்கள். <span class=\"quran-arabic-font text-success\">وَلَكِنَّا</span> <span class=\"quran-arabic-font text-success\">حُمِّلْنَا</span> <span class=\"quran-arabic-font text-success\">أَوْزَاراً</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">زِينَةِ</span> <span class=\"quran-arabic-font text-success\">الْقَوْمِ</span> <span class=\"quran-arabic-font text-success\">فَقَذَفْنَاهَا</span> (ஆனால் நாங்கள் கூட்டத்தினரின் (எகிப்தியரின்) அலங்காரப் பொருட்களிலிருந்து சுமைகளைச் சுமக்கச் செய்யப்பட்டோம்; எனவே அவற்றை நாங்கள் (நெருப்பில்) எறிந்தோம்.) பிறகு அவர்கள் நொண்டிச் சாக்குகளைக் கூறத் தொடங்கினார்கள். எகிப்தை விட்டு வெளியேறும்போது காப்டிக் (கிப்தி) இனத்தவரிடம் கடன் வாங்கியிருந்த தங்க நகைகளை எவ்வாறு அகற்றியதாகக் கூறினார்கள். அவர்கள் அவற்றை (நெருப்பில்) எறிந்தார்கள். அதிலிருந்து ஒரு கன்றுக்குட்டி உருவானது, அது மா என்ற சத்தத்தை எழுப்பியது. இந்தக் கன்றுக்குட்டி அவர்களுக்கு ஒரு சோதனையாகவும் தடையாகவும் அமைந்தது. இதையே அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَكَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">أَلْقَى</span> <span class=\"quran-arabic-font text-success\">السَّامِرِىُّ</span> <span class=\"quran-arabic-font text-success\">فَأَخْرَجَ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">عِجْلاً</span> <span class=\"quran-arabic-font text-success\">جَسَداً</span> <span class=\"quran-arabic-font text-success\">لَّهُ</span> <span class=\"quran-arabic-font text-success\">خُوَارٌ</span><br />\r\n<br />\r\n(\"...அவ்வாறே அஸ்-ஸாமிரீயும் எறிந்தான்.\" பிறகு அவன் அவர்களுக்காக மா என்று சத்தமிடும் ஒரு கன்றுக்குட்டியின் உடலை (சிலையை) வெளிப்படுத்தினான்.) முஹம்மது பின் இஸ்ஹாக் அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَقَالُوا</span> <span class=\"quran-arabic-font text-success\">هَـذَآ</span> <span class=\"quran-arabic-font text-success\">إِلَـهُكُمْ</span> <span class=\"quran-arabic-font text-success\">وَإِلَـهُ</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span><br />\r\n<br />\r\n(\"இதுவே உங்கள் கடவுள், மூஸாவின் கடவுளும் இதுதான்\" என்றார்கள்.) \"அவர்கள் அக்கணமே அந்தக் கன்றுக்குட்டியின் மீது பக்தி கொண்டு, அதற்கு முன் எதன் மீதும் கொள்ளாத அளவு அன்பை அதன் மீது கொண்டார்கள்.\" அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَنَسِىَ</span><br />\r\n<br />\r\n(ஆனால் அவர் மறந்துவிட்டார்.) இதன் பொருள், அஸ்-ஸாமிரீ தான் பின்பற்றி வந்த இஸ்லாமிய மார்க்கத்தைக் கைவிட்டுவிட்டார் என்பதாகும். இவர்களின் அறியாமையையும் முட்டாள்தனத்தையும் விளக்கி, அவர்களைக் கண்டிக்கும் விதமாக அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَفَلاَ</span> <span class=\"quran-arabic-font text-success\">يَرَوْنَ</span> <span class=\"quran-arabic-font text-success\">أَلاَّ</span> <span class=\"quran-arabic-font text-success\">يَرْجِعُ</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">قَوْلاً</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَمْلِكُ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">ضَرّاً</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">نَفْعاً</span><br />\r\n<br />\r\n(அது அவர்களுக்குப் பதில் சொல்லாது என்பதையும், அவர்களுக்கு எவ்விதத் தீங்கோ நன்மையோ செய்ய அதற்குச் சக்தியில்லை என்பதையும் அவர்கள் பார்க்க வேண்டாமா?) இது அந்தக் கன்றுக்குட்டியைப் பற்றியது. 'அவர்கள் அதனிடம் கேட்கும்போதோ பேசும்போதோ அது பதிலளிக்காது என்பதை அவர்கள் உணரவில்லையா?'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَمْلِكُ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">ضَرّاً</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">نَفْعاً</span><br />\r\n<br />\r\n(மேலும் அவர்களுக்குத் தீங்கு செய்யவும் அல்லது நன்மை செய்யவும் அதற்கு எந்த சக்தியும் இல்லை) அதாவது அவர்களின் உலக விவகாரங்களிலும் மறுமையிலும். இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"அல்லாஹ்வின் மீது சத்தியமாக! அந்தக் கன்றுக்குட்டியின் சத்தம் என்பது, அதன் பின்புறம் வழியாகக் காற்று உள்ளே புகுந்து வாய் வழியாக வெளியேறும்போது உண்டான சத்தமே தவிர வேறில்லை.\" ஹஸன் அல்-பஸரீ (ரஹ்) அவர்கள் வழியாகப் பதிவுசெய்யப்பட்ட அல்-ஃபிதன் என்ற ஹதீஸில், இந்தக் கன்றுக்குட்டியின் பெயர் 'பஹ்மூத்' என்று குறிப்பிடப்பட்டுள்ளது. இந்த அறியாமை மிக்க மக்கள், காப்டியர்களின் நகைகளைத் தூக்கி எறிந்ததாகக் கூறித் தங்களைக் காத்துக் கொள்ள முயன்றனர். ஆனால் அந்த நகைகளைத் தீயில் எறிந்து இறுதியில் கன்றுக்குட்டியை வணங்கத் தொடங்கினர். அவர்கள் ஒரு வெறுக்கத்தக்கக் காரியத்திலிருந்து விடுபட முயன்று, அதைவிடக் கொடிய பாவத்தைச் செய்துவிட்டனர். இது அப்துல்லாஹ் பின் உமர் (ரழி) அவர்களிடமிருந்து அறிவிக்கப்பட்ட ஒரு ஆதாரப்பூர்வமான செய்தியைப் போன்றது. ஈராக்கைச் சேர்ந்த ஒருவர், ஆடையில் கொசுவின் இரத்தம் பட்டுவிட்டால் அதன் சட்டம் என்ன என்று அவரிடம் கேட்டார். அந்த ஆடையில் தொழலாமா என்பதை அவர் அறிய விரும்பினார். அதற்கு இப்னு உமர் (ரழி) அவர்கள், \"ஈராக் மக்களைப் பாருங்கள்! இவர்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் பேரர் அல்-ஹுஸைன் (ரழி) அவர்களைக் கொலை செய்தார்கள்; ஆனால் இப்போது கொசுவின் இரத்தத்தைப் பற்றி (சட்டம்) கேட்கிறார்கள்!\" என்று பதிலளித்தார்கள்.<br />\r\n<br />","text":"மூஸா (அலை) அவர்கள் அல்லாஹ்வுடனான சந்திப்பிற்குச் செல்வதும், இஸ்ரவேலர்கள் கன்றுக்குட்டியை வணங்கத் தொடங்குவதும்\n\r\n\n\r\nஃபிர்அவ்ன் அழிக்கப்பட்ட பிறகு, மூஸா (அலை) அவர்கள் இஸ்ரவேலர்களுடன் பயணம் செய்தபோது நடந்தவற்றை அல்லாஹ் விவரிக்கிறான்.\n\r\n\n\r\nفَأَتَوْاْ عَلَى قَوْمٍ يَعْكُفُونَ عَلَى أَصْنَامٍ لَّهُمْ قَالُواْ يَمُوسَى اجْعَلْ لَّنَآ إِلَـهًا كَمَا لَهُمْ ءَالِهَةٌ قَالَ إِنَّكُمْ قَوْمٌ تَجْهَلُونَ\n\r\n\n\r\nإِنَّ هَـؤُلآء مُتَبَّرٌ مَّا هُمْ فِيهِ وَبَـطِلٌ مَّا كَانُواْ يَعْمَلُونَ-\n\r\n\n\r\n(மேலும் அவர்கள் சில சிலைகளை வழிபடுவதில் தங்களை அர்ப்பணித்திருந்த ஒரு கூட்டத்தினரைக் கடந்தனர். அவர்கள், \"மூஸாவே! இவர்களுக்குப் பல தெய்வங்கள் இருப்பதைப் போல எங்களுக்கும் ஒரு தெய்வத்தை உருவாக்குவீராக!\" என்றனர். அதற்கு அவர் (மூஸா), \"நிச்சயமாக நீங்கள் அறிவில்லாத ஒரு கூட்டத்தினர். நிச்சயமாக இவர்கள் எதில் ஈடுபட்டுள்ளார்களோ அது அழிக்கப்படக் கூடியது, அவர்கள் செய்தவை அனைத்தும் வீணானவை\" என்று கூறினார்.) 7:138-139\n\r\n\n\r\nபிறகு, அல்லாஹ் மூஸா (அலை) அவர்களுக்கு முப்பது இரவுகளை வாக்களித்தான், பின்னர் அவற்றுடன் மேலும் பத்து இரவுகளைச் சேர்த்தான். இவ்வாறு மொத்தம் நாற்பது இரவுகள் ஆகின. அந்த உடன்படிக்கையின்படி அவர் அந்த நாட்களில் பகலிலும் இரவிலும் நோன்பு நோற்க வேண்டியிருந்தது. எனவே, மூஸா (அலை) அவர்கள் மலைக்குச் செல்ல விரைந்தார்கள்; தன் சகோதரர் ஹாரூன் (அலை) அவர்களை இஸ்ரவேலர்களுக்குப் பொறுப்பாளராக நியமித்தார்கள். இதையே அல்லாஹ் இவ்வாறு கூறுகிறான்:\n\r\n\n\r\nوَمَآ أَعْجَلَكَ عَن قَومِكَ يمُوسَى\n\r\n\n\r\nقَالَ هُمْ أُوْلآء عَلَى أَثَرِى\n\r\n\n\r\n(\"மூஸாவே! உம்முடைய மக்களை விட்டு நீர் இவ்வளவு விரைவாக வரக் காரணம் என்ன?\" என்று அல்லாஹ் கேட்டான். அதற்கு அவர், \"அவர்கள் இதோ எனது அடிச்சுவடுகளைப் பின்பற்றி (நெருங்கி) வந்து கொண்டிருக்கிறார்கள்\" என்றார்.) இதன் பொருள் அவர்கள் வந்து மலைக்கு அருகில் தங்கியிருக்கிறார்கள் என்பதாகும்.\n\r\n\n\r\nوَعَجِلْتُ إِلَيْكَ رَبِّ لِتَرْضَى\n\r\n\n\r\n(\"என் இறைவனே! நீ திருப்தியடைவதற்காகவே நான் உன்னிடம் விரைந்து வந்தேன்\" என்றார்.) அதாவது, \"இதனால் நீ என் மீது அதிகத் திருப்தி கொள்வாய்\" என்பதாகும்.\n\r\n\n\r\nقَالَ فَإِنَّا قَدْ فَتَنَّا قَوْمَكَ مِن بَعْدِكَ وَأَضَلَّهُمُ السَّامِرِىُّ\n\r\n\n\r\n((அல்லாஹ்) கூறினான்: \"நிச்சயமாக, நீர் சென்ற பிறகு உமது மக்களை நாம் சோதித்தோம்; அஸ்-ஸாமிரீ அவர்களை வழிகெடுத்துவிட்டான்.\") மூஸா (அலை) அவர்கள் பிரிந்து சென்ற பிறகு இஸ்ரவேலர்களுக்கு என்ன நேர்ந்தது என்பதையும், அஸ்-ஸாமிரீ அவர்களுக்காகச் செய்த கன்றுக்குட்டியை அவர்கள் வணங்கத் தொடங்கியதையும் அல்லாஹ் தன் தூதர் மூஸா (அலை) அவர்களுக்குத் தெரிவிக்கிறான். இந்தக் காலப்பகுதியில்தான், தவ்ராத் வேதத்தைக் கொண்ட பலகைகளை (தகடுகளை) அல்லாஹ் மூஸா (அலை) அவர்களுக்காக எழுதினான். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَكَتَبْنَا لَهُ فِى الاٌّلْوَاحِ مِن كُلِّ شَىْءٍ مَّوْعِظَةً وَتَفْصِيلاً لِّكُلِّ شَىْءٍ فَخُذْهَا بِقُوَّةٍ وَأْمُرْ قَوْمَكَ يَأْخُذُواْ بِأَحْسَنِهَا سَأُوْرِيكُمْ دَارَ الْفَـسِقِينَ\n\r\n\n\r\n(மேலும் நாம் அவருக்காக அந்தப் பலகைகளில் அனைத்து விஷயங்களைப் பற்றிய உபதேசங்களையும், ஒவ்வொரு விஷயத்தைப் பற்றிய விளக்கத்தையும் எழுதினோம். \"இவற்றை உறுதியாகப் பற்றிக்கொள்வீராக; உமது மக்களையும் இவற்றிலுள்ள மிகச் சிறந்தவற்றைப் பின்பற்றும்படி ஏவுவீராக. தீயவர்களின் (ஃபாஸிக்குகளின்) இருப்பிடத்தை நான் உங்களுக்கு விரைவில் காட்டுவேன்\" (என்றும் கூறினோம்).) 7:145 இதன் பொருள், \"எனது கட்டளைகளுக்கு அடிபணியாமல் மாறு செய்பவர்களுக்கு நேரும் இறுதி முடிவை நான் உமக்குக் காட்டுவேன்\" என்பதாகும். அல்லாஹ்வின் இக்கூற்றைப் பொறுத்தவரை:\n\r\n\n\r\nفَرَجَعَ مُوسَى إِلَى قَوْمِهِ غَضْبَـنَ أَسِفاً\n\r\n\n\r\n(பின்னர் மூஸா (அலை) அவர்கள் மிகுந்த கோபத்துடனும் கவலையுடனும் தம் மக்களிடம் திரும்பி வந்தார்கள்.) அவர்கள் செய்த காரியத்தை அல்லாஹ் அவருக்குத் தெரிவித்த பிறகு, அவர் அவர்கள் மீது கடும் கோபமும் வருத்தமும் கொண்டார்கள். அவர்களைப் பற்றி மிகுந்த கவலை கொண்டார்கள். இச்சமயத்தில் அவர் தவ்ராத் வேதத்தைப் பெற்றிருந்தார்கள்; அதில் அவர்களின் ஷரீஆ (சட்டம்) இருந்தது, இது அவர்களுக்குக் கிடைத்த பெரும் கௌரவமாகும். ஆனால் அவர்கள் அல்லாஹ் அல்லாதவற்றை வணங்கும் நிலையில் இருந்தார்கள். பகுத்தறிவும் சிந்தனையும் உள்ள எவருக்கும் அவர்கள் செய்தது தவறு என்பதும் முட்டாள்தனம் என்பதும் தெளிவாகத் தெரியும். இதனால்தான் அவர் கோபத்துடனும் கவலையுடனும் திரும்பியதாக அல்லாஹ் கூறுகிறான். இங்கு 'கவலை' என்பதைக் குறிக்க 'அஸிஃப்' (Asif) என்ற வார்த்தை பயன்படுத்தப்பட்டுள்ளது, இது அவரது கோபத்தின் தீவிரத்தை உணர்த்துகிறது. முஜாஹித் அவர்கள், \"கோபத்துடனும் கவலையுடனும் என்றால் கவலையடைந்த நிலையில் என்று பொருள்\" என்றார்கள். கதாதா மற்றும் அஸ்-ஸுத்தீ ஆகியோர், \"அவருக்குப் பிறகு அவருடைய மக்கள் செய்த காரியத்தால் ஏற்பட்ட சோகமான நிலையையே அஸிஃப் குறிக்கிறது\" என்றார்கள்.\n\r\n\n\r\nقَالَ يَقَوْمِ أَلَمْ يَعِدْكُمْ رَبُّكُمْ وَعْداً حَسَناً\n\r\n\n\r\n(அவர் (மூஸா) கூறினார்: \"எனது மக்களே! உங்கள் இறைவன் உங்களுக்கு ஒரு நல்ல வாக்குறுதியை அளிக்கவில்லையா?\") அதாவது, \"இவ்வுலகிலும் மறுமையிலும் உள்ள ஒவ்வொரு நன்மையையும், நற்பேறுகளையும் நான் உங்களுக்குக் கூறியவற்றின் மூலம் அவன் வாக்களிக்கவில்லையா? உங்கள் எதிரியான ஃபிர்அவ்னைத் தோற்கடிக்க அவன் உங்களுக்கு உதவியதையும், உங்களுக்கு வெற்றியைத் தந்து பல்வேறு அருட்கொடைகளை வழங்கியதையும் நீங்கள் ஏற்கனவே பார்த்துள்ளீர்கள்.\"\n\r\n\n\r\nأَفَطَالَ عَلَيْكُمُ الْعَهْدُ\n\r\n\n\r\n(உங்களுக்கு அந்த வாக்குறுதி (நிறைவேறக் காலம்) நீண்டதாகத் தோன்றியதா?) அதாவது, 'அல்லாஹ் வாக்களித்ததைக் காண்பதற்காகக் காத்திருப்பதில் சலிப்படைந்து, அவனது முந்தைய அருட்கொடைகளையும் உங்களுக்கு வழங்கப்பட்ட உடன்படிக்கையையும் மறந்துவிட்டீர்களா?'\n\r\n\n\r\nأَمْ أَرَدتُّمْ أَن يَحِلَّ عَلَيْكُمْ غَضَبٌ مِّن رَّبِّكُمْ فَأَخْلَفْتُم مَّوْعِدِى\n\r\n\n\r\n(அல்லது உங்கள் இறைவனுடைய கோபம் உங்கள் மீது இறங்க வேண்டும் என்று நீங்கள் விரும்பினீர்களா?) இங்கு 'அல்லது' என்பது 'இல்லை, மாறாக' என்ற பொருளில் வருகிறது. இது முந்தைய கருத்தையும் பிந்தைய கருத்தையும் பிரிக்கப் பயன்படுகிறது. அதாவது, \"இல்லை, மாறாக நீங்கள் செய்த காரியத்தின் மூலம் உங்கள் இறைவனின் கோபத்தை உங்கள் மீது ஆகுமாக்கிக் கொள்ளவே விரும்பினீர்கள்; அதனால் எனக்கு அளித்த வாக்குறுதியை நீங்கள் மீறிவிட்டீர்கள்\" என்று பொருள். மூஸா (அலை) அவர்களின் கண்டனத்திற்கு இஸ்ரவேலர்கள் பதிலளித்தனர்:\n\r\n\n\r\nقَالُواْ مَآ أَخْلَفْنَا مَوْعِدَكَ بِمَلْكِنَا\n\r\n\n\r\n(அதற்கு அவர்கள், \"நாங்கள் எங்கள் சுயமாக உம்மிடம் அளித்த வாக்குறுதியை மீறவில்லை\" என்றார்கள்.) அதாவது, \"எங்கள் சக்தியாலோ அல்லது விருப்பத்தாலோ நாங்கள் அதைச் செய்யவில்லை\" என்றார்கள். وَلَكِنَّا حُمِّلْنَا أَوْزَاراً مِّن زِينَةِ الْقَوْمِ فَقَذَفْنَاهَا (ஆனால் நாங்கள் கூட்டத்தினரின் (எகிப்தியரின்) அலங்காரப் பொருட்களிலிருந்து சுமைகளைச் சுமக்கச் செய்யப்பட்டோம்; எனவே அவற்றை நாங்கள் (நெருப்பில்) எறிந்தோம்.) பிறகு அவர்கள் நொண்டிச் சாக்குகளைக் கூறத் தொடங்கினார்கள். எகிப்தை விட்டு வெளியேறும்போது காப்டிக் (கிப்தி) இனத்தவரிடம் கடன் வாங்கியிருந்த தங்க நகைகளை எவ்வாறு அகற்றியதாகக் கூறினார்கள். அவர்கள் அவற்றை (நெருப்பில்) எறிந்தார்கள். அதிலிருந்து ஒரு கன்றுக்குட்டி உருவானது, அது மா என்ற சத்தத்தை எழுப்பியது. இந்தக் கன்றுக்குட்டி அவர்களுக்கு ஒரு சோதனையாகவும் தடையாகவும் அமைந்தது. இதையே அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nفَكَذَلِكَ أَلْقَى السَّامِرِىُّ فَأَخْرَجَ لَهُمْ عِجْلاً جَسَداً لَّهُ خُوَارٌ\n\r\n\n\r\n(\"...அவ்வாறே அஸ்-ஸாமிரீயும் எறிந்தான்.\" பிறகு அவன் அவர்களுக்காக மா என்று சத்தமிடும் ஒரு கன்றுக்குட்டியின் உடலை (சிலையை) வெளிப்படுத்தினான்.) முஹம்மது பின் இஸ்ஹாக் அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்:\n\r\n\n\r\nفَقَالُوا هَـذَآ إِلَـهُكُمْ وَإِلَـهُ مُوسَى\n\r\n\n\r\n(\"இதுவே உங்கள் கடவுள், மூஸாவின் கடவுளும் இதுதான்\" என்றார்கள்.) \"அவர்கள் அக்கணமே அந்தக் கன்றுக்குட்டியின் மீது பக்தி கொண்டு, அதற்கு முன் எதன் மீதும் கொள்ளாத அளவு அன்பை அதன் மீது கொண்டார்கள்.\" அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nفَنَسِىَ\n\r\n\n\r\n(ஆனால் அவர் மறந்துவிட்டார்.) இதன் பொருள், அஸ்-ஸாமிரீ தான் பின்பற்றி வந்த இஸ்லாமிய மார்க்கத்தைக் கைவிட்டுவிட்டார் என்பதாகும். இவர்களின் அறியாமையையும் முட்டாள்தனத்தையும் விளக்கி, அவர்களைக் கண்டிக்கும் விதமாக அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nأَفَلاَ يَرَوْنَ أَلاَّ يَرْجِعُ إِلَيْهِمْ قَوْلاً وَلاَ يَمْلِكُ لَهُمْ ضَرّاً وَلاَ نَفْعاً\n\r\n\n\r\n(அது அவர்களுக்குப் பதில் சொல்லாது என்பதையும், அவர்களுக்கு எவ்விதத் தீங்கோ நன்மையோ செய்ய அதற்குச் சக்தியில்லை என்பதையும் அவர்கள் பார்க்க வேண்டாமா?) இது அந்தக் கன்றுக்குட்டியைப் பற்றியது. 'அவர்கள் அதனிடம் கேட்கும்போதோ பேசும்போதோ அது பதிலளிக்காது என்பதை அவர்கள் உணரவில்லையா?'\n\r\n\n\r\nوَلاَ يَمْلِكُ لَهُمْ ضَرّاً وَلاَ نَفْعاً\n\r\n\n\r\n(மேலும் அவர்களுக்குத் தீங்கு செய்யவும் அல்லது நன்மை செய்யவும் அதற்கு எந்த சக்தியும் இல்லை) அதாவது அவர்களின் உலக விவகாரங்களிலும் மறுமையிலும். இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"அல்லாஹ்வின் மீது சத்தியமாக! அந்தக் கன்றுக்குட்டியின் சத்தம் என்பது, அதன் பின்புறம் வழியாகக் காற்று உள்ளே புகுந்து வாய் வழியாக வெளியேறும்போது உண்டான சத்தமே தவிர வேறில்லை.\" ஹஸன் அல்-பஸரீ (ரஹ்) அவர்கள் வழியாகப் பதிவுசெய்யப்பட்ட அல்-ஃபிதன் என்ற ஹதீஸில், இந்தக் கன்றுக்குட்டியின் பெயர் 'பஹ்மூத்' என்று குறிப்பிடப்பட்டுள்ளது. இந்த அறியாமை மிக்க மக்கள், காப்டியர்களின் நகைகளைத் தூக்கி எறிந்ததாகக் கூறித் தங்களைக் காத்துக் கொள்ள முயன்றனர். ஆனால் அந்த நகைகளைத் தீயில் எறிந்து இறுதியில் கன்றுக்குட்டியை வணங்கத் தொடங்கினர். அவர்கள் ஒரு வெறுக்கத்தக்கக் காரியத்திலிருந்து விடுபட முயன்று, அதைவிடக் கொடிய பாவத்தைச் செய்துவிட்டனர். இது அப்துல்லாஹ் பின் உமர் (ரழி) அவர்களிடமிருந்து அறிவிக்கப்பட்ட ஒரு ஆதாரப்பூர்வமான செய்தியைப் போன்றது. ஈராக்கைச் சேர்ந்த ஒருவர், ஆடையில் கொசுவின் இரத்தம் பட்டுவிட்டால் அதன் சட்டம் என்ன என்று அவரிடம் கேட்டார். அந்த ஆடையில் தொழலாமா என்பதை அவர் அறிய விரும்பினார். அதற்கு இப்னு உமர் (ரழி) அவர்கள், \"ஈராக் மக்களைப் பாருங்கள்! இவர்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் பேரர் அல்-ஹுஸைன் (ரழி) அவர்களைக் கொலை செய்தார்கள்; ஆனால் இப்போது கொசுவின் இரத்தத்தைப் பற்றி (சட்டம்) கேட்கிறார்கள்!\" என்று பதிலளித்தார்கள்."},"90":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=91\" class=\"link\">20:91</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:91 ஐ பார்க்கவும்"},"91":{"html":"<strong>ஹாரூன் (அலை) அவர்கள் கன்றுக்குட்டி வழிபாட்டைத் தடுத்ததும், அதில் இஸ்ரவேலர்கள் பிடிவாதமாக இருந்ததும்</strong><br />\r\n<br />\r\nஹாரூன் (அலை) அவர்கள் கன்றுக்குட்டியை வணங்குவதிலிருந்து அவர்களைத் தடுக்க முயன்றது பற்றியும், இது அவர்களுக்கு ஒரு சோதனை மட்டுமே என்று அவர்களிடம் அவர்கள் கூறியது பற்றியும் மேன்மைமிக்க அல்லாஹ் அறிவிக்கிறான். அவர்களின் இறைவன் அளவற்ற அருளாளன் என்றும், அவனே அனைத்தையும் படைத்து, ஒவ்வொன்றுக்கும் உரிய அளவை நிர்ணயித்தான் என்றும் அவர்கள் (ஹாரூன் அலை) கூறினார்கள். அவன் மகத்தான அரியாசனத்தின் உரிமையாளன், தான் நாடுவனவற்றைச் செய்பவன். <span class=\"quran-arabic-font text-success\">﴾فَاتَّبِعُونِي</span> <span class=\"quran-arabic-font text-success\">وَأَطِيعُوا</span> <span class=\"quran-arabic-font text-success\">أَمْرِي</span> <span class=\"quran-arabic-font text-success\">٩٠﴿</span><br />\r\n<br />\r\n(எனவே என்னைப் பின்பற்றுங்கள், எனது கட்டளைக்குக் கீழ்ப்படியுங்கள்.) அதாவது, \"நான் உங்களுக்குக் கட்டளையிடுவதில் என்னைப் பின்பற்றுங்கள், நான் எவற்றைத் தடுக்கிறேனோ அவற்றை விட்டுவிடுங்கள்.\" <span class=\"quran-arabic-font text-success\">﴾قَالُوا</span> <span class=\"quran-arabic-font text-success\">لَنْ</span> <span class=\"quran-arabic-font text-success\">نَبْرَحَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">عَاكِفِينَ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">يَرْجِعَ</span> <span class=\"quran-arabic-font text-success\">إِلَيْنَا</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span> <span class=\"quran-arabic-font text-success\">٩١﴿</span><br />\r\n<br />\r\n(அவர்கள் கூறினார்கள்: \"மூஸா (அலை) எங்களிடம் திரும்பி வரும் வரை, நாங்கள் இதைத் தொடர்ந்து வணங்கிக்கொண்டே இருப்போம்.\") அதாவது, \"இந்தக் கன்றுக்குட்டியைப் பற்றி மூஸா (அலை) அவர்கள் என்ன சொல்கிறார்கள் என்பதைக் கேட்கும் வரை, இதன் வழிபாட்டை நாங்கள் நிறுத்த மாட்டோம்.\" இவ்வாறு அவர்கள் இந்த விஷயத்தில் ஹாரூன் (அலை) அவர்களை எதிர்த்தார்கள்; அவர்களோடு சண்டையிட்டு, கிட்டத்தட்ட அவர்களைக் கொல்லும் நிலைக்குச் சென்றார்கள். (\"நிச்சயமாக இந்த மக்கள் என்னைப் பலவீனப்படுத்திவிட்டார்கள்; என்னைக் கொல்லவும் முற்பட்டார்கள்\" (<a href=\"qurandisp.php?sura=7&ayah=150\" class=\"link\">7:150</a>) என்று ஹாரூன் (அலை) அவர்கள் கூறினார்கள்.)<br />\r\n<br />","text":"ஹாரூன் (அலை) அவர்கள் கன்றுக்குட்டி வழிபாட்டைத் தடுத்ததும், அதில் இஸ்ரவேலர்கள் பிடிவாதமாக இருந்ததும்\n\r\n\n\r\nஹாரூன் (அலை) அவர்கள் கன்றுக்குட்டியை வணங்குவதிலிருந்து அவர்களைத் தடுக்க முயன்றது பற்றியும், இது அவர்களுக்கு ஒரு சோதனை மட்டுமே என்று அவர்களிடம் அவர்கள் கூறியது பற்றியும் மேன்மைமிக்க அல்லாஹ் அறிவிக்கிறான். அவர்களின் இறைவன் அளவற்ற அருளாளன் என்றும், அவனே அனைத்தையும் படைத்து, ஒவ்வொன்றுக்கும் உரிய அளவை நிர்ணயித்தான் என்றும் அவர்கள் (ஹாரூன் அலை) கூறினார்கள். அவன் மகத்தான அரியாசனத்தின் உரிமையாளன், தான் நாடுவனவற்றைச் செய்பவன். ﴾فَاتَّبِعُونِي وَأَطِيعُوا أَمْرِي ٩٠﴿\n\r\n\n\r\n(எனவே என்னைப் பின்பற்றுங்கள், எனது கட்டளைக்குக் கீழ்ப்படியுங்கள்.) அதாவது, \"நான் உங்களுக்குக் கட்டளையிடுவதில் என்னைப் பின்பற்றுங்கள், நான் எவற்றைத் தடுக்கிறேனோ அவற்றை விட்டுவிடுங்கள்.\" ﴾قَالُوا لَنْ نَبْرَحَ عَلَيْهِ عَاكِفِينَ حَتَّى يَرْجِعَ إِلَيْنَا مُوسَى ٩١﴿\n\r\n\n\r\n(அவர்கள் கூறினார்கள்: \"மூஸா (அலை) எங்களிடம் திரும்பி வரும் வரை, நாங்கள் இதைத் தொடர்ந்து வணங்கிக்கொண்டே இருப்போம்.\") அதாவது, \"இந்தக் கன்றுக்குட்டியைப் பற்றி மூஸா (அலை) அவர்கள் என்ன சொல்கிறார்கள் என்பதைக் கேட்கும் வரை, இதன் வழிபாட்டை நாங்கள் நிறுத்த மாட்டோம்.\" இவ்வாறு அவர்கள் இந்த விஷயத்தில் ஹாரூன் (அலை) அவர்களை எதிர்த்தார்கள்; அவர்களோடு சண்டையிட்டு, கிட்டத்தட்ட அவர்களைக் கொல்லும் நிலைக்குச் சென்றார்கள். (\"நிச்சயமாக இந்த மக்கள் என்னைப் பலவீனப்படுத்திவிட்டார்கள்; என்னைக் கொல்லவும் முற்பட்டார்கள்\" (7:150) என்று ஹாரூன் (அலை) அவர்கள் கூறினார்கள்.)"},"92":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=94\" class=\"link\">20:94</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:94 ஐ பார்க்கவும்"},"93":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=94\" class=\"link\">20:94</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:94 ஐ பார்க்கவும்"},"94":{"html":"<strong>மூஸா (அலை) திரும்பிய பிறகு அவருக்கும் ஹாரூன் (அலை) அவர்களுக்கும் இடையில் என்ன நடந்தது</strong><br />\r\n<br />\r\nமூஸா (அலை) அவர்கள் தம் மக்களிடம் திரும்பி வந்து, அவர்களிடையே ஏற்பட்டிருந்த அந்தப் பாரதூரமான காரியத்தைக் கண்டபோது என்ன நடந்தது என்பதை அல்லாஹ் தெரிவிக்கிறான். இதைக் கண்டதும் மூஸா (அலை) கோபம் கொண்டார்கள்; தன் கையில் வைத்திருந்த (வேத வெளிப்பாடுகள் அடங்கிய) பலகைகளைக் கீழே எறிந்தார்கள். பிறகு, தன் சகோதரர் ஹாரூன் (அலை) அவர்களின் தலையைப் பிடித்துத் தம்மை நோக்கி இழுத்தார்கள். நாம் இதனை முன்னரே ஸூரா அல்-அஃராஃபில் விளக்கியுள்ளோம். அங்கு நாம் இந்த ஹதீஸைக் குறிப்பிட்டிருந்தோம்: <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">لَيْسَ</span> <span class=\"quran-arabic-font text-success\">الْخَبَرُ</span> <span class=\"quran-arabic-font text-success\">كَالْمُعَايَنَة</span>»<span class=\"quran-arabic-font text-success\">﴿</span> (நேரில் காண்பது போன்றதல்ல கேள்விப்படுவது.)<br />\r\n<br />\r\nபிறகு, அவர் தம் சகோதரர் ஹாரூன் (அலை) அவர்களிடம் இப்படிக் கூறி அதட்டத் தொடங்கினார்கள்: <span class=\"quran-arabic-font text-success\">﴾مَا</span> <span class=\"quran-arabic-font text-success\">مَنَعَكَ</span> <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">رَأَيْتَهُمْ</span> <span class=\"quran-arabic-font text-success\">ضَلُّوا</span> <span class=\"quran-arabic-font text-success\">أَلاَّ</span> <span class=\"quran-arabic-font text-success\">تَتَّبِعَنِ﴿</span> (அவர்கள் வழிதவறிச் செல்வதை நீர் கண்டபோது, என்னைப் பின்தொடர்ந்து வராதிருக்க உமக்குத் தடையாக இருந்தது எது?) அதாவது, \"இந்த விஷயம் நடந்த உடனேயே நீர் இது குறித்து எனக்குத் தெரிவித்திருக்க வேண்டும்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَفَعَصَيْتَ</span> <span class=\"quran-arabic-font text-success\">أَمْرِي﴿</span> (நீர் என் கட்டளைக்கு மாறு செய்தீரோ?) \"நான் உமது பொறுப்பில் ஒப்படைத்த விஷயத்தில்,\" என்று அவர் கூறியது, மூஸா (அலை) அவர்களின் இந்தக் கூற்றைக் குறிக்கிறது: <span class=\"quran-arabic-font text-success\">﴾اخْلُفْنِي</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">قَوْمِي</span> <span class=\"quran-arabic-font text-success\">وَأَصْلِحْ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَتَّبِعْ</span> <span class=\"quran-arabic-font text-success\">سَبِيلَ</span> <span class=\"quran-arabic-font text-success\">الْمُفْسِدِينَ﴿</span> (என் மக்களிடையே எனக்குப் பகரமாக இருந்து நீர் அவர்களைச் சீர்படுத்தும்; குழப்பவாதிகளின் வழியைப் பின்பற்றாதீர்.) <a href=\"qurandisp.php?sura=7&ayah=142\" class=\"link\">7:142</a><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">يَبْنَؤُمَّ﴿</span> (அதற்கு ஹாரூன் (அலை) அவர்கள் கூறினார்கள்: \"என் தாயின் மகனே!\") இவ்வாறு தாயைக் குறிப்பிட்டது மூஸா (அலை) அவர்களின் கோபத்தைத் தணிப்பதற்காக ஹாரூன் (அலை) அவர்கள் மேற்கொண்ட முயற்சியாகும். ஏனெனில் அவர் மூஸா (அலை) அவர்களின் உடன் பிறந்த சகோதரர்; அவர்கள் இருவருக்கும் ஒரே பெற்றோரே இருந்தனர். மென்மையையும் அன்பையும் தூண்டுவதற்குத் தாயைக் குறிப்பிடுவது மிகவும் நுட்பமானதும் ஆழமானதுமாகும். அதனால்தான் அவர் இப்படிக் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾يَبْنَؤُمَّ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَأْخُذْ</span> <span class=\"quran-arabic-font text-success\">بِلِحْيَتِي</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">بِرَأْسِي﴿</span> (என் தாயின் மகனே! என் தாடியையோ என் தலையையோ பிடித்து இழுக்காதீர்கள்!)<br />\r\n<br />\r\nஅந்தப் பெரும் அசம்பாவிதம் குறித்து மூஸா (அலை) அவர்களிடம் வந்து தகவல் தெரிவிக்கத் தாமதமானதற்கு ஹாரூன் (அலை) அவர்கள் கூறிய சமாதானம் இதுதான். அவர் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾إِنِّي</span> <span class=\"quran-arabic-font text-success\">خَشِيتُ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تَقُولَ</span> <span class=\"quran-arabic-font text-success\">فَرَّقْتَ</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">بَنِي</span> <span class=\"quran-arabic-font text-success\">إِسْرَائِيلَ﴿</span> (நிச்சயமாக நான் பயந்தேன்.) அதாவது, \"நான் உங்களைப் பின்தொடர்ந்து வந்து இந்த விபரத்தைச் சொன்னால், நான் அவர்களைத் தனியே விட்டுவிட்டு வந்ததாகவும், அவர்களுக்குள் பிரிவினையை ஏற்படுத்திவிட்டதாகவும் நீங்கள் என் மீது குற்றம் சுமத்துவீர்களோ என்று நான் அஞ்சினேன்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلَمْ</span> <span class=\"quran-arabic-font text-success\">تَرْقُبْ</span> <span class=\"quran-arabic-font text-success\">قَوْلِي﴿</span> (மேலும், நீர் என் வார்த்தையைக் கவனத்தில் கொள்ளவில்லை!) இதன் பொருள்: \"உங்களை அவர்கள் மீது பொறுப்பாளராக விட்டுச் சென்றபோது நான் உங்களுக்கு இட்ட கட்டளையை நீர் பேணவில்லை (என்று கூறுவீர்களோ என அஞ்சினேன்).\" இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"ஹாரூன் (அலை) அவர்கள் மூஸா (அலை) அவர்களுக்கு மிகுந்த மரியாதையையும் கீழ்ப்படிதலையும் அளிப்பவர்களாக இருந்தார்கள்.\"<br />\r\n<br />","text":"மூஸா (அலை) திரும்பிய பிறகு அவருக்கும் ஹாரூன் (அலை) அவர்களுக்கும் இடையில் என்ன நடந்தது\n\r\n\n\r\nமூஸா (அலை) அவர்கள் தம் மக்களிடம் திரும்பி வந்து, அவர்களிடையே ஏற்பட்டிருந்த அந்தப் பாரதூரமான காரியத்தைக் கண்டபோது என்ன நடந்தது என்பதை அல்லாஹ் தெரிவிக்கிறான். இதைக் கண்டதும் மூஸா (அலை) கோபம் கொண்டார்கள்; தன் கையில் வைத்திருந்த (வேத வெளிப்பாடுகள் அடங்கிய) பலகைகளைக் கீழே எறிந்தார்கள். பிறகு, தன் சகோதரர் ஹாரூன் (அலை) அவர்களின் தலையைப் பிடித்துத் தம்மை நோக்கி இழுத்தார்கள். நாம் இதனை முன்னரே ஸூரா அல்-அஃராஃபில் விளக்கியுள்ளோம். அங்கு நாம் இந்த ஹதீஸைக் குறிப்பிட்டிருந்தோம்: ﴾«لَيْسَ الْخَبَرُ كَالْمُعَايَنَة»﴿ (நேரில் காண்பது போன்றதல்ல கேள்விப்படுவது.)\n\r\n\n\r\nபிறகு, அவர் தம் சகோதரர் ஹாரூன் (அலை) அவர்களிடம் இப்படிக் கூறி அதட்டத் தொடங்கினார்கள்: ﴾مَا مَنَعَكَ إِذْ رَأَيْتَهُمْ ضَلُّوا أَلاَّ تَتَّبِعَنِ﴿ (அவர்கள் வழிதவறிச் செல்வதை நீர் கண்டபோது, என்னைப் பின்தொடர்ந்து வராதிருக்க உமக்குத் தடையாக இருந்தது எது?) அதாவது, \"இந்த விஷயம் நடந்த உடனேயே நீர் இது குறித்து எனக்குத் தெரிவித்திருக்க வேண்டும்.\"\n\r\n\n\r\n﴾أَفَعَصَيْتَ أَمْرِي﴿ (நீர் என் கட்டளைக்கு மாறு செய்தீரோ?) \"நான் உமது பொறுப்பில் ஒப்படைத்த விஷயத்தில்,\" என்று அவர் கூறியது, மூஸா (அலை) அவர்களின் இந்தக் கூற்றைக் குறிக்கிறது: ﴾اخْلُفْنِي فِي قَوْمِي وَأَصْلِحْ وَلاَ تَتَّبِعْ سَبِيلَ الْمُفْسِدِينَ﴿ (என் மக்களிடையே எனக்குப் பகரமாக இருந்து நீர் அவர்களைச் சீர்படுத்தும்; குழப்பவாதிகளின் வழியைப் பின்பற்றாதீர்.) 7:142\n\r\n\n\r\n﴾قَالَ يَبْنَؤُمَّ﴿ (அதற்கு ஹாரூன் (அலை) அவர்கள் கூறினார்கள்: \"என் தாயின் மகனே!\") இவ்வாறு தாயைக் குறிப்பிட்டது மூஸா (அலை) அவர்களின் கோபத்தைத் தணிப்பதற்காக ஹாரூன் (அலை) அவர்கள் மேற்கொண்ட முயற்சியாகும். ஏனெனில் அவர் மூஸா (அலை) அவர்களின் உடன் பிறந்த சகோதரர்; அவர்கள் இருவருக்கும் ஒரே பெற்றோரே இருந்தனர். மென்மையையும் அன்பையும் தூண்டுவதற்குத் தாயைக் குறிப்பிடுவது மிகவும் நுட்பமானதும் ஆழமானதுமாகும். அதனால்தான் அவர் இப்படிக் கூறினார்கள்: ﴾يَبْنَؤُمَّ لاَ تَأْخُذْ بِلِحْيَتِي وَلاَ بِرَأْسِي﴿ (என் தாயின் மகனே! என் தாடியையோ என் தலையையோ பிடித்து இழுக்காதீர்கள்!)\n\r\n\n\r\nஅந்தப் பெரும் அசம்பாவிதம் குறித்து மூஸா (அலை) அவர்களிடம் வந்து தகவல் தெரிவிக்கத் தாமதமானதற்கு ஹாரூன் (அலை) அவர்கள் கூறிய சமாதானம் இதுதான். அவர் கூறினார்கள்: ﴾إِنِّي خَشِيتُ أَن تَقُولَ فَرَّقْتَ بَيْنَ بَنِي إِسْرَائِيلَ﴿ (நிச்சயமாக நான் பயந்தேன்.) அதாவது, \"நான் உங்களைப் பின்தொடர்ந்து வந்து இந்த விபரத்தைச் சொன்னால், நான் அவர்களைத் தனியே விட்டுவிட்டு வந்ததாகவும், அவர்களுக்குள் பிரிவினையை ஏற்படுத்திவிட்டதாகவும் நீங்கள் என் மீது குற்றம் சுமத்துவீர்களோ என்று நான் அஞ்சினேன்.\"\n\r\n\n\r\n﴾وَلَمْ تَرْقُبْ قَوْلِي﴿ (மேலும், நீர் என் வார்த்தையைக் கவனத்தில் கொள்ளவில்லை!) இதன் பொருள்: \"உங்களை அவர்கள் மீது பொறுப்பாளராக விட்டுச் சென்றபோது நான் உங்களுக்கு இட்ட கட்டளையை நீர் பேணவில்லை (என்று கூறுவீர்களோ என அஞ்சினேன்).\" இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"ஹாரூன் (அலை) அவர்கள் மூஸா (அலை) அவர்களுக்கு மிகுந்த மரியாதையையும் கீழ்ப்படிதலையும் அளிப்பவர்களாக இருந்தார்கள்.\""},"95":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=98\" class=\"link\">20:98</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:98 ஐ பார்க்கவும்"},"96":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=98\" class=\"link\">20:98</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:98 ஐ பார்க்கவும்"},"97":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=98\" class=\"link\">20:98</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:98 ஐ பார்க்கவும்"},"98":{"html":"<strong>ஸாமிரி கன்றுக்குட்டியை எவ்வாறு உருவாக்கினான்</strong><br />\r\n<br />\r\nமூஸா (அலை) அவர்கள் ஸாமிரியிடம், \"நீ எதற்காக இவ்வாறு செய்தாய்? இத்தகைய செயலைச் செய்யத் தூண்டும் எண்ணம் உனக்கு எப்படி வந்தது?\" என்று கேட்டார்கள். முஹம்மது பின் இஸ்ஹாக் அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்: \"ஸாமிரி, பசுக்களை வணங்கும் பழக்கமுடைய பஜர்மா எனும் ஊரைச் சேர்ந்தவன். அவனது உள்ளத்தில் பசு வழிபாட்டின் மீதான பற்று இன்னும் மிச்சமிருந்தது. இருப்பினும், அவன் இஸ்ரவேலர்களுடன் சேர்ந்து இஸ்லாத்தை ஏற்றுக்கொண்டது போல் நடித்தான். அவனது பெயர் மூஸா பின் ளஃபர் ஆகும்.\" கதாதா அவர்கள், \"அவன் ஸாமர்ரா எனும் கிராமத்தைச் சேர்ந்தவன்\" என்று கூறினார்கள். <span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">بَصُرْتُ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَبْصُرُواْ</span> <span class=\"quran-arabic-font text-success\">بِهِ﴿</span><br />\r\n<br />\r\n(ஸாமிரி) கூறினான்: \"அவர்கள் காணாததை நான் கண்டேன்.\" இதன் பொருள்: \"ஃபிர்அவ்னை அழிப்பதற்காக ஜிப்ரீல் (அலை) அவர்கள் வந்தபோது நான் அவர்களைக் கண்டேன்.\" <span class=\"quran-arabic-font text-success\">﴾فَقَبَضْتُ</span> <span class=\"quran-arabic-font text-success\">قَبْضَةً</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">أَثَرِ</span> <span class=\"quran-arabic-font text-success\">الرَّسُولِ﴿</span><br />\r\n<br />\r\n(எனவே, அந்தத் தூதரின் காலடித் தடத்தில் இருந்து ஒரு கைப்பிடி (கப்தா) எடுத்தேன்). அதாவது, ஜிப்ரீல் (அலை) அவர்களுடைய குதிரையின் குளம்படித் தடத்தில் இருந்து மண்ணை எடுத்தான். பல தஃப்ஸீர் அறிஞர்களிடம், குறிப்பாக அவர்களில் பெரும்பாலானோரிடம் இக்கருத்தே பிரபலமாக உள்ளது. முஜாஹித் அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾فَقَبَضْتُ</span> <span class=\"quran-arabic-font text-success\">قَبْضَةً</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">أَثَرِ</span> <span class=\"quran-arabic-font text-success\">الرَّسُولِ﴿</span><br />\r\n<br />\r\n(எனவே, அந்தத் தூதரின் காலடித் தடத்தில் இருந்து ஒரு கைப்பிடி (கப்தா) எடுத்தேன்). \"இது ஜிப்ரீல் (அலை) அவர்களின் குதிரைக் குளம்பின் கீழ் இருந்த மண்ணைக் குறிக்கும்.\" மேலும் அவர்கள் கூறுகையில்: \"'கப்தா' (<span class=\"quran-arabic-font text-success\">قَبْضَةً</span>) என்பது முழுக் கைப்பிடி அளவு என்றும், 'கப்ஸா' (<span class=\"quran-arabic-font text-success\">قَبْصَةً</span>) என்பது விரல் நுனிகளால் அள்ளப்படுவது என்றும் பொருள்படும்\" என்றார்கள். முஜாஹித் அவர்கள் மேலும் கூறினார்கள்: \"ஸாமிரி தன் கையில் இருந்ததை இஸ்ரவேலர்களின் ஆபரணங்கள் மீது எறிந்தான். அது ஒரு கன்றுக்குட்டியின் உருவமாக மாறியது; அதிலிருந்து ஒரு மெல்லிய சத்தம் எழுந்தது. அதனுள் புகுந்த காற்றே அந்தச் சத்தத்திற்குக் காரணமாக அமைந்தது.\" ஆகவே அவன் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾فَنَبَذْتُهَا﴿</span><br />\r\n<br />\r\n(ஆகவே நான் அதனை எறிந்தேன்.) இதன் பொருள்: \"(ஆபரணங்களை) எறிந்து கொண்டிருந்தவர்களுடன் சேர்ந்து நானும் அதனை எறிந்தேன்\" என்பதாகும். <span class=\"quran-arabic-font text-success\">﴾وَكَذلِكَ</span> <span class=\"quran-arabic-font text-success\">سَوَّلَتْ</span> <span class=\"quran-arabic-font text-success\">لِى</span> <span class=\"quran-arabic-font text-success\">نَفْسِى﴿</span><br />\r\n<br />\r\n(இவ்வாறு என் மனம் எனக்குத் தூண்டியது.) அதாவது, அவனது மனது அச்செயலை ஒரு நல்ல காரியமாகச் சித்தரித்தது; அது அவனுக்குப் பிடித்தமானதாகவும் அமைந்தது.<br />\r\n<br />\r\n<strong>ஸாமிரியின் தண்டனையும் கன்றுக்குட்டி எரிக்கப்பட்டதும்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">فَاذْهَبْ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْحَيَوةِ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تَقُولَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">مِسَاسَ﴿</span><br />\r\n<br />\r\n(மூஸா (அலை) அவர்கள்) கூறினார்கள்: \"அப்படியானால் நீ போய்விடு! நிச்சயமாக இந்த வாழ்க்கையில் 'என்னைத் தொடாதீர்கள்' என்று கூறுவதே உனக்கான தண்டனையாகும்.\" இதன் பொருள்: \"எடுப்பதற்கும் தொடுவதற்கும் உனக்கு உரிமை இல்லாத அந்தத் தூதரின் காலடித் தடம் பட்ட மண்ணை நீ எடுத்துத் தொட்டாய். எனவே, 'என்னைத் தொடாதீர்கள்' என்று நீ சொல்லிக்கொண்டிருப்பதே இவ்வுலகில் உனக்குரிய தண்டனையாகும்.\" அதாவது, \"நீ மக்களைத் தொடமாட்டாய், மக்களும் உன்னைத் தொடமாட்டார்கள்.\" <span class=\"quran-arabic-font text-success\">﴾وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">مَوْعِداً﴿</span><br />\r\n<br />\r\n(நிச்சயமாக உனக்கு ஒரு வாக்குறுதி (தண்டனைக்காலம்) உண்டு.) இது மறுமை நாளைக் குறிக்கிறது. <span class=\"quran-arabic-font text-success\">﴾لَّن</span> <span class=\"quran-arabic-font text-success\">تُخْلَفَهُ﴿</span><br />\r\n<br />\r\n(அது உனக்கு மாற்றப்படாது.) அதிலிருந்து தப்பிக்க உனக்கு எந்த வழியும் இருக்காது. கதாதா அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾أَن</span> <span class=\"quran-arabic-font text-success\">تَقُولَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">مِسَاسَ﴿</span><br />\r\n<br />\r\n('என்னைத் தொடாதீர்கள்' என்று நீ கூறுவாய்.) \"இது அவர்களுக்கும் அவர்களின் வழித்தோன்றல்களுக்கும் (அதாவது, அவர்களைப் போன்ற மனநிலையில் இருப்பவர்களுக்கும்) வழங்கப்பட்ட தண்டனையைக் குறிக்கிறது. அவர்கள் இன்றும் 'என்னைத் தொடாதீர்கள்' என்று கூறி வருகின்றனர்.\" அல்லாஹ்வின் கூற்றைப் பற்றி: <span class=\"quran-arabic-font text-success\">﴾وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">مَوْعِداً</span> <span class=\"quran-arabic-font text-success\">لَّن</span> <span class=\"quran-arabic-font text-success\">تُخْلَفَهُ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக உனக்கு ஒரு வாக்குறுதி உண்டு, அது உனக்கு மாற்றப்படாது.) அல்-ஹஸன், கதாதா மற்றும் அபூ நஹிக் ஆகியோர் கூறுகையில்: \"நீ அதிலிருந்து தப்ப முடியாது\" என்றார்கள். <span class=\"quran-arabic-font text-success\">﴾وَانظُرْ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">إِلَـهِكَ﴿</span><br />\r\n<br />\r\n(நீ வணங்கிக் கொண்டிருந்த உன்னுடைய அந்த இறைவனைப் பார்.) நீ எதை வணங்கினாயோ அதைப் பார். <span class=\"quran-arabic-font text-success\">﴾الَّذِى</span> <span class=\"quran-arabic-font text-success\">ظَلْتَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">عَاكِفاً﴿</span><br />\r\n<br />\r\n(எதனை நீ விடாது பற்றிப் பிடித்துக் கொண்டிருந்தாயோ.) எதனை நீ தொடர்ந்து வணங்கி வந்தாயோ - அதாவது அந்தக் கன்றுக்குட்டி. <span class=\"quran-arabic-font text-success\">﴾لَّنُحَرِّقَنَّهُ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">لَنَنسِفَنَّهُ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْيَمِّ</span> <span class=\"quran-arabic-font text-success\">نَسْفاً﴿</span><br />\r\n<br />\r\n(நிச்சயமாக நாம் அதனை எரித்து, பின்னர் அதனைத் தூள் தூளாகக் கடலில் தூவிவிடுவோம்.) <span class=\"quran-arabic-font text-success\">﴾إِنَّمَآ</span> <span class=\"quran-arabic-font text-success\">إِلَـهُكُمُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">لا</span> <span class=\"quran-arabic-font text-success\">إِلَـهَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">وَسِعَ</span> <span class=\"quran-arabic-font text-success\">كُلَّ</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">عِلْماً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(உங்கள் இறைவன் அல்லாஹ் ஒருவனே; அவனைத் தவிர வேறு இறைவன் இல்லை. அவன் எல்லாப் பொருட்களையும் தனது அறிவால் சூழ்ந்துள்ளான்.) மூஸா (அலை) அவர்கள் இஸ்ரவேலர்களிடம் கூறினார்கள்: \"இது உங்கள் இறைவன் அல்ல. உங்கள் இறைவன் அல்லாஹ் ஒருவன் தான். அவனைத் தவிர வணக்கத்திற்குரிய உண்மையான இறைவன் வேறு யாருமில்லை. அவனைத் தவிர வேறு யாருக்கும் வணக்கம் செய்வது தகுதியானது அல்ல. ஏனெனில், அனைத்தும் அவனையே சார்ந்துள்ளன; அனைத்தும் அவனது அடிமைகளே.\" அல்லாஹ்வின் கூற்றைப் பற்றி: <span class=\"quran-arabic-font text-success\">﴾وَسِعَ</span> <span class=\"quran-arabic-font text-success\">كُلَّ</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">عِلْماً﴿</span><br />\r\n<br />\r\n(அவன் எல்லாப் பொருட்களையும் தனது அறிவால் சூழ்ந்துள்ளான்.) 'இல்ம்' (அறிவு) எனும் சொல் இங்குச் சிறப்பித்துக் கூறப்பட்டுள்ளது. அதாவது, அல்லாஹ் அனைத்தையும் அறிந்தவன் என்று பொருள்படும். <span class=\"quran-arabic-font text-success\">﴾أَحَاطَ</span> <span class=\"quran-arabic-font text-success\">بِكُلِّ</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">عِلْمَا﴿</span><br />\r\n<br />\r\n((அல்லாஹ்) தனது அறிவால் எல்லாப் பொருட்களையும் சூழ்ந்துள்ளான்.) <a href=\"qurandisp.php?sura=65&ayah=12\" class=\"link\">65:12</a> மேலும் அவன் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَأَحْصَى</span> <span class=\"quran-arabic-font text-success\">كُلَّ</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">عَدَداً﴿</span><br />\r\n<br />\r\n(அவன் எல்லாப் பொருட்களையும் எண்ணிக்கையினால் கணக்கிட்டு வைத்திருக்கிறான்.) <a href=\"qurandisp.php?sura=72&ayah=28\" class=\"link\">72:28</a> எனவே, <span class=\"quran-arabic-font text-success\">﴾لاَ</span> <span class=\"quran-arabic-font text-success\">يَعْزُبُ</span> <span class=\"quran-arabic-font text-success\">عَنْهُ</span> <span class=\"quran-arabic-font text-success\">مِثْقَالُ</span> <span class=\"quran-arabic-font text-success\">ذَرَّةٍ﴿</span><br />\r\n<br />\r\n(ஓர் அணுவளவும் அவனது அறிவிலிருந்து தப்புவதில்லை.) <a href=\"qurandisp.php?sura=34&ayah=3\" class=\"link\">34:3</a> அவன் மேலும் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَمَا</span> <span class=\"quran-arabic-font text-success\">تَسْقُطُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">وَرَقَةٍ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُهَا</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">حَبَّةٍ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">ظُلُمَاتِ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">رَطْبٍ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَابِسٍ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">كِتَابٍ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٍ﴿</span><br />\r\n<br />\r\n(ஓர் இலை கீழே விழுந்தாலும் அவன் அதனை அறிகிறான். பூமியின் இருள்களில் உள்ள ஒரு தானியமானாலும், பசுமையானதோ அல்லது காய்ந்ததோ எதுவானாலும் அவை ஒரு தெளிவான பதிவேட்டில் (லவ்ஹுல் மஹ்ஃபூழில்) இல்லாமல் இல்லை.) <a href=\"qurandisp.php?sura=6&ayah=59\" class=\"link\">6:59</a> மேலும் அவன் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَمَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دَابَّةٍ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">رِزْقُهَا</span> <span class=\"quran-arabic-font text-success\">وَيَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">مُسْتَقَرَّهَا</span> <span class=\"quran-arabic-font text-success\">وَمُسْتَوْدَعَهَا</span> <span class=\"quran-arabic-font text-success\">كُلٌّ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">كِتَابٍ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(பூமியில் ஊர்ந்து செல்லும் உயிரினங்கள் எதுவாயினும் அவற்றிற்கு உணவளிக்கும் பொறுப்பு அல்லாஹ்வின் மீதே உள்ளது. அவை வசிக்குமிடத்தையும் அவை அடங்குமிடத்தையும் அவன் அறிகிறான். அனைத்தும் ஒரு தெளிவான பதிவேட்டில் உள்ளன.) <a href=\"qurandisp.php?sura=11&ayah=6\" class=\"link\">11:6</a> இதைக் குறிப்பிடும் பல வசனங்கள் உள்ளன.<br />\r\n<br />","text":"ஸாமிரி கன்றுக்குட்டியை எவ்வாறு உருவாக்கினான்\n\r\n\n\r\nமூஸா (அலை) அவர்கள் ஸாமிரியிடம், \"நீ எதற்காக இவ்வாறு செய்தாய்? இத்தகைய செயலைச் செய்யத் தூண்டும் எண்ணம் உனக்கு எப்படி வந்தது?\" என்று கேட்டார்கள். முஹம்மது பின் இஸ்ஹாக் அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்: \"ஸாமிரி, பசுக்களை வணங்கும் பழக்கமுடைய பஜர்மா எனும் ஊரைச் சேர்ந்தவன். அவனது உள்ளத்தில் பசு வழிபாட்டின் மீதான பற்று இன்னும் மிச்சமிருந்தது. இருப்பினும், அவன் இஸ்ரவேலர்களுடன் சேர்ந்து இஸ்லாத்தை ஏற்றுக்கொண்டது போல் நடித்தான். அவனது பெயர் மூஸா பின் ளஃபர் ஆகும்.\" கதாதா அவர்கள், \"அவன் ஸாமர்ரா எனும் கிராமத்தைச் சேர்ந்தவன்\" என்று கூறினார்கள். ﴾قَالَ بَصُرْتُ بِمَا لَمْ يَبْصُرُواْ بِهِ﴿\n\r\n\n\r\n(ஸாமிரி) கூறினான்: \"அவர்கள் காணாததை நான் கண்டேன்.\" இதன் பொருள்: \"ஃபிர்அவ்னை அழிப்பதற்காக ஜிப்ரீல் (அலை) அவர்கள் வந்தபோது நான் அவர்களைக் கண்டேன்.\" ﴾فَقَبَضْتُ قَبْضَةً مِّنْ أَثَرِ الرَّسُولِ﴿\n\r\n\n\r\n(எனவே, அந்தத் தூதரின் காலடித் தடத்தில் இருந்து ஒரு கைப்பிடி (கப்தா) எடுத்தேன்). அதாவது, ஜிப்ரீல் (அலை) அவர்களுடைய குதிரையின் குளம்படித் தடத்தில் இருந்து மண்ணை எடுத்தான். பல தஃப்ஸீர் அறிஞர்களிடம், குறிப்பாக அவர்களில் பெரும்பாலானோரிடம் இக்கருத்தே பிரபலமாக உள்ளது. முஜாஹித் அவர்கள் கூறினார்கள்: ﴾فَقَبَضْتُ قَبْضَةً مِّنْ أَثَرِ الرَّسُولِ﴿\n\r\n\n\r\n(எனவே, அந்தத் தூதரின் காலடித் தடத்தில் இருந்து ஒரு கைப்பிடி (கப்தா) எடுத்தேன்). \"இது ஜிப்ரீல் (அலை) அவர்களின் குதிரைக் குளம்பின் கீழ் இருந்த மண்ணைக் குறிக்கும்.\" மேலும் அவர்கள் கூறுகையில்: \"'கப்தா' (قَبْضَةً) என்பது முழுக் கைப்பிடி அளவு என்றும், 'கப்ஸா' (قَبْصَةً) என்பது விரல் நுனிகளால் அள்ளப்படுவது என்றும் பொருள்படும்\" என்றார்கள். முஜாஹித் அவர்கள் மேலும் கூறினார்கள்: \"ஸாமிரி தன் கையில் இருந்ததை இஸ்ரவேலர்களின் ஆபரணங்கள் மீது எறிந்தான். அது ஒரு கன்றுக்குட்டியின் உருவமாக மாறியது; அதிலிருந்து ஒரு மெல்லிய சத்தம் எழுந்தது. அதனுள் புகுந்த காற்றே அந்தச் சத்தத்திற்குக் காரணமாக அமைந்தது.\" ஆகவே அவன் கூறினான்: ﴾فَنَبَذْتُهَا﴿\n\r\n\n\r\n(ஆகவே நான் அதனை எறிந்தேன்.) இதன் பொருள்: \"(ஆபரணங்களை) எறிந்து கொண்டிருந்தவர்களுடன் சேர்ந்து நானும் அதனை எறிந்தேன்\" என்பதாகும். ﴾وَكَذلِكَ سَوَّلَتْ لِى نَفْسِى﴿\n\r\n\n\r\n(இவ்வாறு என் மனம் எனக்குத் தூண்டியது.) அதாவது, அவனது மனது அச்செயலை ஒரு நல்ல காரியமாகச் சித்தரித்தது; அது அவனுக்குப் பிடித்தமானதாகவும் அமைந்தது.\n\r\n\n\r\nஸாமிரியின் தண்டனையும் கன்றுக்குட்டி எரிக்கப்பட்டதும்\n\r\n\n\r\n﴾قَالَ فَاذْهَبْ فَإِنَّ لَكَ فِى الْحَيَوةِ أَن تَقُولَ لاَ مِسَاسَ﴿\n\r\n\n\r\n(மூஸா (அலை) அவர்கள்) கூறினார்கள்: \"அப்படியானால் நீ போய்விடு! நிச்சயமாக இந்த வாழ்க்கையில் 'என்னைத் தொடாதீர்கள்' என்று கூறுவதே உனக்கான தண்டனையாகும்.\" இதன் பொருள்: \"எடுப்பதற்கும் தொடுவதற்கும் உனக்கு உரிமை இல்லாத அந்தத் தூதரின் காலடித் தடம் பட்ட மண்ணை நீ எடுத்துத் தொட்டாய். எனவே, 'என்னைத் தொடாதீர்கள்' என்று நீ சொல்லிக்கொண்டிருப்பதே இவ்வுலகில் உனக்குரிய தண்டனையாகும்.\" அதாவது, \"நீ மக்களைத் தொடமாட்டாய், மக்களும் உன்னைத் தொடமாட்டார்கள்.\" ﴾وَإِنَّ لَكَ مَوْعِداً﴿\n\r\n\n\r\n(நிச்சயமாக உனக்கு ஒரு வாக்குறுதி (தண்டனைக்காலம்) உண்டு.) இது மறுமை நாளைக் குறிக்கிறது. ﴾لَّن تُخْلَفَهُ﴿\n\r\n\n\r\n(அது உனக்கு மாற்றப்படாது.) அதிலிருந்து தப்பிக்க உனக்கு எந்த வழியும் இருக்காது. கதாதா அவர்கள் கூறினார்கள்: ﴾أَن تَقُولَ لاَ مِسَاسَ﴿\n\r\n\n\r\n('என்னைத் தொடாதீர்கள்' என்று நீ கூறுவாய்.) \"இது அவர்களுக்கும் அவர்களின் வழித்தோன்றல்களுக்கும் (அதாவது, அவர்களைப் போன்ற மனநிலையில் இருப்பவர்களுக்கும்) வழங்கப்பட்ட தண்டனையைக் குறிக்கிறது. அவர்கள் இன்றும் 'என்னைத் தொடாதீர்கள்' என்று கூறி வருகின்றனர்.\" அல்லாஹ்வின் கூற்றைப் பற்றி: ﴾وَإِنَّ لَكَ مَوْعِداً لَّن تُخْلَفَهُ﴿\n\r\n\n\r\n(நிச்சயமாக உனக்கு ஒரு வாக்குறுதி உண்டு, அது உனக்கு மாற்றப்படாது.) அல்-ஹஸன், கதாதா மற்றும் அபூ நஹிக் ஆகியோர் கூறுகையில்: \"நீ அதிலிருந்து தப்ப முடியாது\" என்றார்கள். ﴾وَانظُرْ إِلَى إِلَـهِكَ﴿\n\r\n\n\r\n(நீ வணங்கிக் கொண்டிருந்த உன்னுடைய அந்த இறைவனைப் பார்.) நீ எதை வணங்கினாயோ அதைப் பார். ﴾الَّذِى ظَلْتَ عَلَيْهِ عَاكِفاً﴿\n\r\n\n\r\n(எதனை நீ விடாது பற்றிப் பிடித்துக் கொண்டிருந்தாயோ.) எதனை நீ தொடர்ந்து வணங்கி வந்தாயோ - அதாவது அந்தக் கன்றுக்குட்டி. ﴾لَّنُحَرِّقَنَّهُ ثُمَّ لَنَنسِفَنَّهُ فِى الْيَمِّ نَسْفاً﴿\n\r\n\n\r\n(நிச்சயமாக நாம் அதனை எரித்து, பின்னர் அதனைத் தூள் தூளாகக் கடலில் தூவிவிடுவோம்.) ﴾إِنَّمَآ إِلَـهُكُمُ اللَّهُ الَّذِى لا إِلَـهَ إِلاَّ هُوَ وَسِعَ كُلَّ شَىْءٍ عِلْماً ﴿\n\r\n\n\r\n(உங்கள் இறைவன் அல்லாஹ் ஒருவனே; அவனைத் தவிர வேறு இறைவன் இல்லை. அவன் எல்லாப் பொருட்களையும் தனது அறிவால் சூழ்ந்துள்ளான்.) மூஸா (அலை) அவர்கள் இஸ்ரவேலர்களிடம் கூறினார்கள்: \"இது உங்கள் இறைவன் அல்ல. உங்கள் இறைவன் அல்லாஹ் ஒருவன் தான். அவனைத் தவிர வணக்கத்திற்குரிய உண்மையான இறைவன் வேறு யாருமில்லை. அவனைத் தவிர வேறு யாருக்கும் வணக்கம் செய்வது தகுதியானது அல்ல. ஏனெனில், அனைத்தும் அவனையே சார்ந்துள்ளன; அனைத்தும் அவனது அடிமைகளே.\" அல்லாஹ்வின் கூற்றைப் பற்றி: ﴾وَسِعَ كُلَّ شَىْءٍ عِلْماً﴿\n\r\n\n\r\n(அவன் எல்லாப் பொருட்களையும் தனது அறிவால் சூழ்ந்துள்ளான்.) 'இல்ம்' (அறிவு) எனும் சொல் இங்குச் சிறப்பித்துக் கூறப்பட்டுள்ளது. அதாவது, அல்லாஹ் அனைத்தையும் அறிந்தவன் என்று பொருள்படும். ﴾أَحَاطَ بِكُلِّ شَىْءٍ عِلْمَا﴿\n\r\n\n\r\n((அல்லாஹ்) தனது அறிவால் எல்லாப் பொருட்களையும் சூழ்ந்துள்ளான்.) 65:12 மேலும் அவன் கூறுகிறான்: ﴾وَأَحْصَى كُلَّ شَىْءٍ عَدَداً﴿\n\r\n\n\r\n(அவன் எல்லாப் பொருட்களையும் எண்ணிக்கையினால் கணக்கிட்டு வைத்திருக்கிறான்.) 72:28 எனவே, ﴾لاَ يَعْزُبُ عَنْهُ مِثْقَالُ ذَرَّةٍ﴿\n\r\n\n\r\n(ஓர் அணுவளவும் அவனது அறிவிலிருந்து தப்புவதில்லை.) 34:3 அவன் மேலும் கூறுகிறான்: ﴾وَمَا تَسْقُطُ مِن وَرَقَةٍ إِلاَّ يَعْلَمُهَا وَلاَ حَبَّةٍ فِى ظُلُمَاتِ الْأَرْضِ وَلاَ رَطْبٍ وَلاَ يَابِسٍ إِلاَّ فِى كِتَابٍ مُّبِينٍ﴿\n\r\n\n\r\n(ஓர் இலை கீழே விழுந்தாலும் அவன் அதனை அறிகிறான். பூமியின் இருள்களில் உள்ள ஒரு தானியமானாலும், பசுமையானதோ அல்லது காய்ந்ததோ எதுவானாலும் அவை ஒரு தெளிவான பதிவேட்டில் (லவ்ஹுல் மஹ்ஃபூழில்) இல்லாமல் இல்லை.) 6:59 மேலும் அவன் கூறுகிறான்: ﴾وَمَا مِن دَابَّةٍ فِي الْأَرْضِ إِلاَّ عَلَى اللَّهِ رِزْقُهَا وَيَعْلَمُ مُسْتَقَرَّهَا وَمُسْتَوْدَعَهَا كُلٌّ فِى كِتَابٍ مُّبِينٍ ﴿\n\r\n\n\r\n(பூமியில் ஊர்ந்து செல்லும் உயிரினங்கள் எதுவாயினும் அவற்றிற்கு உணவளிக்கும் பொறுப்பு அல்லாஹ்வின் மீதே உள்ளது. அவை வசிக்குமிடத்தையும் அவை அடங்குமிடத்தையும் அவன் அறிகிறான். அனைத்தும் ஒரு தெளிவான பதிவேட்டில் உள்ளன.) 11:6 இதைக் குறிப்பிடும் பல வசனங்கள் உள்ளன."},"99":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=101\" class=\"link\">20:101</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:101 ஐ பார்க்கவும்"},"100":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=101\" class=\"link\">20:101</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:101 ஐ பார்க்கவும்"},"101":{"html":"<strong>முழு குர்ஆனும் அல்லாஹ்வின் நினைவூட்டலாகும்; அதைப் புறக்கணிப்போருக்கான தண்டனையை விவரித்தல்</strong><br />\r\n<br />\r\nமேன்மைமிக்க அல்லாஹ், நபி முஹம்மது (ஸல்) அவர்களிடம் கூறுகிறான்: \"(முஹம்மதே!) மூஸா (அலை) அவர்களின் வரலாற்றையும், அவருக்கும் ஃபிர்அவ்ன் மற்றும் அவனது படைகளுக்கும் இடையே நடந்தவற்றையும் அவை உண்மையில் நடந்தவாறே உங்களுக்கு நாம் கூறியுள்ளோம். அதேபோன்று, கடந்த கால நிகழ்வுகளை எந்தவொரு கூட்டலும் குறைத்தலும் இன்றி, அவை நிகழ்ந்தவாறே உங்களுக்கு நாம் விவரிக்கிறோம். மேலும், நம்மிடமிருந்து ஒரு நினைவூட்டலாக, மகத்தான குர்ஆனையும் உங்களுக்கு வழங்கியுள்ளோம்; அதற்கு முன்னாலோ பின்னாலோ எந்தப் பொய்யும் அதை நெருங்க முடியாது.\" இது மிக்க ஞானமுள்ள, பெரும் புகழுக்குரியவனிடமிருந்து அருளப்பட்ட வஹீ (இறைச்செய்தி) ஆகும். முந்தைய நபிமார்கள் அனுப்பப்பட்ட காலத்திலிருந்து, முஹம்மது (ஸல்) அவர்களின் வருகையோடு நபித்துவம் நிறைவுபெறும் வரை, எந்த ஒரு நபிக்கும் இதனைப் போன்ற அல்லது இதனை விடவும் முழுமையான ஒரு வேதம் வழங்கப்படவில்லை. கடந்த கால மற்றும் எதிர்கால நிகழ்வுகளைப் பற்றி குர்ஆனைக் காட்டிலும் அதிக தகவல்களைக் கொண்ட வேறெந்த வேதமும் எந்த நபிக்கும் வழங்கப்படவில்லை. மனிதர்களுக்கு இடையிலான வேறுபாடுகளைத் தீர்மானிக்கும் தீர்ப்பு இதிலிருந்தே பெறப்படுகிறது. எனவே, அல்லாஹ் அதைப் பற்றி இவ்வாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَّنْ</span> <span class=\"quran-arabic-font text-success\">أَعْرَضَ</span> <span class=\"quran-arabic-font text-success\">عَنْهُ</span><br />\r\n<br />\r\n(எவர் அதைப் புறக்கணிக்கிறாரோ,) இதன் பொருள், எவர் குர்ஆனை மறுத்து, அதன் கட்டளைகளையும் அறிவுரைகளையும் பின்பற்றுவதைத் தவிர்த்து, அதையல்லாத வேறு ஒன்றில் நேர்வழியைத் தேடுகிறாரோ, அவரை அல்லாஹ் வழிகேட்டில் விட்டுவிட்டு, நரகத்தின் பாதையில் செலுத்திவிடுவான். இதனால்தான் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَّنْ</span> <span class=\"quran-arabic-font text-success\">أَعْرَضَ</span> <span class=\"quran-arabic-font text-success\">عَنْهُ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">يَحْمِلُ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَةِ</span> <span class=\"quran-arabic-font text-success\">وِزْرًا</span><br />\r\n<br />\r\n(எவர் அதைப் புறக்கணிக்கிறாரோ, நிச்சயமாக அவர் மறுமை நாளில் ஒரு பெரும் சுமையைச் சுமப்பார்.) இங்கு சுமை என்பது பாவத்தைக் குறிக்கிறது. இது அல்லாஹ் கூறுவது போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">يَكْفُرْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْأَحْزَابِ</span> <span class=\"quran-arabic-font text-success\">فَالنَّارُ</span> <span class=\"quran-arabic-font text-success\">مَوْعِدُهُ</span><br />\r\n<br />\r\n(ஆனால், பல்வேறு கூட்டத்தினரில் எவர் அதை நிராகரிக்கிறாரோ, அவருக்கு வாக்களிக்கப்பட்ட இடம் நரக நெருப்பு தான்.) <a href=\"qurandisp.php?sura=11&ayah=17\" class=\"link\">11:17</a>. இது குர்ஆன் சென்றடையும் அரபுகள், அரபல்லாதவர்கள், வேதமுடையவர்கள் மற்றும் பிறர் என அனைவருக்கும் பொதுவாகப் பொருந்தும். அல்லாஹ் இவ்வாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِأُنذِرَكُم</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">بَلَغَ</span><br />\r\n<br />\r\n(இதன் மூலம் உங்களையும், இது எவரைச் சென்றடைகிறதோ அவரையும் நான் எச்சரிப்பதற்காக.) <a href=\"qurandisp.php?sura=6&ayah=19\" class=\"link\">6:19</a>. குர்ஆன், அது சென்றடையும் ஒவ்வொருவருக்கும் ஓர் இறுதி எச்சரிக்கையாகும். எவர் அதைப் பின்பற்றுகிறாரோ அவர் நேர்வழி பெற்றவராவார்; எவர் அதனை எதிர்த்துப் புறக்கணிக்கிறாரோ அவர் வழிகெட்டவராவார். அவர் இவ்வுலக வாழ்வில் துரதிர்ஷ்டசாலியாக இருப்பார், மேலும் மறுமை நாளில் அவருடைய தங்குமிடம் நரக நெருப்பாக இருக்கும் என்று அவருக்கு எச்சரிக்கப்பட்டுள்ளது. இதன்காரணமாகவே அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَّنْ</span> <span class=\"quran-arabic-font text-success\">أَعْرَضَ</span> <span class=\"quran-arabic-font text-success\">عَنْهُ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">يَحْمِلُ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَةِ</span> <span class=\"quran-arabic-font text-success\">وِزْرًا</span> <span class=\"quran-arabic-font text-success\">خَالِدِينَ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span><br />\r\n<br />\r\n(எவர் அதைப் புறக்கணிக்கிறாரோ, நிச்சயமாக அவர் மறுமை நாளில் ஒரு பெரும் சுமையைச் சுமப்பார். அதில் அவர்கள் நிரந்தரமாகத் தங்குவார்கள்.) <a href=\"qurandisp.php?sura=20&ayah=100\" class=\"link\">20:100</a>-101. அவர்களால் இதைத் தவிர்க்கவோ அல்லது இதிலிருந்து தப்பிக்கவோ முடியாது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَسَاءَ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَةِ</span> <span class=\"quran-arabic-font text-success\">حِمْلًا</span><br />\r\n<br />\r\n(மறுமை நாளில் அந்தச் சுமை அவர்களுக்கு மிகவும் கெட்டதாக இருக்கும்.)<br />\r\n<br />\r\n<br />\r\n<br />","text":"முழு குர்ஆனும் அல்லாஹ்வின் நினைவூட்டலாகும்; அதைப் புறக்கணிப்போருக்கான தண்டனையை விவரித்தல்\n\r\n\n\r\nமேன்மைமிக்க அல்லாஹ், நபி முஹம்மது (ஸல்) அவர்களிடம் கூறுகிறான்: \"(முஹம்மதே!) மூஸா (அலை) அவர்களின் வரலாற்றையும், அவருக்கும் ஃபிர்அவ்ன் மற்றும் அவனது படைகளுக்கும் இடையே நடந்தவற்றையும் அவை உண்மையில் நடந்தவாறே உங்களுக்கு நாம் கூறியுள்ளோம். அதேபோன்று, கடந்த கால நிகழ்வுகளை எந்தவொரு கூட்டலும் குறைத்தலும் இன்றி, அவை நிகழ்ந்தவாறே உங்களுக்கு நாம் விவரிக்கிறோம். மேலும், நம்மிடமிருந்து ஒரு நினைவூட்டலாக, மகத்தான குர்ஆனையும் உங்களுக்கு வழங்கியுள்ளோம்; அதற்கு முன்னாலோ பின்னாலோ எந்தப் பொய்யும் அதை நெருங்க முடியாது.\" இது மிக்க ஞானமுள்ள, பெரும் புகழுக்குரியவனிடமிருந்து அருளப்பட்ட வஹீ (இறைச்செய்தி) ஆகும். முந்தைய நபிமார்கள் அனுப்பப்பட்ட காலத்திலிருந்து, முஹம்மது (ஸல்) அவர்களின் வருகையோடு நபித்துவம் நிறைவுபெறும் வரை, எந்த ஒரு நபிக்கும் இதனைப் போன்ற அல்லது இதனை விடவும் முழுமையான ஒரு வேதம் வழங்கப்படவில்லை. கடந்த கால மற்றும் எதிர்கால நிகழ்வுகளைப் பற்றி குர்ஆனைக் காட்டிலும் அதிக தகவல்களைக் கொண்ட வேறெந்த வேதமும் எந்த நபிக்கும் வழங்கப்படவில்லை. மனிதர்களுக்கு இடையிலான வேறுபாடுகளைத் தீர்மானிக்கும் தீர்ப்பு இதிலிருந்தே பெறப்படுகிறது. எனவே, அல்லாஹ் அதைப் பற்றி இவ்வாறு கூறுகிறான்:\n\r\n\n\r\nمَّنْ أَعْرَضَ عَنْهُ\n\r\n\n\r\n(எவர் அதைப் புறக்கணிக்கிறாரோ,) இதன் பொருள், எவர் குர்ஆனை மறுத்து, அதன் கட்டளைகளையும் அறிவுரைகளையும் பின்பற்றுவதைத் தவிர்த்து, அதையல்லாத வேறு ஒன்றில் நேர்வழியைத் தேடுகிறாரோ, அவரை அல்லாஹ் வழிகேட்டில் விட்டுவிட்டு, நரகத்தின் பாதையில் செலுத்திவிடுவான். இதனால்தான் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nمَّنْ أَعْرَضَ عَنْهُ فَإِنَّهُ يَحْمِلُ يَوْمَ الْقِيَامَةِ وِزْرًا\n\r\n\n\r\n(எவர் அதைப் புறக்கணிக்கிறாரோ, நிச்சயமாக அவர் மறுமை நாளில் ஒரு பெரும் சுமையைச் சுமப்பார்.) இங்கு சுமை என்பது பாவத்தைக் குறிக்கிறது. இது அல்லாஹ் கூறுவது போன்றதாகும்:\n\r\n\n\r\nوَمَن يَكْفُرْ بِهِ مِنَ الْأَحْزَابِ فَالنَّارُ مَوْعِدُهُ\n\r\n\n\r\n(ஆனால், பல்வேறு கூட்டத்தினரில் எவர் அதை நிராகரிக்கிறாரோ, அவருக்கு வாக்களிக்கப்பட்ட இடம் நரக நெருப்பு தான்.) 11:17. இது குர்ஆன் சென்றடையும் அரபுகள், அரபல்லாதவர்கள், வேதமுடையவர்கள் மற்றும் பிறர் என அனைவருக்கும் பொதுவாகப் பொருந்தும். அல்லாஹ் இவ்வாறு கூறுகிறான்:\n\r\n\n\r\nلِأُنذِرَكُم بِهِ وَمَن بَلَغَ\n\r\n\n\r\n(இதன் மூலம் உங்களையும், இது எவரைச் சென்றடைகிறதோ அவரையும் நான் எச்சரிப்பதற்காக.) 6:19. குர்ஆன், அது சென்றடையும் ஒவ்வொருவருக்கும் ஓர் இறுதி எச்சரிக்கையாகும். எவர் அதைப் பின்பற்றுகிறாரோ அவர் நேர்வழி பெற்றவராவார்; எவர் அதனை எதிர்த்துப் புறக்கணிக்கிறாரோ அவர் வழிகெட்டவராவார். அவர் இவ்வுலக வாழ்வில் துரதிர்ஷ்டசாலியாக இருப்பார், மேலும் மறுமை நாளில் அவருடைய தங்குமிடம் நரக நெருப்பாக இருக்கும் என்று அவருக்கு எச்சரிக்கப்பட்டுள்ளது. இதன்காரணமாகவே அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nمَّنْ أَعْرَضَ عَنْهُ فَإِنَّهُ يَحْمِلُ يَوْمَ الْقِيَامَةِ وِزْرًا خَالِدِينَ فِيهِ\n\r\n\n\r\n(எவர் அதைப் புறக்கணிக்கிறாரோ, நிச்சயமாக அவர் மறுமை நாளில் ஒரு பெரும் சுமையைச் சுமப்பார். அதில் அவர்கள் நிரந்தரமாகத் தங்குவார்கள்.) 20:100-101. அவர்களால் இதைத் தவிர்க்கவோ அல்லது இதிலிருந்து தப்பிக்கவோ முடியாது.\n\r\n\n\r\nوَسَاءَ لَهُمْ يَوْمَ الْقِيَامَةِ حِمْلًا\n\r\n\n\r\n(மறுமை நாளில் அந்தச் சுமை அவர்களுக்கு மிகவும் கெட்டதாக இருக்கும்.)"},"102":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=104\" class=\"link\">20:104</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:104 ஐ பார்க்கவும்"},"103":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=104\" class=\"link\">20:104</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:104 ஐ பார்க்கவும்"},"104":{"html":"<strong>ஸூர் ஊதப்படுதலும் மறுமை நாளும்</strong><br />\r\n<br />\r\nஅல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் ஸூர் (எக்காளம்) பற்றிக் கேட்கப்பட்டபோது, அவர்கள், «<span class=\"quran-arabic-font text-success\">قَرْنٌ</span> <span class=\"quran-arabic-font text-success\">يُنْفَخُ</span> <span class=\"quran-arabic-font text-success\">فِيه</span>» (அது ஊதப்படக்கூடிய ஒரு கொம்பாகும்) என்று பதிலளித்தார்கள் என ஒரு ஹதீஸில் உறுதிப்படுத்தப்பட்டுள்ளது. ஸூர் என்பது வானங்கள் மற்றும் பூமியின் அகலத்திற்கு நிகரான சுற்றளவு கொண்ட ஒரு பிரம்மாண்டமான கொம்பு என்று அபூ ஹுரைரா (ரழி) அவர்கள் வழியாக அறிவிக்கப்படும் ஹதீஸில் கூறப்பட்டுள்ளது. இஸ்ராஃபீல் (அலை) அவர்கள் அதில் ஊதுவார்கள். நபி (ஸல்) அவர்கள் கூறியதாவது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">كَيْفَ</span> <span class=\"quran-arabic-font text-success\">أَنْعَمُ</span> <span class=\"quran-arabic-font text-success\">وَصَاحِبُ</span> <span class=\"quran-arabic-font text-success\">الْقَرْنِ</span> <span class=\"quran-arabic-font text-success\">قَدِ</span> <span class=\"quran-arabic-font text-success\">الْتَقَمَ</span> <span class=\"quran-arabic-font text-success\">الْقَرْنَ</span> <span class=\"quran-arabic-font text-success\">وَحَنَى</span> <span class=\"quran-arabic-font text-success\">جَبْهَتَهُ،</span> <span class=\"quran-arabic-font text-success\">وَاسْتَمَعَ</span> <span class=\"quran-arabic-font text-success\">مَتَى</span> <span class=\"quran-arabic-font text-success\">يُؤْمَرُ</span>»<br />\r\n<br />\r\n(ஸூருக்குரியவர் அக்கொம்பைத் தம் வாயில் வைத்து, எப்போது கட்டளையிடப்படும் என்று செவிமடுத்துத் தன் நெற்றியைச் சாய்த்துக் காத்திருக்கும் நிலையில் நான் எவ்வாறு நிம்மதியாக இருக்க முடியும்?) என்று மற்றொரு ஹதீஸில் கூறப்பட்டுள்ளது. “அல்லாஹ்வின் தூதரே! நாங்கள் என்ன கூற வேண்டும்?” என்று மக்கள் கேட்டார்கள். அதற்கு அவர்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">قُولُوا</span>: <span class=\"quran-arabic-font text-success\">حَسْبُنَا</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">وَنِعْمَ</span> <span class=\"quran-arabic-font text-success\">الْوَكِيلُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">تَوَكَّلْنَا</span>»<br />\r\n<br />\r\n(கூறுங்கள்: அல்லாஹ்வே எங்களுக்குப் போதுமானவன்; அவன் மிகச்சிறந்த பாதுகாப்பாளன். அல்லாஹ்வின் மீதே நாங்கள் முழுமையாக நம்பிக்கை வைக்கிறோம்) எனக் கூறினார்கள்.<br />\r\n<br />\r\nஅவனது (அல்லாஹ்வின்) கூற்றான:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَنَحْشُرُ</span> <span class=\"quran-arabic-font text-success\">الْمُجْرِمِينَ</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">زُرْقاً</span><br />\r\n<br />\r\n(அந்நாளில் குற்றவாளிகளை நீலக் கண்களுடையோராக நாம் ஒன்றுதிரட்டுவோம்) என்பதில், அந்தப் பயங்கரமான சூழ்நிலையின் கடுமையால் அவர்களின் கண்கள் நீல நிறமாக மாறும் எனக் கூறப்பட்டுள்ளது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَتَخَافَتُونَ</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمْ</span><br />\r\n<br />\r\n(அவர்கள் தங்களுக்குள் மிக மெல்லிய குரலில் பேசிக்கொள்வார்கள்.) இப்னு அப்பாஸ் (ரழி) அவர்கள், “இதன் பொருள் தங்களுக்குள் இரகசியமாகப் பேசுவதாகும்” என்று கூறினார்கள். அதாவது, அவர்களில் சிலர் மற்றவர்களிடம்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">لَّبِثْتُمْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">عَشْراً</span><br />\r\n<br />\r\n(நீங்கள் பத்து நாட்களுக்கு மேல் தங்கவில்லை) என்று கூறுவார்கள். அதாவது இவ்வுலக வாழ்க்கையில் நீங்கள் மிகக் குறைந்த காலமே தங்கியிருந்தீர்கள்; அந்தக் காலம் பத்து நாட்களுக்கு நிகரானதாகவே இருந்தது. பிறகு, உயர்ந்தோனாகிய அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">نَّحْنُ</span> <span class=\"quran-arabic-font text-success\">أَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">يَقُولُونَ</span><br />\r\n<br />\r\n(அவர்கள் என்ன பேசிக்கொள்வார்கள் என்பதை நாம் நன்கு அறிவோம்,) அதாவது, அவர்கள் தங்களுக்குள் உரையாடிக்கொண்டிருக்கும் நிலையை (நாம் அறிவோம்).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">يَقُولُ</span> <span class=\"quran-arabic-font text-success\">أَمْثَلُهُمْ</span> <span class=\"quran-arabic-font text-success\">طَرِيقَةً</span><br />\r\n<br />\r\n(அவர்களில் அறிவிலும் விவேகத்திலும் சிறந்தவர் கூறும்போது;) அவர்களில் மிகச் சிறந்த புத்திசாலித்தனம் கொண்டவர்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">لَّبِثْتُمْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">يَوْماً</span><br />\r\n<br />\r\n(நீங்கள் ஒரு நாளைத் தவிர அதிகமாகத் தங்கவில்லை!) என்று கூறுவார். ஏனெனில், மறுமை நாளில் அவர்கள் இவ்வுலக வாழ்க்கையின் சுருக்கத்தை உணர்வார்கள். மீண்டும் மீண்டும் வரும் காலங்கள், அடுத்தடுத்து வரும் இரவுகள், பகல்கள் மற்றும் மணிநேரங்களைக் கொண்ட இவ்வுலக வாழ்க்கை, வெறும் ஒரு நாளைப் போலவே தோன்றும். இதன் காரணமாகவே, மறுமை நாளில் நிராகரிப்பாளர்கள் இவ்வுலக வாழ்க்கையை மிகக் குறுகியதாகக் கருதுவார்கள். தங்களுக்கு வழங்கப்பட்ட அவகாசம் மிகக் குறைவு என்று வாதிட்டு, தங்களுக்கு எதிராகச் சான்றுகள் நிலைநாட்டப்படுவதைத் தடுக்க அவர்கள் முயல்வார்கள். இதைப் பற்றி அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَوْمَ</span> <span class=\"quran-arabic-font text-success\">تَقُومُ</span> <span class=\"quran-arabic-font text-success\">السَّاعَةُ</span> <span class=\"quran-arabic-font text-success\">يُقْسِمُ</span> <span class=\"quran-arabic-font text-success\">الْمُجْرِمُونَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">لَبِثُواْ</span> <span class=\"quran-arabic-font text-success\">غَيْرَ</span> <span class=\"quran-arabic-font text-success\">سَاعَةٍ</span><br />\r\n<br />\r\n(மேலும், மறுமை நாள் நிலைபெறும் நாளில், குற்றவாளிகள் தாங்கள் ஒரு மணி நேரமேயன்றி அதிகமாக உலகில் தங்கவில்லை என்று சத்தியம் செய்வார்கள்) அவனது கூற்று வரும் வரை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَكِنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">كُنتمْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَعْلَمُونَ</span><br />\r\n<br />\r\n(ஆனால், நீங்கள் இதனை அறியாதவர்களாக இருந்தீர்கள்.) <a href=\"qurandisp.php?sura=30&ayah=55\" class=\"link\">30:55</a>-56<br />\r\n<br />\r\nஅல்லாஹ் மேலும் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَوَلَمْ</span> <span class=\"quran-arabic-font text-success\">نُعَمِّرْكُمْ</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">يَتَذَكَّرُ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">تَذَكَّرَ</span> <span class=\"quran-arabic-font text-success\">وَجَآءَكُمُ</span> <span class=\"quran-arabic-font text-success\">النَّذِيرُ</span><br />\r\n<br />\r\n(சிந்தித்துப் பார்க்கக் கூடியவர் சிந்திக்கும் அளவுக்கு நாம் உங்களுக்கு நீண்ட ஆயுளைத் தரவில்லையா? மேலும், எச்சரிப்பவரும் உங்களிடம் வந்தாரே!) <a href=\"qurandisp.php?sura=35&ayah=37\" class=\"link\">35:37</a><br />\r\n<br />\r\nஉயர்ந்தோனாகிய அல்லாஹ் மேலும் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">كَمْ</span> <span class=\"quran-arabic-font text-success\">لَبِثْتُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">عَدَدَ</span> <span class=\"quran-arabic-font text-success\">سِنِينَ</span> - <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">لَبِثْنَا</span> <span class=\"quran-arabic-font text-success\">يَوْماً</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">بَعْضَ</span> <span class=\"quran-arabic-font text-success\">يَوْمٍ</span> <span class=\"quran-arabic-font text-success\">فَاسْأَلِ</span> <span class=\"quran-arabic-font text-success\">الْعَآدِّينَ</span> - <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">لَّبِثْتُمْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">قَلِيلاً</span> <span class=\"quran-arabic-font text-success\">لَّوْ</span> <span class=\"quran-arabic-font text-success\">أَنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">تَعْلَمُونَ</span><br />\r\n<br />\r\n((அல்லாஹ் கேட்பான்:) பூமியில் நீங்கள் எத்தனை ஆண்டுகள் தங்கியிருந்தீர்கள்? அவர்கள் கூறுவார்கள்: “நாங்கள் ஒரு நாள் அல்லது ஒரு நாளின் சிறு பகுதி தங்கியிருந்தோம்; கணக்கிடுபவர்களிடம் கேட்டுப் பாருங்கள்.” அதற்கு அவன் (அல்லாஹ்) கூறுவான்: “நீங்கள் அறிந்திருந்தால், (உண்மையில்) நீங்கள் மிகக் கொஞ்ச காலமே தங்கியிருந்தீர்கள் என்பது உங்களுக்குத் தெரிந்திருக்கும்!” ) <a href=\"qurandisp.php?sura=23&ayah=112\" class=\"link\">23:112</a>-114<br />\r\n<br />\r\nஅதாவது, நீங்கள் பூமியில் மிகக் குறைந்த காலமே தங்கியிருந்தீர்கள். இதனை நீங்கள் உணர்ந்திருந்தால், நிலையற்ற இவ்வுலக வாழ்க்கையை விட நிலையான மறுமை வாழ்க்கையையேத் தேர்ந்தெடுத்திருப்பீர்கள். ஆனால், நீங்களோ தீய வழியில் நடந்து, நிலையான மற்றும் நிரந்தரமான வாழ்க்கையை விட தற்காலிகமான இவ்வுலக வாழ்க்கைக்கு முன்னுரிமை அளித்தீர்கள்.<br />\r\n<br />","text":"ஸூர் ஊதப்படுதலும் மறுமை நாளும்\n\r\n\n\r\nஅல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் ஸூர் (எக்காளம்) பற்றிக் கேட்கப்பட்டபோது, அவர்கள், «قَرْنٌ يُنْفَخُ فِيه» (அது ஊதப்படக்கூடிய ஒரு கொம்பாகும்) என்று பதிலளித்தார்கள் என ஒரு ஹதீஸில் உறுதிப்படுத்தப்பட்டுள்ளது. ஸூர் என்பது வானங்கள் மற்றும் பூமியின் அகலத்திற்கு நிகரான சுற்றளவு கொண்ட ஒரு பிரம்மாண்டமான கொம்பு என்று அபூ ஹுரைரா (ரழி) அவர்கள் வழியாக அறிவிக்கப்படும் ஹதீஸில் கூறப்பட்டுள்ளது. இஸ்ராஃபீல் (அலை) அவர்கள் அதில் ஊதுவார்கள். நபி (ஸல்) அவர்கள் கூறியதாவது:\n\r\n\n\r\n«كَيْفَ أَنْعَمُ وَصَاحِبُ الْقَرْنِ قَدِ الْتَقَمَ الْقَرْنَ وَحَنَى جَبْهَتَهُ، وَاسْتَمَعَ مَتَى يُؤْمَرُ»\n\r\n\n\r\n(ஸூருக்குரியவர் அக்கொம்பைத் தம் வாயில் வைத்து, எப்போது கட்டளையிடப்படும் என்று செவிமடுத்துத் தன் நெற்றியைச் சாய்த்துக் காத்திருக்கும் நிலையில் நான் எவ்வாறு நிம்மதியாக இருக்க முடியும்?) என்று மற்றொரு ஹதீஸில் கூறப்பட்டுள்ளது. “அல்லாஹ்வின் தூதரே! நாங்கள் என்ன கூற வேண்டும்?” என்று மக்கள் கேட்டார்கள். அதற்கு அவர்கள்:\n\r\n\n\r\n«قُولُوا: حَسْبُنَا اللهُ وَنِعْمَ الْوَكِيلُ عَلَى اللهِ تَوَكَّلْنَا»\n\r\n\n\r\n(கூறுங்கள்: அல்லாஹ்வே எங்களுக்குப் போதுமானவன்; அவன் மிகச்சிறந்த பாதுகாப்பாளன். அல்லாஹ்வின் மீதே நாங்கள் முழுமையாக நம்பிக்கை வைக்கிறோம்) எனக் கூறினார்கள்.\n\r\n\n\r\nஅவனது (அல்லாஹ்வின்) கூற்றான:\n\r\n\n\r\nوَنَحْشُرُ الْمُجْرِمِينَ يَوْمَئِذٍ زُرْقاً\n\r\n\n\r\n(அந்நாளில் குற்றவாளிகளை நீலக் கண்களுடையோராக நாம் ஒன்றுதிரட்டுவோம்) என்பதில், அந்தப் பயங்கரமான சூழ்நிலையின் கடுமையால் அவர்களின் கண்கள் நீல நிறமாக மாறும் எனக் கூறப்பட்டுள்ளது.\n\r\n\n\r\nيَتَخَافَتُونَ بَيْنَهُمْ\n\r\n\n\r\n(அவர்கள் தங்களுக்குள் மிக மெல்லிய குரலில் பேசிக்கொள்வார்கள்.) இப்னு அப்பாஸ் (ரழி) அவர்கள், “இதன் பொருள் தங்களுக்குள் இரகசியமாகப் பேசுவதாகும்” என்று கூறினார்கள். அதாவது, அவர்களில் சிலர் மற்றவர்களிடம்:\n\r\n\n\r\nإِن لَّبِثْتُمْ إِلاَّ عَشْراً\n\r\n\n\r\n(நீங்கள் பத்து நாட்களுக்கு மேல் தங்கவில்லை) என்று கூறுவார்கள். அதாவது இவ்வுலக வாழ்க்கையில் நீங்கள் மிகக் குறைந்த காலமே தங்கியிருந்தீர்கள்; அந்தக் காலம் பத்து நாட்களுக்கு நிகரானதாகவே இருந்தது. பிறகு, உயர்ந்தோனாகிய அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nنَّحْنُ أَعْلَمُ بِمَا يَقُولُونَ\n\r\n\n\r\n(அவர்கள் என்ன பேசிக்கொள்வார்கள் என்பதை நாம் நன்கு அறிவோம்,) அதாவது, அவர்கள் தங்களுக்குள் உரையாடிக்கொண்டிருக்கும் நிலையை (நாம் அறிவோம்).\n\r\n\n\r\nإِذْ يَقُولُ أَمْثَلُهُمْ طَرِيقَةً\n\r\n\n\r\n(அவர்களில் அறிவிலும் விவேகத்திலும் சிறந்தவர் கூறும்போது;) அவர்களில் மிகச் சிறந்த புத்திசாலித்தனம் கொண்டவர்:\n\r\n\n\r\nإِن لَّبِثْتُمْ إِلاَّ يَوْماً\n\r\n\n\r\n(நீங்கள் ஒரு நாளைத் தவிர அதிகமாகத் தங்கவில்லை!) என்று கூறுவார். ஏனெனில், மறுமை நாளில் அவர்கள் இவ்வுலக வாழ்க்கையின் சுருக்கத்தை உணர்வார்கள். மீண்டும் மீண்டும் வரும் காலங்கள், அடுத்தடுத்து வரும் இரவுகள், பகல்கள் மற்றும் மணிநேரங்களைக் கொண்ட இவ்வுலக வாழ்க்கை, வெறும் ஒரு நாளைப் போலவே தோன்றும். இதன் காரணமாகவே, மறுமை நாளில் நிராகரிப்பாளர்கள் இவ்வுலக வாழ்க்கையை மிகக் குறுகியதாகக் கருதுவார்கள். தங்களுக்கு வழங்கப்பட்ட அவகாசம் மிகக் குறைவு என்று வாதிட்டு, தங்களுக்கு எதிராகச் சான்றுகள் நிலைநாட்டப்படுவதைத் தடுக்க அவர்கள் முயல்வார்கள். இதைப் பற்றி அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَيَوْمَ تَقُومُ السَّاعَةُ يُقْسِمُ الْمُجْرِمُونَ مَا لَبِثُواْ غَيْرَ سَاعَةٍ\n\r\n\n\r\n(மேலும், மறுமை நாள் நிலைபெறும் நாளில், குற்றவாளிகள் தாங்கள் ஒரு மணி நேரமேயன்றி அதிகமாக உலகில் தங்கவில்லை என்று சத்தியம் செய்வார்கள்) அவனது கூற்று வரும் வரை:\n\r\n\n\r\nوَلَكِنَّكُمْ كُنتمْ لاَ تَعْلَمُونَ\n\r\n\n\r\n(ஆனால், நீங்கள் இதனை அறியாதவர்களாக இருந்தீர்கள்.) 30:55-56\n\r\n\n\r\nஅல்லாஹ் மேலும் கூறுகிறான்:\n\r\n\n\r\nأَوَلَمْ نُعَمِّرْكُمْ مَّا يَتَذَكَّرُ فِيهِ مَن تَذَكَّرَ وَجَآءَكُمُ النَّذِيرُ\n\r\n\n\r\n(சிந்தித்துப் பார்க்கக் கூடியவர் சிந்திக்கும் அளவுக்கு நாம் உங்களுக்கு நீண்ட ஆயுளைத் தரவில்லையா? மேலும், எச்சரிப்பவரும் உங்களிடம் வந்தாரே!) 35:37\n\r\n\n\r\nஉயர்ந்தோனாகிய அல்லாஹ் மேலும் கூறுகிறான்:\n\r\n\n\r\nقَالَ كَمْ لَبِثْتُمْ فِى الْأَرْضِ عَدَدَ سِنِينَ - قَالُواْ لَبِثْنَا يَوْماً أَوْ بَعْضَ يَوْمٍ فَاسْأَلِ الْعَآدِّينَ - قَالَ إِن لَّبِثْتُمْ إِلاَّ قَلِيلاً لَّوْ أَنَّكُمْ كُنتُمْ تَعْلَمُونَ\n\r\n\n\r\n((அல்லாஹ் கேட்பான்:) பூமியில் நீங்கள் எத்தனை ஆண்டுகள் தங்கியிருந்தீர்கள்? அவர்கள் கூறுவார்கள்: “நாங்கள் ஒரு நாள் அல்லது ஒரு நாளின் சிறு பகுதி தங்கியிருந்தோம்; கணக்கிடுபவர்களிடம் கேட்டுப் பாருங்கள்.” அதற்கு அவன் (அல்லாஹ்) கூறுவான்: “நீங்கள் அறிந்திருந்தால், (உண்மையில்) நீங்கள் மிகக் கொஞ்ச காலமே தங்கியிருந்தீர்கள் என்பது உங்களுக்குத் தெரிந்திருக்கும்!” ) 23:112-114\n\r\n\n\r\nஅதாவது, நீங்கள் பூமியில் மிகக் குறைந்த காலமே தங்கியிருந்தீர்கள். இதனை நீங்கள் உணர்ந்திருந்தால், நிலையற்ற இவ்வுலக வாழ்க்கையை விட நிலையான மறுமை வாழ்க்கையையேத் தேர்ந்தெடுத்திருப்பீர்கள். ஆனால், நீங்களோ தீய வழியில் நடந்து, நிலையான மற்றும் நிரந்தரமான வாழ்க்கையை விட தற்காலிகமான இவ்வுலக வாழ்க்கைக்கு முன்னுரிமை அளித்தீர்கள்."},"105":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=108\" class=\"link\">20:108</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:108 ஐ பார்க்கவும்"},"106":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=108\" class=\"link\">20:108</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:108 ஐ பார்க்கவும்"},"107":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=108\" class=\"link\">20:108</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:108 ஐ பார்க்கவும்"},"108":{"html":"<strong>மலைகள் அழிக்கப்படுவதும், பூமி ஒரு சமதளமாக மாறுவதும்</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான், <span class=\"quran-arabic-font text-success\">﴾وَيَسْأَلُونَكَ</span> <span class=\"quran-arabic-font text-success\">عَنِ</span> <span class=\"quran-arabic-font text-success\">الْجِبَالِ﴿</span><br />\r\n<br />\r\n(மேலும், அவர்கள் மலைகளைப் பற்றி உம்மிடம் (ஸல்) கேட்கிறார்கள்.) மறுமை நாளில் அந்த மலைகள் அப்படியே இருக்குமா அல்லது அழிந்துவிடுமா என்பதுதான் இந்தக் கேள்வி. <span class=\"quran-arabic-font text-success\">﴾فَقُلْ</span> <span class=\"quran-arabic-font text-success\">يَنسِفُهَا</span> <span class=\"quran-arabic-font text-success\">رَبِّى</span> <span class=\"quran-arabic-font text-success\">نَسْفاً﴿</span><br />\r\n<br />\r\n(நீர் கூறுவீராக: \"என் இறைவன் அவற்றை வெடிக்கச் செய்து தூள் தூளாகச் சிதறடித்துவிடுவான்.\") இதன் பொருள் என்னவென்றால், அல்லாஹ் அவற்றை அவற்றின் இடங்களிலிருந்து அகற்றி, முற்றிலும் துடைத்தெறிந்து அப்புறப்படுத்திவிடுவான். <span class=\"quran-arabic-font text-success\">﴾فَيَذَرُهَا﴿</span><br />\r\n<br />\r\n(பின்னர் அவன் அதனை விட்டுவிடுவான்;) இது பூமியைக் குறிக்கிறது; <span class=\"quran-arabic-font text-success\">﴾قَاعاً</span> <span class=\"quran-arabic-font text-success\">صَفْصَفاً﴿</span><br />\r\n<br />\r\n(வெட்டவெளியான ஒரு சமதளமாக.) இதன் பொருள், சீராகப் பரந்து விரிந்த ஒரு சமவெளி என்பதாகும். 'காஃ' (Qa`) என்பது சமமான நிலப்பகுதியைக் குறிக்கும், 'ஸஃப்ஸஃபா' (Safsafa) என்ற சொல் இந்த அர்த்தத்தை வலியுறுத்தப் பயன்படுத்தப்படுகிறது. 'ஸஃப்ஸஃபா' என்பதற்கு எந்தத் தாவரமும் வளராத நிலம் என்றும் ஒரு கருத்து உண்டு. இரண்டாவது கருத்தும் இதில் அடங்கும் என்றாலும், முதல் கருத்தே முன்னுரிமை பெறுகிறது. இது குறித்து அல்லாஹ் கூறுகிறான், <span class=\"quran-arabic-font text-success\">﴾لاَّ</span> <span class=\"quran-arabic-font text-success\">تَرَى</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">عِوَجاً</span> <span class=\"quran-arabic-font text-success\">وَلا</span> <span class=\"quran-arabic-font text-success\">أَمْتاً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அதில் நீர் எந்தக் கோணலையோ மேடுபள்ளத்தையோ காணமாட்டீர்.) அதாவது, அந்த நாளில் பூமியில் எந்தப் பள்ளத்தாக்கையும், குன்றையும் அல்லது தாழ்வான, உயரமான எந்த இடத்தையும் நீர் காணமாட்டீர். இப்னு அப்பாஸ் (ரழி), இக்ரிமா (ரழி), முஜாஹித் (ரழி), அல்-ஹஸன் அல்-பஸரி (ரழி), அத்-தஹ்ஹாக் (ரழி), கத்தாதா (ரழி) உள்ளிட்ட ஸலஃபுகள் (முன்னோர்கள்) அனைவரும் இதையே கூறியுள்ளார்கள். <br />\r\n<br />\r\n<strong>மக்கள் அழைப்பவரின் குரலை நோக்கி விரைவார்கள்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">يَتَّبِعُونَ</span> <span class=\"quran-arabic-font text-success\">الدَّاعِىَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">عِوَجَ</span> <span class=\"quran-arabic-font text-success\">لَهُ﴿</span><br />\r\n<br />\r\n(அந்த நாளில் மனிதர்கள் அல்லாஹ்வின் அழைப்பாளரை எவ்விதக் கோணலுமின்றி (நேரடியாகப்) பின்பற்றுவார்கள்.) அந்த நாளில் இத்தகைய பயங்கரமான காட்சிகளையும் நிலைகளையும் காணும்போது, அவர்கள் அழைப்பாளரின் குரலுக்கு உடனடியாகப் பதிலளிப்பார்கள். அவர்கள் எங்கு செல்லும்படி கட்டளையிடப்படுகிறார்களோ, அங்கே விரைந்து செல்வார்கள். இவ்வுலக வாழ்க்கையில் அவர்கள் இவ்வாறு (அல்லாஹ்வின் அழைப்புக்குக் கீழ்ப்படிந்து) இருந்திருந்தால் அது அவர்களுக்குப் பயனுள்ளதாக இருந்திருக்கும், ஆனால் மறுமையில் அவர்களுக்கு அது எந்தப் பயனும் தராது. இதனை அல்லாஹ் இவ்வாறு கூறுகிறான், <span class=\"quran-arabic-font text-success\">﴾أَسْمِعْ</span> <span class=\"quran-arabic-font text-success\">بِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَأَبْصِرْ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَأْتُونَنَا﴿</span><br />\r\n<br />\r\n(அவர்கள் நம்மிடம் வரும் நாளில், எவ்வளவு தெளிவாகக் கேட்பார்கள், பார்ப்பார்கள்!) (<a href=\"qurandisp.php?sura=19&ayah=38\" class=\"link\">19:38</a>). அல்லாஹ் மேலும் கூறுகிறான், <span class=\"quran-arabic-font text-success\">﴾مُّهْطِعِينَ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">الدَّاعِ﴿</span><br />\r\n<br />\r\n(அழைப்பாளரை நோக்கி விரைபவர்களாக.) (<a href=\"qurandisp.php?sura=54&ayah=8\" class=\"link\">54:8</a>) அல்லாஹ்வின் கூற்றான, <span class=\"quran-arabic-font text-success\">﴾وَخَشَعَتِ</span> <span class=\"quran-arabic-font text-success\">الأَصْوَاتُ</span> <span class=\"quran-arabic-font text-success\">لِلرَّحْمَـنِ﴿</span><br />\r\n<br />\r\n(மேலும், குரல்கள் அனைத்தும் அளவற்ற அருளாளனுக்காக ஒடுங்கிவிடும்,) என்பது குறித்து இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறுகையில், \"இதன் பொருள் அவர்கள் மௌனமாகிவிடுவார்கள்\" என்றார்கள். அஸ்-ஸுத்தி அவர்களும் இதையே கூறியுள்ளார்கள். <span class=\"quran-arabic-font text-success\">﴾فَلاَ</span> <span class=\"quran-arabic-font text-success\">تَسْمَعُ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">هَمْساً﴿</span><br />\r\n<br />\r\n(அங்கே 'ஹம்ஸைத்' தவிர வேறு எதையும் நீர் கேட்கமாட்டீர்.) இப்னு அப்பாஸ் (ரழி) அவர்கள், \"இதன் பொருள் பாதங்களின் காலடி ஓசை\" என்று கூறியதாக ஸயீத் பின் ஜுபைர் (ரழி) அவர்கள் அறிவிக்கிறார்கள். இக்ரிமா (ரழி), முஜாஹித் (ரழி), அத்-தஹ்ஹாக் (ரழி), அர்-ரபீஃ பின் அனஸ் (ரழி), கத்தாதா (ரழி), இப்னு ஜைத் (ரழி) மற்றும் பிறரும் இதையே கூறியுள்ளனர். அலி பின் அபீ தல்ஹா (ரழி) அவர்கள் வழியாக இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறுகையில், <span class=\"quran-arabic-font text-success\">﴾فَلاَ</span> <span class=\"quran-arabic-font text-success\">تَسْمَعُ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">هَمْساً﴿</span> (அங்கே 'ஹம்ஸைத்' தவிர வேறு எதையும் நீர் கேட்கமாட்டீர்) என்பதில் \"ஹம்ஸ் என்றால் மெல்லிய அல்லது மறைவான குரல் என்று பொருள்\" என்றார்கள். இது இக்ரிமா (ரழி) மற்றும் அத்-தஹ்ஹாக் (ரழி) ஆகியோரிடமிருந்தும் அறிவிக்கப்பட்டுள்ளது. ஸயீத் பின் ஜுபைர் (ரழி) அவர்கள் கூறுகையில், <span class=\"quran-arabic-font text-success\">﴾فَلاَ</span> <span class=\"quran-arabic-font text-success\">تَسْمَعُ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">هَمْساً﴿</span> (\"ஹம்ஸ் என்பது இரகசியப் பேச்சையும் பாதங்களின் காலடி ஓசையையும் குறிக்கும்\") என்றார்கள்.<br />\r\n<br />\r\n<br />\r\n<br />","text":"மலைகள் அழிக்கப்படுவதும், பூமி ஒரு சமதளமாக மாறுவதும்\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான், ﴾وَيَسْأَلُونَكَ عَنِ الْجِبَالِ﴿\n\r\n\n\r\n(மேலும், அவர்கள் மலைகளைப் பற்றி உம்மிடம் (ஸல்) கேட்கிறார்கள்.) மறுமை நாளில் அந்த மலைகள் அப்படியே இருக்குமா அல்லது அழிந்துவிடுமா என்பதுதான் இந்தக் கேள்வி. ﴾فَقُلْ يَنسِفُهَا رَبِّى نَسْفاً﴿\n\r\n\n\r\n(நீர் கூறுவீராக: \"என் இறைவன் அவற்றை வெடிக்கச் செய்து தூள் தூளாகச் சிதறடித்துவிடுவான்.\") இதன் பொருள் என்னவென்றால், அல்லாஹ் அவற்றை அவற்றின் இடங்களிலிருந்து அகற்றி, முற்றிலும் துடைத்தெறிந்து அப்புறப்படுத்திவிடுவான். ﴾فَيَذَرُهَا﴿\n\r\n\n\r\n(பின்னர் அவன் அதனை விட்டுவிடுவான்;) இது பூமியைக் குறிக்கிறது; ﴾قَاعاً صَفْصَفاً﴿\n\r\n\n\r\n(வெட்டவெளியான ஒரு சமதளமாக.) இதன் பொருள், சீராகப் பரந்து விரிந்த ஒரு சமவெளி என்பதாகும். 'காஃ' (Qa`) என்பது சமமான நிலப்பகுதியைக் குறிக்கும், 'ஸஃப்ஸஃபா' (Safsafa) என்ற சொல் இந்த அர்த்தத்தை வலியுறுத்தப் பயன்படுத்தப்படுகிறது. 'ஸஃப்ஸஃபா' என்பதற்கு எந்தத் தாவரமும் வளராத நிலம் என்றும் ஒரு கருத்து உண்டு. இரண்டாவது கருத்தும் இதில் அடங்கும் என்றாலும், முதல் கருத்தே முன்னுரிமை பெறுகிறது. இது குறித்து அல்லாஹ் கூறுகிறான், ﴾لاَّ تَرَى فِيهَا عِوَجاً وَلا أَمْتاً ﴿\n\r\n\n\r\n(அதில் நீர் எந்தக் கோணலையோ மேடுபள்ளத்தையோ காணமாட்டீர்.) அதாவது, அந்த நாளில் பூமியில் எந்தப் பள்ளத்தாக்கையும், குன்றையும் அல்லது தாழ்வான, உயரமான எந்த இடத்தையும் நீர் காணமாட்டீர். இப்னு அப்பாஸ் (ரழி), இக்ரிமா (ரழி), முஜாஹித் (ரழி), அல்-ஹஸன் அல்-பஸரி (ரழி), அத்-தஹ்ஹாக் (ரழி), கத்தாதா (ரழி) உள்ளிட்ட ஸலஃபுகள் (முன்னோர்கள்) அனைவரும் இதையே கூறியுள்ளார்கள்.\n\r\n\n\r\nமக்கள் அழைப்பவரின் குரலை நோக்கி விரைவார்கள்\n\r\n\n\r\n﴾يَوْمَئِذٍ يَتَّبِعُونَ الدَّاعِىَ لاَ عِوَجَ لَهُ﴿\n\r\n\n\r\n(அந்த நாளில் மனிதர்கள் அல்லாஹ்வின் அழைப்பாளரை எவ்விதக் கோணலுமின்றி (நேரடியாகப்) பின்பற்றுவார்கள்.) அந்த நாளில் இத்தகைய பயங்கரமான காட்சிகளையும் நிலைகளையும் காணும்போது, அவர்கள் அழைப்பாளரின் குரலுக்கு உடனடியாகப் பதிலளிப்பார்கள். அவர்கள் எங்கு செல்லும்படி கட்டளையிடப்படுகிறார்களோ, அங்கே விரைந்து செல்வார்கள். இவ்வுலக வாழ்க்கையில் அவர்கள் இவ்வாறு (அல்லாஹ்வின் அழைப்புக்குக் கீழ்ப்படிந்து) இருந்திருந்தால் அது அவர்களுக்குப் பயனுள்ளதாக இருந்திருக்கும், ஆனால் மறுமையில் அவர்களுக்கு அது எந்தப் பயனும் தராது. இதனை அல்லாஹ் இவ்வாறு கூறுகிறான், ﴾أَسْمِعْ بِهِمْ وَأَبْصِرْ يَوْمَ يَأْتُونَنَا﴿\n\r\n\n\r\n(அவர்கள் நம்மிடம் வரும் நாளில், எவ்வளவு தெளிவாகக் கேட்பார்கள், பார்ப்பார்கள்!) (19:38). அல்லாஹ் மேலும் கூறுகிறான், ﴾مُّهْطِعِينَ إِلَى الدَّاعِ﴿\n\r\n\n\r\n(அழைப்பாளரை நோக்கி விரைபவர்களாக.) (54:8) அல்லாஹ்வின் கூற்றான, ﴾وَخَشَعَتِ الأَصْوَاتُ لِلرَّحْمَـنِ﴿\n\r\n\n\r\n(மேலும், குரல்கள் அனைத்தும் அளவற்ற அருளாளனுக்காக ஒடுங்கிவிடும்,) என்பது குறித்து இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறுகையில், \"இதன் பொருள் அவர்கள் மௌனமாகிவிடுவார்கள்\" என்றார்கள். அஸ்-ஸுத்தி அவர்களும் இதையே கூறியுள்ளார்கள். ﴾فَلاَ تَسْمَعُ إِلاَّ هَمْساً﴿\n\r\n\n\r\n(அங்கே 'ஹம்ஸைத்' தவிர வேறு எதையும் நீர் கேட்கமாட்டீர்.) இப்னு அப்பாஸ் (ரழி) அவர்கள், \"இதன் பொருள் பாதங்களின் காலடி ஓசை\" என்று கூறியதாக ஸயீத் பின் ஜுபைர் (ரழி) அவர்கள் அறிவிக்கிறார்கள். இக்ரிமா (ரழி), முஜாஹித் (ரழி), அத்-தஹ்ஹாக் (ரழி), அர்-ரபீஃ பின் அனஸ் (ரழி), கத்தாதா (ரழி), இப்னு ஜைத் (ரழி) மற்றும் பிறரும் இதையே கூறியுள்ளனர். அலி பின் அபீ தல்ஹா (ரழி) அவர்கள் வழியாக இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறுகையில், ﴾فَلاَ تَسْمَعُ إِلاَّ هَمْساً﴿ (அங்கே 'ஹம்ஸைத்' தவிர வேறு எதையும் நீர் கேட்கமாட்டீர்) என்பதில் \"ஹம்ஸ் என்றால் மெல்லிய அல்லது மறைவான குரல் என்று பொருள்\" என்றார்கள். இது இக்ரிமா (ரழி) மற்றும் அத்-தஹ்ஹாக் (ரழி) ஆகியோரிடமிருந்தும் அறிவிக்கப்பட்டுள்ளது. ஸயீத் பின் ஜுபைர் (ரழி) அவர்கள் கூறுகையில், ﴾فَلاَ تَسْمَعُ إِلاَّ هَمْساً﴿ (\"ஹம்ஸ் என்பது இரகசியப் பேச்சையும் பாதங்களின் காலடி ஓசையையும் குறிக்கும்\") என்றார்கள்."},"109":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=112\" class=\"link\">20:112</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:112 ஐ பார்க்கவும்"},"110":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=112\" class=\"link\">20:112</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:112 ஐ பார்க்கவும்"},"111":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=112\" class=\"link\">20:112</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:112 ஐ பார்க்கவும்"},"112":{"html":"<strong>பரிந்துரையும் பிரதிபலனும்</strong><br />\r\n<br />\r\nஉயர்ந்தோனாகிய அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾يَوْمَئِذٍ﴿</span><br />\r\n(அந்நாளில்) அதாவது மறுமை நாளில், <span class=\"quran-arabic-font text-success\">﴾لاَّ</span> <span class=\"quran-arabic-font text-success\">تَنفَعُ</span> <span class=\"quran-arabic-font text-success\">الشَّفَاعَةُ﴿</span><br />\r\n(எந்தப் பரிந்துரையும் பயனளிக்காது.) அதாவது அல்லாஹ்விடம் எவருடைய பரிந்துரையும் எடுபடாது. <span class=\"quran-arabic-font text-success\">﴾إِلاَّ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">أَذِنَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنُ</span> <span class=\"quran-arabic-font text-success\">وَرَضِىَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">قَوْلاً﴿</span><br />\r\n(அளவற்ற அருளாளன் எவருக்கு அனுமதி அளித்து, எவரது சொல்லையும் அவன் பொருந்திக்கொண்டானோ அவரைத் தவிர.) இது அவனது இந்த வசனத்தைப் போன்றதாகும்: <span class=\"quran-arabic-font text-success\">﴾مَن</span> <span class=\"quran-arabic-font text-success\">ذَا</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">يَشْفَعُ</span> <span class=\"quran-arabic-font text-success\">عِندَهُ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">بِإِذْنِهِ﴿</span><br />\r\n(அவனது அனுமதியின்றி அவனிடம் பரிந்துரை செய்பவர் யார்?) (<a href=\"qurandisp.php?sura=2&ayah=255\" class=\"link\">2:255</a>).<br />\r\n<br />\r\nஇது அவனது இந்த வசனத்தையும் ஒத்திருக்கிறது: <span class=\"quran-arabic-font text-success\">﴾وَكَمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">مَّلَكٍ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">السَّمَـوَتِ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تُغْنِى</span> <span class=\"quran-arabic-font text-success\">شَفَـعَتُهُمْ</span> <span class=\"quran-arabic-font text-success\">شَيْئاً</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَعْدِ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَأْذَنَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">لِمَن</span> <span class=\"quran-arabic-font text-success\">يَشَآءُ</span> <span class=\"quran-arabic-font text-success\">وَيَرْضَى</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(வானங்களில் எத்தனையோ வானவர்கள் இருக்கின்றனர்; அல்லாஹ் தான் நாடியவர்களுக்கும், தான் பொருந்திக்கொண்டவர்களுக்கும் அனுமதி அளித்த பின்னரே தவிர, அவர்களின் பரிந்துரை எவ்விதப் பயனும் அளிக்காது.) (<a href=\"qurandisp.php?sura=53&ayah=26\" class=\"link\">53:26</a>). மேலும் அவன் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَشْفَعُونَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">لِمَنِ</span> <span class=\"quran-arabic-font text-success\">ارْتَضَى</span> <span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">خَشْيَتِهِ</span> <span class=\"quran-arabic-font text-success\">مُشْفِقُونَ﴿</span><br />\r\n(அவன் எவரைப் பொருந்திக்கொண்டானோ அவருக்காகவே தவிர அவர்கள் பரிந்துரை செய்ய மாட்டார்கள்; மேலும் அவர்கள் அவன் மீதான அச்சத்தால் நடுங்குபவர்களாக இருப்பார்கள்.) (<a href=\"qurandisp.php?sura=21&ayah=28\" class=\"link\">21:28</a>). மேலும் அவன் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَنفَعُ</span> <span class=\"quran-arabic-font text-success\">الشَّفَـعَةُ</span> <span class=\"quran-arabic-font text-success\">عِندَهُ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">لِمَنْ</span> <span class=\"quran-arabic-font text-success\">أَذِنَ</span> <span class=\"quran-arabic-font text-success\">لَهُ﴿</span><br />\r\n(அவன் அனுமதி அளித்தவருக்கே தவிர அவனிடம் பரிந்துரை பயனளிக்காது.) (<a href=\"qurandisp.php?sura=34&ayah=23\" class=\"link\">34:23</a>).<br />\r\n<br />\r\nமேலும் அவன் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَقُومُ</span> <span class=\"quran-arabic-font text-success\">الرُّوحُ</span> <span class=\"quran-arabic-font text-success\">وَالْمَلَـئِكَةُ</span> <span class=\"quran-arabic-font text-success\">صَفّاً</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يَتَكَلَّمُونَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">أَذِنَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنُ</span> <span class=\"quran-arabic-font text-success\">وَقَالَ</span> <span class=\"quran-arabic-font text-success\">صَوَاباً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(அர்-ரூஹும் வானவர்களும் அணிவகுத்து நிற்கும் அந்நாளில், அளவற்ற அருளாளன் அனுமதி அளித்தவர்களையும், சரியானவற்றைப் பேசுபவர்களையும் தவிர வேறெவரும் பேச மாட்டார்கள்.) (<a href=\"qurandisp.php?sura=78&ayah=38\" class=\"link\">78:38</a>). இரண்டு ஸஹீஹ் நூல்களிலும் (புகாரி மற்றும் முஸ்லிம்), ஆதமுடைய மக்களின் தலைவரும் அல்லாஹ்விடம் படைப்பினங்களிலேயே மிகுந்த கண்ணியத்திற்குரியவருமான முஹம்மது (ஸல்) அவர்கள் கூறியதாக அறிவிக்கப்பட்டுள்ளது: <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">آتِي</span> <span class=\"quran-arabic-font text-success\">تَحْتَ</span> <span class=\"quran-arabic-font text-success\">الْعَرْشِ،</span> <span class=\"quran-arabic-font text-success\">وَأَخِرُّ</span> <span class=\"quran-arabic-font text-success\">للهِ</span> <span class=\"quran-arabic-font text-success\">سَاجِدًا،</span> <span class=\"quran-arabic-font text-success\">وَيَفْتَحُ</span> <span class=\"quran-arabic-font text-success\">عَلَيَّ</span> <span class=\"quran-arabic-font text-success\">بِمَحَامِدَ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">أُحْصِيهَا</span> <span class=\"quran-arabic-font text-success\">الْآنَ،</span> <span class=\"quran-arabic-font text-success\">فَيَدَعُنِي</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">شَاءَ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يَدَعَنِي،</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يَقُولُ</span>: <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">مُحَمَّدُ،</span> <span class=\"quran-arabic-font text-success\">ارْفَعْ</span> <span class=\"quran-arabic-font text-success\">رَأْسَكَ</span> <span class=\"quran-arabic-font text-success\">وَقُلْ</span> <span class=\"quran-arabic-font text-success\">يُسْمَعْ،</span> <span class=\"quran-arabic-font text-success\">وَاشْفَعْ</span> <span class=\"quran-arabic-font text-success\">تُشَفَّعْ</span> <span class=\"quran-arabic-font text-success\">فَيَحُدُّ</span> <span class=\"quran-arabic-font text-success\">لِي</span> <span class=\"quran-arabic-font text-success\">حَدًّا،</span> <span class=\"quran-arabic-font text-success\">فَأُدْخِلُهُمُ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةَ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">أَعُود</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(நான் அர்ஷுக்குக் கீழே வந்து (அல்லாஹ்வை) ஸஜ்தா செய்து விழுவேன். அப்போது, இப்போது என்னால் விவரிக்க இயலாத புகழுரைகள் எனக்கு உணர்த்தப்படும். அல்லாஹ் நாடும் வரை என்னை அந்த நிலையிலேயே விட்டுவிடுவான். பிறகு அவன், \"முஹம்மதே! உமது தலையை உயர்த்தும். பேசுங்கள், உமது வார்த்தை செவிமடுக்கப்படும்; பரிந்துரை செய்யுங்கள், உமது பரிந்துரை ஏற்கப்படும்\" என்று கூறுவான். பிறகு பரிந்துரை செய்வதற்காக எனக்கு ஒரு குறிப்பிட்ட மக்கள் (எல்லை) நிர்ணயிக்கப்படுவார்கள். நான் அவர்களைச் சொர்க்கத்தில் நுழையச் செய்வேன், பிறகு மீண்டும் திரும்புவேன்.) நபி (ஸல்) அவர்கள் இவ்வாறு நான்கு முறை செய்வதாகக் குறிப்பிட்டார்கள். அவர் மீதும் ஏனைய நபிமார்கள் (அலை) அவர்கள் மீதும் அல்லாஹ்வின் ஸலவாத்தும் ஸலாமும் உண்டாவதாக.<br />\r\n<br />\r\nமற்றொரு ஹதீஸில் நபி (ஸல்) அவர்கள் பின்வருமாறு கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">يَقُولُ</span> <span class=\"quran-arabic-font text-success\">تَعَالَى</span>: <span class=\"quran-arabic-font text-success\">أَخْرِجُوا</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">قَلْبِهِ</span> <span class=\"quran-arabic-font text-success\">مِثْقَالُ</span> <span class=\"quran-arabic-font text-success\">حَبَّةٍ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">إِيمَانٍ،</span> <span class=\"quran-arabic-font text-success\">فَيُخْرِجُونَ</span> <span class=\"quran-arabic-font text-success\">خَلْقًا</span> <span class=\"quran-arabic-font text-success\">كَثِيرًا،</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يَقُولُ</span>: <span class=\"quran-arabic-font text-success\">أَخْرِجُوا</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">قَلْبِهِ</span> <span class=\"quran-arabic-font text-success\">نِصْفُ</span> <span class=\"quran-arabic-font text-success\">مِثْقَالٍ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">إِيمَانٍ،</span> <span class=\"quran-arabic-font text-success\">أَخْرِجُوا</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">قَلْبِهِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَزِنُ</span> <span class=\"quran-arabic-font text-success\">ذَرَّةً،</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">قَلْبِهِ</span> <span class=\"quran-arabic-font text-success\">أَدْنَى</span> <span class=\"quran-arabic-font text-success\">أَدْنَى</span> <span class=\"quran-arabic-font text-success\">مِثْقَالِ</span> <span class=\"quran-arabic-font text-success\">ذَرَّةٍ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">إِيمَان</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(உயர்ந்தோனாகிய அல்லாஹ், \"எவரது உள்ளத்தில் ஒரு வித்தளவு ஈமான் இருக்கிறதோ அவரை நரகத்திலிருந்து வெளியேற்றுங்கள்\" என்று கூறுவான். அவ்வாறே ஏராளமான மக்கள் வெளியேற்றப்படுவார்கள். பிறகு அவன், \"எவரது உள்ளத்தில் அரை வித்தளவு ஈமான் இருக்கிறதோ அவரை நரகத்திலிருந்து வெளியேற்றுங்கள்; எவரது உள்ளத்தில் ஒரு அணுவளவு ஈமான் இருக்கிறதோ அவரை வெளியேற்றுங்கள்; எவரது உள்ளத்தில் கடுகளவுக்கும் மிக மிகச் சிறிய அணுவளவு ஈமான் இருக்கிறதோ அவரையும் வெளியேற்றுங்கள்\" என்று கூறுவான்.) அந்த ஹதீஸ் தொடர்கிறது.<br />\r\n<br />\r\nஅல்லாஹ்வின் வசனத்தைப் பொருத்தவரை: <span class=\"quran-arabic-font text-success\">﴾يَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">أَيْدِيهِمْ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">خَلْفَهُمْ﴿</span><br />\r\n(அவர்களுக்கு முன்னால் இருப்பதையும், அவர்களுக்குப் பின்னால் இருப்பதையும் அவன் அறிகிறான்,) அவன் தனது ஞானத்தால் அனைத்துப் படைப்புகளையும் சூழ்ந்திருக்கிறான். <span class=\"quran-arabic-font text-success\">﴾وَلاَ</span> <span class=\"quran-arabic-font text-success\">يُحِيطُونَ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">عِلْماً﴿</span><br />\r\n(ஆனால் அவர்கள் அவனது ஞானத்திலிருந்து எதையும் முழுமையாக அறியமாட்டார்கள்.) இது அவனது இந்த வசனத்தைப் போன்றதே: <span class=\"quran-arabic-font text-success\">﴾وَلاَ</span> <span class=\"quran-arabic-font text-success\">يُحِيطُونَ</span> <span class=\"quran-arabic-font text-success\">بِشَيْءٍ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">عِلْمِهِ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">شَآءَ﴿</span><br />\r\n(அவன் நாடியதைத் தவிர அவனது ஞானத்திலிருந்து எதையும் அவர்களால் சூழ்ந்து அறிய முடியாது.) (<a href=\"qurandisp.php?sura=2&ayah=255\" class=\"link\">2:255</a>).<br />\r\n<br />\r\nஅல்லாஹ்வின் வசனத்தைப் பொருத்தவரை: <span class=\"quran-arabic-font text-success\">﴾وَعَنَتِ</span> <span class=\"quran-arabic-font text-success\">الْوُجُوهُ</span> <span class=\"quran-arabic-font text-success\">لِلْحَىِّ</span> <span class=\"quran-arabic-font text-success\">الْقَيُّومِ﴿</span><br />\r\n(நித்தியமானவனும், அனைத்தையும் நிர்வகிப்பவனுமானவனுக்கு முன்னால் அனைத்து முகங்களும் பணிந்துவிடும்.) இப்னு அப்பாஸ் (ரழி) அவர்களும் ஏனையோரும் கூறினார்கள்: \"இதன் பொருள், படைப்புகள் அனைத்தும் அடக்கியாளும் வல்லமை மிக்கவன், மரணமே இல்லாத நித்தியமானவன், உறக்கமின்றி அனைத்தையும் நிர்வகிப்பவனுமானவனுக்கு முன்னால் பணிந்தும், அடங்கியும், கீழ்ப்படிந்தும் இருக்கும் என்பதாகும்.\" அவனே அனைத்தையும் பராமரிப்பவன்; அனைத்து விவகாரங்களையும் தீர்மானித்து பாதுகாப்பவன். அவன் தன் சுயத்தில் முழுமையானவன். அனைத்தும் அவனையே சார்ந்திருக்கின்றன, அவனின்றி எதுவும் நிலைத்திருக்க முடியாது.<br />\r\n<br />\r\nஅவனது வசனத்தைப் பொருத்தவரை: <span class=\"quran-arabic-font text-success\">﴾وَقَدْ</span> <span class=\"quran-arabic-font text-success\">خَابَ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">حَمَلَ</span> <span class=\"quran-arabic-font text-success\">ظُلْماً﴿</span><br />\r\n(அநீதியைச் சுமந்து வந்தவன் நிச்சயமாகத் தோல்வியடைந்துவிட்டான்.) அதாவது மறுமை நாளில். ஏனெனில், நிச்சயமாக அல்லாஹ் ஒவ்வொருவருக்கும் சேர வேண்டிய உரிமைகளை அவர்களுக்குப் பெற்றுத் தருவான். கொம்பில்லாத ஆட்டிற்காக, கொம்புள்ள ஆட்டிடமிருந்து பழிவாங்கப்படும் அளவுக்கு நீதி நிலைநாட்டப்படும். ஸஹீஹ் நூலில் நபி (ஸல்) அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">إِيَّاكُمْ</span> <span class=\"quran-arabic-font text-success\">وَالظُّلْمَ،</span> <span class=\"quran-arabic-font text-success\">فَإِنَّ</span> <span class=\"quran-arabic-font text-success\">الظُّلْمَ</span> <span class=\"quran-arabic-font text-success\">ظُلُمَاتٌ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَة</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(அநீதி இழைப்பதைத் தவிர்த்துக் கொள்ளுங்கள்; ஏனெனில் அநீதியானது மறுமை நாளில் அடர்ந்த இருள்களாக மாறும்.) மேலும், அல்லாஹ்வுக்கு இணை வைத்த நிலையில் (ஷிர்க்) அவனைச் சந்திப்பவருக்கே உண்மையான தோல்வி இருக்கிறது. உயர்ந்தோனாகிய அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">الشِّرْكَ</span> <span class=\"quran-arabic-font text-success\">لَظُلْمٌ</span> <span class=\"quran-arabic-font text-success\">عَظِيمٌ﴿</span><br />\r\n(\"நிச்சயமாக இணை வைத்தல் என்பது மிகப்பெரிய அநீதியாகும்.\")<br />\r\n<br />\r\nஅல்லாஹ்வின் வசனம்: <span class=\"quran-arabic-font text-success\">﴾وَمَن</span> <span class=\"quran-arabic-font text-success\">يَعْمَلْ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الصَّـلِحَـتِ</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">مُؤْمِنٌ</span> <span class=\"quran-arabic-font text-success\">فَلاَ</span> <span class=\"quran-arabic-font text-success\">يَخَافُ</span> <span class=\"quran-arabic-font text-success\">ظُلْماً</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">هَضْماً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(மேலும், ஒரு இறைநம்பிக்கையாளராக இருந்து நற்செயல்களைச் செய்தவர், அநீதியையோ அல்லது நன்மைகளில் குறைவையோ கண்டு அஞ்ச மாட்டார்.) அநீதி இழைப்பவர்களையும் அவர்களுக்கான எச்சரிக்கையையும் அல்லாஹ் குறிப்பிட்ட பிறகு, இறையச்சமுடையவர்களைப் புகழ்ந்து அவர்களுக்கான கூலியைக் குறிப்பிடுகிறான். அவர்கள் அநீதி இழைக்கப்படவோ ஒடுக்கப்படவோ மாட்டார்கள் என்பதே அவர்களுக்கான தீர்ப்பாகும். அதாவது அவர்களின் தீமைகள் அதிகரிக்கப்படாது, அவர்களின் நன்மைகள் குறைக்கப்படாது. இதனை இப்னு அப்பாஸ் (ரழி), முஜாஹித், அத்-தஹ்ஹாக், அல்-ஹஸன், கத்தாதா மற்றும் பலர் கூறியுள்ளனர். 'ஸுல்ம்' என்பது ஒருவரது பாவங்கள் மற்றவர் மீது சுமத்தப்பட்டு பாவம் அதிகரிப்பதாகும்; 'ஹத்ம்' என்பது நன்மைகள் குறைக்கப்படுவதாகும்.<br />\r\n<br />\r\n<br />\r\n<br />\r\n<br />\r\n<br />","text":"பரிந்துரையும் பிரதிபலனும்\n\r\n\n\r\nஉயர்ந்தோனாகிய அல்லாஹ் கூறுகிறான்: ﴾يَوْمَئِذٍ﴿\n\r\n(அந்நாளில்) அதாவது மறுமை நாளில், ﴾لاَّ تَنفَعُ الشَّفَاعَةُ﴿\n\r\n(எந்தப் பரிந்துரையும் பயனளிக்காது.) அதாவது அல்லாஹ்விடம் எவருடைய பரிந்துரையும் எடுபடாது. ﴾إِلاَّ مَنْ أَذِنَ لَهُ الرَّحْمَـنُ وَرَضِىَ لَهُ قَوْلاً﴿\n\r\n(அளவற்ற அருளாளன் எவருக்கு அனுமதி அளித்து, எவரது சொல்லையும் அவன் பொருந்திக்கொண்டானோ அவரைத் தவிர.) இது அவனது இந்த வசனத்தைப் போன்றதாகும்: ﴾مَن ذَا الَّذِى يَشْفَعُ عِندَهُ إِلاَّ بِإِذْنِهِ﴿\n\r\n(அவனது அனுமதியின்றி அவனிடம் பரிந்துரை செய்பவர் யார்?) (2:255).\n\r\n\n\r\nஇது அவனது இந்த வசனத்தையும் ஒத்திருக்கிறது: ﴾وَكَمْ مِّن مَّلَكٍ فِى السَّمَـوَتِ لاَ تُغْنِى شَفَـعَتُهُمْ شَيْئاً إِلاَّ مِن بَعْدِ أَن يَأْذَنَ اللَّهُ لِمَن يَشَآءُ وَيَرْضَى ﴿\n\r\n(வானங்களில் எத்தனையோ வானவர்கள் இருக்கின்றனர்; அல்லாஹ் தான் நாடியவர்களுக்கும், தான் பொருந்திக்கொண்டவர்களுக்கும் அனுமதி அளித்த பின்னரே தவிர, அவர்களின் பரிந்துரை எவ்விதப் பயனும் அளிக்காது.) (53:26). மேலும் அவன் கூறுகிறான்: ﴾وَلاَ يَشْفَعُونَ إِلاَّ لِمَنِ ارْتَضَى وَهُمْ مِّنْ خَشْيَتِهِ مُشْفِقُونَ﴿\n\r\n(அவன் எவரைப் பொருந்திக்கொண்டானோ அவருக்காகவே தவிர அவர்கள் பரிந்துரை செய்ய மாட்டார்கள்; மேலும் அவர்கள் அவன் மீதான அச்சத்தால் நடுங்குபவர்களாக இருப்பார்கள்.) (21:28). மேலும் அவன் கூறுகிறான்: ﴾وَلاَ تَنفَعُ الشَّفَـعَةُ عِندَهُ إِلاَّ لِمَنْ أَذِنَ لَهُ﴿\n\r\n(அவன் அனுமதி அளித்தவருக்கே தவிர அவனிடம் பரிந்துரை பயனளிக்காது.) (34:23).\n\r\n\n\r\nமேலும் அவன் கூறுகிறான்: ﴾يَوْمَ يَقُومُ الرُّوحُ وَالْمَلَـئِكَةُ صَفّاً لاَّ يَتَكَلَّمُونَ إِلاَّ مَنْ أَذِنَ لَهُ الرَّحْمَـنُ وَقَالَ صَوَاباً ﴿\n\r\n(அர்-ரூஹும் வானவர்களும் அணிவகுத்து நிற்கும் அந்நாளில், அளவற்ற அருளாளன் அனுமதி அளித்தவர்களையும், சரியானவற்றைப் பேசுபவர்களையும் தவிர வேறெவரும் பேச மாட்டார்கள்.) (78:38). இரண்டு ஸஹீஹ் நூல்களிலும் (புகாரி மற்றும் முஸ்லிம்), ஆதமுடைய மக்களின் தலைவரும் அல்லாஹ்விடம் படைப்பினங்களிலேயே மிகுந்த கண்ணியத்திற்குரியவருமான முஹம்மது (ஸல்) அவர்கள் கூறியதாக அறிவிக்கப்பட்டுள்ளது: ﴾«آتِي تَحْتَ الْعَرْشِ، وَأَخِرُّ للهِ سَاجِدًا، وَيَفْتَحُ عَلَيَّ بِمَحَامِدَ لَا أُحْصِيهَا الْآنَ، فَيَدَعُنِي مَا شَاءَ أَنْ يَدَعَنِي، ثُمَّ يَقُولُ: يَا مُحَمَّدُ، ارْفَعْ رَأْسَكَ وَقُلْ يُسْمَعْ، وَاشْفَعْ تُشَفَّعْ فَيَحُدُّ لِي حَدًّا، فَأُدْخِلُهُمُ الْجَنَّةَ ثُمَّ أَعُود»﴿\n\r\n(நான் அர்ஷுக்குக் கீழே வந்து (அல்லாஹ்வை) ஸஜ்தா செய்து விழுவேன். அப்போது, இப்போது என்னால் விவரிக்க இயலாத புகழுரைகள் எனக்கு உணர்த்தப்படும். அல்லாஹ் நாடும் வரை என்னை அந்த நிலையிலேயே விட்டுவிடுவான். பிறகு அவன், \"முஹம்மதே! உமது தலையை உயர்த்தும். பேசுங்கள், உமது வார்த்தை செவிமடுக்கப்படும்; பரிந்துரை செய்யுங்கள், உமது பரிந்துரை ஏற்கப்படும்\" என்று கூறுவான். பிறகு பரிந்துரை செய்வதற்காக எனக்கு ஒரு குறிப்பிட்ட மக்கள் (எல்லை) நிர்ணயிக்கப்படுவார்கள். நான் அவர்களைச் சொர்க்கத்தில் நுழையச் செய்வேன், பிறகு மீண்டும் திரும்புவேன்.) நபி (ஸல்) அவர்கள் இவ்வாறு நான்கு முறை செய்வதாகக் குறிப்பிட்டார்கள். அவர் மீதும் ஏனைய நபிமார்கள் (அலை) அவர்கள் மீதும் அல்லாஹ்வின் ஸலவாத்தும் ஸலாமும் உண்டாவதாக.\n\r\n\n\r\nமற்றொரு ஹதீஸில் நபி (ஸல்) அவர்கள் பின்வருமாறு கூறினார்கள்: ﴾«يَقُولُ تَعَالَى: أَخْرِجُوا مِنَ النَّارِ مَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ حَبَّةٍ مِنْ إِيمَانٍ، فَيُخْرِجُونَ خَلْقًا كَثِيرًا، ثُمَّ يَقُولُ: أَخْرِجُوا مِنَ النَّارِ مَنْ كَانَ فِي قَلْبِهِ نِصْفُ مِثْقَالٍ مِنْ إِيمَانٍ، أَخْرِجُوا مِنَ النَّارِ مَنْ كَانَ فِي قَلْبِهِ مَا يَزِنُ ذَرَّةً، مَنْ كَانَ فِي قَلْبِهِ أَدْنَى أَدْنَى مِثْقَالِ ذَرَّةٍ مِنْ إِيمَان»﴿\n\r\n(உயர்ந்தோனாகிய அல்லாஹ், \"எவரது உள்ளத்தில் ஒரு வித்தளவு ஈமான் இருக்கிறதோ அவரை நரகத்திலிருந்து வெளியேற்றுங்கள்\" என்று கூறுவான். அவ்வாறே ஏராளமான மக்கள் வெளியேற்றப்படுவார்கள். பிறகு அவன், \"எவரது உள்ளத்தில் அரை வித்தளவு ஈமான் இருக்கிறதோ அவரை நரகத்திலிருந்து வெளியேற்றுங்கள்; எவரது உள்ளத்தில் ஒரு அணுவளவு ஈமான் இருக்கிறதோ அவரை வெளியேற்றுங்கள்; எவரது உள்ளத்தில் கடுகளவுக்கும் மிக மிகச் சிறிய அணுவளவு ஈமான் இருக்கிறதோ அவரையும் வெளியேற்றுங்கள்\" என்று கூறுவான்.) அந்த ஹதீஸ் தொடர்கிறது.\n\r\n\n\r\nஅல்லாஹ்வின் வசனத்தைப் பொருத்தவரை: ﴾يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ﴿\n\r\n(அவர்களுக்கு முன்னால் இருப்பதையும், அவர்களுக்குப் பின்னால் இருப்பதையும் அவன் அறிகிறான்,) அவன் தனது ஞானத்தால் அனைத்துப் படைப்புகளையும் சூழ்ந்திருக்கிறான். ﴾وَلاَ يُحِيطُونَ بِهِ عِلْماً﴿\n\r\n(ஆனால் அவர்கள் அவனது ஞானத்திலிருந்து எதையும் முழுமையாக அறியமாட்டார்கள்.) இது அவனது இந்த வசனத்தைப் போன்றதே: ﴾وَلاَ يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلاَّ بِمَا شَآءَ﴿\n\r\n(அவன் நாடியதைத் தவிர அவனது ஞானத்திலிருந்து எதையும் அவர்களால் சூழ்ந்து அறிய முடியாது.) (2:255).\n\r\n\n\r\nஅல்லாஹ்வின் வசனத்தைப் பொருத்தவரை: ﴾وَعَنَتِ الْوُجُوهُ لِلْحَىِّ الْقَيُّومِ﴿\n\r\n(நித்தியமானவனும், அனைத்தையும் நிர்வகிப்பவனுமானவனுக்கு முன்னால் அனைத்து முகங்களும் பணிந்துவிடும்.) இப்னு அப்பாஸ் (ரழி) அவர்களும் ஏனையோரும் கூறினார்கள்: \"இதன் பொருள், படைப்புகள் அனைத்தும் அடக்கியாளும் வல்லமை மிக்கவன், மரணமே இல்லாத நித்தியமானவன், உறக்கமின்றி அனைத்தையும் நிர்வகிப்பவனுமானவனுக்கு முன்னால் பணிந்தும், அடங்கியும், கீழ்ப்படிந்தும் இருக்கும் என்பதாகும்.\" அவனே அனைத்தையும் பராமரிப்பவன்; அனைத்து விவகாரங்களையும் தீர்மானித்து பாதுகாப்பவன். அவன் தன் சுயத்தில் முழுமையானவன். அனைத்தும் அவனையே சார்ந்திருக்கின்றன, அவனின்றி எதுவும் நிலைத்திருக்க முடியாது.\n\r\n\n\r\nஅவனது வசனத்தைப் பொருத்தவரை: ﴾وَقَدْ خَابَ مَنْ حَمَلَ ظُلْماً﴿\n\r\n(அநீதியைச் சுமந்து வந்தவன் நிச்சயமாகத் தோல்வியடைந்துவிட்டான்.) அதாவது மறுமை நாளில். ஏனெனில், நிச்சயமாக அல்லாஹ் ஒவ்வொருவருக்கும் சேர வேண்டிய உரிமைகளை அவர்களுக்குப் பெற்றுத் தருவான். கொம்பில்லாத ஆட்டிற்காக, கொம்புள்ள ஆட்டிடமிருந்து பழிவாங்கப்படும் அளவுக்கு நீதி நிலைநாட்டப்படும். ஸஹீஹ் நூலில் நபி (ஸல்) அவர்கள் கூறினார்கள்: ﴾«إِيَّاكُمْ وَالظُّلْمَ، فَإِنَّ الظُّلْمَ ظُلُمَاتٌ يَوْمَ الْقِيَامَة»﴿\n\r\n(அநீதி இழைப்பதைத் தவிர்த்துக் கொள்ளுங்கள்; ஏனெனில் அநீதியானது மறுமை நாளில் அடர்ந்த இருள்களாக மாறும்.) மேலும், அல்லாஹ்வுக்கு இணை வைத்த நிலையில் (ஷிர்க்) அவனைச் சந்திப்பவருக்கே உண்மையான தோல்வி இருக்கிறது. உயர்ந்தோனாகிய அல்லாஹ் கூறுகிறான்: ﴾إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ﴿\n\r\n(\"நிச்சயமாக இணை வைத்தல் என்பது மிகப்பெரிய அநீதியாகும்.\")\n\r\n\n\r\nஅல்லாஹ்வின் வசனம்: ﴾وَمَن يَعْمَلْ مِنَ الصَّـلِحَـتِ وَهُوَ مُؤْمِنٌ فَلاَ يَخَافُ ظُلْماً وَلاَ هَضْماً ﴿\n\r\n(மேலும், ஒரு இறைநம்பிக்கையாளராக இருந்து நற்செயல்களைச் செய்தவர், அநீதியையோ அல்லது நன்மைகளில் குறைவையோ கண்டு அஞ்ச மாட்டார்.) அநீதி இழைப்பவர்களையும் அவர்களுக்கான எச்சரிக்கையையும் அல்லாஹ் குறிப்பிட்ட பிறகு, இறையச்சமுடையவர்களைப் புகழ்ந்து அவர்களுக்கான கூலியைக் குறிப்பிடுகிறான். அவர்கள் அநீதி இழைக்கப்படவோ ஒடுக்கப்படவோ மாட்டார்கள் என்பதே அவர்களுக்கான தீர்ப்பாகும். அதாவது அவர்களின் தீமைகள் அதிகரிக்கப்படாது, அவர்களின் நன்மைகள் குறைக்கப்படாது. இதனை இப்னு அப்பாஸ் (ரழி), முஜாஹித், அத்-தஹ்ஹாக், அல்-ஹஸன், கத்தாதா மற்றும் பலர் கூறியுள்ளனர். 'ஸுல்ம்' என்பது ஒருவரது பாவங்கள் மற்றவர் மீது சுமத்தப்பட்டு பாவம் அதிகரிப்பதாகும்; 'ஹத்ம்' என்பது நன்மைகள் குறைக்கப்படுவதாகும்."},"113":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=114\" class=\"link\">20:114</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:114 ஐ பார்க்கவும்"},"114":{"html":"<strong>மக்கள் தக்வா (இறையச்சம்) கொள்ளவும் படிப்பினை பெறவும் குர்ஆன் அருளப்பட்டது</strong><br />\r\n<br />\r\nமறுமை நாளில் நன்மையோ தீமையோ செய்தவருக்கு அதற்கான கூலி வழங்கப்படும் என்பதையும், அதிலிருந்து தப்பிக்க வழியே இல்லை என்பதையும் மேலானவனான அல்லாஹ் குறிப்பிட்ட பிறகு, தெளிவான மற்றும் செழுமையான அரபி மொழியில் நற்செய்தி கூறுவதாகவும் எச்சரிப்பதாகவும் குர்ஆன் அருளப்பட்டுள்ளது என அவன் விளக்குகிறான். அதில் எந்தக் குழப்பமோ குறையோ இல்லை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">أَنزَلْنَاهُ</span> <span class=\"quran-arabic-font text-success\">قُرْءَانًا</span> <span class=\"quran-arabic-font text-success\">عَرَبِيًّا</span> <span class=\"quran-arabic-font text-success\">وَصَرَّفْنَا</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْوَعِيدِ</span> <span class=\"quran-arabic-font text-success\">لَعَلَّهُمْ</span> <span class=\"quran-arabic-font text-success\">يَتَّقُونَ</span><br />\r\n<br />\r\n(இவ்வாறே, நாம் இதனை அரபி மொழி குர்ஆனாக இறக்கியருளினோம்; அவர்கள் தக்வா (இறையச்சம்) கொள்வதற்காக இதில் எச்சரிக்கைகளைத் தெளிவுபடுத்தியுள்ளோம்.) இதன் பொருள்: அவர்கள் பாவங்கள், விலக்கப்பட்டவை மற்றும் அருவருப்பான செயல்களை விட்டுவிடுவதற்காக என்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">يُحْدِثُ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">ذِكْراً</span><br />\r\n<br />\r\n(அல்லது அது அவர்களுக்கு ஒரு படிப்பினையை ஏற்படுத்தும்.) இதன் பொருள்: அல்லாஹ்வுக்குக் கீழ்ப்படிவதையும் அவனை நெருங்குவதற்குரிய நற்செயல்களையும் செய்யத் தூண்டுவதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَتَعَالَى</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">الْمَلِكُ</span> <span class=\"quran-arabic-font text-success\">الْحَقُّ</span><br />\r\n<br />\r\n(உண்மையான அரசனாகிய அல்லாஹ் மிக உயர்ந்தவன்.) இதன் பொருள்: அவன் மிகவும் பரிசுத்தமானவன், மகத்துவமிக்கவன். அவனே உண்மையான அரசன்; அவன் சத்தியமானவன், அவனது வாக்குறுதி உண்மையானது. அவ்வாறே அவனது எச்சரிக்கையும், அவனது தூதர்களும், சுவனமும், நரகமும், அவனிடமிருந்து வரும் அனைத்தும் உண்மையானவை. தன் அடியார்களுக்கு எச்சரிக்கை விடுக்காமலும், தூதர்களை அனுப்பாமலும், தகுந்த காரணங்களை அவர்களுக்கு வழங்காமலும் அவன் தண்டிப்பதில்லை என்பது அவனது நீதியாகும். இதனால் (மறுமை நாளில்) எவருக்கும் எந்த வாதமோ சந்தேகமோ இருக்காது.<br />\r\n<br />\r\n<strong>குர்ஆன் வஹீ (இறைச்செய்தி)யாக அருளப்படும்போது அவசரப்படாமல் அதைக் கேட்குமாறு நபி (ஸல்) அவர்களுக்கு இடப்பட்ட கட்டளை</strong><br />\r\n<br />\r\nஅல்லாஹ்வின் இந்தக் கூற்றைப் பற்றி:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَعْجَلْ</span> <span class=\"quran-arabic-font text-success\">بِالْقُرْءانِ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يُقْضَى</span> <span class=\"quran-arabic-font text-success\">إِلَيْكَ</span> <span class=\"quran-arabic-font text-success\">وَحْيُهُ</span><br />\r\n<br />\r\n(மேலும், குர்ஆனின் வஹீ (இறைச்செய்தி) உங்களுக்கு முழுமையாக்கப்படுவதற்கு முன்பு, அதைக் கொண்டு அவசரப்படாதீர்கள்.) இது அல்லாஹ்வின் பின்வரும் கூற்றைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تُحَرِّكْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">لِسَانَكَ</span> <span class=\"quran-arabic-font text-success\">لِتَعْجَلَ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> - <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">عَلَيْنَا</span> <span class=\"quran-arabic-font text-success\">جَمْعَهُ</span> <span class=\"quran-arabic-font text-success\">وَقُرْءَانَهُ</span> - <span class=\"quran-arabic-font text-success\">فَإِذَا</span> <span class=\"quran-arabic-font text-success\">قَرَأْنَاهُ</span> <span class=\"quran-arabic-font text-success\">فَاتَّبِعْ</span> <span class=\"quran-arabic-font text-success\">قُرْءَانَهُ</span> - <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">عَلَيْنَا</span> <span class=\"quran-arabic-font text-success\">بَيَانَهُ</span><br />\r\n<br />\r\n(அவசரமாக ஓதுவதற்காக உமது நாவை அசைக்காதீர். நிச்சயமாக, அதனை ஒன்று சேர்ப்பதும், ஓத வைப்பதும் நமது பொறுப்பாகும். ஆகவே நாம் அதனை ஓதும்போது, அதன் ஓதுதலைப் பின்பற்றுவீராக. பின்னர் அதனைத் தெளிவுபடுத்துவதும் நமது பொறுப்பாகும்.) <a href=\"qurandisp.php?sura=75&ayah=16\" class=\"link\">75:16</a>-19. ஸஹீஹ் (புகாரி)யில் இப்னு அப்பாஸ் (ரழி) அவர்கள் அறிவிக்கிறார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் வஹீ (இறைச்செய்தி)யை உள்வாங்கிக் கொள்வதற்காக மிகுந்த சிரமங்களை எதிர்கொள்வார்கள். அவ்வாறு செய்யும்போது, அவர்கள் தம் நாவை வேகமாக அசைப்பார்கள். அப்போது அல்லாஹ் இந்த வசனத்தை இறக்கியருளினான். அதாவது, ஜிப்ரீல் (அலை) அவர்கள் ஒரு வசனத்தை ஓதும்போது, அதை மனனம் செய்ய வேண்டும் என்ற ஆர்வத்தில் நபி (ஸல்) அவர்களும் அவருடன் சேர்ந்து ஓதுவார்கள். பின்னர், இந்தச் சிரமத்திலிருந்து அவர்களை விடுவிப்பதற்காக, அல்லாஹ் இதைவிட எளிதான வழியை அவர்களுக்குக் காட்டினான். அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تُحَرِّكْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">لِسَانَكَ</span> <span class=\"quran-arabic-font text-success\">لِتَعْجَلَ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> - <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">عَلَيْنَا</span> <span class=\"quran-arabic-font text-success\">جَمْعَهُ</span> <span class=\"quran-arabic-font text-success\">وَقُرْءَانَهُ</span><br />\r\n<br />\r\n(அவசரமாக ஓதுவதற்காக உமது நாவை அசைக்காதீர். நிச்சயமாக, அதனை ஒன்று சேர்ப்பதும், ஓத வைப்பதும் நமது பொறுப்பாகும்.) <a href=\"qurandisp.php?sura=75&ayah=16\" class=\"link\">75:16</a>-17. இதன் பொருள், \"அதனை உமது நெஞ்சில் நாம் ஒன்று சேர்ப்போம்; பிறகு உம்மால் அதிலிருந்து எதையும் மறக்காமல் மக்களுக்கு ஓதிக் காட்ட முடியும்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَإِذَا</span> <span class=\"quran-arabic-font text-success\">قَرَأْنَاهُ</span> <span class=\"quran-arabic-font text-success\">فَاتَّبِعْ</span> <span class=\"quran-arabic-font text-success\">قُرْءَانَهُ</span> - <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">عَلَيْنَا</span> <span class=\"quran-arabic-font text-success\">بَيَانَهُ</span><br />\r\n<br />\r\n(ஆகவே நாம் அதனை ஓதும்போது, அதன் ஓதுதலைப் பின்பற்றுவீராக. பின்னர் அதனைத் தெளிவுபடுத்துவதும் நமது பொறுப்பாகும்.) <a href=\"qurandisp.php?sura=75&ayah=18\" class=\"link\">75:18</a>-19. மேலும் இந்த வசனத்தில் அவன் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَعْجَلْ</span> <span class=\"quran-arabic-font text-success\">بِالْقُرْءانِ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يُقْضَى</span> <span class=\"quran-arabic-font text-success\">إِلَيْكَ</span> <span class=\"quran-arabic-font text-success\">وَحْيُهُ</span><br />\r\n<br />\r\n(மேலும், குர்ஆனின் வஹீ (இறைச்செய்தி) உங்களுக்கு முழுமையாக்கப்படுவதற்கு முன்பு, அதைக் கொண்டு அவசரப்படாதீர்கள்.) இது நபி (ஸல்) அவர்கள் அமைதியாகக் கேட்க வேண்டும் என்பதற்கான கட்டளையாகும்: 'வானவர் (ஜிப்ரீல் (அலை)) உங்களுக்கு ஓதி முடித்ததும், அவருக்குப் பின் நீங்கள் அதை ஓதுங்கள்.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقُل</span> <span class=\"quran-arabic-font text-success\">رَّبِّ</span> <span class=\"quran-arabic-font text-success\">زِدْنِى</span> <span class=\"quran-arabic-font text-success\">عِلْماً</span><br />\r\n<br />\r\n(மேலும் கூறுங்கள்: \"என் இறைவா! எனக்குக் கல்வியை அதிகப்படுத்து.\") அதாவது, \"உன்னிடமிருந்து எனக்கு இன்னும் அதிக ஞானத்தை வழங்குவாயாக.\" இப்னு உயைனா அவர்கள் கூறினார்கள்: \"வல்லமையும் கண்ணியமும் மிக்க அல்லாஹ் நபி (ஸல்) அவர்களைத் தன்வசம் அழைத்துக்கொள்ளும் வரை (அதாவது அவர்கள் மரணிக்கும் வரை), அவர்கள் கல்வியில் மென்மேலும் உயர்வதை நிறுத்தவில்லை.\" இதனால்தான் ஹதீஸில் இவ்வாறு வந்துள்ளது: \"யா அல்லாஹ்! நீ எனக்குக் கற்றுத் தந்தவற்றின் மூலம் எனக்குப் பயனளிப்பாயாக; எனக்குப் பயனளிக்கக்கூடியவற்றை எனக்குக் கற்றுத் தருவாயாக; இன்னும் எனக்குக் கல்வியை அதிகப்படுத்துவாயாக; எல்லா நிலைகளிலும் அல்லாஹ்வுக்கே புகழனைத்தும்.\"<br />\r\n<br />","text":"மக்கள் தக்வா (இறையச்சம்) கொள்ளவும் படிப்பினை பெறவும் குர்ஆன் அருளப்பட்டது\n\r\n\n\r\nமறுமை நாளில் நன்மையோ தீமையோ செய்தவருக்கு அதற்கான கூலி வழங்கப்படும் என்பதையும், அதிலிருந்து தப்பிக்க வழியே இல்லை என்பதையும் மேலானவனான அல்லாஹ் குறிப்பிட்ட பிறகு, தெளிவான மற்றும் செழுமையான அரபி மொழியில் நற்செய்தி கூறுவதாகவும் எச்சரிப்பதாகவும் குர்ஆன் அருளப்பட்டுள்ளது என அவன் விளக்குகிறான். அதில் எந்தக் குழப்பமோ குறையோ இல்லை.\n\r\n\n\r\nوَكَذَلِكَ أَنزَلْنَاهُ قُرْءَانًا عَرَبِيًّا وَصَرَّفْنَا فِيهِ مِنَ الْوَعِيدِ لَعَلَّهُمْ يَتَّقُونَ\n\r\n\n\r\n(இவ்வாறே, நாம் இதனை அரபி மொழி குர்ஆனாக இறக்கியருளினோம்; அவர்கள் தக்வா (இறையச்சம்) கொள்வதற்காக இதில் எச்சரிக்கைகளைத் தெளிவுபடுத்தியுள்ளோம்.) இதன் பொருள்: அவர்கள் பாவங்கள், விலக்கப்பட்டவை மற்றும் அருவருப்பான செயல்களை விட்டுவிடுவதற்காக என்பதாகும்.\n\r\n\n\r\nأَوْ يُحْدِثُ لَهُمْ ذِكْراً\n\r\n\n\r\n(அல்லது அது அவர்களுக்கு ஒரு படிப்பினையை ஏற்படுத்தும்.) இதன் பொருள்: அல்லாஹ்வுக்குக் கீழ்ப்படிவதையும் அவனை நெருங்குவதற்குரிய நற்செயல்களையும் செய்யத் தூண்டுவதாகும்.\n\r\n\n\r\nفَتَعَالَى اللَّهُ الْمَلِكُ الْحَقُّ\n\r\n\n\r\n(உண்மையான அரசனாகிய அல்லாஹ் மிக உயர்ந்தவன்.) இதன் பொருள்: அவன் மிகவும் பரிசுத்தமானவன், மகத்துவமிக்கவன். அவனே உண்மையான அரசன்; அவன் சத்தியமானவன், அவனது வாக்குறுதி உண்மையானது. அவ்வாறே அவனது எச்சரிக்கையும், அவனது தூதர்களும், சுவனமும், நரகமும், அவனிடமிருந்து வரும் அனைத்தும் உண்மையானவை. தன் அடியார்களுக்கு எச்சரிக்கை விடுக்காமலும், தூதர்களை அனுப்பாமலும், தகுந்த காரணங்களை அவர்களுக்கு வழங்காமலும் அவன் தண்டிப்பதில்லை என்பது அவனது நீதியாகும். இதனால் (மறுமை நாளில்) எவருக்கும் எந்த வாதமோ சந்தேகமோ இருக்காது.\n\r\n\n\r\nகுர்ஆன் வஹீ (இறைச்செய்தி)யாக அருளப்படும்போது அவசரப்படாமல் அதைக் கேட்குமாறு நபி (ஸல்) அவர்களுக்கு இடப்பட்ட கட்டளை\n\r\n\n\r\nஅல்லாஹ்வின் இந்தக் கூற்றைப் பற்றி:\n\r\n\n\r\nوَلاَ تَعْجَلْ بِالْقُرْءانِ مِن قَبْلِ أَن يُقْضَى إِلَيْكَ وَحْيُهُ\n\r\n\n\r\n(மேலும், குர்ஆனின் வஹீ (இறைச்செய்தி) உங்களுக்கு முழுமையாக்கப்படுவதற்கு முன்பு, அதைக் கொண்டு அவசரப்படாதீர்கள்.) இது அல்லாஹ்வின் பின்வரும் கூற்றைப் போன்றது:\n\r\n\n\r\nلاَ تُحَرِّكْ بِهِ لِسَانَكَ لِتَعْجَلَ بِهِ - إِنَّ عَلَيْنَا جَمْعَهُ وَقُرْءَانَهُ - فَإِذَا قَرَأْنَاهُ فَاتَّبِعْ قُرْءَانَهُ - ثُمَّ إِنَّ عَلَيْنَا بَيَانَهُ\n\r\n\n\r\n(அவசரமாக ஓதுவதற்காக உமது நாவை அசைக்காதீர். நிச்சயமாக, அதனை ஒன்று சேர்ப்பதும், ஓத வைப்பதும் நமது பொறுப்பாகும். ஆகவே நாம் அதனை ஓதும்போது, அதன் ஓதுதலைப் பின்பற்றுவீராக. பின்னர் அதனைத் தெளிவுபடுத்துவதும் நமது பொறுப்பாகும்.) 75:16-19. ஸஹீஹ் (புகாரி)யில் இப்னு அப்பாஸ் (ரழி) அவர்கள் அறிவிக்கிறார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் வஹீ (இறைச்செய்தி)யை உள்வாங்கிக் கொள்வதற்காக மிகுந்த சிரமங்களை எதிர்கொள்வார்கள். அவ்வாறு செய்யும்போது, அவர்கள் தம் நாவை வேகமாக அசைப்பார்கள். அப்போது அல்லாஹ் இந்த வசனத்தை இறக்கியருளினான். அதாவது, ஜிப்ரீல் (அலை) அவர்கள் ஒரு வசனத்தை ஓதும்போது, அதை மனனம் செய்ய வேண்டும் என்ற ஆர்வத்தில் நபி (ஸல்) அவர்களும் அவருடன் சேர்ந்து ஓதுவார்கள். பின்னர், இந்தச் சிரமத்திலிருந்து அவர்களை விடுவிப்பதற்காக, அல்லாஹ் இதைவிட எளிதான வழியை அவர்களுக்குக் காட்டினான். அல்லாஹ் கூறினான்:\n\r\n\n\r\nلاَ تُحَرِّكْ بِهِ لِسَانَكَ لِتَعْجَلَ بِهِ - إِنَّ عَلَيْنَا جَمْعَهُ وَقُرْءَانَهُ\n\r\n\n\r\n(அவசரமாக ஓதுவதற்காக உமது நாவை அசைக்காதீர். நிச்சயமாக, அதனை ஒன்று சேர்ப்பதும், ஓத வைப்பதும் நமது பொறுப்பாகும்.) 75:16-17. இதன் பொருள், \"அதனை உமது நெஞ்சில் நாம் ஒன்று சேர்ப்போம்; பிறகு உம்மால் அதிலிருந்து எதையும் மறக்காமல் மக்களுக்கு ஓதிக் காட்ட முடியும்.\"\n\r\n\n\r\nفَإِذَا قَرَأْنَاهُ فَاتَّبِعْ قُرْءَانَهُ - ثُمَّ إِنَّ عَلَيْنَا بَيَانَهُ\n\r\n\n\r\n(ஆகவே நாம் அதனை ஓதும்போது, அதன் ஓதுதலைப் பின்பற்றுவீராக. பின்னர் அதனைத் தெளிவுபடுத்துவதும் நமது பொறுப்பாகும்.) 75:18-19. மேலும் இந்த வசனத்தில் அவன் கூறுகிறான்:\n\r\n\n\r\nوَلاَ تَعْجَلْ بِالْقُرْءانِ مِن قَبْلِ أَن يُقْضَى إِلَيْكَ وَحْيُهُ\n\r\n\n\r\n(மேலும், குர்ஆனின் வஹீ (இறைச்செய்தி) உங்களுக்கு முழுமையாக்கப்படுவதற்கு முன்பு, அதைக் கொண்டு அவசரப்படாதீர்கள்.) இது நபி (ஸல்) அவர்கள் அமைதியாகக் கேட்க வேண்டும் என்பதற்கான கட்டளையாகும்: 'வானவர் (ஜிப்ரீல் (அலை)) உங்களுக்கு ஓதி முடித்ததும், அவருக்குப் பின் நீங்கள் அதை ஓதுங்கள்.'\n\r\n\n\r\nوَقُل رَّبِّ زِدْنِى عِلْماً\n\r\n\n\r\n(மேலும் கூறுங்கள்: \"என் இறைவா! எனக்குக் கல்வியை அதிகப்படுத்து.\") அதாவது, \"உன்னிடமிருந்து எனக்கு இன்னும் அதிக ஞானத்தை வழங்குவாயாக.\" இப்னு உயைனா அவர்கள் கூறினார்கள்: \"வல்லமையும் கண்ணியமும் மிக்க அல்லாஹ் நபி (ஸல்) அவர்களைத் தன்வசம் அழைத்துக்கொள்ளும் வரை (அதாவது அவர்கள் மரணிக்கும் வரை), அவர்கள் கல்வியில் மென்மேலும் உயர்வதை நிறுத்தவில்லை.\" இதனால்தான் ஹதீஸில் இவ்வாறு வந்துள்ளது: \"யா அல்லாஹ்! நீ எனக்குக் கற்றுத் தந்தவற்றின் மூலம் எனக்குப் பயனளிப்பாயாக; எனக்குப் பயனளிக்கக்கூடியவற்றை எனக்குக் கற்றுத் தருவாயாக; இன்னும் எனக்குக் கல்வியை அதிகப்படுத்துவாயாக; எல்லா நிலைகளிலும் அல்லாஹ்வுக்கே புகழனைத்தும்.\""},"115":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=122\" class=\"link\">20:122</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:122 ஐ பார்க்கவும்"},"116":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=122\" class=\"link\">20:122</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:122 ஐ பார்க்கவும்"},"117":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=122\" class=\"link\">20:122</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:122 ஐ பார்க்கவும்"},"118":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=122\" class=\"link\">20:122</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:122 ஐ பார்க்கவும்"},"119":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=122\" class=\"link\">20:122</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:122 ஐ பார்க்கவும்"},"120":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=122\" class=\"link\">20:122</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:122 ஐ பார்க்கவும்"},"121":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=122\" class=\"link\">20:122</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:122 ஐ பார்க்கவும்"},"122":{"html":"<strong>ஆதம் (அலை) மற்றும் இப்லீஸின் கதை</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">عَهِدْنَآ</span> <span class=\"quran-arabic-font text-success\">إِلَىٰٓ</span> <span class=\"quran-arabic-font text-success\">ءَادَمَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلُ</span> <span class=\"quran-arabic-font text-success\">فَنَسِىَ</span> <span class=\"quran-arabic-font text-success\">وَلَمْ</span> <span class=\"quran-arabic-font text-success\">نَجِدْ</span> <span class=\"quran-arabic-font text-success\">لَهُۥ</span> <span class=\"quran-arabic-font text-success\">عَزْمًا</span><br />\r\n<br />\r\n(\"நிச்சயமாக இதற்கு முன்னர் நாம் ஆதமிடம் (ஒரு) வாக்குறுதி வாங்கினோம்; ஆனால் அவர் (அதை) மறந்துவிட்டார்; அவரிடம் (உறுதியான) மனவலிமையை நாம் காணவில்லை.\")<br />\r\n<br />\r\nஇப்னு அபீ ஹாதிம் அவர்கள் பதிவு செய்துள்ளார்கள்: இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள், \"நிச்சயமாக, மனிதனுக்கு ஒரு உடன்படிக்கை வழங்கப்பட்டு, அவன் அதை மறந்துவிட்டதால் (நஸிய) அவனுக்கு 'இன்ஸான்' என்று பெயரிடப்பட்டது.\" அலீ பின் அபீ தல்ஹா அவர்களும் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து இதையே அறிவித்துள்ளார்கள். \"அவன் மறந்துவிட்டான்\" என்பதன் பொருள், \"அவன் அதை விட்டுவிட்டான்\" என்பதாகும் என்று முஜாஹித் மற்றும் அல்-ஹஸன் ஆகியோர் கூறினார்கள். அல்லாஹ்வின் இக்கூற்றைப் பொறுத்தவரை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِذْ</span> <span class=\"quran-arabic-font text-success\">قُلْنَا</span> <span class=\"quran-arabic-font text-success\">لِلْمَلَائِكَةِ</span> <span class=\"quran-arabic-font text-success\">اسْجُدُواْ</span> <span class=\"quran-arabic-font text-success\">لِآدَمَ</span><br />\r\n<br />\r\n(\"மேலும், நாம் வானவர்களிடம்: 'ஆதமுக்கு ஸஜ்தா செய்யுங்கள்' என்று கூறியபோது.\") ஆதம் (அலை) அவர்கள் எவ்வாறு கண்ணியப்படுத்தப்பட்டார்கள், அவர்களுக்கு எத்தகைய மரியாதை வழங்கப்பட்டது என்பதை இங்கு அல்லாஹ் குறிப்பிடுகிறான். தான் படைத்த பலரை விட அவருக்கு எவ்வாறு சிறப்பளித்தான் என்பதையும் அவன் குறிப்பிடுகிறான். இந்தக் கதையைப் பற்றிய விளக்கம் ஏற்கனவே ஸூரத்துல் பகரா, ஸூரத்துல் அஃராஃப், ஸூரத்துல் ஹிஜ்ர் மற்றும் ஸூரத்துல் கஹ்ஃப் ஆகியவற்றில் இடம்பெற்றுள்ளது. இது ஸூரா ஸாத்தின் இறுதியிலும் மீண்டும் குறிப்பிடப்படும். இந்தக் கதையில், ஆதம் (அலை) அவர்களின் படைப்பைப் பற்றியும், அவர்களுக்குக் கண்ணியமும் மரியாதையும் அளிக்கும் விதமாக ஸஜ்தா செய்யுமாறு வானவர்களுக்கு அல்லாஹ் கட்டளையிட்டதையும் அவன் குறிப்பிடுகிறான். மேலும், ஆதமின் சந்ததியினர் மீதும், அவர்களுக்கு முன்னால் அவர்களின் தந்தை ஆதம் (அலை) அவர்கள் மீதும் இப்லீஸ் கொண்டிருந்த பகைமையையும் அவன் விளக்குகிறான். இதன் காரணமாகவே அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَسَجَدُواْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">إِبْلِيسَ</span> <span class=\"quran-arabic-font text-success\">أَبَى</span><br />\r\n<br />\r\n(\"இப்லீஸைத் தவிர அவர்கள் (அனைவரும்) ஸஜ்தா செய்தார்கள்; அவன் மறுத்துவிட்டான்.\") அதாவது, அவன் ஸஜ்தா செய்ய மறுத்துப் பெருமையடித்தான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَقُلْنَا</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">آدَمُ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">عَدُوٌّ</span> <span class=\"quran-arabic-font text-success\">لَّكَ</span> <span class=\"quran-arabic-font text-success\">وَلِزَوْجِكَ</span><br />\r\n<br />\r\n(\"பின்னர் நாம் கூறினோம்: 'ஆதமே! நிச்சயமாக இவன் உமக்கும் உம்முடைய மனைவிக்கும் எதிரியாவான்...'\") இங்கு 'மனைவி' என்பது ஹவ்வா (அலை) அவர்களைக் குறிக்கிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَلاَ</span> <span class=\"quran-arabic-font text-success\">يُخْرِجَنَّكُمَا</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">فَتَشْقَى</span><br />\r\n<br />\r\n(\"ஆகவே, அவன் உங்கள் இருவரையும் சொர்க்கத்திலிருந்து வெளியேற்றிவிட வேண்டாம்; (அவ்வாறு வெளியேறினால்) நீர் துன்பத்திற்குள்ளாவீர்.\") அதாவது, 'சொர்க்கத்திலிருந்து உங்களை வெளியேற்றக்கூடிய எதையும் செய்வதற்கு அவசரப்படாதீர்கள்; இல்லையெனில் நீர் உமது வாழ்வாதாரத்தைத் தேடி அலைந்து களைப்படையவும், சிரமப்படவும், கவலைப்படவும் நேரிடும். ஆனால், இந்தச் சொர்க்கத்திலோ நீர் எந்தச் சுமைகளும் கஷ்டங்களும் இன்றி சுகமான வாழ்வு வாழ்கிறீர்.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">أَلاَّ</span> <span class=\"quran-arabic-font text-success\">تَجُوعَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَعْرَى</span><br />\r\n<br />\r\n(\"நிச்சயமாக, நீர் அதில் பசியடையவும் மாட்டீர், நிர்வாணமாக இருக்கவும் மாட்டீர்.\") பசியையும் நிர்வாணத்தையும் அல்லாஹ் இங்கு ஒன்றாகக் குறிப்பிட்டதற்குக் காரணம், பசி என்பது அகரீதியான அவமானம், நிர்வாணம் என்பது புறரீதியான அவமானம் என்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَنَّكَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَظْمَؤُا</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَضْحَى</span><br />\r\n<br />\r\n(\"மேலும், நீர் அதில் தாகிக்கவும் மாட்டீர், வெயிலால் (வெப்பத்தால்) கஷ்டப்படவும் மாட்டீர்.\") இந்த இரண்டு தன்மைகளும் ஒன்றிற்கொன்று எதிரானவை. தாகம் என்பது அக வெப்பம் மற்றும் நீர் இன்மையால் ஏற்படும் வறட்சி; வெயில் என்பது புற வெப்பமாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَوَسْوَسَ</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِ</span> <span class=\"quran-arabic-font text-success\">الشَّيْطَانُ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">آدَمُ</span> <span class=\"quran-arabic-font text-success\">هَلْ</span> <span class=\"quran-arabic-font text-success\">أَدُلُّكَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">شَجَرَةِ</span> <span class=\"quran-arabic-font text-success\">الْخُلْدِ</span> <span class=\"quran-arabic-font text-success\">وَمُلْكٍ</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يَبْلَى</span><br />\r\n<br />\r\n(\"பின்னர் ஷைத்தான் அவருக்கு ஊசலாட்டத்தை ஏற்படுத்தினான்; அவன் கூறினான்: 'ஆதமே! நிலையான வாழ்வளிக்கும் மரத்தைப் பற்றியும், ஒருபோதும் அழியாத ஓர் அரசாங்கத்தைப் பற்றியும் உமக்கு நான் அறிவிக்கட்டுமா?'\") அவன் வஞ்சகத்தின் மூலம் அவர்களை வீழ்த்தினான் என்பது ஏற்கனவே குறிப்பிடப்பட்டுள்ளது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَاسَمَهُمَآ</span> <span class=\"quran-arabic-font text-success\">إِنِّي</span> <span class=\"quran-arabic-font text-success\">لَكُمَا</span> <span class=\"quran-arabic-font text-success\">لَمِنَ</span> <span class=\"quran-arabic-font text-success\">النَّاصِحِينَ</span><br />\r\n<br />\r\n(\"நிச்சயமாக நான் உங்கள் இருவருக்கும் நலம் விரும்புபவர்களில் ஒருவன் என்று அவன் அவர்கள் இருவரிடமும் (அல்லாஹ்வின் மீது) சத்தியம் செய்தான்.\") <a href=\"qurandisp.php?sura=7&ayah=21\" class=\"link\">7:21</a> சொர்க்கத்திலுள்ள அனைத்துப் பழங்களையும் அவர்கள் உண்ணலாம், ஆனால் ஒரு குறிப்பிட்ட மரத்தை மட்டும் நெருங்கக்கூடாது என்று அல்லாஹ் ஆதம் (அலை) அவர்களிடமும் அவரது மனைவியிடமும் உடன்படிக்கை செய்திருந்தான் என்பது ஏற்கனவே விளக்கப்பட்டுள்ளது. இருப்பினும், அவர்கள் இருவரும் அதிலிருந்து உண்ணும் வரை இப்லீஸ் அவர்களைத் தூண்டிக்கொண்டே இருந்தான். அது 'ஷஜரத்துல் குல்த்' (நிலையான வாழ்வளிக்கும் மரம்) ஆகும். அதன் கனியை உண்பவர் மரணமின்றி என்றும் நிலைத்திருப்பார் என்பது அதன் பொருளாகும். இந்த நிலையான வாழ்வளிக்கும் மரத்தைப் பற்றி ஒரு ஹதீஸ் அறிவிக்கப்பட்டுள்ளது. அபூ ஹுரைரா (ரழி) அவர்கள் அறிவிக்கிறார்கள்: நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">شَجَرَةً</span> <span class=\"quran-arabic-font text-success\">يَسِيرُ</span> <span class=\"quran-arabic-font text-success\">الرَّاكِبُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">ظِلِّهَا</span> <span class=\"quran-arabic-font text-success\">مِائَةَ</span> <span class=\"quran-arabic-font text-success\">عَامٍ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَقْطَعُهَا،</span> <span class=\"quran-arabic-font text-success\">وَهِيَ</span> <span class=\"quran-arabic-font text-success\">شَجَرَةُ</span> <span class=\"quran-arabic-font text-success\">الْخُلْد</span>»<br />\r\n<br />\r\n(\"நிச்சயமாகச் சொர்க்கத்தில் ஒரு மரம் இருக்கிறது; அதன் நிழலில் ஒரு பயணி நூறு ஆண்டுகள் பயணித்தாலும் அதைக் கடக்க முடியாது. அதுதான் நிலையான வாழ்வளிக்கும் மரமாகும்.\") இந்த ஹதீஸை இமாம் அஹ்மத் அவர்களும் பதிவு செய்துள்ளார்கள். அல்லாஹ்வின் இக்கூற்றைப் பொறுத்தவரை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأَكَلاَ</span> <span class=\"quran-arabic-font text-success\">مِنْهَا</span> <span class=\"quran-arabic-font text-success\">فَبَدَتْ</span> <span class=\"quran-arabic-font text-success\">لَهُمَا</span> <span class=\"quran-arabic-font text-success\">سَوْءَتُهُمَا</span><br />\r\n<br />\r\n(\"பின்னர் அவர்கள் இருவரும் அதிலிருந்து உண்டார்கள்; உடனே அவர்களின் மறைவிடங்கள் அவர்களுக்கு வெளிப்பட்டன.\") உபை பின் கஅப் (ரழி) அவர்கள் அறிவிக்கிறார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">خَلَقَ</span> <span class=\"quran-arabic-font text-success\">آدَمَ</span> <span class=\"quran-arabic-font text-success\">رَجُلًا</span> <span class=\"quran-arabic-font text-success\">طُوَالًا</span> <span class=\"quran-arabic-font text-success\">كَثِيرَ</span> <span class=\"quran-arabic-font text-success\">شَعْرِ</span> <span class=\"quran-arabic-font text-success\">الرَّأْسِ،</span> <span class=\"quran-arabic-font text-success\">كَأَنَّهُ</span> <span class=\"quran-arabic-font text-success\">نَخْلَةُ</span> <span class=\"quran-arabic-font text-success\">سَحُوقٍ،</span> <span class=\"quran-arabic-font text-success\">فَلَمَّا</span> <span class=\"quran-arabic-font text-success\">ذَاقَ</span> <span class=\"quran-arabic-font text-success\">الشَّجَرَةَ</span> <span class=\"quran-arabic-font text-success\">سَقَطَ</span> <span class=\"quran-arabic-font text-success\">عَنْهُ</span> <span class=\"quran-arabic-font text-success\">لِبَاسُهُ،</span> <span class=\"quran-arabic-font text-success\">فَأَوَّلُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">بَدَا</span> <span class=\"quran-arabic-font text-success\">مِنْهُ</span> <span class=\"quran-arabic-font text-success\">عَوْرَتُهُ،</span> <span class=\"quran-arabic-font text-success\">فَلَمَّا</span> <span class=\"quran-arabic-font text-success\">نَظَرَ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">عَوْرَتِهِ</span> <span class=\"quran-arabic-font text-success\">جَعَلَ</span> <span class=\"quran-arabic-font text-success\">يَشْتَدُّ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ،</span> <span class=\"quran-arabic-font text-success\">فَأَخَذَتْ</span> <span class=\"quran-arabic-font text-success\">شَعْرَهُ</span> <span class=\"quran-arabic-font text-success\">شَجَرَةٌ</span> <span class=\"quran-arabic-font text-success\">فَنَازَعَهَا،</span> <span class=\"quran-arabic-font text-success\">فَنَادَاهُ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَنُ</span>: <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">آدَمُ</span> <span class=\"quran-arabic-font text-success\">مِنِّي</span> <span class=\"quran-arabic-font text-success\">تَفِرُّ،</span> <span class=\"quran-arabic-font text-success\">فَلَمَّا</span> <span class=\"quran-arabic-font text-success\">سَمِعَ</span> <span class=\"quran-arabic-font text-success\">كَلَامَ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَنِ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span>: <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">لَا،</span> <span class=\"quran-arabic-font text-success\">وَلَكِنِ</span> <span class=\"quran-arabic-font text-success\">اسْتِحْيَاءً،</span> <span class=\"quran-arabic-font text-success\">أَرَأَيْتَ</span> <span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">تُبْتُ</span> <span class=\"quran-arabic-font text-success\">وَرَجَعْتُ</span> <span class=\"quran-arabic-font text-success\">أَعَائِدِي</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ؟</span> <span class=\"quran-arabic-font text-success\">قَالَ</span>: <span class=\"quran-arabic-font text-success\">نَعَم</span>»<br />\r\n<br />\r\n(\"நிச்சயமாக அல்லாஹ் ஆதம் (அலை) அவர்களைத் தலையில் அடர்த்தியான முடியைக் கொண்ட உயரமான மனிதராகப் படைத்தான்; அவர் ஒரு நீண்ட பேரீச்சை மரத்தைப் போன்று இருந்தார். அவர் அந்த மரத்தின் கனியைச் சுவைத்தபோது, அவரது ஆடை அவரை விட்டு நீங்கியது. முதலில் அவரது மறைவிடமே வெளிப்பட்டது. அவர் தனது மறைவிடத்தைக் கண்டதும் சொர்க்கத்திற்குள் ஓடத் தொடங்கினார். அப்போது ஒரு மரம் அவரது தலைமுடியைப் பிடித்துக்கொண்டது; அவர் அதிலிருந்து விடுபடப் போராடினார். அப்போது ரஹ்மான் (அளவற்ற அருளாளன்) அவரை அழைத்து: 'ஆதமே! நீர் என்னிடமிருந்தா ஓடுகிறீர்?' என்று கேட்டான். ரஹ்மானின் பேச்சைக் கேட்டதும் அவர்: 'இல்லை என் இறைவா! மாறாக, வெட்கத்தினால் (ஓடுகிறேன்). நான் தவ்பா செய்து மீண்டால், என்னை மீண்டும் சொர்க்கத்திற்குத் திருப்புவாயா?' என்று கேட்டார். அதற்கு அவன் 'ஆம்' என்றான்.\") இதுவே அல்லாஹ்வின் இக்கூற்றின் பொருளாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَتَلَقَّى</span> <span class=\"quran-arabic-font text-success\">ءَادَمُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">رَّبِّهِ</span> <span class=\"quran-arabic-font text-success\">كَلِمَاتٍ</span> <span class=\"quran-arabic-font text-success\">فَتَابَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span><br />\r\n<br />\r\n(\"பின்னர் ஆதம் தம் இறைவனிடமிருந்து சில வார்த்தைகளைக் கற்றுக்கொண்டார்; எனவே அவன் அவரை மன்னித்தான்.\") <a href=\"qurandisp.php?sura=2&ayah=37\" class=\"link\">2:37</a> இருப்பினும், இந்த அறிவிப்பாளர் தொடரில் அல்-ஹஸனுக்கும் உபை பின் கஅப் (ரழி) அவர்களுக்குமிடையில் முறிவு உள்ளது. அல்-ஹஸன் இந்த ஹதீஸை உபை (ரழி) அவர்களிடமிருந்து நேரடியாகக் கேட்கவில்லை. இந்த அறிவிப்பு நபி (ஸல்) அவர்களிடமிருந்து வந்ததா என்பது சந்தேகத்திற்குரியது. அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَطَفِقَا</span> <span class=\"quran-arabic-font text-success\">يَخْصِفَانِ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">وَرَقِ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span><br />\r\n<br />\r\n(\"மேலும் அவர்கள் சொர்க்கத்தின் இலைகளைக் கொண்டு தங்களை மூடிக்கொள்ளத் தொடங்கினார்கள்.\") முஜாஹித் அவர்கள் கூறினார்கள்: \"அவர்கள் இலைகளை ஆடை போலத் தம்மீது ஒட்டத் தொடங்கினார்கள்.\" கத்தாதா மற்றும் அஸ்-ஸுத்தீ ஆகியோரும் இதையே கூறினார்கள். அல்லாஹ்வின் இக்கூற்றைப் பொறுத்தவரை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأَكَلاَ</span> <span class=\"quran-arabic-font text-success\">مِنْهَا</span> <span class=\"quran-arabic-font text-success\">فَبَدَتْ</span> <span class=\"quran-arabic-font text-success\">لَهُمَا</span> <span class=\"quran-arabic-font text-success\">سَوْءَتُهُمَا</span> <span class=\"quran-arabic-font text-success\">وَطَفِقَا</span> <span class=\"quran-arabic-font text-success\">يَخْصِفَانِ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">وَرَقِ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">وَعَصَى</span> <span class=\"quran-arabic-font text-success\">ءَادَمُ</span> <span class=\"quran-arabic-font text-success\">رَبَّهُ</span> <span class=\"quran-arabic-font text-success\">فَغَوَى</span> - <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">اجْتَبَاهُ</span> <span class=\"quran-arabic-font text-success\">رَبُّهُ</span> <span class=\"quran-arabic-font text-success\">فَتَابَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">وَهَدَى</span><br />\r\n<br />\r\n(\"பின்னர் அவர்கள் இருவரும் அதிலிருந்து உண்டார்கள்; உடனே அவர்களின் மறைவிடங்கள் அவர்களுக்கு வெளிப்பட்டன. மேலும் அவர்கள் சொர்க்கத்தின் இலைகளைக் கொண்டு தங்களை மூடிக்கொள்ளத் தொடங்கினார்கள். இவ்வாறு ஆதம் தம் இறைவனுக்கு மாறு செய்தார்; அதனால் அவர் வழிதவறினார். பின்னர் அவரது இறைவன் அவரைத் தேர்ந்தெடுத்து, அவரை மன்னித்து, அவருக்கு நேர்வழியைக் காட்டினான்.\") அபூ ஹுரைரா (ரழி) அவர்கள் அறிவிக்கிறார்கள்: நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">حَاجَّ</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span> <span class=\"quran-arabic-font text-success\">آدَمَ،</span> <span class=\"quran-arabic-font text-success\">فَقَالَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span>: <span class=\"quran-arabic-font text-success\">أَنْتَ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">أَخْرَجْتَ</span> <span class=\"quran-arabic-font text-success\">النَّاسَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">بِذَنْبِكَ</span> <span class=\"quran-arabic-font text-success\">وَأَشْقَيْتَهُمْ؟</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">آدَمُ</span>: <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">مُوسَى،</span> <span class=\"quran-arabic-font text-success\">أَنْتَ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">اصْطَفَاكَ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">بِرِسَالَاتِهِ</span> <span class=\"quran-arabic-font text-success\">وَبِكَلَامِهِ،</span> <span class=\"quran-arabic-font text-success\">أَتَلُومُنِي</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَمْرٍ</span> <span class=\"quran-arabic-font text-success\">كَتَبَهُ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">عَلَيَّ</span> <span class=\"quran-arabic-font text-success\">قَبْلَ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يَخْلُقَنِي</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">قَدَّرَهُ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">عَلَيَّ</span> <span class=\"quran-arabic-font text-success\">قَبْلَ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يَخْلُقَنِي؟</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">رَسُولُ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">صَلَّى</span> <span class=\"quran-arabic-font text-success\">الله</span> <span class=\"quran-arabic-font text-success\">عليه</span> <span class=\"quran-arabic-font text-success\">وسلّم</span>: <span class=\"quran-arabic-font text-success\">فَحَجَّ</span> <span class=\"quran-arabic-font text-success\">آدَمُ</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span>»<br />\r\n<br />\r\n(\"மூஸா (அலை) அவர்கள் ஆதம் (அலை) அவர்களிடம் விவாதித்தார்கள். அவர் கூறினார்கள்: 'உமது பாவத்தினால் மனிதர்களைச் சொர்க்கத்திலிருந்து வெளியேற்றி, அவர்களைத் துன்பத்திற்குள்ளாக்கியவர் நீர்தானே?' அதற்கு ஆதம் (அலை) அவர்கள்: 'மூஸாவே! அல்லாஹ் தனது வஹீ (இறைச்செய்தி)களுக்காகவும், தனது நேரடிப் பேச்சுக்காகவும் தேர்ந்தெடுத்தவர் நீர்தானே? நான் படைக்கப்படுவதற்கு முன்பே அல்லாஹ் என் மீது விதித்துவிட்ட ஒரு விஷயத்திற்காகவா நீர் என்னைக் குறை கூறுகிறீர்?' என்று கேட்டார்கள்.\") பின்னர் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்: (\"இவ்வாறு ஆதம் (அலை) அவர்கள் மூஸா (அலை) அவர்களைத் தர்க்கத்தில் வென்றுவிட்டார்கள்.\") இந்த ஹதீஸ் புகாரி, முஸ்லிம் ஆகிய இரு ஸஹீஹ் நூல்களிலும் மற்றும் முஸ்னத் தொகுப்புகளிலும் பல்வேறு அறிவிப்பாளர் தொடர்களில் இடம்பெற்றுள்ளது.<br />\r\n<br />","text":"ஆதம் (அலை) மற்றும் இப்லீஸின் கதை\n\r\n\n\r\nوَلَقَدْ عَهِدْنَآ إِلَىٰٓ ءَادَمَ مِن قَبْلُ فَنَسِىَ وَلَمْ نَجِدْ لَهُۥ عَزْمًا\n\r\n\n\r\n(\"நிச்சயமாக இதற்கு முன்னர் நாம் ஆதமிடம் (ஒரு) வாக்குறுதி வாங்கினோம்; ஆனால் அவர் (அதை) மறந்துவிட்டார்; அவரிடம் (உறுதியான) மனவலிமையை நாம் காணவில்லை.\")\n\r\n\n\r\nஇப்னு அபீ ஹாதிம் அவர்கள் பதிவு செய்துள்ளார்கள்: இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள், \"நிச்சயமாக, மனிதனுக்கு ஒரு உடன்படிக்கை வழங்கப்பட்டு, அவன் அதை மறந்துவிட்டதால் (நஸிய) அவனுக்கு 'இன்ஸான்' என்று பெயரிடப்பட்டது.\" அலீ பின் அபீ தல்ஹா அவர்களும் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து இதையே அறிவித்துள்ளார்கள். \"அவன் மறந்துவிட்டான்\" என்பதன் பொருள், \"அவன் அதை விட்டுவிட்டான்\" என்பதாகும் என்று முஜாஹித் மற்றும் அல்-ஹஸன் ஆகியோர் கூறினார்கள். அல்லாஹ்வின் இக்கூற்றைப் பொறுத்தவரை:\n\r\n\n\r\nوَإِذْ قُلْنَا لِلْمَلَائِكَةِ اسْجُدُواْ لِآدَمَ\n\r\n\n\r\n(\"மேலும், நாம் வானவர்களிடம்: 'ஆதமுக்கு ஸஜ்தா செய்யுங்கள்' என்று கூறியபோது.\") ஆதம் (அலை) அவர்கள் எவ்வாறு கண்ணியப்படுத்தப்பட்டார்கள், அவர்களுக்கு எத்தகைய மரியாதை வழங்கப்பட்டது என்பதை இங்கு அல்லாஹ் குறிப்பிடுகிறான். தான் படைத்த பலரை விட அவருக்கு எவ்வாறு சிறப்பளித்தான் என்பதையும் அவன் குறிப்பிடுகிறான். இந்தக் கதையைப் பற்றிய விளக்கம் ஏற்கனவே ஸூரத்துல் பகரா, ஸூரத்துல் அஃராஃப், ஸூரத்துல் ஹிஜ்ர் மற்றும் ஸூரத்துல் கஹ்ஃப் ஆகியவற்றில் இடம்பெற்றுள்ளது. இது ஸூரா ஸாத்தின் இறுதியிலும் மீண்டும் குறிப்பிடப்படும். இந்தக் கதையில், ஆதம் (அலை) அவர்களின் படைப்பைப் பற்றியும், அவர்களுக்குக் கண்ணியமும் மரியாதையும் அளிக்கும் விதமாக ஸஜ்தா செய்யுமாறு வானவர்களுக்கு அல்லாஹ் கட்டளையிட்டதையும் அவன் குறிப்பிடுகிறான். மேலும், ஆதமின் சந்ததியினர் மீதும், அவர்களுக்கு முன்னால் அவர்களின் தந்தை ஆதம் (அலை) அவர்கள் மீதும் இப்லீஸ் கொண்டிருந்த பகைமையையும் அவன் விளக்குகிறான். இதன் காரணமாகவே அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nفَسَجَدُواْ إِلاَّ إِبْلِيسَ أَبَى\n\r\n\n\r\n(\"இப்லீஸைத் தவிர அவர்கள் (அனைவரும்) ஸஜ்தா செய்தார்கள்; அவன் மறுத்துவிட்டான்.\") அதாவது, அவன் ஸஜ்தா செய்ய மறுத்துப் பெருமையடித்தான்.\n\r\n\n\r\nفَقُلْنَا يَا آدَمُ إِنَّ هَـذَا عَدُوٌّ لَّكَ وَلِزَوْجِكَ\n\r\n\n\r\n(\"பின்னர் நாம் கூறினோம்: 'ஆதமே! நிச்சயமாக இவன் உமக்கும் உம்முடைய மனைவிக்கும் எதிரியாவான்...'\") இங்கு 'மனைவி' என்பது ஹவ்வா (அலை) அவர்களைக் குறிக்கிறது.\n\r\n\n\r\nفَلاَ يُخْرِجَنَّكُمَا مِنَ الْجَنَّةِ فَتَشْقَى\n\r\n\n\r\n(\"ஆகவே, அவன் உங்கள் இருவரையும் சொர்க்கத்திலிருந்து வெளியேற்றிவிட வேண்டாம்; (அவ்வாறு வெளியேறினால்) நீர் துன்பத்திற்குள்ளாவீர்.\") அதாவது, 'சொர்க்கத்திலிருந்து உங்களை வெளியேற்றக்கூடிய எதையும் செய்வதற்கு அவசரப்படாதீர்கள்; இல்லையெனில் நீர் உமது வாழ்வாதாரத்தைத் தேடி அலைந்து களைப்படையவும், சிரமப்படவும், கவலைப்படவும் நேரிடும். ஆனால், இந்தச் சொர்க்கத்திலோ நீர் எந்தச் சுமைகளும் கஷ்டங்களும் இன்றி சுகமான வாழ்வு வாழ்கிறீர்.'\n\r\n\n\r\nإِنَّ لَكَ أَلاَّ تَجُوعَ فِيهَا وَلاَ تَعْرَى\n\r\n\n\r\n(\"நிச்சயமாக, நீர் அதில் பசியடையவும் மாட்டீர், நிர்வாணமாக இருக்கவும் மாட்டீர்.\") பசியையும் நிர்வாணத்தையும் அல்லாஹ் இங்கு ஒன்றாகக் குறிப்பிட்டதற்குக் காரணம், பசி என்பது அகரீதியான அவமானம், நிர்வாணம் என்பது புறரீதியான அவமானம் என்பதாகும்.\n\r\n\n\r\nوَأَنَّكَ لاَ تَظْمَؤُا فِيهَا وَلاَ تَضْحَى\n\r\n\n\r\n(\"மேலும், நீர் அதில் தாகிக்கவும் மாட்டீர், வெயிலால் (வெப்பத்தால்) கஷ்டப்படவும் மாட்டீர்.\") இந்த இரண்டு தன்மைகளும் ஒன்றிற்கொன்று எதிரானவை. தாகம் என்பது அக வெப்பம் மற்றும் நீர் இன்மையால் ஏற்படும் வறட்சி; வெயில் என்பது புற வெப்பமாகும்.\n\r\n\n\r\nفَوَسْوَسَ إِلَيْهِ الشَّيْطَانُ قَالَ يَا آدَمُ هَلْ أَدُلُّكَ عَلَى شَجَرَةِ الْخُلْدِ وَمُلْكٍ لاَّ يَبْلَى\n\r\n\n\r\n(\"பின்னர் ஷைத்தான் அவருக்கு ஊசலாட்டத்தை ஏற்படுத்தினான்; அவன் கூறினான்: 'ஆதமே! நிலையான வாழ்வளிக்கும் மரத்தைப் பற்றியும், ஒருபோதும் அழியாத ஓர் அரசாங்கத்தைப் பற்றியும் உமக்கு நான் அறிவிக்கட்டுமா?'\") அவன் வஞ்சகத்தின் மூலம் அவர்களை வீழ்த்தினான் என்பது ஏற்கனவே குறிப்பிடப்பட்டுள்ளது.\n\r\n\n\r\nوَقَاسَمَهُمَآ إِنِّي لَكُمَا لَمِنَ النَّاصِحِينَ\n\r\n\n\r\n(\"நிச்சயமாக நான் உங்கள் இருவருக்கும் நலம் விரும்புபவர்களில் ஒருவன் என்று அவன் அவர்கள் இருவரிடமும் (அல்லாஹ்வின் மீது) சத்தியம் செய்தான்.\") 7:21 சொர்க்கத்திலுள்ள அனைத்துப் பழங்களையும் அவர்கள் உண்ணலாம், ஆனால் ஒரு குறிப்பிட்ட மரத்தை மட்டும் நெருங்கக்கூடாது என்று அல்லாஹ் ஆதம் (அலை) அவர்களிடமும் அவரது மனைவியிடமும் உடன்படிக்கை செய்திருந்தான் என்பது ஏற்கனவே விளக்கப்பட்டுள்ளது. இருப்பினும், அவர்கள் இருவரும் அதிலிருந்து உண்ணும் வரை இப்லீஸ் அவர்களைத் தூண்டிக்கொண்டே இருந்தான். அது 'ஷஜரத்துல் குல்த்' (நிலையான வாழ்வளிக்கும் மரம்) ஆகும். அதன் கனியை உண்பவர் மரணமின்றி என்றும் நிலைத்திருப்பார் என்பது அதன் பொருளாகும். இந்த நிலையான வாழ்வளிக்கும் மரத்தைப் பற்றி ஒரு ஹதீஸ் அறிவிக்கப்பட்டுள்ளது. அபூ ஹுரைரா (ரழி) அவர்கள் அறிவிக்கிறார்கள்: நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِنَّ فِي الْجَنَّةِ شَجَرَةً يَسِيرُ الرَّاكِبُ فِي ظِلِّهَا مِائَةَ عَامٍ مَا يَقْطَعُهَا، وَهِيَ شَجَرَةُ الْخُلْد»\n\r\n\n\r\n(\"நிச்சயமாகச் சொர்க்கத்தில் ஒரு மரம் இருக்கிறது; அதன் நிழலில் ஒரு பயணி நூறு ஆண்டுகள் பயணித்தாலும் அதைக் கடக்க முடியாது. அதுதான் நிலையான வாழ்வளிக்கும் மரமாகும்.\") இந்த ஹதீஸை இமாம் அஹ்மத் அவர்களும் பதிவு செய்துள்ளார்கள். அல்லாஹ்வின் இக்கூற்றைப் பொறுத்தவரை:\n\r\n\n\r\nفَأَكَلاَ مِنْهَا فَبَدَتْ لَهُمَا سَوْءَتُهُمَا\n\r\n\n\r\n(\"பின்னர் அவர்கள் இருவரும் அதிலிருந்து உண்டார்கள்; உடனே அவர்களின் மறைவிடங்கள் அவர்களுக்கு வெளிப்பட்டன.\") உபை பின் கஅப் (ரழி) அவர்கள் அறிவிக்கிறார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِنَّ اللهَ خَلَقَ آدَمَ رَجُلًا طُوَالًا كَثِيرَ شَعْرِ الرَّأْسِ، كَأَنَّهُ نَخْلَةُ سَحُوقٍ، فَلَمَّا ذَاقَ الشَّجَرَةَ سَقَطَ عَنْهُ لِبَاسُهُ، فَأَوَّلُ مَا بَدَا مِنْهُ عَوْرَتُهُ، فَلَمَّا نَظَرَ إِلَى عَوْرَتِهِ جَعَلَ يَشْتَدُّ فِي الْجَنَّةِ، فَأَخَذَتْ شَعْرَهُ شَجَرَةٌ فَنَازَعَهَا، فَنَادَاهُ الرَّحْمَنُ: يَا آدَمُ مِنِّي تَفِرُّ، فَلَمَّا سَمِعَ كَلَامَ الرَّحْمَنِ قَالَ: يَا رَبِّ لَا، وَلَكِنِ اسْتِحْيَاءً، أَرَأَيْتَ إِنْ تُبْتُ وَرَجَعْتُ أَعَائِدِي إِلَى الْجَنَّةِ؟ قَالَ: نَعَم»\n\r\n\n\r\n(\"நிச்சயமாக அல்லாஹ் ஆதம் (அலை) அவர்களைத் தலையில் அடர்த்தியான முடியைக் கொண்ட உயரமான மனிதராகப் படைத்தான்; அவர் ஒரு நீண்ட பேரீச்சை மரத்தைப் போன்று இருந்தார். அவர் அந்த மரத்தின் கனியைச் சுவைத்தபோது, அவரது ஆடை அவரை விட்டு நீங்கியது. முதலில் அவரது மறைவிடமே வெளிப்பட்டது. அவர் தனது மறைவிடத்தைக் கண்டதும் சொர்க்கத்திற்குள் ஓடத் தொடங்கினார். அப்போது ஒரு மரம் அவரது தலைமுடியைப் பிடித்துக்கொண்டது; அவர் அதிலிருந்து விடுபடப் போராடினார். அப்போது ரஹ்மான் (அளவற்ற அருளாளன்) அவரை அழைத்து: 'ஆதமே! நீர் என்னிடமிருந்தா ஓடுகிறீர்?' என்று கேட்டான். ரஹ்மானின் பேச்சைக் கேட்டதும் அவர்: 'இல்லை என் இறைவா! மாறாக, வெட்கத்தினால் (ஓடுகிறேன்). நான் தவ்பா செய்து மீண்டால், என்னை மீண்டும் சொர்க்கத்திற்குத் திருப்புவாயா?' என்று கேட்டார். அதற்கு அவன் 'ஆம்' என்றான்.\") இதுவே அல்லாஹ்வின் இக்கூற்றின் பொருளாகும்:\n\r\n\n\r\nفَتَلَقَّى ءَادَمُ مِن رَّبِّهِ كَلِمَاتٍ فَتَابَ عَلَيْهِ\n\r\n\n\r\n(\"பின்னர் ஆதம் தம் இறைவனிடமிருந்து சில வார்த்தைகளைக் கற்றுக்கொண்டார்; எனவே அவன் அவரை மன்னித்தான்.\") 2:37 இருப்பினும், இந்த அறிவிப்பாளர் தொடரில் அல்-ஹஸனுக்கும் உபை பின் கஅப் (ரழி) அவர்களுக்குமிடையில் முறிவு உள்ளது. அல்-ஹஸன் இந்த ஹதீஸை உபை (ரழி) அவர்களிடமிருந்து நேரடியாகக் கேட்கவில்லை. இந்த அறிவிப்பு நபி (ஸல்) அவர்களிடமிருந்து வந்ததா என்பது சந்தேகத்திற்குரியது. அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ الْجَنَّةِ\n\r\n\n\r\n(\"மேலும் அவர்கள் சொர்க்கத்தின் இலைகளைக் கொண்டு தங்களை மூடிக்கொள்ளத் தொடங்கினார்கள்.\") முஜாஹித் அவர்கள் கூறினார்கள்: \"அவர்கள் இலைகளை ஆடை போலத் தம்மீது ஒட்டத் தொடங்கினார்கள்.\" கத்தாதா மற்றும் அஸ்-ஸுத்தீ ஆகியோரும் இதையே கூறினார்கள். அல்லாஹ்வின் இக்கூற்றைப் பொறுத்தவரை:\n\r\n\n\r\nفَأَكَلاَ مِنْهَا فَبَدَتْ لَهُمَا سَوْءَتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ الْجَنَّةِ وَعَصَى ءَادَمُ رَبَّهُ فَغَوَى - ثُمَّ اجْتَبَاهُ رَبُّهُ فَتَابَ عَلَيْهِ وَهَدَى\n\r\n\n\r\n(\"பின்னர் அவர்கள் இருவரும் அதிலிருந்து உண்டார்கள்; உடனே அவர்களின் மறைவிடங்கள் அவர்களுக்கு வெளிப்பட்டன. மேலும் அவர்கள் சொர்க்கத்தின் இலைகளைக் கொண்டு தங்களை மூடிக்கொள்ளத் தொடங்கினார்கள். இவ்வாறு ஆதம் தம் இறைவனுக்கு மாறு செய்தார்; அதனால் அவர் வழிதவறினார். பின்னர் அவரது இறைவன் அவரைத் தேர்ந்தெடுத்து, அவரை மன்னித்து, அவருக்கு நேர்வழியைக் காட்டினான்.\") அபூ ஹுரைரா (ரழி) அவர்கள் அறிவிக்கிறார்கள்: நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«حَاجَّ مُوسَى آدَمَ، فَقَالَ لَهُ: أَنْتَ الَّذِي أَخْرَجْتَ النَّاسَ مِنَ الْجَنَّةِ بِذَنْبِكَ وَأَشْقَيْتَهُمْ؟ قَالَ آدَمُ: يَا مُوسَى، أَنْتَ الَّذِي اصْطَفَاكَ اللهُ بِرِسَالَاتِهِ وَبِكَلَامِهِ، أَتَلُومُنِي عَلَى أَمْرٍ كَتَبَهُ اللهُ عَلَيَّ قَبْلَ أَنْ يَخْلُقَنِي أَوْ قَدَّرَهُ اللهُ عَلَيَّ قَبْلَ أَنْ يَخْلُقَنِي؟ قَالَ رَسُولُ اللهِ صَلَّى الله عليه وسلّم: فَحَجَّ آدَمُ مُوسَى»\n\r\n\n\r\n(\"மூஸா (அலை) அவர்கள் ஆதம் (அலை) அவர்களிடம் விவாதித்தார்கள். அவர் கூறினார்கள்: 'உமது பாவத்தினால் மனிதர்களைச் சொர்க்கத்திலிருந்து வெளியேற்றி, அவர்களைத் துன்பத்திற்குள்ளாக்கியவர் நீர்தானே?' அதற்கு ஆதம் (அலை) அவர்கள்: 'மூஸாவே! அல்லாஹ் தனது வஹீ (இறைச்செய்தி)களுக்காகவும், தனது நேரடிப் பேச்சுக்காகவும் தேர்ந்தெடுத்தவர் நீர்தானே? நான் படைக்கப்படுவதற்கு முன்பே அல்லாஹ் என் மீது விதித்துவிட்ட ஒரு விஷயத்திற்காகவா நீர் என்னைக் குறை கூறுகிறீர்?' என்று கேட்டார்கள்.\") பின்னர் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்: (\"இவ்வாறு ஆதம் (அலை) அவர்கள் மூஸா (அலை) அவர்களைத் தர்க்கத்தில் வென்றுவிட்டார்கள்.\") இந்த ஹதீஸ் புகாரி, முஸ்லிம் ஆகிய இரு ஸஹீஹ் நூல்களிலும் மற்றும் முஸ்னத் தொகுப்புகளிலும் பல்வேறு அறிவிப்பாளர் தொடர்களில் இடம்பெற்றுள்ளது."},"123":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=126\" class=\"link\">20:126</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:126 ஐ பார்க்கவும்"},"124":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=126\" class=\"link\">20:126</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:126 ஐ பார்க்கவும்"},"125":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=126\" class=\"link\">20:126</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:126 ஐ பார்க்கவும்"},"126":{"html":"<strong>ஆதம் (அலை) பூமிக்கு இறக்கப்பட்டதும், நேர்வழி பெற்றோருக்கான நற்பேறுகள் மற்றும் வரம்பு மீறியோருக்கான தண்டனை பற்றிய வாக்குறுதியும்</strong><br />\r\n<br />\r\nஅல்லாஹ் ஆதம் (அலை), ஹவ்வா (அலை) மற்றும் இப்லீஸிடம், “நீங்கள் அனைவரும் இங்கிருந்து இறங்கிவிடுங்கள்” என்று கூறினான். அதாவது, நீங்கள் ஒவ்வொருவரும் சுவனத்திலிருந்து வெளியேற வேண்டும் என்பதாகும். இதனைப் பற்றி நாம் சூரா அல்-பகராவில் விரிவாக விளக்கியுள்ளோம். <span class=\"quran-arabic-font text-success\">﴾بَعْضُكُمْ</span> <span class=\"quran-arabic-font text-success\">لِبَعْضٍ</span> <span class=\"quran-arabic-font text-success\">عَدُوٌّ﴿</span> (உங்களில் சிலர் சிலருக்குப் பகைவர்களாவீர்கள்.) (<a href=\"qurandisp.php?sura=2&ayah=36\" class=\"link\">2:36</a>). இதனை அல்லாஹ், ஆதம் (அலை) மற்றும் அவரது சந்ததியினருக்கும், இப்லீஸ் மற்றும் அவனது சந்ததியினருக்கும் கூறினான்.<br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்றான, <span class=\"quran-arabic-font text-success\">﴾فَإِمَّا</span> <span class=\"quran-arabic-font text-success\">يَأْتِيَنَّكُم</span> <span class=\"quran-arabic-font text-success\">مِّنِّي</span> <span class=\"quran-arabic-font text-success\">هُدًى﴿</span> (என்னிடமிருந்து உங்களுக்கு நேர்வழி வரும்போது,) என்பது குறித்து அபுல் ஆலியா (ரழி) அவர்கள் கூறுகையில், “இந்த (நேர்வழி) என்பது நபிமார்களையும், தூதர்களையும் மற்றும் சான்றுகளையும் குறிக்கும்” என்று கூறினார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَمَنِ</span> <span class=\"quran-arabic-font text-success\">اتَّبَعَ</span> <span class=\"quran-arabic-font text-success\">هُدَايَ</span> <span class=\"quran-arabic-font text-success\">فَلاَ</span> <span class=\"quran-arabic-font text-success\">يَضِلُّ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَشْقَى﴿</span> (யார் எனது நேர்வழியைப் பின்பற்றுகிறாரோ, அவர் வழிதவறவும் மாட்டார்; துயரப்படவும் மாட்டார்.) இது குறித்து இப்னு அப்பாஸ் (ரழி) அவர்கள், “அவர் இவ்வுலகில் வழிதவற மாட்டார், மறுமையில் இழிவடையவும் மாட்டார்” என்று கூறினார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمَنْ</span> <span class=\"quran-arabic-font text-success\">أَعْرَضَ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">ذِكْرِي﴿</span> (ஆனால், எவர் எனது நினைவூட்டலைப் புறக்கணிக்கிறாரோ,) இதன் பொருள்: “எவர் எனது கட்டளையையும், எனது தூதருக்கு நான் அருளிய வஹீ (இறைச்செய்தி)யையும் எதிர்க்கிறாரோ, அவர் அதனைப் புறக்கணித்து, அலட்சியம் செய்து, அதல்லாத வேறொன்றிலிருந்து நேர்வழியைத் தேடுகிறார்” என்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَإِنَّ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">مَعِيشَةً</span> <span class=\"quran-arabic-font text-success\">ضَنكاً﴿</span> (நிச்சயமாக அவருக்கு நெருக்கடியான வாழ்வு உண்டு,) அதாவது, இவ்வுலகில் அவரது வாழ்க்கை கடினமானதாக இருக்கும். அவருக்கு எந்த அமைதியும், மன நிம்மதியும் இருக்காது. மாறாக, அவரது வழிகேட்டின் காரணமாக அவரது உள்ளம் குறுகியதாகவும், சிரமமானதாகவும் இருக்கும். அவர் வெளித்தோற்றத்தில் வசதியாகத் தெரிந்தாலும், அவர் விரும்பியதை உடுத்தி, விரும்பியதை உண்டு, விரும்பிய இடத்தில் வாழ்ந்தாலும், அவர் மகிழ்ச்சியாக இருக்கமாட்டார். ஏனெனில், அவரது உள்ளத்தில் தூய்மையான உறுதியோ நேர்வழியோ இருக்காது. அவர் எப்போதும் பதற்றத்திலும், குழப்பத்திலும், சந்தேகத்திலும் இருப்பார். அவர் எப்போதும் நிச்சயமற்ற நிலையிலேயே இருப்பார். இதுவே அந்த நெருக்கடியான வாழ்வாகும். மேலும், இது குறித்து அபூ ஹுரைரா (ரழி) அவர்கள் அறிவிக்கும் நபிமொழியில், “நெருக்கடியான வாழ்வு என்றால் என்னவென்று அறிவீர்களா? அது மண்ணறை (கப்று) வேதனையாகும்” என்று கூறப்பட்டுள்ளது.<br />\r\n<br />\r\nஅவனது கூற்றான, <span class=\"quran-arabic-font text-success\">﴾وَنَحْشُرُهُ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَةِ</span> <span class=\"quran-arabic-font text-success\">أَعْمَى﴿</span> (மேலும், மறுமை நாளில் நாம் அவனைப் பார்வையற்றவனாக எழுப்புவோம்.) என்பது குறித்து முஜாஹித் (ரழி), அபூ ஸாலிஹ் (ரழி) மற்றும் அஸ்-ஸுத்தி (ரழி) ஆகியோர், “இதன் பொருள், அவனிடம் (தன்னைத் தற்காத்துக்கொள்ள) எந்த ஆதாரமும் இருக்காது” என்று கூறினார்கள். இக்ரிமா (ரழி) அவர்கள், “அவன் நரகத்தைத் தவிர மற்ற அனைத்திற்கும் குருடாக்கப்படுவான்” என்று கூறினார்கள். அல்லாஹ் கூறுவது போல இது இருக்கிறது: <span class=\"quran-arabic-font text-success\">﴾وَنَحْشُرُهُمْ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَةِ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">وُجُوهِهِمْ</span> <span class=\"quran-arabic-font text-success\">عُمْيًا</span> <span class=\"quran-arabic-font text-success\">وَبُكْمًا</span> <span class=\"quran-arabic-font text-success\">وَصُمًّا</span> <span class=\"quran-arabic-font text-success\">مَّأْوَاهُمْ</span> <span class=\"quran-arabic-font text-success\">جَهَنَّمُ﴿</span> (மேலும், மறுமை நாளில் அவர்களை அவர்களுடைய முகங்குப்புற விழச் செய்து, குருடர்களாகவும், ஊமையர்களாகவும், செவிடர்களாகவும் நாம் ஒன்று சேர்ப்போம். அவர்கள் தங்குமிடம் நரகமாகும்.) (<a href=\"qurandisp.php?sura=17&ayah=97\" class=\"link\">17:97</a>).<br />\r\n<br />\r\nஇதனால்தான் அவன் கேட்பான்: <span class=\"quran-arabic-font text-success\">﴾رَبِّ</span> <span class=\"quran-arabic-font text-success\">لِمَ</span> <span class=\"quran-arabic-font text-success\">حَشَرْتَنِي</span> <span class=\"quran-arabic-font text-success\">أَعْمَى</span> <span class=\"quran-arabic-font text-success\">وَقَدْ</span> <span class=\"quran-arabic-font text-success\">كُنتُ</span> <span class=\"quran-arabic-font text-success\">بَصِيراً﴿</span> (என் இறைவா! நான் பார்வையுடையவனாக இருந்தேனே! நீ ஏன் என்னைக் குருடனாக எழுப்பினாய்?) அதாவது, இவ்வுலக வாழ்க்கையில் அவன் பார்வையுடையவனாக இருந்தான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">كَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">أَتَتْكَ</span> <span class=\"quran-arabic-font text-success\">آيَاتُنَا</span> <span class=\"quran-arabic-font text-success\">فَنَسِيتَهَا</span> <span class=\"quran-arabic-font text-success\">وَكَذلِكَ</span> <span class=\"quran-arabic-font text-success\">الْيَوْمَ</span> <span class=\"quran-arabic-font text-success\">تُنْسَى</span> <span class=\"quran-arabic-font text-success\">﴿</span> ((அதற்கு அல்லாஹ்) கூறுவான்: “இப்படித்தான் நம்முடைய வசனங்கள் உன்னிடம் வந்தன; அவற்றை நீ மறந்துவிட்டாய் (புறக்கணித்தாய்). அவ்வாறே இன்றைய தினம் நீயும் மறக்கப்படுவாய் (கைவிடப்படுவாய்).”)<br />\r\n<br />\r\nஇதன் பொருள்: “அல்லாஹ்வின் சான்றுகள் உனக்கு எட்டிய பின்னரும், அவற்றை நினைவில் கொள்ளாத ஒருவனைப் போல நீ அவற்றைப் புறக்கணித்தாய். அவற்றை அலட்சியம் செய்தாய், அவற்றைப் பற்றி கவலையற்று இருந்தாய். எனவே, இன்று உன்னை மறந்த ஒருவரைப் போல நாம் உன்னை நடத்துவோம்.”<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَالْيَوْمَ</span> <span class=\"quran-arabic-font text-success\">نَنسَاهُمْ</span> <span class=\"quran-arabic-font text-success\">كَمَا</span> <span class=\"quran-arabic-font text-success\">نَسُواْ</span> <span class=\"quran-arabic-font text-success\">لِقَآءَ</span> <span class=\"quran-arabic-font text-success\">يَوْمِهِمْ</span> <span class=\"quran-arabic-font text-success\">هَـذَا﴿</span> (ஆகவே, அவர்கள் இன்றைய தினத்தின் சந்திப்பை மறந்ததைப் போலவே, இன்றைய தினம் நாம் அவர்களை மறந்துவிடுவோம்.) (<a href=\"qurandisp.php?sura=7&ayah=51\" class=\"link\">7:51</a>).<br />\r\n<br />\r\nஏனெனில், நிச்சயமாக தண்டனை என்பது அவர் செய்த செயலின் தன்மைக்கு ஏற்பவே அமையும். எனினும், குர்ஆனின் பொருளைப் புரிந்து கொண்டு, அதன் சட்டதிட்டங்களின்படி செயல்படும் நிலையில், அதன் வார்த்தைகளை (மனப்பாடம் செய்ததை) மறந்து விடுவது இந்த குறிப்பிட்ட அச்சுறுத்தலுக்குள் வராது. இருப்பினும், குர்ஆனின் வார்த்தைகளை மறப்பது என்பது வேறு சில காரணங்களுக்காக எச்சரிக்கப்பட்டுள்ளது. சுன்னாவில் இது முற்றிலும் தடுக்கப்பட்டுள்ளது என்றும், தான் முன்னர் மனனம் செய்த குர்ஆனை மறப்பவருக்கு எதிராகக் கடுமையான எச்சரிக்கைகள் உள்ளன என்றும் அறிவிக்கப்பட்டுள்ளது. இமாம் அஹ்மத் (ரஹ்) அவர்கள் கூறுகிறார்கள்: நபி (ஸல்) அவர்கள் கூறினார்கள்: “குர்ஆனை ஓதிய பின்னர் அதை மறந்துவிடும் எவரும், மறுமை நாளில் அல்லாஹ்வை (தொழு நோயாளியைப் போன்று) அங்கவீனம் உள்ளவராகவே சந்திப்பார்.”<br />\r\n<br />","text":"ஆதம் (அலை) பூமிக்கு இறக்கப்பட்டதும், நேர்வழி பெற்றோருக்கான நற்பேறுகள் மற்றும் வரம்பு மீறியோருக்கான தண்டனை பற்றிய வாக்குறுதியும்\n\r\n\n\r\nஅல்லாஹ் ஆதம் (அலை), ஹவ்வா (அலை) மற்றும் இப்லீஸிடம், “நீங்கள் அனைவரும் இங்கிருந்து இறங்கிவிடுங்கள்” என்று கூறினான். அதாவது, நீங்கள் ஒவ்வொருவரும் சுவனத்திலிருந்து வெளியேற வேண்டும் என்பதாகும். இதனைப் பற்றி நாம் சூரா அல்-பகராவில் விரிவாக விளக்கியுள்ளோம். ﴾بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ﴿ (உங்களில் சிலர் சிலருக்குப் பகைவர்களாவீர்கள்.) (2:36). இதனை அல்லாஹ், ஆதம் (அலை) மற்றும் அவரது சந்ததியினருக்கும், இப்லீஸ் மற்றும் அவனது சந்ததியினருக்கும் கூறினான்.\n\r\n\n\r\nஅல்லாஹ்வின் கூற்றான, ﴾فَإِمَّا يَأْتِيَنَّكُم مِّنِّي هُدًى﴿ (என்னிடமிருந்து உங்களுக்கு நேர்வழி வரும்போது,) என்பது குறித்து அபுல் ஆலியா (ரழி) அவர்கள் கூறுகையில், “இந்த (நேர்வழி) என்பது நபிமார்களையும், தூதர்களையும் மற்றும் சான்றுகளையும் குறிக்கும்” என்று கூறினார்கள்.\n\r\n\n\r\n﴾فَمَنِ اتَّبَعَ هُدَايَ فَلاَ يَضِلُّ وَلاَ يَشْقَى﴿ (யார் எனது நேர்வழியைப் பின்பற்றுகிறாரோ, அவர் வழிதவறவும் மாட்டார்; துயரப்படவும் மாட்டார்.) இது குறித்து இப்னு அப்பாஸ் (ரழி) அவர்கள், “அவர் இவ்வுலகில் வழிதவற மாட்டார், மறுமையில் இழிவடையவும் மாட்டார்” என்று கூறினார்கள்.\n\r\n\n\r\n﴾وَمَنْ أَعْرَضَ عَن ذِكْرِي﴿ (ஆனால், எவர் எனது நினைவூட்டலைப் புறக்கணிக்கிறாரோ,) இதன் பொருள்: “எவர் எனது கட்டளையையும், எனது தூதருக்கு நான் அருளிய வஹீ (இறைச்செய்தி)யையும் எதிர்க்கிறாரோ, அவர் அதனைப் புறக்கணித்து, அலட்சியம் செய்து, அதல்லாத வேறொன்றிலிருந்து நேர்வழியைத் தேடுகிறார்” என்பதாகும்.\n\r\n\n\r\n﴾فَإِنَّ لَهُ مَعِيشَةً ضَنكاً﴿ (நிச்சயமாக அவருக்கு நெருக்கடியான வாழ்வு உண்டு,) அதாவது, இவ்வுலகில் அவரது வாழ்க்கை கடினமானதாக இருக்கும். அவருக்கு எந்த அமைதியும், மன நிம்மதியும் இருக்காது. மாறாக, அவரது வழிகேட்டின் காரணமாக அவரது உள்ளம் குறுகியதாகவும், சிரமமானதாகவும் இருக்கும். அவர் வெளித்தோற்றத்தில் வசதியாகத் தெரிந்தாலும், அவர் விரும்பியதை உடுத்தி, விரும்பியதை உண்டு, விரும்பிய இடத்தில் வாழ்ந்தாலும், அவர் மகிழ்ச்சியாக இருக்கமாட்டார். ஏனெனில், அவரது உள்ளத்தில் தூய்மையான உறுதியோ நேர்வழியோ இருக்காது. அவர் எப்போதும் பதற்றத்திலும், குழப்பத்திலும், சந்தேகத்திலும் இருப்பார். அவர் எப்போதும் நிச்சயமற்ற நிலையிலேயே இருப்பார். இதுவே அந்த நெருக்கடியான வாழ்வாகும். மேலும், இது குறித்து அபூ ஹுரைரா (ரழி) அவர்கள் அறிவிக்கும் நபிமொழியில், “நெருக்கடியான வாழ்வு என்றால் என்னவென்று அறிவீர்களா? அது மண்ணறை (கப்று) வேதனையாகும்” என்று கூறப்பட்டுள்ளது.\n\r\n\n\r\nஅவனது கூற்றான, ﴾وَنَحْشُرُهُ يَوْمَ الْقِيَامَةِ أَعْمَى﴿ (மேலும், மறுமை நாளில் நாம் அவனைப் பார்வையற்றவனாக எழுப்புவோம்.) என்பது குறித்து முஜாஹித் (ரழி), அபூ ஸாலிஹ் (ரழி) மற்றும் அஸ்-ஸுத்தி (ரழி) ஆகியோர், “இதன் பொருள், அவனிடம் (தன்னைத் தற்காத்துக்கொள்ள) எந்த ஆதாரமும் இருக்காது” என்று கூறினார்கள். இக்ரிமா (ரழி) அவர்கள், “அவன் நரகத்தைத் தவிர மற்ற அனைத்திற்கும் குருடாக்கப்படுவான்” என்று கூறினார்கள். அல்லாஹ் கூறுவது போல இது இருக்கிறது: ﴾وَنَحْشُرُهُمْ يَوْمَ الْقِيَامَةِ عَلَى وُجُوهِهِمْ عُمْيًا وَبُكْمًا وَصُمًّا مَّأْوَاهُمْ جَهَنَّمُ﴿ (மேலும், மறுமை நாளில் அவர்களை அவர்களுடைய முகங்குப்புற விழச் செய்து, குருடர்களாகவும், ஊமையர்களாகவும், செவிடர்களாகவும் நாம் ஒன்று சேர்ப்போம். அவர்கள் தங்குமிடம் நரகமாகும்.) (17:97).\n\r\n\n\r\nஇதனால்தான் அவன் கேட்பான்: ﴾رَبِّ لِمَ حَشَرْتَنِي أَعْمَى وَقَدْ كُنتُ بَصِيراً﴿ (என் இறைவா! நான் பார்வையுடையவனாக இருந்தேனே! நீ ஏன் என்னைக் குருடனாக எழுப்பினாய்?) அதாவது, இவ்வுலக வாழ்க்கையில் அவன் பார்வையுடையவனாக இருந்தான்.\n\r\n\n\r\n﴾قَالَ كَذَلِكَ أَتَتْكَ آيَاتُنَا فَنَسِيتَهَا وَكَذلِكَ الْيَوْمَ تُنْسَى ﴿ ((அதற்கு அல்லாஹ்) கூறுவான்: “இப்படித்தான் நம்முடைய வசனங்கள் உன்னிடம் வந்தன; அவற்றை நீ மறந்துவிட்டாய் (புறக்கணித்தாய்). அவ்வாறே இன்றைய தினம் நீயும் மறக்கப்படுவாய் (கைவிடப்படுவாய்).”)\n\r\n\n\r\nஇதன் பொருள்: “அல்லாஹ்வின் சான்றுகள் உனக்கு எட்டிய பின்னரும், அவற்றை நினைவில் கொள்ளாத ஒருவனைப் போல நீ அவற்றைப் புறக்கணித்தாய். அவற்றை அலட்சியம் செய்தாய், அவற்றைப் பற்றி கவலையற்று இருந்தாய். எனவே, இன்று உன்னை மறந்த ஒருவரைப் போல நாம் உன்னை நடத்துவோம்.”\n\r\n\n\r\n﴾فَالْيَوْمَ نَنسَاهُمْ كَمَا نَسُواْ لِقَآءَ يَوْمِهِمْ هَـذَا﴿ (ஆகவே, அவர்கள் இன்றைய தினத்தின் சந்திப்பை மறந்ததைப் போலவே, இன்றைய தினம் நாம் அவர்களை மறந்துவிடுவோம்.) (7:51).\n\r\n\n\r\nஏனெனில், நிச்சயமாக தண்டனை என்பது அவர் செய்த செயலின் தன்மைக்கு ஏற்பவே அமையும். எனினும், குர்ஆனின் பொருளைப் புரிந்து கொண்டு, அதன் சட்டதிட்டங்களின்படி செயல்படும் நிலையில், அதன் வார்த்தைகளை (மனப்பாடம் செய்ததை) மறந்து விடுவது இந்த குறிப்பிட்ட அச்சுறுத்தலுக்குள் வராது. இருப்பினும், குர்ஆனின் வார்த்தைகளை மறப்பது என்பது வேறு சில காரணங்களுக்காக எச்சரிக்கப்பட்டுள்ளது. சுன்னாவில் இது முற்றிலும் தடுக்கப்பட்டுள்ளது என்றும், தான் முன்னர் மனனம் செய்த குர்ஆனை மறப்பவருக்கு எதிராகக் கடுமையான எச்சரிக்கைகள் உள்ளன என்றும் அறிவிக்கப்பட்டுள்ளது. இமாம் அஹ்மத் (ரஹ்) அவர்கள் கூறுகிறார்கள்: நபி (ஸல்) அவர்கள் கூறினார்கள்: “குர்ஆனை ஓதிய பின்னர் அதை மறந்துவிடும் எவரும், மறுமை நாளில் அல்லாஹ்வை (தொழு நோயாளியைப் போன்று) அங்கவீனம் உள்ளவராகவே சந்திப்பார்.”"},"127":{"html":"<strong>வரம்பு மீறுபவர்களுக்குக் கடுமையான வேதனை</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">نَجْزِي</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">أَسْرَفَ</span> <span class=\"quran-arabic-font text-success\">وَلَمْ</span> <span class=\"quran-arabic-font text-success\">يُؤْمِن</span> <span class=\"quran-arabic-font text-success\">بِآيَاتِ</span> <span class=\"quran-arabic-font text-success\">رَبِّهِ</span><br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்: \"வரம்பு மீறி, அல்லாஹ்வின் அத்தாட்சிகளை (ஆயத்களை) நம்பாதவர்களுக்கு இவ்வுலகிலும் மறுமையிலும் நாம் இவ்வாறே கூலி வழங்குகிறோம்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَّهُمْ</span> <span class=\"quran-arabic-font text-success\">عَذَابٌ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْحَيَاةِ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">وَلَعَذَابُ</span> <span class=\"quran-arabic-font text-success\">الْآخِرَةِ</span> <span class=\"quran-arabic-font text-success\">أَشَقُّ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">لَهُم</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">وَاقٍ</span><br />\r\n<br />\r\n(அவர்களுக்கு இவ்வுலக வாழ்விலும் வேதனை உண்டு; நிச்சயமாக மறுமையின் வேதனை மிகவும் கடுமையானது. மேலும், அல்லாஹ்விடமிருந்து அவர்களைக் காப்பாற்றுபவர் எவருமில்லை.) (<a href=\"qurandisp.php?sura=13&ayah=34\" class=\"link\">13:34</a>) எனவே அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَعَذَابُ</span> <span class=\"quran-arabic-font text-success\">الْآخِرَةِ</span> <span class=\"quran-arabic-font text-success\">أَشَدُّ</span> <span class=\"quran-arabic-font text-success\">وَأَبْقَى</span><br />\r\n<br />\r\n(மேலும், மறுமையின் வேதனை மிகவும் கடுமையானதும், மிக நீண்ட காலம் நிலைத்திருக்கக்கூடியதும் ஆகும்.) அதாவது: இவ்வுலக தண்டனையை விட இது மிகக் கொடியது மற்றும் அதிக வலியுள்ளது; அவர்கள் அந்த வேதனையில் என்றென்றும் தங்கியிருப்பார்கள். தன் மனைவி சட்டவிரோத தாம்பத்திய உறவில் ஈடுபட்டதாகக் குற்றம் சாட்டி, இருவரும் சத்தியம் செய்தபோது, கணவன் மற்றும் மனைவி ஆகிய இருவரிடமும் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">عَذَابَ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">أَهْوَنُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عَذَابِ</span> <span class=\"quran-arabic-font text-success\">الْآخِرَة</span>»<br />\r\n<br />\r\n(நிச்சயமாக, மறுமையின் வேதனையோடு ஒப்பிடும்போது, இவ்வுலக வாழ்வின் வேதனை இலேசானது.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَفَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَهْدِ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">كَمْ</span> <span class=\"quran-arabic-font text-success\">أَهْلَكْنَا</span> <span class=\"quran-arabic-font text-success\">قَبْلَهُم</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْقُرُونِ</span> <span class=\"quran-arabic-font text-success\">يَمْشُونَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">مَسَاكِنِهِمْ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">لَآيَاتٍ</span> <span class=\"quran-arabic-font text-success\">لِّأُولِي</span> <span class=\"quran-arabic-font text-success\">النُّهَى</span><br />\r\n<br />","text":"வரம்பு மீறுபவர்களுக்குக் கடுமையான வேதனை\n\r\n\n\r\nوَكَذَلِكَ نَجْزِي مَنْ أَسْرَفَ وَلَمْ يُؤْمِن بِآيَاتِ رَبِّهِ\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்: \"வரம்பு மீறி, அல்லாஹ்வின் அத்தாட்சிகளை (ஆயத்களை) நம்பாதவர்களுக்கு இவ்வுலகிலும் மறுமையிலும் நாம் இவ்வாறே கூலி வழங்குகிறோம்.\"\n\r\n\n\r\nلَّهُمْ عَذَابٌ فِي الْحَيَاةِ الدُّنْيَا وَلَعَذَابُ الْآخِرَةِ أَشَقُّ وَمَا لَهُم مِّنَ اللَّهِ مِن وَاقٍ\n\r\n\n\r\n(அவர்களுக்கு இவ்வுலக வாழ்விலும் வேதனை உண்டு; நிச்சயமாக மறுமையின் வேதனை மிகவும் கடுமையானது. மேலும், அல்லாஹ்விடமிருந்து அவர்களைக் காப்பாற்றுபவர் எவருமில்லை.) (13:34) எனவே அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَلَعَذَابُ الْآخِرَةِ أَشَدُّ وَأَبْقَى\n\r\n\n\r\n(மேலும், மறுமையின் வேதனை மிகவும் கடுமையானதும், மிக நீண்ட காலம் நிலைத்திருக்கக்கூடியதும் ஆகும்.) அதாவது: இவ்வுலக தண்டனையை விட இது மிகக் கொடியது மற்றும் அதிக வலியுள்ளது; அவர்கள் அந்த வேதனையில் என்றென்றும் தங்கியிருப்பார்கள். தன் மனைவி சட்டவிரோத தாம்பத்திய உறவில் ஈடுபட்டதாகக் குற்றம் சாட்டி, இருவரும் சத்தியம் செய்தபோது, கணவன் மற்றும் மனைவி ஆகிய இருவரிடமும் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِنَّ عَذَابَ الدُّنْيَا أَهْوَنُ مِنْ عَذَابِ الْآخِرَة»\n\r\n\n\r\n(நிச்சயமாக, மறுமையின் வேதனையோடு ஒப்பிடும்போது, இவ்வுலக வாழ்வின் வேதனை இலேசானது.)\n\r\n\n\r\nأَفَلَمْ يَهْدِ لَهُمْ كَمْ أَهْلَكْنَا قَبْلَهُم مِّنَ الْقُرُونِ يَمْشُونَ فِي مَسَاكِنِهِمْ إِنَّ فِي ذَلِكَ لَآيَاتٍ لِّأُولِي النُّهَى"},"128":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=130\" class=\"link\">20:130</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:130 ஐ பார்க்கவும்"},"129":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=130\" class=\"link\">20:130</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:130 ஐ பார்க்கவும்"},"130":{"html":"<strong>பல சமுதாயங்கள் அழிக்கப்பட்டன; அவற்றில் ஒரு படிப்பினை உள்ளது</strong><br />\r\n<br />\r\nஉயர்ந்தோனாகிய அல்லாஹ் கூறுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَفَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَهْدِ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span><br />\r\n<br />\r\n(இது அவர்களுக்கு வழிகாட்டவில்லையா...) நபி (ஸல்) அவர்கள் கொண்டு வந்த சத்தியத்தை நிராகரிப்பவர்களுக்கு இது ஒரு எச்சரிக்கையாகக் கூறப்படுகிறது: ‘இவர்களுக்கு முன்னிருந்த முந்தைய சமுதாயங்களில் தூதர்களைப் பொய்யாக்கியவர்களை நாம் அழித்தோம். அவர்கள் வெளிப்படையான பகையை வெளிப்படுத்தினார்கள்; அதன் விளைவாக இன்று அவர்களின் சுவடுகூட எஞ்சவில்லை. இவர்கள் விட்டுச்சென்ற பாழடைந்த வீடுகளே இதற்குச் சாட்சியாக உள்ளன. இப்போது மற்றவர்கள் அவற்றைச் சுதந்தரித்து, அந்த முன்னைய மக்களின் குடியிருப்புகளில் நடமாடி வருகிறார்கள்.’<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">لَآيَاتٍ</span> <span class=\"quran-arabic-font text-success\">لِّأُولِي</span> <span class=\"quran-arabic-font text-success\">النُّهَى</span><br />\r\n<br />\r\n(நிச்சயமாக, இதில் அறிவுடையோருக்குப் பல அத்தாட்சிகள் உள்ளன.) அதாவது, சீரான புத்தியும் சரியான புரிதலும் கொண்டவர்களுக்கு இதில் பாடங்கள் உள்ளன. அல்லாஹ் மற்றோர் இடத்தில் கூறுவது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَفَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَسِيرُوا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">فَتَكُونَ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">قُلُوبٌ</span> <span class=\"quran-arabic-font text-success\">يَعْقِلُونَ</span> <span class=\"quran-arabic-font text-success\">بِهَا</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">آذَانٌ</span> <span class=\"quran-arabic-font text-success\">يَسْمَعُونَ</span> <span class=\"quran-arabic-font text-success\">بِهَا</span> <span class=\"quran-arabic-font text-success\">فَإِنَّهَا</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تَعْمَى</span> <span class=\"quran-arabic-font text-success\">الْأَبْصَارُ</span> <span class=\"quran-arabic-font text-success\">وَلَكِن</span> <span class=\"quran-arabic-font text-success\">تَعْمَى</span> <span class=\"quran-arabic-font text-success\">الْقُلُوبُ</span> <span class=\"quran-arabic-font text-success\">الَّتِي</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الصُّدُورِ</span><br />\r\n<br />\r\n(அவர்கள் பூமியில் பயணம் செய்யவில்லையா? அவ்வாறு செய்திருந்தால், அவர்கள் சிந்தித்துப் புரிந்துகொள்ளக்கூடிய உள்ளங்களும், செவியேற்கக்கூடிய காதுகளும் அவர்களுக்குக் கிடைத்திருக்கும். நிச்சயமாக, கண்கள் குருடாவதில்லை, மாறாக நெஞ்சங்களுக்குள் இருக்கும் இதயங்களே குருடாகிவிடுகின்றன.) <a href=\"qurandisp.php?sura=22&ayah=46\" class=\"link\">22:46</a>. அல்லாஹ் ஸூரத்து அலிஃப் லாம் மீம் அஸ்-ஸஜ்தாவிலும் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَوَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَهْدِ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">كَمْ</span> <span class=\"quran-arabic-font text-success\">أَهْلَكْنَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِهِمْ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْقُرُونِ</span> <span class=\"quran-arabic-font text-success\">يَمْشُونَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">مَسَاكِنِهِمْ</span><br />\r\n<br />\r\n(இவர்களுக்கு முன்னிருந்த எத்தனையோ தலைமுறையினரை நாம் அழித்திருக்கிறோம் என்பது இவர்களுக்கு வழிகாட்டவில்லையா? அவர்களின் குடியிருப்புகளில் இவர்கள் இன்று நடமாடுகிறார்கள்.) <a href=\"qurandisp.php?sura=32&ayah=26\" class=\"link\">32:26</a>. பின்னர், உயர்ந்தோனாகிய அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَوْلاَ</span> <span class=\"quran-arabic-font text-success\">كَلِمَةٌ</span> <span class=\"quran-arabic-font text-success\">سَبَقَتْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">رَّبِّكَ</span> <span class=\"quran-arabic-font text-success\">لَكَانَ</span> <span class=\"quran-arabic-font text-success\">لِزَاماً</span> <span class=\"quran-arabic-font text-success\">وَأَجَلٌ</span> <span class=\"quran-arabic-font text-success\">مُّسَمًّى</span><br />\r\n<br />\r\n(உமது இறைவனிடமிருந்து ஏற்கனவே ஒரு வார்த்தை முந்திச் சென்றிராமலும், ஒரு குறிப்பிட்ட காலம் நிர்ணயிக்கப்பட்டிராமலும் இருந்தால், (அவர்களுக்கான தண்டனை) இவ்வுலகிலேயே நிச்சயமாக வந்திருக்கும்.) <a href=\"qurandisp.php?sura=20&ayah=129\" class=\"link\">20:129</a>. இதன் பொருள் என்னவென்றால், ஒருவருக்கு எதிராக ஆதாரங்கள் நிலைநாட்டப்படும் வரை அவனைத் தண்டிக்க மாட்டான் என்றும், இந்த நிராகரிப்பாளர்களுக்கான தண்டனை அவன் நிர்ணயித்த ஒரு குறிப்பிட்ட நேரத்தில் தான் நிகழும் என்றும் அல்லாஹ் ஏற்கனவே விதித்திருக்கவில்லை என்றால், தண்டனை அவர்களை இப்போதே பிடித்திருக்கும்.<br />\r\n<br />\r\n<strong>பொறுமை காப்பதற்கும் ஐவேளைத் தொழுகைகளை நிறைவேற்றுவதற்குமான கட்டளை</strong><br />\r\n<br />\r\nஅல்லாஹ் தன் நபி (ஸல்) அவர்களுக்கு ஆறுதல் கூறும் வகையில் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَاصْبِرْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَقُولُونَ</span><br />\r\n<br />\r\n(ஆகவே, அவர்கள் சொல்வதை நீர் பொறுமையுடன் சகித்துக் கொள்வீராக,) அதாவது, \"அவர்கள் உம்மை நிராகரிப்பது குறித்து நீர் பொறுமையைக் கடைப்பிடிப்பீராக.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَسَبِّحْ</span> <span class=\"quran-arabic-font text-success\">بِحَمْدِ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">قَبْلَ</span> <span class=\"quran-arabic-font text-success\">طُلُوعِ</span> <span class=\"quran-arabic-font text-success\">الشَّمْسِ</span><br />\r\n<br />\r\n(சூரியன் உதிப்பதற்கு முன்னதாக உமது இறைவனைப் புகழ்ந்து துதிப்பீராக,) இது அதிகாலை (ஃபஜ்ர்) தொழுகையைக் குறிக்கிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَبْلَ</span> <span class=\"quran-arabic-font text-success\">غُرُوبِهَا</span><br />\r\n<br />\r\n(மேலும், அது மறைவதற்கு முன்னரும் (துதிப்பீராக),) இது மாலை (அஸர்) தொழுகையைக் குறிக்கிறது. ஜரீர் பின் அப்துல்லாஹ் அல்-பஜலீ (ரழி) அவர்கள் அறிவித்ததாக புகாரி, முஸ்லிம் ஆகிய இரு ஆதாரப்பூர்வமான நூல்களிலும் (ஸஹீஹைன்) இது குறிப்பிடப்பட்டுள்ளது. அவர்கள் கூறினார்கள்: \"ஒருமுறை நாங்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுடன் அமர்ந்திருந்தோம். அப்போது அவர்கள் பௌர்ணமி அன்று நிலவைப் பார்த்துவிட்டு இவ்வாறு கூறினார்கள்:\"<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">سَتَرَوْنَ</span> <span class=\"quran-arabic-font text-success\">رَبَّكُمْ</span> <span class=\"quran-arabic-font text-success\">كَمَا</span> <span class=\"quran-arabic-font text-success\">تَرَوْنَ</span> <span class=\"quran-arabic-font text-success\">هَذَا</span> <span class=\"quran-arabic-font text-success\">الْقَمَرَ،</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تُضَامُونَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">رُؤْيَتِهِ،</span> <span class=\"quran-arabic-font text-success\">فَإِنِ</span> <span class=\"quran-arabic-font text-success\">اسْتَطَعْتُمْ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تُغْلَبُوا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">صَلَاةٍ</span> <span class=\"quran-arabic-font text-success\">قَبْلَ</span> <span class=\"quran-arabic-font text-success\">طُلُوعِ</span> <span class=\"quran-arabic-font text-success\">الشَّمْسِ</span> <span class=\"quran-arabic-font text-success\">وَقَبْلَ</span> <span class=\"quran-arabic-font text-success\">غُرُوبِهَا</span> <span class=\"quran-arabic-font text-success\">فَافْعَلُوا</span>»<br />\r\n<br />\r\n(நிச்சயமாக நீங்கள் உங்கள் இறைவனை (மறுமையில்), இந்த நிலவைக் காண்பது போன்றே காண்பீர்கள். அவனைக் காண்பதில் உங்களுக்கு எந்தச் சிரமமும் இருக்காது. எனவே, சூரிய உதயத்திற்கு முன்புள்ள (ஃபஜ்ர்) தொழுகையையும், சூரிய அஸ்தமனத்திற்கு முன்புள்ள (அஸர்) தொழுகையையும் தவறாமல் நிறைவேற்ற உங்களால் முடிந்தால், அதைச் செய்யுங்கள்.) பின்னர் அவர்கள் இந்த வசனத்தை ஓதினார்கள். இமாம் அஹ்மத் அவர்கள், உமாரா பின் ருஅய்பா (ரழி) அவர்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறுவதைக் கேட்டதாகப் பதிவு செய்துள்ளார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَنْ</span> <span class=\"quran-arabic-font text-success\">يَلِجَ</span> <span class=\"quran-arabic-font text-success\">النَّارَ</span> <span class=\"quran-arabic-font text-success\">أَحَدٌ</span> <span class=\"quran-arabic-font text-success\">صَلَّى</span> <span class=\"quran-arabic-font text-success\">قَبْلَ</span> <span class=\"quran-arabic-font text-success\">طُلُوعِ</span> <span class=\"quran-arabic-font text-success\">الشَّمْسِ</span> <span class=\"quran-arabic-font text-success\">وَقَبْلَ</span> <span class=\"quran-arabic-font text-success\">غُرُوبِهَا</span>»<br />\r\n<br />\r\n(சூரியன் உதிப்பதற்கு முன்னரும், அது மறைவதற்கு முன்னரும் தொழுபவர் ஒருபோதும் நரகில் நுழைய மாட்டார்.) இச்செய்தியை முஸ்லிம் அவர்களும் பதிவு செய்துள்ளார்கள். அல்லாஹ்வின் இந்த வசனத்தைப் பொறுத்தவரை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمِنْ</span> <span class=\"quran-arabic-font text-success\">ءَانَآءِ</span> <span class=\"quran-arabic-font text-success\">الَّيْلِ</span> <span class=\"quran-arabic-font text-success\">فَسَبِّحْ</span><br />\r\n<br />\r\n(இரவின் சில நேரங்களிலும் துதிப்பீராக.) இதன் பொருள், இரவின் நேரங்களில் இரவுத் தொழுகையை (தஹஜ்ஜுத்) தொழுவதாகும். சில அறிஞர்கள், இது மஃரிப் மற்றும் இஷா தொழுகைகளையும் குறிக்கும் என்று கூறியுள்ளனர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَطْرَافَ</span> <span class=\"quran-arabic-font text-success\">النَّهَارِ</span><br />\r\n<br />\r\n(பகலின் இரு முனைகளிலும் (துதிப்பீராக),) இது இரவின் நேரங்களுக்கு எதிரானது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَعَلَّكَ</span> <span class=\"quran-arabic-font text-success\">تَرْضَى</span><br />\r\n<br />\r\n(நீர் திருப்தியடைவதற்காக.) அல்லாஹ் மற்றோர் இடத்தில் கூறுவது போல்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَسَوْفَ</span> <span class=\"quran-arabic-font text-success\">يُعْطِيكَ</span> <span class=\"quran-arabic-font text-success\">رَبُّكَ</span> <span class=\"quran-arabic-font text-success\">فَتَرْضَى</span><br />\r\n<br />\r\n(நிச்சயமாக உமது இறைவன் உமக்கு (ஏராளமான நன்மைகளை) வழங்குவான், அப்போது நீர் திருப்தியடைவீர்.) <a href=\"qurandisp.php?sura=93&ayah=5\" class=\"link\">93:5</a>. ஸஹீஹ் நூலில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியதாகப் பதிவு செய்யப்பட்டுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يَقُولُ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">تَعَالَى</span> <span class=\"quran-arabic-font text-success\">يَاأَهْلَ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ،</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُونَ</span>: <span class=\"quran-arabic-font text-success\">لَبَّيْكَ</span> <span class=\"quran-arabic-font text-success\">رَبَّنَا</span> <span class=\"quran-arabic-font text-success\">وَسَعْدَيْكَ،</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُ</span>: <span class=\"quran-arabic-font text-success\">هَلْ</span> <span class=\"quran-arabic-font text-success\">رَضِيتُمْ؟</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُونَ</span>: <span class=\"quran-arabic-font text-success\">رَبَّنَا</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">نَرْضَى</span> <span class=\"quran-arabic-font text-success\">وَقَدْ</span> <span class=\"quran-arabic-font text-success\">أَعْطَيْتَنَا</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">تُعْطِ</span> <span class=\"quran-arabic-font text-success\">أَحَدًا</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">خَلْقِكَ،</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُ</span>: <span class=\"quran-arabic-font text-success\">إِنِّي</span> <span class=\"quran-arabic-font text-success\">أُعْطِيكُمْ</span> <span class=\"quran-arabic-font text-success\">أَفْضَلَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ،</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُونَ</span>: <span class=\"quran-arabic-font text-success\">وَأَيُّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">أَفْضَلُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ؟</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُ</span>: <span class=\"quran-arabic-font text-success\">أَحِلُّ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">رِضْوَانِي</span> <span class=\"quran-arabic-font text-success\">فَلَا</span> <span class=\"quran-arabic-font text-success\">أَسْخَطُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">بَعْدَهُ</span> <span class=\"quran-arabic-font text-success\">أَبَدًا</span>»<br />\r\n<br />\r\n(உயர்ந்தோனாகிய அல்லாஹ், \"சொர்க்கவாசிகளே!\" என்று அழைப்பான். அதற்கு அவர்கள், \"எங்கள் இறைவா! இதோ உனது கட்டளைக்குக் கீழ்ப்படியக் காத்திருக்கிறோம்; நன்மைகள் அனைத்தும் உன் வசமே உள்ளன\" என்று பதிலளிப்பார்கள். பின்னர் அவன், \"நீங்கள் திருப்தியடைந்துவிட்டீர்களா?\" என்று கேட்பான். அதற்கு அவர்கள், \"எங்கள் இறைவா! உனது படைப்புகளில் எவருக்கும் அளிக்காதவற்றை எங்களுக்கு நீ அளித்திருக்கும்போது, நாங்கள் ஏன் திருப்தியடையாமல் இருக்கப் போகிறோம்?\" என்று கூறுவார்கள். அப்போது அல்லாஹ், \"இதைவிடச் சிறந்த ஒன்றை நான் உங்களுக்கு வழங்கப் போகிறேன்\" என்பான். அதற்கு அவர்கள், \"இதைவிடச் சிறந்தது எதுவாக இருக்க முடியும்?\" எனக் கேட்பார்கள். அதற்கு அல்லாஹ், \"உங்களுக்கு எனது திருப்பொருத்தத்தை வழங்குகிறேன்; இதற்குப் பிறகு உங்கள் மீது நான் எப்போதும் கோபப்பட மாட்டேன்\" என்று கூறுவான்.) மற்றொரு ஹதீஸில் இவ்வாறு கூறப்படும் என்று வந்துள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">أَهْلَ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ،</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">عِنْدَ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">مَوْعِدًا</span> <span class=\"quran-arabic-font text-success\">يُرِيدُ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يُنْجِزَكُمُوهُ</span>: <span class=\"quran-arabic-font text-success\">فَيَقُولُونَ</span>: <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">هُوَ؟</span> <span class=\"quran-arabic-font text-success\">أَلَمْ</span> <span class=\"quran-arabic-font text-success\">يُبَيِّضْ</span> <span class=\"quran-arabic-font text-success\">وُجُوهَنَا</span> <span class=\"quran-arabic-font text-success\">وَيُثْقِلْ</span> <span class=\"quran-arabic-font text-success\">مَوَازِينَنَا</span> <span class=\"quran-arabic-font text-success\">وَيُزَحْزِحْنَا</span> <span class=\"quran-arabic-font text-success\">عَنِ</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">وَيُدْخِلْنَا</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةَ،</span> <span class=\"quran-arabic-font text-success\">فَيُكْشَفُ</span> <span class=\"quran-arabic-font text-success\">الْحِجَابُ</span> <span class=\"quran-arabic-font text-success\">فَيَنْظُرُونَ</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِ،</span> <span class=\"quran-arabic-font text-success\">فَوَ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">أَعْطَاهُمْ</span> <span class=\"quran-arabic-font text-success\">خَيْرًا</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">النَّظَرِ</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِ،</span> <span class=\"quran-arabic-font text-success\">وَهِيَ</span> <span class=\"quran-arabic-font text-success\">الزِّيَادَة</span>»<br />\r\n<br />\r\n(\"சொர்க்கவாசிகளே! அல்லாஹ் உங்களுக்கு ஒரு வாக்குறுதி அளித்துள்ளான், அதை அவன் இப்போது நிறைவேற்ற நாடுகிறான்\" என்று கூறப்படும். அதற்கு அவர்கள், \"அது என்ன? அவன் எங்கள் முகங்களைப் பிரகாசமாக்கவில்லையா? எங்களது (நற்செயல்களின்) தராசைக் கனமாக்கவில்லையா? எங்களை நரகிலிருந்து காத்து சொர்க்கத்தில் நுழைவிக்கவில்லையா?\" என்று கேட்பார்கள். அப்போது திரை விலக்கப்படும், அவர்கள் அல்லாஹ்வை உற்று நோக்குவார்கள். அல்லாஹ்வின் மீது சத்தியமாக! அவனைத் தரிசிப்பதை விடச் சிறந்த எதையும் அவன் அவர்களுக்கு வழங்கவில்லை. இதுவே (குர்ஆனில் கூறப்பட்டுள்ள) அதிகப்படியான அருட்கொடையாகும்.)<br />\r\n<br />","text":"பல சமுதாயங்கள் அழிக்கப்பட்டன; அவற்றில் ஒரு படிப்பினை உள்ளது\n\r\n\n\r\nஉயர்ந்தோனாகிய அல்லாஹ் கூறுகிறான்,\n\r\n\n\r\nأَفَلَمْ يَهْدِ لَهُمْ\n\r\n\n\r\n(இது அவர்களுக்கு வழிகாட்டவில்லையா...) நபி (ஸல்) அவர்கள் கொண்டு வந்த சத்தியத்தை நிராகரிப்பவர்களுக்கு இது ஒரு எச்சரிக்கையாகக் கூறப்படுகிறது: ‘இவர்களுக்கு முன்னிருந்த முந்தைய சமுதாயங்களில் தூதர்களைப் பொய்யாக்கியவர்களை நாம் அழித்தோம். அவர்கள் வெளிப்படையான பகையை வெளிப்படுத்தினார்கள்; அதன் விளைவாக இன்று அவர்களின் சுவடுகூட எஞ்சவில்லை. இவர்கள் விட்டுச்சென்ற பாழடைந்த வீடுகளே இதற்குச் சாட்சியாக உள்ளன. இப்போது மற்றவர்கள் அவற்றைச் சுதந்தரித்து, அந்த முன்னைய மக்களின் குடியிருப்புகளில் நடமாடி வருகிறார்கள்.’\n\r\n\n\r\nإِنَّ فِي ذَلِكَ لَآيَاتٍ لِّأُولِي النُّهَى\n\r\n\n\r\n(நிச்சயமாக, இதில் அறிவுடையோருக்குப் பல அத்தாட்சிகள் உள்ளன.) அதாவது, சீரான புத்தியும் சரியான புரிதலும் கொண்டவர்களுக்கு இதில் பாடங்கள் உள்ளன. அல்லாஹ் மற்றோர் இடத்தில் கூறுவது போல:\n\r\n\n\r\nأَفَلَمْ يَسِيرُوا فِي الْأَرْضِ فَتَكُونَ لَهُمْ قُلُوبٌ يَعْقِلُونَ بِهَا أَوْ آذَانٌ يَسْمَعُونَ بِهَا فَإِنَّهَا لَا تَعْمَى الْأَبْصَارُ وَلَكِن تَعْمَى الْقُلُوبُ الَّتِي فِي الصُّدُورِ\n\r\n\n\r\n(அவர்கள் பூமியில் பயணம் செய்யவில்லையா? அவ்வாறு செய்திருந்தால், அவர்கள் சிந்தித்துப் புரிந்துகொள்ளக்கூடிய உள்ளங்களும், செவியேற்கக்கூடிய காதுகளும் அவர்களுக்குக் கிடைத்திருக்கும். நிச்சயமாக, கண்கள் குருடாவதில்லை, மாறாக நெஞ்சங்களுக்குள் இருக்கும் இதயங்களே குருடாகிவிடுகின்றன.) 22:46. அல்லாஹ் ஸூரத்து அலிஃப் லாம் மீம் அஸ்-ஸஜ்தாவிலும் கூறுகிறான்:\n\r\n\n\r\nأَوَلَمْ يَهْدِ لَهُمْ كَمْ أَهْلَكْنَا مِن قَبْلِهِمْ مِّنَ الْقُرُونِ يَمْشُونَ فِى مَسَاكِنِهِمْ\n\r\n\n\r\n(இவர்களுக்கு முன்னிருந்த எத்தனையோ தலைமுறையினரை நாம் அழித்திருக்கிறோம் என்பது இவர்களுக்கு வழிகாட்டவில்லையா? அவர்களின் குடியிருப்புகளில் இவர்கள் இன்று நடமாடுகிறார்கள்.) 32:26. பின்னர், உயர்ந்தோனாகிய அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَلَوْلاَ كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ لَكَانَ لِزَاماً وَأَجَلٌ مُّسَمًّى\n\r\n\n\r\n(உமது இறைவனிடமிருந்து ஏற்கனவே ஒரு வார்த்தை முந்திச் சென்றிராமலும், ஒரு குறிப்பிட்ட காலம் நிர்ணயிக்கப்பட்டிராமலும் இருந்தால், (அவர்களுக்கான தண்டனை) இவ்வுலகிலேயே நிச்சயமாக வந்திருக்கும்.) 20:129. இதன் பொருள் என்னவென்றால், ஒருவருக்கு எதிராக ஆதாரங்கள் நிலைநாட்டப்படும் வரை அவனைத் தண்டிக்க மாட்டான் என்றும், இந்த நிராகரிப்பாளர்களுக்கான தண்டனை அவன் நிர்ணயித்த ஒரு குறிப்பிட்ட நேரத்தில் தான் நிகழும் என்றும் அல்லாஹ் ஏற்கனவே விதித்திருக்கவில்லை என்றால், தண்டனை அவர்களை இப்போதே பிடித்திருக்கும்.\n\r\n\n\r\nபொறுமை காப்பதற்கும் ஐவேளைத் தொழுகைகளை நிறைவேற்றுவதற்குமான கட்டளை\n\r\n\n\r\nஅல்லாஹ் தன் நபி (ஸல்) அவர்களுக்கு ஆறுதல் கூறும் வகையில் கூறுகிறான்:\n\r\n\n\r\nفَاصْبِرْ عَلَى مَا يَقُولُونَ\n\r\n\n\r\n(ஆகவே, அவர்கள் சொல்வதை நீர் பொறுமையுடன் சகித்துக் கொள்வீராக,) அதாவது, \"அவர்கள் உம்மை நிராகரிப்பது குறித்து நீர் பொறுமையைக் கடைப்பிடிப்பீராக.\"\n\r\n\n\r\nوَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ الشَّمْسِ\n\r\n\n\r\n(சூரியன் உதிப்பதற்கு முன்னதாக உமது இறைவனைப் புகழ்ந்து துதிப்பீராக,) இது அதிகாலை (ஃபஜ்ர்) தொழுகையைக் குறிக்கிறது.\n\r\n\n\r\nوَقَبْلَ غُرُوبِهَا\n\r\n\n\r\n(மேலும், அது மறைவதற்கு முன்னரும் (துதிப்பீராக),) இது மாலை (அஸர்) தொழுகையைக் குறிக்கிறது. ஜரீர் பின் அப்துல்லாஹ் அல்-பஜலீ (ரழி) அவர்கள் அறிவித்ததாக புகாரி, முஸ்லிம் ஆகிய இரு ஆதாரப்பூர்வமான நூல்களிலும் (ஸஹீஹைன்) இது குறிப்பிடப்பட்டுள்ளது. அவர்கள் கூறினார்கள்: \"ஒருமுறை நாங்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுடன் அமர்ந்திருந்தோம். அப்போது அவர்கள் பௌர்ணமி அன்று நிலவைப் பார்த்துவிட்டு இவ்வாறு கூறினார்கள்:\"\n\r\n\n\r\n«إِنَّكُمْ سَتَرَوْنَ رَبَّكُمْ كَمَا تَرَوْنَ هَذَا الْقَمَرَ، لَا تُضَامُونَ فِي رُؤْيَتِهِ، فَإِنِ اسْتَطَعْتُمْ أَنْ لَا تُغْلَبُوا عَلَى صَلَاةٍ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ غُرُوبِهَا فَافْعَلُوا»\n\r\n\n\r\n(நிச்சயமாக நீங்கள் உங்கள் இறைவனை (மறுமையில்), இந்த நிலவைக் காண்பது போன்றே காண்பீர்கள். அவனைக் காண்பதில் உங்களுக்கு எந்தச் சிரமமும் இருக்காது. எனவே, சூரிய உதயத்திற்கு முன்புள்ள (ஃபஜ்ர்) தொழுகையையும், சூரிய அஸ்தமனத்திற்கு முன்புள்ள (அஸர்) தொழுகையையும் தவறாமல் நிறைவேற்ற உங்களால் முடிந்தால், அதைச் செய்யுங்கள்.) பின்னர் அவர்கள் இந்த வசனத்தை ஓதினார்கள். இமாம் அஹ்மத் அவர்கள், உமாரா பின் ருஅய்பா (ரழி) அவர்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறுவதைக் கேட்டதாகப் பதிவு செய்துள்ளார்கள்:\n\r\n\n\r\n«لَنْ يَلِجَ النَّارَ أَحَدٌ صَلَّى قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ غُرُوبِهَا»\n\r\n\n\r\n(சூரியன் உதிப்பதற்கு முன்னரும், அது மறைவதற்கு முன்னரும் தொழுபவர் ஒருபோதும் நரகில் நுழைய மாட்டார்.) இச்செய்தியை முஸ்லிம் அவர்களும் பதிவு செய்துள்ளார்கள். அல்லாஹ்வின் இந்த வசனத்தைப் பொறுத்தவரை:\n\r\n\n\r\nوَمِنْ ءَانَآءِ الَّيْلِ فَسَبِّحْ\n\r\n\n\r\n(இரவின் சில நேரங்களிலும் துதிப்பீராக.) இதன் பொருள், இரவின் நேரங்களில் இரவுத் தொழுகையை (தஹஜ்ஜுத்) தொழுவதாகும். சில அறிஞர்கள், இது மஃரிப் மற்றும் இஷா தொழுகைகளையும் குறிக்கும் என்று கூறியுள்ளனர்.\n\r\n\n\r\nوَأَطْرَافَ النَّهَارِ\n\r\n\n\r\n(பகலின் இரு முனைகளிலும் (துதிப்பீராக),) இது இரவின் நேரங்களுக்கு எதிரானது.\n\r\n\n\r\nلَعَلَّكَ تَرْضَى\n\r\n\n\r\n(நீர் திருப்தியடைவதற்காக.) அல்லாஹ் மற்றோர் இடத்தில் கூறுவது போல்:\n\r\n\n\r\nوَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَى\n\r\n\n\r\n(நிச்சயமாக உமது இறைவன் உமக்கு (ஏராளமான நன்மைகளை) வழங்குவான், அப்போது நீர் திருப்தியடைவீர்.) 93:5. ஸஹீஹ் நூலில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியதாகப் பதிவு செய்யப்பட்டுள்ளது:\n\r\n\n\r\n«يَقُولُ اللهُ تَعَالَى يَاأَهْلَ الْجَنَّةِ، فَيَقُولُونَ: لَبَّيْكَ رَبَّنَا وَسَعْدَيْكَ، فَيَقُولُ: هَلْ رَضِيتُمْ؟ فَيَقُولُونَ: رَبَّنَا وَمَا لَنَا لَا نَرْضَى وَقَدْ أَعْطَيْتَنَا مَا لَمْ تُعْطِ أَحَدًا مِنْ خَلْقِكَ، فَيَقُولُ: إِنِّي أُعْطِيكُمْ أَفْضَلَ مِنْ ذَلِكَ، فَيَقُولُونَ: وَأَيُّ شَيْءٍ أَفْضَلُ مِنْ ذَلِكَ؟ فَيَقُولُ: أَحِلُّ عَلَيْكُمْ رِضْوَانِي فَلَا أَسْخَطُ عَلَيْكُمْ بَعْدَهُ أَبَدًا»\n\r\n\n\r\n(உயர்ந்தோனாகிய அல்லாஹ், \"சொர்க்கவாசிகளே!\" என்று அழைப்பான். அதற்கு அவர்கள், \"எங்கள் இறைவா! இதோ உனது கட்டளைக்குக் கீழ்ப்படியக் காத்திருக்கிறோம்; நன்மைகள் அனைத்தும் உன் வசமே உள்ளன\" என்று பதிலளிப்பார்கள். பின்னர் அவன், \"நீங்கள் திருப்தியடைந்துவிட்டீர்களா?\" என்று கேட்பான். அதற்கு அவர்கள், \"எங்கள் இறைவா! உனது படைப்புகளில் எவருக்கும் அளிக்காதவற்றை எங்களுக்கு நீ அளித்திருக்கும்போது, நாங்கள் ஏன் திருப்தியடையாமல் இருக்கப் போகிறோம்?\" என்று கூறுவார்கள். அப்போது அல்லாஹ், \"இதைவிடச் சிறந்த ஒன்றை நான் உங்களுக்கு வழங்கப் போகிறேன்\" என்பான். அதற்கு அவர்கள், \"இதைவிடச் சிறந்தது எதுவாக இருக்க முடியும்?\" எனக் கேட்பார்கள். அதற்கு அல்லாஹ், \"உங்களுக்கு எனது திருப்பொருத்தத்தை வழங்குகிறேன்; இதற்குப் பிறகு உங்கள் மீது நான் எப்போதும் கோபப்பட மாட்டேன்\" என்று கூறுவான்.) மற்றொரு ஹதீஸில் இவ்வாறு கூறப்படும் என்று வந்துள்ளது:\n\r\n\n\r\n«يَا أَهْلَ الْجَنَّةِ، إِنَّ لَكُمْ عِنْدَ اللهِ مَوْعِدًا يُرِيدُ أَنْ يُنْجِزَكُمُوهُ: فَيَقُولُونَ: وَمَا هُوَ؟ أَلَمْ يُبَيِّضْ وُجُوهَنَا وَيُثْقِلْ مَوَازِينَنَا وَيُزَحْزِحْنَا عَنِ النَّارِ وَيُدْخِلْنَا الْجَنَّةَ، فَيُكْشَفُ الْحِجَابُ فَيَنْظُرُونَ إِلَيْهِ، فَوَ اللهِ مَا أَعْطَاهُمْ خَيْرًا مِنَ النَّظَرِ إِلَيْهِ، وَهِيَ الزِّيَادَة»\n\r\n\n\r\n(\"சொர்க்கவாசிகளே! அல்லாஹ் உங்களுக்கு ஒரு வாக்குறுதி அளித்துள்ளான், அதை அவன் இப்போது நிறைவேற்ற நாடுகிறான்\" என்று கூறப்படும். அதற்கு அவர்கள், \"அது என்ன? அவன் எங்கள் முகங்களைப் பிரகாசமாக்கவில்லையா? எங்களது (நற்செயல்களின்) தராசைக் கனமாக்கவில்லையா? எங்களை நரகிலிருந்து காத்து சொர்க்கத்தில் நுழைவிக்கவில்லையா?\" என்று கேட்பார்கள். அப்போது திரை விலக்கப்படும், அவர்கள் அல்லாஹ்வை உற்று நோக்குவார்கள். அல்லாஹ்வின் மீது சத்தியமாக! அவனைத் தரிசிப்பதை விடச் சிறந்த எதையும் அவன் அவர்களுக்கு வழங்கவில்லை. இதுவே (குர்ஆனில் கூறப்பட்டுள்ள) அதிகப்படியான அருட்கொடையாகும்.)"},"131":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=135\" class=\"link\">20:135</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:135 ஐ பார்க்கவும்"},"132":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=135\" class=\"link\">20:135</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:135 ஐ பார்க்கவும்"},"133":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=135\" class=\"link\">20:135</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:135 ஐ பார்க்கவும்"},"134":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=20&ayah=135\" class=\"link\">20:135</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 20:135 ஐ பார்க்கவும்"},"135":{"html":"<strong>செல்வந்தர்களின் சுகபோகங்களைக் கவனிக்காதீர்கள், அல்லாஹ்வின் வணக்கத்தில் பொறுமையைக் கடைப்பிடியுங்கள்</strong><br />\r\n<br />\r\nஉயர்ந்தோன் அல்லாஹ் தனது தூதர் முஹம்மது (ஸல்) அவர்களிடம் கூறுகிறான், \"இவ்வுலக ஆடம்பரங்களில் திளைத்திருக்கும் இவர்களும், இவர்களைப் போன்றவர்களும் அனுபவிக்கும் வசதிகளை நீர் பார்த்துவிடாதீர். ஏனெனில், நிச்சயமாக அவை மிகக் குறுகிய கால ஆடம்பரமும், அற்பமான அருட்கொடையுமேயாகும். அவர்களைச் சோதிப்பதற்காகவே நாம் அவற்றை வழங்கியுள்ளோம். எனது அடியார்களில் மிகச் சிலரே உண்மையான நன்றியுள்ளவர்களாக இருக்கின்றனர்.\" முஜாஹித் அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَزْوَاجًا</span> <span class=\"quran-arabic-font text-success\">مِّنْهُمْ</span><br />\r\n<br />\r\n(அவர்களில் பல்வேறு பிரிவினர்) என்பது \"செல்வந்தர்களைக் குறிக்கிறது.\" இதன் பொருள், \"நிச்சயமாக, அவர்களுக்கு நாம் வழங்கியதை விடச் சிறந்ததை (முஹம்மதே!) உமக்கு வழங்கியுள்ளோம்\" என்பதாகும். இது அல்லாஹ் வேறொரு வசனத்தில் கூறுவதைப் போன்றதேயாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">آتَيْنَاكَ</span> <span class=\"quran-arabic-font text-success\">سَبْعًا</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْمَثَانِي</span> <span class=\"quran-arabic-font text-success\">وَالْقُرْآنَ</span> <span class=\"quran-arabic-font text-success\">الْعَظِيمَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَمُدَّنَّ</span> <span class=\"quran-arabic-font text-success\">عَيْنَيْكَ</span><br />\r\n<br />\r\n(நிச்சயமாக, திரும்பத் திரும்ப ஓதப்படும் ஏழு வசனங்களையும், மகத்தான குர்ஆனையும் நாம் உமக்கு வழங்கியுள்ளோம். எனவே, உமது பார்வையை (இவ்வுலக ஆதாயங்களை நோக்கி) நீட்டாதீர்.) <a href=\"qurandisp.php?sura=15&ayah=87\" class=\"link\">15:87</a>-88 அவ்வாறே, மறுமையில் தனது தூதருக்காக அல்லாஹ் சேமித்து வைத்துள்ளவை மிகவும் மகத்தானவை. அது விவரிக்க இயலாத, எல்லையற்ற நற்பலனாகும். இதனை அல்லாஹ் இவ்வாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَسَوْفَ</span> <span class=\"quran-arabic-font text-success\">يُعْطِيكَ</span> <span class=\"quran-arabic-font text-success\">رَبُّكَ</span> <span class=\"quran-arabic-font text-success\">فَتَرْضَى</span><br />\r\n<br />\r\n(நிச்சயமாக, உமது இறைவன் நீர் திருப்தியடையும் அளவுக்கு உமக்கு வழங்குவான்.) <a href=\"qurandisp.php?sura=93&ayah=5\" class=\"link\">93:5</a> இந்தக் காரணத்திற்காகவே அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَرِزْقُ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">خَيْرٌ</span> <span class=\"quran-arabic-font text-success\">وَأَبْقَى</span><br />\r\n<br />\r\n(ஆனால் உமது இறைவனின் வாழ்வாதாரம் சிறந்ததும் நிலைத்திருக்கக் கூடியதும் ஆகும்.)<br />\r\n<br />\r\nஸஹீஹ் (நூற்களில்) பதிவு செய்யப்பட்டுள்ளதாவது: உமர் பின் அல்-கத்தாப் (ரழி) அவர்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தமது மனைவியரிடமிருந்து விலகி இருப்பதாகச் சத்தியம் செய்துவிட்டுத் தங்களைத் தனிமைப்படுத்திக் கொண்டிருந்த ஒரு சிறிய அறைக்குள் நுழைந்தார்கள். அவர் உள்ளே சென்றபோது, நபி (ஸல்) அவர்கள் கரடுமுரடான ஒரு பாயின் மீது படுத்திருப்பதைப் பார்த்தார். அந்த அறையில் ஒரு குவியல் கருவேல மரக் காய்களையும், தொங்கிக்கொண்டிருந்த சில தோல் பைகளையும் தவிர வேறெதுவும் இருக்கவில்லை. இதைக் கண்ட உமர் (ரழி) அவர்களின் கண்கள் கண்ணீரால் பெருகின. அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அவரிடம் கேட்டார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يُبْكِيكَ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">عُمَرُ؟</span>»<br />\r\n<br />\r\n(உமரே! நீர் ஏன் அழுகிறீர்?) அதற்கு அவர், \"அல்லாஹ்வின் தூதரே! பாரசீக மன்னன் கிஸ்ராவும் ரோமானிய மன்னன் சீசரும் சகல ஆடம்பர வசதிகளுடன் வாழ்கிறார்கள்; ஆனால் அல்லாஹ் தனது படைப்புகளிலேயே தேர்ந்தெடுத்த உற்ற நண்பரான தாங்களோ இத்தகைய நிலையில் இருக்கிறீர்களே!\" என்று பதிலளித்தார். அதற்கு நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَوَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">شَكٍّ</span> <span class=\"quran-arabic-font text-success\">أَنْتَ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">ابْنَ</span> <span class=\"quran-arabic-font text-success\">الْخَطَّابِ؟</span> <span class=\"quran-arabic-font text-success\">أُولَئِكَ</span> <span class=\"quran-arabic-font text-success\">قَوْمٌ</span> <span class=\"quran-arabic-font text-success\">عُجِّلَتْ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">طَيِّبَاتُهُمْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">حَيَاتِهِمُ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span>»<br />\r\n<br />\r\n(கத்தாபின் மகனே! உமக்கு இன்னும் சந்தேகம் இருக்கிறதா? அவர்கள் தங்களுக்குரிய நல்லவைகளை இவ்வுலக வாழ்க்கையிலேயே அவசரமாகப் பெற்றுக்கொண்ட சமூகத்தினர் ஆவர்.)<br />\r\n<br />\r\nஇவ்வாறாக, உலக சுகபோகங்களை அடையும் ஆற்றல் இருந்தபோதிலும், இவ்வுலக ஆடம்பரங்கள் விஷயத்தில் நபி (ஸல்) அவர்கள் மிகவும் பற்றற்றவர்களாகவே இருந்தார்கள். உலகச் செல்வங்களில் ஏதேனும் கிடைத்தால் கூட, அதனை அல்லாஹ்வின் அடியார்களுக்காக இங்கும் அங்குமாகச் செலவிட்டு விடுவார்கள். மறுநாளுக்காக எதனையும் தமக்கெனச் சேமித்து வைக்க மாட்டார்கள். இப்னு அபீ ஹாதிம் அவர்கள் அபூ ஸயீத் (ரழி) அவர்கள் வாயிலாக அறிவிக்கிறார்கள்; அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">أَخْوَفَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">أَخَافُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَفْتَحُ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">زَهْرَةِ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span>»<br />\r\n<br />\r\n(நிச்சயமாக, உங்களுக்கு இவ்வுலகின் கவர்ச்சிகளிலிருந்து அல்லாஹ் எவற்றைத் திறக்கப்போகிறானோ, அதனைப் பற்றியே நான் உங்கள் விஷயத்தில் அதிகம் அஞ்சுகிறேன்.) ஸஹாபாக்கள் (தோழர்கள்), \"அல்லாஹ்வின் தூதரே! இவ்வுலகின் கவர்ச்சி என்பது எது?\" என்று கேட்டார்கள். அதற்கு அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">بَرَكَاتُ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span>»<br />\r\n<br />\r\n(பூமியின் பரக்கத்துகள் (அருள்வளங்கள்).) கத்தாதா மற்றும் அஸ்-ஸுத்தி ஆகியோர் கூறுகையில், \"இவ்வுலக வாழ்வின் கவர்ச்சி என்பது இவ்வுலகின் அழகிய அலங்காரங்களைக் குறிக்கும்\" என்றனர். கத்தாதா அவர்கள்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِنَفْتِنَهُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span><br />\r\n<br />\r\n(அதன் மூலம் நாம் அவர்களைச் சோதிப்பதற்காக) என்பதற்கு, \"நாம் அவர்களைச் சோதனைக்கு உள்ளாக்குவதற்காக\" என்று விளக்கமளித்தார்.<br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்றான,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأْمُرْ</span> <span class=\"quran-arabic-font text-success\">أَهْلَكَ</span> <span class=\"quran-arabic-font text-success\">بِالصَّلوةِ</span> <span class=\"quran-arabic-font text-success\">وَاصْطَبِرْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهَا</span><br />\r\n<br />\r\n(உமது குடும்பத்தினரைத் தொழுகையை ஏவுவீராக, அதன் மீது நீரும் உறுதியாக இருப்பீராக) என்பதன் பொருள்: தொழுகையை நிலைநாட்டுவதன் மூலம் அவர்களை அல்லாஹ்வின் தண்டனையிலிருந்து காப்பாற்றுவதாகும்; மேலும் அதனை நிறைவேற்றுவதில் நீரும் பொறுமையாகவும் உறுதியாகவும் இருப்பீராக என்பதாகும். இதனை அல்லாஹ் இவ்வாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">أَيُّهَا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">آمَنُوا</span> <span class=\"quran-arabic-font text-success\">قُوا</span> <span class=\"quran-arabic-font text-success\">أَنفُسَكُمْ</span> <span class=\"quran-arabic-font text-success\">وَأَهْلِيكُمْ</span> <span class=\"quran-arabic-font text-success\">نَاراً</span><br />\r\n<br />\r\n(ஈமான் கொண்டவர்களே! உங்களையும் உங்கள் குடும்பத்தினரையும் நரக நெருப்பிலிருந்து பாதுகாத்துக் கொள்ளுங்கள்.) <a href=\"qurandisp.php?sura=66&ayah=6\" class=\"link\">66:6</a><br />\r\n<br />\r\nஇப்னு அபீ ஹாதிம் பதிவு செய்துள்ள அறிவிப்பில், ஜைத் பின் அஸ்லம் அவர்கள் தனது தந்தையின் வாயிலாகக் கூறுவதாவது: அவரும் யர்ஃபாவும் சில சமயம் உமர் பின் அல்-கத்தாப் (ரழி) அவர்களிடம் இரவில் தங்குவார்கள். உமர் (ரழி) அவர்கள் இரவில் ஒரு குறிப்பிட்ட நேரத்தில் எழுந்து தொழுவது வழக்கம். சில சமயம் அவர்கள் எழ மாட்டார்கள். அப்போது நாங்கள், \"வழக்கமாக எழுவதைப் போல் இன்று அவர்கள் எழ மாட்டார்கள் போலும்\" எனப் பேசிக் கொள்வோம். ஆனால் அவர்கள் விழிக்கும்போது தமது குடும்பத்தினரையும் எழுப்பி விடுவார்கள். அப்போது அவர்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأْمُرْ</span> <span class=\"quran-arabic-font text-success\">أَهْلَكَ</span> <span class=\"quran-arabic-font text-success\">بِالصَّلوةِ</span> <span class=\"quran-arabic-font text-success\">وَاصْطَبِرْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهَا</span><br />\r\n<br />\r\n(உமது குடும்பத்தினரைத் தொழுகையை ஏவுவீராக, அதன் மீது நீரும் உறுதியாக இருப்பீராக) என்று ஓதுவார்கள்.<br />\r\n<br />\r\nஅல்லாஹ் கூறினான்;<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">نَسْأَلُكَ</span> <span class=\"quran-arabic-font text-success\">رِزْقاً</span> <span class=\"quran-arabic-font text-success\">نَّحْنُ</span> <span class=\"quran-arabic-font text-success\">نَرْزُقُكَ</span><br />\r\n<br />\r\n(நாம் உம்மிடம் வாழ்வாதாரத்தைக் கோரவில்லை; நாமே உமக்கு வாழ்வாதாரம் வழங்குகிறோம்.) இதன் பொருள், நீர் தொழுகையை நிலைநாட்டினால், நீர் எதிர்பாராத விதத்தில் உமக்குரிய வாழ்வாதாரம் (ரிஸ்க்) வந்து சேரும் என்பதாகும். இதனை அல்லாஹ் இவ்வாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">يَتَّقِ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">يَجْعَل</span> <span class=\"quran-arabic-font text-success\">لَّهُ</span> <span class=\"quran-arabic-font text-success\">مَخْرَجًا</span> <span class=\"quran-arabic-font text-success\">وَيَرْزُقْهُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">حَيْثُ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَحْتَسِبُ</span><br />\r\n<br />\r\n(எவர் அல்லாஹ்வுக்கு அஞ்சி (தக்வாவுடன்) நடக்கிறாரோ, அவருக்கு அவன் ஒரு வழியை ஏற்படுத்துவான். மேலும், அவர் கற்பனை செய்து பார்த்திராத வழிகளில் அவருக்கு அவன் வாழ்வாதாரத்தை வழங்குவான்.) <a href=\"qurandisp.php?sura=65&ayah=2\" class=\"link\">65:2</a>-3<br />\r\n<br />\r\nஅல்லாஹ் மேலும் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">خَلَقْتُ</span> <span class=\"quran-arabic-font text-success\">الْجِنَّ</span> <span class=\"quran-arabic-font text-success\">وَالإِنسَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">لِيَعْبُدُونِ</span> - <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">أُرِيدُ</span> <span class=\"quran-arabic-font text-success\">مِنْهُم</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">رِّزْقٍ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">أُرِيدُ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يُطْعِمُونِ</span> - <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">الرَّزَّاقُ</span> <span class=\"quran-arabic-font text-success\">ذُو</span> <span class=\"quran-arabic-font text-success\">الْقُوَّةِ</span> <span class=\"quran-arabic-font text-success\">الْمَتِينُ</span><br />\r\n<br />\r\n(ஜின்களையும் மனிதர்களையும் என்னை வணங்குவதற்காகவே தவிர நான் படைக்கவில்லை. அவர்களிடமிருந்து நான் எந்த வாழ்வாதாரத்தையும் நாடவில்லை; அவர்கள் எனக்கு உணவளிக்க வேண்டும் என்றும் நான் நாடவில்லை. நிச்சயமாக அல்லாஹ்வே உணவளிப்பவன்; அவன் பேராற்றல் மிக்கவன், மிகவும் பலமானவன்) <a href=\"qurandisp.php?sura=51&ayah=56\" class=\"link\">51:56</a>-58.<br />\r\n<br />\r\nஎனவேதான் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">نَسْأَلُكَ</span> <span class=\"quran-arabic-font text-success\">رِزْقاً</span> <span class=\"quran-arabic-font text-success\">نَّحْنُ</span> <span class=\"quran-arabic-font text-success\">نَرْزُقُكَ</span><br />\r\n<br />\r\n(நாம் உம்மிடம் வாழ்வாதாரத்தைக் கோரவில்லை; நாமே உமக்கு வாழ்வாதாரம் வழங்குகிறோம்.) நிச்சயமாக அத்-திர்மிதி மற்றும் இப்னு மாஜா ஆகிய நூற்களில், அபூ ஹுரைரா (ரழி) அவர்கள் வாயிலாக அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يَقُولُ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">تَعَالى</span>: <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">ابْنَ</span> <span class=\"quran-arabic-font text-success\">آدَمَ</span> <span class=\"quran-arabic-font text-success\">تَفَرَّغْ</span> <span class=\"quran-arabic-font text-success\">لِعِبَادَتِي</span> <span class=\"quran-arabic-font text-success\">أَمْلَأْ</span> <span class=\"quran-arabic-font text-success\">صَدْرَكَ</span> <span class=\"quran-arabic-font text-success\">غِنىً</span> <span class=\"quran-arabic-font text-success\">وَأَسُدَّ</span> <span class=\"quran-arabic-font text-success\">فَقْرَكَ،</span> <span class=\"quran-arabic-font text-success\">وَإِنْ</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">تَفْعَلْ،</span> <span class=\"quran-arabic-font text-success\">مَلَأْتُ</span> <span class=\"quran-arabic-font text-success\">صَدْرَكَ</span> <span class=\"quran-arabic-font text-success\">شُغْلًا</span> <span class=\"quran-arabic-font text-success\">وَلَمْ</span> <span class=\"quran-arabic-font text-success\">أَسُدَّ</span> <span class=\"quran-arabic-font text-success\">فَقْرَك</span>»<br />\r\n<br />\r\n(உயர்ந்தோன் அல்லாஹ் கூறுகிறான்: \"ஆதமின் மகனே! எனது வணக்கத்திற்காக உன்னை முழுமையாக ஈடுபடுத்திக்கொள்; நான் உனது உள்ளத்தை மனநிறைவால் நிரப்புவேன், உனது வறுமையைத் தீர்ப்பேன். நீ அவ்வாறு செய்யாவிட்டால், உனது உள்ளத்தை வேலைப் பளுவால் நிரப்புவேன், உனது வறுமையையும் நான் போக்க மாட்டேன்.\")<br />\r\n<br />\r\nமேலும் ஜைத் பின் தாபித் (ரழி) அவர்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறக் கேட்டதாக அறிவிக்கப்படுகிறது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">كَانَتِ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">هَمَّهُ</span> <span class=\"quran-arabic-font text-success\">فَرَّقَ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">أَمْرَهُ،</span> <span class=\"quran-arabic-font text-success\">وَجَعَلَ</span> <span class=\"quran-arabic-font text-success\">فَقْرَهُ</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">عَيْنَيْهِ،</span> <span class=\"quran-arabic-font text-success\">وَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَأْتِهِ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">كُتِبَ</span> <span class=\"quran-arabic-font text-success\">لَهُ،</span> <span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">كَانَتِ</span> <span class=\"quran-arabic-font text-success\">الْآخِرَةُ</span> <span class=\"quran-arabic-font text-success\">نِيَّتَهُ،</span> <span class=\"quran-arabic-font text-success\">جَمَعَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">أَمْرَهُ</span> <span class=\"quran-arabic-font text-success\">وَجَعَلَ</span> <span class=\"quran-arabic-font text-success\">غِنَاهُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">قَلْبِهِ،</span> <span class=\"quran-arabic-font text-success\">وَأَتَتْهُ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">وَهِيَ</span> <span class=\"quran-arabic-font text-success\">رَاغِمَة</span>»<br />\r\n<br />\r\n(எவரது கவலை இவ்வுலகமாக இருக்கிறதோ, அவரது விவகாரங்களை அல்லாஹ் சிரமமாக்கி விடுவான். மேலும், வறுமையை அவரது இரு கண்களுக்கு முன்னால் நிறுத்தி விடுவான். இவ்வுலகிலிருந்து அவருக்கு எழுதப்பட்டதைத் தவிர வேறெதுவும் அவருக்குக் கிடைக்காது. எவரது நோக்கம் மறுமையாக இருக்கிறதோ, அவரது விவகாரங்களை அல்லாஹ் எளிதாக்கி விடுவான். மேலும், அவரது உள்ளத்தில் மனநிறைவை வைப்பான். இவ்வுலகம் அவரைத் தேடிப் பணிந்து வந்து சேரும்.)<br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்றான,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالْعَاقِبَةُ</span> <span class=\"quran-arabic-font text-success\">لِلتَّقْوَى</span><br />\r\n<br />\r\n(நல்ல முடிவு இறையச்சம் உடையவர்களுக்கே (தக்வாவுக்கே) உரியது) என்பதன் பொருள், இவ்வுலகிலும் மறுமையிலும் ஏற்படப்போகும் நல்முடிவாகும். மறுமையில், அல்லாஹ்வை அஞ்சி நடந்தவர்களுக்கே சொர்க்கம் எனும் நல்முடிவு கிட்டும். ஸஹீஹில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியதாக அறிவிக்கப்பட்டுள்ளது: \"இன்றிரவு நான் (கனவில்) ‘உக்பா பின் ராஃபி’ என்பவருடைய வீட்டில் இருப்பதைப் போன்றும், ‘இப்னு தாப்’ (ரகப் பேரீச்சம்) பழங்கள் நமக்குக் கொண்டு வரப்படுவதைப் போன்றும் கண்டேன். இதற்கு, ‘இவ்வுலகில் நல்முடிவு (ஆகிபத்) நமக்கே உரியது; மறுமையில் நமக்கு உயர்வும் (ரிஃப்அத்) உண்டு; நமது மார்க்கம் தூய்மையானது (தாப்)’ என்று நான் விளக்கம் கொண்டேன்.\"<br />\r\n<br />\r\n<strong>குர்ஆனே ஓர் ஆதாரமாக இருக்கும்போது, ஆதாரங்களுக்காக இணைவைப்பாளர்கள் அத்தாட்சிகளைக் கோருதல்</strong><br />\r\n<br />\r\nநிராகரிப்பாளர்கள் கூறும் கூற்றைப் பற்றி உயர்ந்தோன் அல்லாஹ் தெரிவிக்கிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَوْلاَ</span><br />\r\n<br />\r\n(ஏன் இல்லை?) அதாவது, \"முஹம்மது (ஸல்) அவர்கள் தமது இறைவனிடமிருந்து ஓர் அத்தாட்சியை ஏன் நம்மிடம் கொண்டு வரவில்லை?\" என்பது இதன் பொருளாகும். அவர் அல்லாஹ்வின் தூதர் (ஸல்) எனும் அவரது கூற்றிற்கு ஆதாரமாகத் திகழும் ஓர் அற்புதத்தையே அவர்கள் நாடினர். அதற்கு உயர்ந்தோன் அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَوَلَمْ</span> <span class=\"quran-arabic-font text-success\">تَأْتِهِمْ</span> <span class=\"quran-arabic-font text-success\">بَيِّنَةُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الصُّحُفِ</span> <span class=\"quran-arabic-font text-success\">الْأُولَى</span><br />\r\n<br />\r\n(முந்தைய வேதங்களில் உள்ளவற்றின் தெளிவான ஆதாரம் அவர்களிடம் வரவில்லையா?)<br />\r\n<br />\r\nஇதன் பொருள் குர்ஆன் ஆகும். எழுதப்படிக்கத் தெரியாத, முந்தைய வேதக்காரர்களிடம் கல்வி பயிலாத ஒருவராக அவர் இருந்தபோதிலும், அல்லாஹ் அவருக்கு இக்குர்ஆனை வஹீ (இறைச்செய்தி) ஆக அருளினான். இக்குர்ஆனோ கடந்த கால மக்களின் பழங்கால நிகழ்வுகளைப் பற்றியத் தகவல்களைத் தன்னுள் கொண்டுள்ளது. முந்தைய வேதங்களில் கூறப்பட்டுள்ள உண்மையான தகவல்களுடன் இது ஒத்துப்போகிறது. குர்ஆன் முந்தைய வேதங்களை மேற்பார்வையிடுவதும் ஆகும். எது சரியானது என்பதை இது உறுதிப்படுத்துவதுடன், அந்த வேதங்களில் தவறாகப் புகுத்தப்பட்ட செய்திகளை விளக்குகிறது. இவ்வசனம் சூரத்துல் அன்கபூத்தில் உள்ள அல்லாஹ்வின் கூற்றைப் போன்றதேயாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">لَوْلاَ</span> <span class=\"quran-arabic-font text-success\">أُنزِلَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">آيَاتٌ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">رَّبِّهِ</span> <span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">إِنَّمَا</span> <span class=\"quran-arabic-font text-success\">الْآيَاتُ</span> <span class=\"quran-arabic-font text-success\">عِندَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَإِنَّمَا</span> <span class=\"quran-arabic-font text-success\">أَنَاْ</span> <span class=\"quran-arabic-font text-success\">نَذِيرٌ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٌ</span> - <span class=\"quran-arabic-font text-success\">أَوَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَكْفِهِمْ</span> <span class=\"quran-arabic-font text-success\">أَنَّا</span> <span class=\"quran-arabic-font text-success\">أَنزَلْنَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْكَ</span> <span class=\"quran-arabic-font text-success\">الْكِتَابَ</span> <span class=\"quran-arabic-font text-success\">يُتْلَى</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">لَرَحْمَةً</span> <span class=\"quran-arabic-font text-success\">وَذِكْرَى</span> <span class=\"quran-arabic-font text-success\">لِقَوْمٍ</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُونَ</span><br />\r\n<br />\r\n(மேலும் அவர்கள் கூறுகிறார்கள்: \"அவரது இறைவனிடமிருந்து அவருக்கு அத்தாட்சிகள் இறக்கப்பட வேண்டாமா?\" நீர் கூறும்: \"அத்தாட்சிகள் அனைத்தும் அல்லாஹ்விடமே உள்ளன; நான் பகிரங்கமாக எச்சரிக்கை செய்பவன் மட்டுமே.\" அவர்களுக்கு ஓதிக்காட்டப்படும் இவ்வேதத்தை நாம் உமக்கு அருளியிருப்பது அவர்களுக்குப் போதுமானதாக இல்லையா? நிச்சயமாக இதில் ஈமான் கொண்ட மக்களுக்கு ஓர் அருளும் நினைவூட்டலும் உள்ளது.) <a href=\"qurandisp.php?sura=29&ayah=50\" class=\"link\">29:50</a>-51<br />\r\n<br />\r\nஇரண்டு ஸஹீஹ்களிலும் பதிவு செய்யப்பட்டுள்ள ஒரு ஹதீஸில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">نَبِيَ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">وَقَدْ</span> <span class=\"quran-arabic-font text-success\">أُوتِيَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْآياتِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">آمَنَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">مِثْلِهِ</span> <span class=\"quran-arabic-font text-success\">الْبَشَرُ،</span> <span class=\"quran-arabic-font text-success\">وَإِنَّمَا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">أُوتِيتُهُ</span> <span class=\"quran-arabic-font text-success\">وَحْيًا</span> <span class=\"quran-arabic-font text-success\">أَوْحَاهُ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">إِلَيَّ،</span> <span class=\"quran-arabic-font text-success\">فَأَرْجُو</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">أَكُونَ</span> <span class=\"quran-arabic-font text-success\">أَكْثَرَهُمْ</span> <span class=\"quran-arabic-font text-success\">تَابِعًا</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَة</span>»<br />\r\n<br />\r\n(எந்த ஒரு நபியும் மனிதர்கள் நம்பிக்கை கொள்வதற்குத் தேவையான அத்தாட்சிகள் வழங்கப்படாமல் இருந்ததில்லை. எனக்கு வழங்கப்பட்டதோ அல்லாஹ் எனக்கு வழங்கிய வஹீ (இறைச்செய்தி) ஆகும். எனவே, மறுமை நாளில் மற்ற நபிமார்களை விட அதிகமானப் பின்பற்றுபவர்களைக் கொண்டவனாக நான் இருப்பேன் என்று நம்புகிறேன்.) இந்த ஹதீஸில், தமக்கு வழங்கப்பட்ட அத்தாட்சிகளிலேயே மிக மகத்தானதான குர்ஆனை மட்டுமே நபி (ஸல்) அவர்கள் குறிப்பிட்டுள்ளார்கள். இருப்பினும், அவர்களுக்கு எண்ணற்ற இதர அற்புதங்களும் இருந்தன. அவை குறித்த நூல்களில் பதிவு செய்யப்பட்டுள்ளன.<br />\r\n<br />\r\nபின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">أَنَّا</span> <span class=\"quran-arabic-font text-success\">أَهْلَكْنَاهُمْ</span> <span class=\"quran-arabic-font text-success\">بِعَذَابٍ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">قَبْلِهِ</span> <span class=\"quran-arabic-font text-success\">لَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">رَبَّنَا</span> <span class=\"quran-arabic-font text-success\">لَوْلا</span> <span class=\"quran-arabic-font text-success\">أَرْسَلْتَ</span> <span class=\"quran-arabic-font text-success\">إِلَيْنَا</span> <span class=\"quran-arabic-font text-success\">رَسُولاً</span><br />\r\n<br />\r\n(நாம் இவர்களுக்கு முன்னரே இவர்களை வேதனையைக் கொண்டு அழித்திருந்தால், இவர்கள் நிச்சயமாகக் கூறுவார்கள்: \"எங்கள் இறைவா! நீ எங்களுக்கு ஒரு தூதரை அனுப்பியிருக்கக் கூடாதா...\") இதன் பொருள்: \"இந்த கண்ணியமிக்க தூதரை அனுப்பி, மகத்தான இவ்வேதத்தை அருளுவதற்கு முன்னரே நாம் இந்த நிராகரிப்பவர்களை அழித்திருந்தால், அவர்கள் இவ்வாறு கூறியிருப்பார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">رَبَّنَا</span> <span class=\"quran-arabic-font text-success\">لَوْلا</span> <span class=\"quran-arabic-font text-success\">أَرْسَلْتَ</span> <span class=\"quran-arabic-font text-success\">إِلَيْنَا</span> <span class=\"quran-arabic-font text-success\">رَسُولاً</span><br />\r\n<br />\r\n(எங்கள் இறைவா! நீ எங்களுக்கு ஒரு தூதரை அனுப்பியிருக்கக் கூடாதா?) அதாவது, 'நீர் எங்களை அழிப்பதற்கு முன்னரே தூதரை அனுப்பியிருந்தால் நாங்கள் அவரை ஈமான் கொண்டு பின்பற்றியிருப்போம்' என்று கூறியிருப்பார்கள்.\"<br />\r\n<br />\r\nஇதனை அல்லாஹ் இவ்வாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَنَتَّبِعَ</span> <span class=\"quran-arabic-font text-success\">آيَاتِكَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">نَّذِلَّ</span> <span class=\"quran-arabic-font text-success\">وَنَخْزَى</span><br />\r\n<br />\r\n(நாங்கள் இழிவடைவதற்கும் அவமானப்படுவதற்கும் முன்னதாகவே உமது வசனங்களைப் பின்பற்றியிருப்போம்.) இந்த நிராகரிப்பாளர்கள் மிகவும் பிடிவாதக் குணமுடையவர்கள் என்றும், அவர்கள் ஒருபோதும் ஈமான் கொள்ள மாட்டார்கள் என்றும் உயர்ந்தோன் அல்லாஹ் விளக்குகிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">جَاءَتْهُمْ</span> <span class=\"quran-arabic-font text-success\">كُلُّ</span> <span class=\"quran-arabic-font text-success\">آيَةٍ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">يَرَوُاْ</span> <span class=\"quran-arabic-font text-success\">الْعَذَابَ</span> <span class=\"quran-arabic-font text-success\">الْأَلِيمَ</span><br />\r\n<br />\r\n(வேதனைமிக்கத் தண்டனையை அவர்கள் நேரில் காணும் வரை, எல்லா அத்தாட்சிகளும் அவர்களிடம் வந்தாலும் (அவர்கள் ஈமான் கொள்ள மாட்டார்கள்).) <a href=\"qurandisp.php?sura=10&ayah=97\" class=\"link\">10:97</a><br />\r\n<br />\r\nஇது அல்லாஹ்வின் இந்த வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَهَذَا</span> <span class=\"quran-arabic-font text-success\">كِتَابٌ</span> <span class=\"quran-arabic-font text-success\">أَنزَلْنَاهُ</span> <span class=\"quran-arabic-font text-success\">مُبَارَكٌ</span> <span class=\"quran-arabic-font text-success\">فَاتَّبِعُوهُ</span> <span class=\"quran-arabic-font text-success\">وَاتَّقُواْ</span> <span class=\"quran-arabic-font text-success\">لَعَلَّكُمْ</span> <span class=\"quran-arabic-font text-success\">تُرْحَمُونَ</span><br />\r\n<br />\r\n(மேலும் நாம் அருளிய இப்புனிதமிக்க வேதத்தைப் பின்பற்றுங்கள்; அல்லாஹ்வுக்கு அஞ்சுங்கள்; நீங்கள் கருணை செய்யப்படுவீர்கள்.) இது முதல்<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">يَصْدِفُونَ</span><br />\r\n<br />\r\n(அவர்கள் புறக்கணித்ததன் காரணமாக) என்பது வரை (<a href=\"qurandisp.php?sura=6&ayah=155\" class=\"link\">6:155</a>-157). அல்லாஹ் மேலும் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَقْسَمُواْ</span> <span class=\"quran-arabic-font text-success\">بِاللَّهِ</span> <span class=\"quran-arabic-font text-success\">جَهْدَ</span> <span class=\"quran-arabic-font text-success\">أَيْمَانِهِمْ</span> <span class=\"quran-arabic-font text-success\">لَئِن</span> <span class=\"quran-arabic-font text-success\">جَاءَهُمْ</span> <span class=\"quran-arabic-font text-success\">نَذِيرٌ</span> <span class=\"quran-arabic-font text-success\">لَّيَكُونُنَّ</span> <span class=\"quran-arabic-font text-success\">أَهْدَى</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">إِحْدَى</span> <span class=\"quran-arabic-font text-success\">الْأُمَمِ</span><br />\r\n<br />\r\n(தங்களிடம் ஓர் எச்சரிக்கையாளர் வந்தால், மற்றெந்தச் சமூகத்தையும் விட நேர்வழி நடப்போம் என்று அவர்கள் அல்லாஹ்வின் மீது மிக உறுதியாகச் சத்தியம் செய்தனர்.) <a href=\"qurandisp.php?sura=35&ayah=42\" class=\"link\">35:42</a><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَقْسَمُواْ</span> <span class=\"quran-arabic-font text-success\">بِاللَّهِ</span> <span class=\"quran-arabic-font text-success\">جَهْدَ</span> <span class=\"quran-arabic-font text-success\">أَيْمَانِهِمْ</span> <span class=\"quran-arabic-font text-success\">لَئِن</span> <span class=\"quran-arabic-font text-success\">جَاءَتْهُمْ</span> <span class=\"quran-arabic-font text-success\">آيَةٌ</span> <span class=\"quran-arabic-font text-success\">لَّيُؤْمِنُنَّ</span> <span class=\"quran-arabic-font text-success\">بِهَا</span><br />\r\n<br />\r\n(தங்களிடம் ஓர் அத்தாட்சி வந்தால், அதன் மீது நிச்சயமாக ஈமான் கொள்வதாக அவர்கள் அல்லாஹ்வின் மீது மிக உறுதியாகச் சத்தியம் செய்கின்றனர்.) <a href=\"qurandisp.php?sura=6&ayah=109\" class=\"link\">6:109</a> (வசனம் முடியும் வரை).<br />\r\n<br />\r\nபின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span><br />\r\n<br />\r\n(நீர் கூறுவீராக!) \"முஹம்மதே! உம்மைப் பொய்ப்பித்து எதிர்த்து வரும் அந்த நிராகரிப்பாளர்களிடம் கூறும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كُلٌّ</span> <span class=\"quran-arabic-font text-success\">مُّتَرَبِّصٌ</span><br />\r\n<br />\r\n(ஒவ்வொருவரும் எதிர்பார்த்துக் காத்திருக்கின்றனர்;) நீங்களும் நாங்களும்;<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَتَرَبَّصُواْ</span><br />\r\n<br />\r\n(எனவே நீங்களும் காத்திருங்கள்;) இது காத்திருக்குமாறு இடும் கட்டளையாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَسَتَعْلَمُونَ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">أَصْحَابُ</span> <span class=\"quran-arabic-font text-success\">الصِّرَاطِ</span> <span class=\"quran-arabic-font text-success\">السَّوِيِّ</span><br />\r\n<br />\r\n(யார் அஸ்-ஸிராத் அஸ்-ஸவிய்யில் (நேரான பாதையில்) இருப்பவர் என்பதை நீங்கள் விரைவில் அறிந்து கொள்வீர்கள்.) இதன் பொருள் நேரான பாதையாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَنِ</span> <span class=\"quran-arabic-font text-success\">اهْتَدَى</span><br />\r\n<br />\r\n(யார் நேர்வழி பெற்றவர் என்பதையும் (அறிந்து கொள்வீர்கள்).) அதாவது உண்மைக்கும் நேர்வழிக்கும் வழிகாட்டப்பட்டவர்கள் யார் என்பதாகும். இது அல்லாஹ்வின் இந்த வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَسَوْفَ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُونَ</span> <span class=\"quran-arabic-font text-success\">حِينَ</span> <span class=\"quran-arabic-font text-success\">يَرَوْنَ</span> <span class=\"quran-arabic-font text-success\">الْعَذَابَ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">أَضَلُّ</span> <span class=\"quran-arabic-font text-success\">سَبِيلاً</span><br />\r\n<br />\r\n(அவர்கள் வேதனையைக் காணும்போது, பாதையிலிருந்து மிகவும் வழிதவறியவர் யார் என்பதை அறிந்து கொள்வார்கள்.) <a href=\"qurandisp.php?sura=25&ayah=42\" class=\"link\">25:42</a> மேலும் அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">سَيَعْلَمُونَ</span> <span class=\"quran-arabic-font text-success\">غَداً</span> <span class=\"quran-arabic-font text-success\">مَّنِ</span> <span class=\"quran-arabic-font text-success\">الْكَذَّابُ</span> <span class=\"quran-arabic-font text-success\">الْأَشِرُ</span><br />\r\n<br />\r\n(நாளை அவர்கள் யார் பெரும் பொய்யர், யார் திமிர் பிடித்தவர் என்பதை அறிந்து கொள்வார்கள்!) <a href=\"qurandisp.php?sura=54&ayah=26\" class=\"link\">54:26</a><br />\r\n<br />\r\nஇத்துடன் சூரா தா ஹாவின் தஃப்ஸீர் நிறைவுற்றது. எல்லாப் புகழும் நன்றியும் அல்லாஹ்வுக்கே உரியது. அல்லாஹ் நாடினால், இதனைத் தொடர்ந்து சூரத்துல் அன்பியாவின் தஃப்ஸீர் வரும். புகழ் அனைத்தும் அல்லாஹ்வுக்கே!<br />\r\n<br />","text":"செல்வந்தர்களின் சுகபோகங்களைக் கவனிக்காதீர்கள், அல்லாஹ்வின் வணக்கத்தில் பொறுமையைக் கடைப்பிடியுங்கள்\n\r\n\n\r\nஉயர்ந்தோன் அல்லாஹ் தனது தூதர் முஹம்மது (ஸல்) அவர்களிடம் கூறுகிறான், \"இவ்வுலக ஆடம்பரங்களில் திளைத்திருக்கும் இவர்களும், இவர்களைப் போன்றவர்களும் அனுபவிக்கும் வசதிகளை நீர் பார்த்துவிடாதீர். ஏனெனில், நிச்சயமாக அவை மிகக் குறுகிய கால ஆடம்பரமும், அற்பமான அருட்கொடையுமேயாகும். அவர்களைச் சோதிப்பதற்காகவே நாம் அவற்றை வழங்கியுள்ளோம். எனது அடியார்களில் மிகச் சிலரே உண்மையான நன்றியுள்ளவர்களாக இருக்கின்றனர்.\" முஜாஹித் அவர்கள் கூறினார்கள்:\n\r\n\n\r\nأَزْوَاجًا مِّنْهُمْ\n\r\n\n\r\n(அவர்களில் பல்வேறு பிரிவினர்) என்பது \"செல்வந்தர்களைக் குறிக்கிறது.\" இதன் பொருள், \"நிச்சயமாக, அவர்களுக்கு நாம் வழங்கியதை விடச் சிறந்ததை (முஹம்மதே!) உமக்கு வழங்கியுள்ளோம்\" என்பதாகும். இது அல்லாஹ் வேறொரு வசனத்தில் கூறுவதைப் போன்றதேயாகும்:\n\r\n\n\r\nوَلَقَدْ آتَيْنَاكَ سَبْعًا مِّنَ الْمَثَانِي وَالْقُرْآنَ الْعَظِيمَ لاَ تَمُدَّنَّ عَيْنَيْكَ\n\r\n\n\r\n(நிச்சயமாக, திரும்பத் திரும்ப ஓதப்படும் ஏழு வசனங்களையும், மகத்தான குர்ஆனையும் நாம் உமக்கு வழங்கியுள்ளோம். எனவே, உமது பார்வையை (இவ்வுலக ஆதாயங்களை நோக்கி) நீட்டாதீர்.) 15:87-88 அவ்வாறே, மறுமையில் தனது தூதருக்காக அல்லாஹ் சேமித்து வைத்துள்ளவை மிகவும் மகத்தானவை. அது விவரிக்க இயலாத, எல்லையற்ற நற்பலனாகும். இதனை அல்லாஹ் இவ்வாறு கூறுகிறான்:\n\r\n\n\r\nوَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَى\n\r\n\n\r\n(நிச்சயமாக, உமது இறைவன் நீர் திருப்தியடையும் அளவுக்கு உமக்கு வழங்குவான்.) 93:5 இந்தக் காரணத்திற்காகவே அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَرِزْقُ رَبِّكَ خَيْرٌ وَأَبْقَى\n\r\n\n\r\n(ஆனால் உமது இறைவனின் வாழ்வாதாரம் சிறந்ததும் நிலைத்திருக்கக் கூடியதும் ஆகும்.)\n\r\n\n\r\nஸஹீஹ் (நூற்களில்) பதிவு செய்யப்பட்டுள்ளதாவது: உமர் பின் அல்-கத்தாப் (ரழி) அவர்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தமது மனைவியரிடமிருந்து விலகி இருப்பதாகச் சத்தியம் செய்துவிட்டுத் தங்களைத் தனிமைப்படுத்திக் கொண்டிருந்த ஒரு சிறிய அறைக்குள் நுழைந்தார்கள். அவர் உள்ளே சென்றபோது, நபி (ஸல்) அவர்கள் கரடுமுரடான ஒரு பாயின் மீது படுத்திருப்பதைப் பார்த்தார். அந்த அறையில் ஒரு குவியல் கருவேல மரக் காய்களையும், தொங்கிக்கொண்டிருந்த சில தோல் பைகளையும் தவிர வேறெதுவும் இருக்கவில்லை. இதைக் கண்ட உமர் (ரழி) அவர்களின் கண்கள் கண்ணீரால் பெருகின. அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அவரிடம் கேட்டார்கள்:\n\r\n\n\r\n«مَا يُبْكِيكَ يَا عُمَرُ؟»\n\r\n\n\r\n(உமரே! நீர் ஏன் அழுகிறீர்?) அதற்கு அவர், \"அல்லாஹ்வின் தூதரே! பாரசீக மன்னன் கிஸ்ராவும் ரோமானிய மன்னன் சீசரும் சகல ஆடம்பர வசதிகளுடன் வாழ்கிறார்கள்; ஆனால் அல்லாஹ் தனது படைப்புகளிலேயே தேர்ந்தெடுத்த உற்ற நண்பரான தாங்களோ இத்தகைய நிலையில் இருக்கிறீர்களே!\" என்று பதிலளித்தார். அதற்கு நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«أَوَ فِي شَكٍّ أَنْتَ يَا ابْنَ الْخَطَّابِ؟ أُولَئِكَ قَوْمٌ عُجِّلَتْ لَهُمْ طَيِّبَاتُهُمْ فِي حَيَاتِهِمُ الدُّنْيَا»\n\r\n\n\r\n(கத்தாபின் மகனே! உமக்கு இன்னும் சந்தேகம் இருக்கிறதா? அவர்கள் தங்களுக்குரிய நல்லவைகளை இவ்வுலக வாழ்க்கையிலேயே அவசரமாகப் பெற்றுக்கொண்ட சமூகத்தினர் ஆவர்.)\n\r\n\n\r\nஇவ்வாறாக, உலக சுகபோகங்களை அடையும் ஆற்றல் இருந்தபோதிலும், இவ்வுலக ஆடம்பரங்கள் விஷயத்தில் நபி (ஸல்) அவர்கள் மிகவும் பற்றற்றவர்களாகவே இருந்தார்கள். உலகச் செல்வங்களில் ஏதேனும் கிடைத்தால் கூட, அதனை அல்லாஹ்வின் அடியார்களுக்காக இங்கும் அங்குமாகச் செலவிட்டு விடுவார்கள். மறுநாளுக்காக எதனையும் தமக்கெனச் சேமித்து வைக்க மாட்டார்கள். இப்னு அபீ ஹாதிம் அவர்கள் அபூ ஸயீத் (ரழி) அவர்கள் வாயிலாக அறிவிக்கிறார்கள்; அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِنَّ أَخْوَفَ مَا أَخَافُ عَلَيْكُمْ مَا يَفْتَحُ اللهُ لَكُمْ مِنْ زَهْرَةِ الدُّنْيَا»\n\r\n\n\r\n(நிச்சயமாக, உங்களுக்கு இவ்வுலகின் கவர்ச்சிகளிலிருந்து அல்லாஹ் எவற்றைத் திறக்கப்போகிறானோ, அதனைப் பற்றியே நான் உங்கள் விஷயத்தில் அதிகம் அஞ்சுகிறேன்.) ஸஹாபாக்கள் (தோழர்கள்), \"அல்லாஹ்வின் தூதரே! இவ்வுலகின் கவர்ச்சி என்பது எது?\" என்று கேட்டார்கள். அதற்கு அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«بَرَكَاتُ الْأَرْضِ»\n\r\n\n\r\n(பூமியின் பரக்கத்துகள் (அருள்வளங்கள்).) கத்தாதா மற்றும் அஸ்-ஸுத்தி ஆகியோர் கூறுகையில், \"இவ்வுலக வாழ்வின் கவர்ச்சி என்பது இவ்வுலகின் அழகிய அலங்காரங்களைக் குறிக்கும்\" என்றனர். கத்தாதா அவர்கள்,\n\r\n\n\r\nلِنَفْتِنَهُمْ فِيهِ\n\r\n\n\r\n(அதன் மூலம் நாம் அவர்களைச் சோதிப்பதற்காக) என்பதற்கு, \"நாம் அவர்களைச் சோதனைக்கு உள்ளாக்குவதற்காக\" என்று விளக்கமளித்தார்.\n\r\n\n\r\nஅல்லாஹ்வின் கூற்றான,\n\r\n\n\r\nوَأْمُرْ أَهْلَكَ بِالصَّلوةِ وَاصْطَبِرْ عَلَيْهَا\n\r\n\n\r\n(உமது குடும்பத்தினரைத் தொழுகையை ஏவுவீராக, அதன் மீது நீரும் உறுதியாக இருப்பீராக) என்பதன் பொருள்: தொழுகையை நிலைநாட்டுவதன் மூலம் அவர்களை அல்லாஹ்வின் தண்டனையிலிருந்து காப்பாற்றுவதாகும்; மேலும் அதனை நிறைவேற்றுவதில் நீரும் பொறுமையாகவும் உறுதியாகவும் இருப்பீராக என்பதாகும். இதனை அல்லாஹ் இவ்வாறு கூறுகிறான்:\n\r\n\n\r\nيَا أَيُّهَا الَّذِينَ آمَنُوا قُوا أَنفُسَكُمْ وَأَهْلِيكُمْ نَاراً\n\r\n\n\r\n(ஈமான் கொண்டவர்களே! உங்களையும் உங்கள் குடும்பத்தினரையும் நரக நெருப்பிலிருந்து பாதுகாத்துக் கொள்ளுங்கள்.) 66:6\n\r\n\n\r\nஇப்னு அபீ ஹாதிம் பதிவு செய்துள்ள அறிவிப்பில், ஜைத் பின் அஸ்லம் அவர்கள் தனது தந்தையின் வாயிலாகக் கூறுவதாவது: அவரும் யர்ஃபாவும் சில சமயம் உமர் பின் அல்-கத்தாப் (ரழி) அவர்களிடம் இரவில் தங்குவார்கள். உமர் (ரழி) அவர்கள் இரவில் ஒரு குறிப்பிட்ட நேரத்தில் எழுந்து தொழுவது வழக்கம். சில சமயம் அவர்கள் எழ மாட்டார்கள். அப்போது நாங்கள், \"வழக்கமாக எழுவதைப் போல் இன்று அவர்கள் எழ மாட்டார்கள் போலும்\" எனப் பேசிக் கொள்வோம். ஆனால் அவர்கள் விழிக்கும்போது தமது குடும்பத்தினரையும் எழுப்பி விடுவார்கள். அப்போது அவர்கள்:\n\r\n\n\r\nوَأْمُرْ أَهْلَكَ بِالصَّلوةِ وَاصْطَبِرْ عَلَيْهَا\n\r\n\n\r\n(உமது குடும்பத்தினரைத் தொழுகையை ஏவுவீராக, அதன் மீது நீரும் உறுதியாக இருப்பீராக) என்று ஓதுவார்கள்.\n\r\n\n\r\nஅல்லாஹ் கூறினான்;\n\r\n\n\r\nلاَ نَسْأَلُكَ رِزْقاً نَّحْنُ نَرْزُقُكَ\n\r\n\n\r\n(நாம் உம்மிடம் வாழ்வாதாரத்தைக் கோரவில்லை; நாமே உமக்கு வாழ்வாதாரம் வழங்குகிறோம்.) இதன் பொருள், நீர் தொழுகையை நிலைநாட்டினால், நீர் எதிர்பாராத விதத்தில் உமக்குரிய வாழ்வாதாரம் (ரிஸ்க்) வந்து சேரும் என்பதாகும். இதனை அல்லாஹ் இவ்வாறு கூறுகிறான்:\n\r\n\n\r\nوَمَن يَتَّقِ اللَّهَ يَجْعَل لَّهُ مَخْرَجًا وَيَرْزُقْهُ مِنْ حَيْثُ لاَ يَحْتَسِبُ\n\r\n\n\r\n(எவர் அல்லாஹ்வுக்கு அஞ்சி (தக்வாவுடன்) நடக்கிறாரோ, அவருக்கு அவன் ஒரு வழியை ஏற்படுத்துவான். மேலும், அவர் கற்பனை செய்து பார்த்திராத வழிகளில் அவருக்கு அவன் வாழ்வாதாரத்தை வழங்குவான்.) 65:2-3\n\r\n\n\r\nஅல்லாஹ் மேலும் கூறுகிறான்:\n\r\n\n\r\nوَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلاَّ لِيَعْبُدُونِ - مَا أُرِيدُ مِنْهُم مِّن رِّزْقٍ وَمَا أُرِيدُ أَن يُطْعِمُونِ - إِنَّ اللَّهَ هُوَ الرَّزَّاقُ ذُو الْقُوَّةِ الْمَتِينُ\n\r\n\n\r\n(ஜின்களையும் மனிதர்களையும் என்னை வணங்குவதற்காகவே தவிர நான் படைக்கவில்லை. அவர்களிடமிருந்து நான் எந்த வாழ்வாதாரத்தையும் நாடவில்லை; அவர்கள் எனக்கு உணவளிக்க வேண்டும் என்றும் நான் நாடவில்லை. நிச்சயமாக அல்லாஹ்வே உணவளிப்பவன்; அவன் பேராற்றல் மிக்கவன், மிகவும் பலமானவன்) 51:56-58.\n\r\n\n\r\nஎனவேதான் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nلاَ نَسْأَلُكَ رِزْقاً نَّحْنُ نَرْزُقُكَ\n\r\n\n\r\n(நாம் உம்மிடம் வாழ்வாதாரத்தைக் கோரவில்லை; நாமே உமக்கு வாழ்வாதாரம் வழங்குகிறோம்.) நிச்சயமாக அத்-திர்மிதி மற்றும் இப்னு மாஜா ஆகிய நூற்களில், அபூ ஹுரைரா (ரழி) அவர்கள் வாயிலாக அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«يَقُولُ اللهُ تَعَالى: يَا ابْنَ آدَمَ تَفَرَّغْ لِعِبَادَتِي أَمْلَأْ صَدْرَكَ غِنىً وَأَسُدَّ فَقْرَكَ، وَإِنْ لَمْ تَفْعَلْ، مَلَأْتُ صَدْرَكَ شُغْلًا وَلَمْ أَسُدَّ فَقْرَك»\n\r\n\n\r\n(உயர்ந்தோன் அல்லாஹ் கூறுகிறான்: \"ஆதமின் மகனே! எனது வணக்கத்திற்காக உன்னை முழுமையாக ஈடுபடுத்திக்கொள்; நான் உனது உள்ளத்தை மனநிறைவால் நிரப்புவேன், உனது வறுமையைத் தீர்ப்பேன். நீ அவ்வாறு செய்யாவிட்டால், உனது உள்ளத்தை வேலைப் பளுவால் நிரப்புவேன், உனது வறுமையையும் நான் போக்க மாட்டேன்.\")\n\r\n\n\r\nமேலும் ஜைத் பின் தாபித் (ரழி) அவர்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறக் கேட்டதாக அறிவிக்கப்படுகிறது:\n\r\n\n\r\n«مَنْ كَانَتِ الدُّنْيَا هَمَّهُ فَرَّقَ اللهُ عَلَيْهِ أَمْرَهُ، وَجَعَلَ فَقْرَهُ بَيْنَ عَيْنَيْهِ، وَلَمْ يَأْتِهِ مِنَ الدُّنْيَا إِلَّا مَا كُتِبَ لَهُ، وَمَنْ كَانَتِ الْآخِرَةُ نِيَّتَهُ، جَمَعَ لَهُ أَمْرَهُ وَجَعَلَ غِنَاهُ فِي قَلْبِهِ، وَأَتَتْهُ الدُّنْيَا وَهِيَ رَاغِمَة»\n\r\n\n\r\n(எவரது கவலை இவ்வுலகமாக இருக்கிறதோ, அவரது விவகாரங்களை அல்லாஹ் சிரமமாக்கி விடுவான். மேலும், வறுமையை அவரது இரு கண்களுக்கு முன்னால் நிறுத்தி விடுவான். இவ்வுலகிலிருந்து அவருக்கு எழுதப்பட்டதைத் தவிர வேறெதுவும் அவருக்குக் கிடைக்காது. எவரது நோக்கம் மறுமையாக இருக்கிறதோ, அவரது விவகாரங்களை அல்லாஹ் எளிதாக்கி விடுவான். மேலும், அவரது உள்ளத்தில் மனநிறைவை வைப்பான். இவ்வுலகம் அவரைத் தேடிப் பணிந்து வந்து சேரும்.)\n\r\n\n\r\nஅல்லாஹ்வின் கூற்றான,\n\r\n\n\r\nوَالْعَاقِبَةُ لِلتَّقْوَى\n\r\n\n\r\n(நல்ல முடிவு இறையச்சம் உடையவர்களுக்கே (தக்வாவுக்கே) உரியது) என்பதன் பொருள், இவ்வுலகிலும் மறுமையிலும் ஏற்படப்போகும் நல்முடிவாகும். மறுமையில், அல்லாஹ்வை அஞ்சி நடந்தவர்களுக்கே சொர்க்கம் எனும் நல்முடிவு கிட்டும். ஸஹீஹில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியதாக அறிவிக்கப்பட்டுள்ளது: \"இன்றிரவு நான் (கனவில்) ‘உக்பா பின் ராஃபி’ என்பவருடைய வீட்டில் இருப்பதைப் போன்றும், ‘இப்னு தாப்’ (ரகப் பேரீச்சம்) பழங்கள் நமக்குக் கொண்டு வரப்படுவதைப் போன்றும் கண்டேன். இதற்கு, ‘இவ்வுலகில் நல்முடிவு (ஆகிபத்) நமக்கே உரியது; மறுமையில் நமக்கு உயர்வும் (ரிஃப்அத்) உண்டு; நமது மார்க்கம் தூய்மையானது (தாப்)’ என்று நான் விளக்கம் கொண்டேன்.\"\n\r\n\n\r\nகுர்ஆனே ஓர் ஆதாரமாக இருக்கும்போது, ஆதாரங்களுக்காக இணைவைப்பாளர்கள் அத்தாட்சிகளைக் கோருதல்\n\r\n\n\r\nநிராகரிப்பாளர்கள் கூறும் கூற்றைப் பற்றி உயர்ந்தோன் அல்லாஹ் தெரிவிக்கிறான்:\n\r\n\n\r\nلَوْلاَ\n\r\n\n\r\n(ஏன் இல்லை?) அதாவது, \"முஹம்மது (ஸல்) அவர்கள் தமது இறைவனிடமிருந்து ஓர் அத்தாட்சியை ஏன் நம்மிடம் கொண்டு வரவில்லை?\" என்பது இதன் பொருளாகும். அவர் அல்லாஹ்வின் தூதர் (ஸல்) எனும் அவரது கூற்றிற்கு ஆதாரமாகத் திகழும் ஓர் அற்புதத்தையே அவர்கள் நாடினர். அதற்கு உயர்ந்தோன் அல்லாஹ் கூறினான்:\n\r\n\n\r\nأَوَلَمْ تَأْتِهِمْ بَيِّنَةُ مَا فِي الصُّحُفِ الْأُولَى\n\r\n\n\r\n(முந்தைய வேதங்களில் உள்ளவற்றின் தெளிவான ஆதாரம் அவர்களிடம் வரவில்லையா?)\n\r\n\n\r\nஇதன் பொருள் குர்ஆன் ஆகும். எழுதப்படிக்கத் தெரியாத, முந்தைய வேதக்காரர்களிடம் கல்வி பயிலாத ஒருவராக அவர் இருந்தபோதிலும், அல்லாஹ் அவருக்கு இக்குர்ஆனை வஹீ (இறைச்செய்தி) ஆக அருளினான். இக்குர்ஆனோ கடந்த கால மக்களின் பழங்கால நிகழ்வுகளைப் பற்றியத் தகவல்களைத் தன்னுள் கொண்டுள்ளது. முந்தைய வேதங்களில் கூறப்பட்டுள்ள உண்மையான தகவல்களுடன் இது ஒத்துப்போகிறது. குர்ஆன் முந்தைய வேதங்களை மேற்பார்வையிடுவதும் ஆகும். எது சரியானது என்பதை இது உறுதிப்படுத்துவதுடன், அந்த வேதங்களில் தவறாகப் புகுத்தப்பட்ட செய்திகளை விளக்குகிறது. இவ்வசனம் சூரத்துல் அன்கபூத்தில் உள்ள அல்லாஹ்வின் கூற்றைப் போன்றதேயாகும்:\n\r\n\n\r\nوَقَالُواْ لَوْلاَ أُنزِلَ عَلَيْهِ آيَاتٌ مِّن رَّبِّهِ قُلْ إِنَّمَا الْآيَاتُ عِندَ اللَّهِ وَإِنَّمَا أَنَاْ نَذِيرٌ مُّبِينٌ - أَوَلَمْ يَكْفِهِمْ أَنَّا أَنزَلْنَا عَلَيْكَ الْكِتَابَ يُتْلَى عَلَيْهِمْ إِنَّ فِي ذَلِكَ لَرَحْمَةً وَذِكْرَى لِقَوْمٍ يُؤْمِنُونَ\n\r\n\n\r\n(மேலும் அவர்கள் கூறுகிறார்கள்: \"அவரது இறைவனிடமிருந்து அவருக்கு அத்தாட்சிகள் இறக்கப்பட வேண்டாமா?\" நீர் கூறும்: \"அத்தாட்சிகள் அனைத்தும் அல்லாஹ்விடமே உள்ளன; நான் பகிரங்கமாக எச்சரிக்கை செய்பவன் மட்டுமே.\" அவர்களுக்கு ஓதிக்காட்டப்படும் இவ்வேதத்தை நாம் உமக்கு அருளியிருப்பது அவர்களுக்குப் போதுமானதாக இல்லையா? நிச்சயமாக இதில் ஈமான் கொண்ட மக்களுக்கு ஓர் அருளும் நினைவூட்டலும் உள்ளது.) 29:50-51\n\r\n\n\r\nஇரண்டு ஸஹீஹ்களிலும் பதிவு செய்யப்பட்டுள்ள ஒரு ஹதீஸில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«مَا مِنْ نَبِيَ إِلَّا وَقَدْ أُوتِيَ مِنَ الْآياتِ مَا آمَنَ عَلَى مِثْلِهِ الْبَشَرُ، وَإِنَّمَا كَانَ الَّذِي أُوتِيتُهُ وَحْيًا أَوْحَاهُ اللهُ إِلَيَّ، فَأَرْجُو أَنْ أَكُونَ أَكْثَرَهُمْ تَابِعًا يَوْمَ الْقِيَامَة»\n\r\n\n\r\n(எந்த ஒரு நபியும் மனிதர்கள் நம்பிக்கை கொள்வதற்குத் தேவையான அத்தாட்சிகள் வழங்கப்படாமல் இருந்ததில்லை. எனக்கு வழங்கப்பட்டதோ அல்லாஹ் எனக்கு வழங்கிய வஹீ (இறைச்செய்தி) ஆகும். எனவே, மறுமை நாளில் மற்ற நபிமார்களை விட அதிகமானப் பின்பற்றுபவர்களைக் கொண்டவனாக நான் இருப்பேன் என்று நம்புகிறேன்.) இந்த ஹதீஸில், தமக்கு வழங்கப்பட்ட அத்தாட்சிகளிலேயே மிக மகத்தானதான குர்ஆனை மட்டுமே நபி (ஸல்) அவர்கள் குறிப்பிட்டுள்ளார்கள். இருப்பினும், அவர்களுக்கு எண்ணற்ற இதர அற்புதங்களும் இருந்தன. அவை குறித்த நூல்களில் பதிவு செய்யப்பட்டுள்ளன.\n\r\n\n\r\nபின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَلَوْ أَنَّا أَهْلَكْنَاهُمْ بِعَذَابٍ مِّن قَبْلِهِ لَقَالُواْ رَبَّنَا لَوْلا أَرْسَلْتَ إِلَيْنَا رَسُولاً\n\r\n\n\r\n(நாம் இவர்களுக்கு முன்னரே இவர்களை வேதனையைக் கொண்டு அழித்திருந்தால், இவர்கள் நிச்சயமாகக் கூறுவார்கள்: \"எங்கள் இறைவா! நீ எங்களுக்கு ஒரு தூதரை அனுப்பியிருக்கக் கூடாதா...\") இதன் பொருள்: \"இந்த கண்ணியமிக்க தூதரை அனுப்பி, மகத்தான இவ்வேதத்தை அருளுவதற்கு முன்னரே நாம் இந்த நிராகரிப்பவர்களை அழித்திருந்தால், அவர்கள் இவ்வாறு கூறியிருப்பார்கள்:\n\r\n\n\r\nرَبَّنَا لَوْلا أَرْسَلْتَ إِلَيْنَا رَسُولاً\n\r\n\n\r\n(எங்கள் இறைவா! நீ எங்களுக்கு ஒரு தூதரை அனுப்பியிருக்கக் கூடாதா?) அதாவது, 'நீர் எங்களை அழிப்பதற்கு முன்னரே தூதரை அனுப்பியிருந்தால் நாங்கள் அவரை ஈமான் கொண்டு பின்பற்றியிருப்போம்' என்று கூறியிருப்பார்கள்.\"\n\r\n\n\r\nஇதனை அல்லாஹ் இவ்வாறு கூறுகிறான்:\n\r\n\n\r\nفَنَتَّبِعَ آيَاتِكَ مِن قَبْلِ أَن نَّذِلَّ وَنَخْزَى\n\r\n\n\r\n(நாங்கள் இழிவடைவதற்கும் அவமானப்படுவதற்கும் முன்னதாகவே உமது வசனங்களைப் பின்பற்றியிருப்போம்.) இந்த நிராகரிப்பாளர்கள் மிகவும் பிடிவாதக் குணமுடையவர்கள் என்றும், அவர்கள் ஒருபோதும் ஈமான் கொள்ள மாட்டார்கள் என்றும் உயர்ந்தோன் அல்லாஹ் விளக்குகிறான்.\n\r\n\n\r\nوَلَوْ جَاءَتْهُمْ كُلُّ آيَةٍ حَتَّى يَرَوُاْ الْعَذَابَ الْأَلِيمَ\n\r\n\n\r\n(வேதனைமிக்கத் தண்டனையை அவர்கள் நேரில் காணும் வரை, எல்லா அத்தாட்சிகளும் அவர்களிடம் வந்தாலும் (அவர்கள் ஈமான் கொள்ள மாட்டார்கள்).) 10:97\n\r\n\n\r\nஇது அல்லாஹ்வின் இந்த வசனத்தைப் போன்றது:\n\r\n\n\r\nوَهَذَا كِتَابٌ أَنزَلْنَاهُ مُبَارَكٌ فَاتَّبِعُوهُ وَاتَّقُواْ لَعَلَّكُمْ تُرْحَمُونَ\n\r\n\n\r\n(மேலும் நாம் அருளிய இப்புனிதமிக்க வேதத்தைப் பின்பற்றுங்கள்; அல்லாஹ்வுக்கு அஞ்சுங்கள்; நீங்கள் கருணை செய்யப்படுவீர்கள்.) இது முதல்\n\r\n\n\r\nبِمَا كَانُواْ يَصْدِفُونَ\n\r\n\n\r\n(அவர்கள் புறக்கணித்ததன் காரணமாக) என்பது வரை (6:155-157). அல்லாஹ் மேலும் கூறுகிறான்:\n\r\n\n\r\nوَأَقْسَمُواْ بِاللَّهِ جَهْدَ أَيْمَانِهِمْ لَئِن جَاءَهُمْ نَذِيرٌ لَّيَكُونُنَّ أَهْدَى مِنْ إِحْدَى الْأُمَمِ\n\r\n\n\r\n(தங்களிடம் ஓர் எச்சரிக்கையாளர் வந்தால், மற்றெந்தச் சமூகத்தையும் விட நேர்வழி நடப்போம் என்று அவர்கள் அல்லாஹ்வின் மீது மிக உறுதியாகச் சத்தியம் செய்தனர்.) 35:42\n\r\n\n\r\nوَأَقْسَمُواْ بِاللَّهِ جَهْدَ أَيْمَانِهِمْ لَئِن جَاءَتْهُمْ آيَةٌ لَّيُؤْمِنُنَّ بِهَا\n\r\n\n\r\n(தங்களிடம் ஓர் அத்தாட்சி வந்தால், அதன் மீது நிச்சயமாக ஈமான் கொள்வதாக அவர்கள் அல்லாஹ்வின் மீது மிக உறுதியாகச் சத்தியம் செய்கின்றனர்.) 6:109 (வசனம் முடியும் வரை).\n\r\n\n\r\nபின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nقُلْ\n\r\n\n\r\n(நீர் கூறுவீராக!) \"முஹம்மதே! உம்மைப் பொய்ப்பித்து எதிர்த்து வரும் அந்த நிராகரிப்பாளர்களிடம் கூறும்:\n\r\n\n\r\nكُلٌّ مُّتَرَبِّصٌ\n\r\n\n\r\n(ஒவ்வொருவரும் எதிர்பார்த்துக் காத்திருக்கின்றனர்;) நீங்களும் நாங்களும்;\n\r\n\n\r\nفَتَرَبَّصُواْ\n\r\n\n\r\n(எனவே நீங்களும் காத்திருங்கள்;) இது காத்திருக்குமாறு இடும் கட்டளையாகும்.\n\r\n\n\r\nفَسَتَعْلَمُونَ مَنْ أَصْحَابُ الصِّرَاطِ السَّوِيِّ\n\r\n\n\r\n(யார் அஸ்-ஸிராத் அஸ்-ஸவிய்யில் (நேரான பாதையில்) இருப்பவர் என்பதை நீங்கள் விரைவில் அறிந்து கொள்வீர்கள்.) இதன் பொருள் நேரான பாதையாகும்.\n\r\n\n\r\nوَمَنِ اهْتَدَى\n\r\n\n\r\n(யார் நேர்வழி பெற்றவர் என்பதையும் (அறிந்து கொள்வீர்கள்).) அதாவது உண்மைக்கும் நேர்வழிக்கும் வழிகாட்டப்பட்டவர்கள் யார் என்பதாகும். இது அல்லாஹ்வின் இந்த வசனத்தைப் போன்றது:\n\r\n\n\r\nوَسَوْفَ يَعْلَمُونَ حِينَ يَرَوْنَ الْعَذَابَ مَنْ أَضَلُّ سَبِيلاً\n\r\n\n\r\n(அவர்கள் வேதனையைக் காணும்போது, பாதையிலிருந்து மிகவும் வழிதவறியவர் யார் என்பதை அறிந்து கொள்வார்கள்.) 25:42 மேலும் அல்லாஹ் கூறினான்:\n\r\n\n\r\nسَيَعْلَمُونَ غَداً مَّنِ الْكَذَّابُ الْأَشِرُ\n\r\n\n\r\n(நாளை அவர்கள் யார் பெரும் பொய்யர், யார் திமிர் பிடித்தவர் என்பதை அறிந்து கொள்வார்கள்!) 54:26\n\r\n\n\r\nஇத்துடன் சூரா தா ஹாவின் தஃப்ஸீர் நிறைவுற்றது. எல்லாப் புகழும் நன்றியும் அல்லாஹ்வுக்கே உரியது. அல்லாஹ் நாடினால், இதனைத் தொடர்ந்து சூரத்துல் அன்பியாவின் தஃப்ஸீர் வரும். புகழ் அனைத்தும் அல்லாஹ்வுக்கே!"}}};})(self);
